    item_count: u32,
    page_count: u32,
    remaining_pages: u32,
}

#[derive(Debug, PartialEq)]
pub struct CommandEnvelopeSet {
    commands: std::collections::VecDeque<CommandBatchEntry>,
    page_storage: std::collections::VecDeque<FixedCommandPage>,
    pages: usize,
    bytes: usize,
}

impl CommandEnvelopeSet {
    pub fn try_new() -> Result<Self, semio_framework_diagnostic::Fault> {
        let mut commands = std::collections::VecDeque::new();
        commands
            .try_reserve_exact(COMMAND_BATCH_MAXIMUM_ITEMS)
            .map_err(|_| semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.command-batch-allocation"), "fixed command batch authority could not reserve its exact 64 slots"))?;
        Ok(Self { commands, page_storage: std::collections::VecDeque::new(), pages: 0, bytes: 0 })
    }

    pub fn try_push(&mut self, command: CommandEnvelope) -> Result<(), (semio_framework_diagnostic::Fault, CommandEnvelope)> {
        if self.commands.len() == COMMAND_BATCH_MAXIMUM_ITEMS {
            return Err((semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.command-batch-cap"), "command batch exceeds its exact 64-item authority"), command));
        }
        let pages = match self.pages.checked_add(command.command.page_len()) {
            Some(pages) if pages <= COMMAND_MAXIMUM_PAGES => pages,
            _ => return Err((semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.command-batch-page-cap"), "command batch exceeds its aggregate page authority"), command)),
        };
        let bytes = match self.bytes.checked_add(command.command.byte_len()) {
            Some(bytes) if bytes <= COMMAND_MAXIMUM_BYTES => bytes,
            _ => return Err((semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.command-batch-byte-cap"), "command batch exceeds its aggregate assembled-byte authority"), command)),
        };
        if self.page_storage.try_reserve_exact(command.command.page_len()).is_err() {
            return Err((semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.command-batch-page-allocation"), "command batch could not reserve the exact page slots this command declares"), command));
        }
        let CommandEnvelope { instance, seq, command } = command;
        let PagedCommand { pages: mut command_pages, kind, metadata, item_count, .. } = command;
        let page_count = u32::try_from(command_pages.len()).expect("admitted command page count is u32-bounded");
        self.commands.push_back(CommandBatchEntry { instance, seq, kind, metadata, item_count, page_count, remaining_pages: page_count });
        while let Some(page) = command_pages.pop_front() {
            self.page_storage.push_back(page);
        }
        self.pages = pages;
        self.bytes = bytes;
        Ok(())
    }

    pub fn close_step(&mut self, maximum_bytes: usize) -> (bool, usize) {
        let Some(command) = self.commands.front_mut() else {
            return (self.page_storage.is_empty(), 0);
        };
        if command.remaining_pages == 0 {
            let _terminal = self.commands.pop_front().expect("empty command-build shell was present");
            return (self.commands.is_empty() && self.page_storage.is_empty(), 0);
        }
        let Some(page_len) = self.page_storage.front().map(FixedCommandPage::len) else {
            return (false, 0);
        };
        if page_len > maximum_bytes {
            return (false, 0);
        }
        let page = self.page_storage.pop_front().expect("command-build page was present");
        let released = page.len();
        self.pages -= 1;
        self.bytes -= released;
        command.remaining_pages -= 1;
        drop(page);
        if command.remaining_pages == 0 {
            let _terminal = self.commands.pop_front().expect("empty command-build shell was present");
        }
        (self.commands.is_empty() && self.page_storage.is_empty(), released)
    }

    pub fn terminal_is_empty(&self) -> bool {
        self.commands.is_empty() && self.page_storage.is_empty() && self.pages == 0 && self.bytes == 0
    }
}

#[derive(Debug)]
pub struct RejectedCommandBuild {
    rejected: Option<CommandEnvelope>,
    admitted: CommandEnvelopeSet,
}

impl RejectedCommandBuild {
    pub fn new(admitted: CommandEnvelopeSet, rejected: CommandEnvelope) -> Self {
        Self { rejected: Some(rejected), admitted }
    }

    pub fn from_admitted(admitted: CommandEnvelopeSet) -> Self {
        Self { rejected: None, admitted }
    }

    pub fn close_step(&mut self, maximum_bytes: usize) -> (bool, usize) {
        if let Some(rejected) = self.rejected.as_mut() {
            let Some((empty, released)) = rejected.command.release_front_page(maximum_bytes) else {
                return (false, 0);
            };
            if empty {
                let _terminal = self.rejected.take().expect("rejected command reached terminal empty");
            }
            return (self.terminal_is_empty(), released);
        }
        self.admitted.close_step(maximum_bytes)
    }

    pub fn terminal_is_empty(&self) -> bool {
        self.rejected.is_none() && self.admitted.terminal_is_empty()
    }

    pub fn remaining_pages(&self) -> usize {
        self.rejected.as_ref().map_or(0, |rejected| rejected.command.page_len()) + self.admitted.pages
    }

    pub fn remaining_bytes(&self) -> usize {
        self.rejected.as_ref().map_or(0, |rejected| rejected.command.byte_len()) + self.admitted.bytes
    }
}

#[derive(Debug)]
pub struct RejectedCommandBuildRegistry<const CAPACITY: usize> {
    slots: [Option<RejectedCommandBuild>; CAPACITY],
    close_index: usize,
    occupied: usize,
}

impl<const CAPACITY: usize> Default for RejectedCommandBuildRegistry<CAPACITY> {
    fn default() -> Self {
        Self::new()
    }
}

impl<const CAPACITY: usize> RejectedCommandBuildRegistry<CAPACITY> {
    pub fn new() -> Self {
        assert!(CAPACITY > 0);
        Self { slots: std::array::from_fn(|_| None), close_index: 0, occupied: 0 }
    }

    pub fn can_insert(&self, key: u64) -> bool {
        self.slots[key as usize % CAPACITY].is_none()
    }

    pub fn try_insert(&mut self, key: u64, owner: RejectedCommandBuild) -> Result<(), (semio_framework_diagnostic::Fault, RejectedCommandBuild)> {
        let index = key as usize % CAPACITY;
        if self.slots[index].is_some() {
            return Err((semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.command-build-close-capacity"), "fixed rejected command-build close registry is occupied or collided"), owner));
        }
        self.slots[index] = Some(owner);
        self.occupied += 1;
        Ok(())
    }

    pub fn insert_admitted(&mut self, key: u64, owner: RejectedCommandBuild) {
        let index = key as usize % CAPACITY;
        assert!(self.slots[index].is_none(), "fixed rejected command-build admission changed before insert");
        self.slots[index] = Some(owner);
        self.occupied += 1;
    }

    pub fn close_step(&mut self, maximum_bytes: usize) -> (bool, usize, usize) {
        if self.occupied == 0 {
            return (true, 0, 0);
        }
        for _ in 0..CAPACITY {
            let index = self.close_index;
            self.close_index = (self.close_index + 1) % CAPACITY;
            let Some(owner) = self.slots[index].as_mut() else {
                continue;
            };
            let (terminal, released) = owner.close_step(maximum_bytes);
            if terminal {
                let terminal = self.slots[index].take().expect("terminal rejected command build was present");
                self.occupied -= 1;
                assert!(terminal.terminal_is_empty(), "rejected command build terminal witness changed before removal");
            }
            return (self.occupied == 0, 1, released);
        }
        (false, 0, 0)
    }

    pub fn terminal_is_empty(&self) -> bool {
        self.occupied == 0
    }
}

impl CommandBatch {
    pub fn try_new(generation: u64, commands: CommandEnvelopeSet) -> Result<Self, (semio_framework_diagnostic::Fault, CommandEnvelopeSet)> {
        if commands.commands.is_empty() {
            return Err((semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.command-batch-cap"), "command batch requires at least one exact command owner"), commands));
        }
        Ok(Self { generation, commands: commands.commands, pages: commands.page_storage, bytes: commands.bytes })
    }

    pub fn generation(&self) -> u64 {
        self.generation
    }

    pub fn remaining_pages(&self) -> usize {
        self.pages.len()
    }

    pub fn remaining_bytes(&self) -> usize {
        self.bytes
    }

    fn terminal_is_empty(&self) -> bool {
        self.commands.is_empty() && self.pages.is_empty() && self.bytes == 0
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CommandBatchProgress {
    PageReady,
    Waiting,
    Complete,
    Faulted,
}

#[derive(Debug)]
pub struct CommandBatchDriver {
    owner: u64,
    batch: CommandBatch,
    command_index: u32,
    page_index: u32,
    admitted_page_count: u32,
    admitted_kind: u8,
    faulted: bool,
    waiting: bool,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum CommandDriverRetentionState {
    Active,
    Suspended,
    Closing,
}

#[derive(Debug)]
struct CommandDriverRetentionSlot {
    key: u64,
    generation: u64,
    driver: CommandBatchDriver,
    state: CommandDriverRetentionState,
    close_previous: Option<u16>,
    close_next: Option<u16>,
}

#[derive(Debug)]
pub struct CommandDriverRegistry<const CAPACITY: usize> {
    slots: [Option<CommandDriverRetentionSlot>; CAPACITY],
    close_head: Option<u16>,
    close_tail: Option<u16>,
    occupied: usize,
}

impl<const CAPACITY: usize> Default for CommandDriverRegistry<CAPACITY> {
    fn default() -> Self {
        Self::new()
    }
}

impl<const CAPACITY: usize> CommandDriverRegistry<CAPACITY> {
    pub fn new() -> Self {
        assert!(CAPACITY > 0 && CAPACITY <= usize::from(u16::MAX));
        Self { slots: std::array::from_fn(|_| None), close_head: None, close_tail: None, occupied: 0 }
    }

    pub fn try_insert(&mut self, key: u64, generation: u64, driver: CommandBatchDriver) -> Result<(), (semio_framework_diagnostic::Fault, CommandBatchDriver)> {
        if !self.can_insert(key) {
            return Err((semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.command-driver-capacity"), "fixed retained command-driver slot is occupied or collided"), driver));
        }
        self.insert_admitted(key, generation, driver);
        Ok(())
    }

    pub fn can_insert(&self, key: u64) -> bool {
        self.slots[key as usize % CAPACITY].is_none()
    }

    pub fn insert_admitted(&mut self, key: u64, generation: u64, driver: CommandBatchDriver) {
        let index = key as usize % CAPACITY;
        assert!(self.slots[index].is_none(), "fixed retained command-driver admission changed before insert");
        self.slots[index] = Some(CommandDriverRetentionSlot { key, generation, driver, state: CommandDriverRetentionState::Active, close_previous: None, close_next: None });
        self.occupied += 1;
    }

    pub fn with_driver_mut<R>(&mut self, key: u64, generation: u64, f: impl FnOnce(&mut CommandBatchDriver) -> R) -> Result<R, semio_framework_diagnostic::Fault> {
        let slot = self.slot_mut(key, generation)?;
        if slot.state != CommandDriverRetentionState::Active {
            return Err(semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.command-driver-not-active"), "retained command driver is suspended or closing"));
        }
        Ok(f(&mut slot.driver))
    }

    pub fn prepare_suspend(&mut self, key: u64, generation: u64) -> Result<(), semio_framework_diagnostic::Fault> {
        let index = self.index_of(key, generation)?;
        if self.slots[index].as_ref().expect("retained command slot exists").state != CommandDriverRetentionState::Active {
            return Err(semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.command-driver-suspend-state"), "retained command driver is not active before suspension"));
        }
        self.link_close(index);
        self.slots[index].as_mut().expect("retained command slot exists").state = CommandDriverRetentionState::Suspended;
        Ok(())
    }

    pub fn resume(&mut self, key: u64, generation: u64) -> Result<(), semio_framework_diagnostic::Fault> {
        let index = self.index_of(key, generation)?;
        if self.slots[index].as_ref().expect("retained command slot exists").state != CommandDriverRetentionState::Suspended {
            return Err(semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.command-driver-resume-state"), "retained command driver is not suspended before resume"));
        }
        self.unlink_close(index);
        self.slots[index].as_mut().expect("retained command slot exists").state = CommandDriverRetentionState::Active;
        Ok(())
    }

    pub fn begin_close(&mut self, key: u64, generation: u64) -> Result<(), semio_framework_diagnostic::Fault> {
        let index = self.index_of(key, generation)?;
        let state = self.slots[index].as_ref().expect("retained command slot exists").state;
        if state == CommandDriverRetentionState::Active {
            self.link_close(index);
        }
        self.slots[index].as_mut().expect("retained command slot exists").state = CommandDriverRetentionState::Closing;
        Ok(())
    }

    pub fn begin_close_key(&mut self, key: u64) -> Result<u64, semio_framework_diagnostic::Fault> {
        let index = key as usize % CAPACITY;
        let generation = match self.slots[index].as_ref() {
            Some(slot) if slot.key == key => slot.generation,
            _ => return Err(semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.command-driver-stale"), "retained command driver key is stale")),
        };
        self.begin_close(key, generation)?;
        Ok(generation)
    }

    pub fn remove_terminal(&mut self, key: u64, generation: u64) -> Result<(), semio_framework_diagnostic::Fault> {
        let index = self.index_of(key, generation)?;
        if !self.slots[index].as_ref().expect("retained command slot exists").driver.terminal_is_empty() {
            return Err(semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.command-driver-nonterminal-remove"), "retained command driver cannot be removed before terminal empty"));
        }
        if self.slots[index].as_ref().expect("retained command slot exists").state != CommandDriverRetentionState::Active {
            self.unlink_close(index);
        }
        let terminal = self.slots[index].take().expect("retained command slot exists");
        self.occupied -= 1;
        drop(terminal);
        Ok(())
    }

    pub fn close_step(&mut self, maximum_bytes: usize) -> (bool, usize, usize) {
        let Some(index) = self.close_head.map(usize::from) else {
            return (self.occupied == 0, 0, 0);
        };
        let (terminal, released) = {
            let slot = self.slots[index].as_mut().expect("close-list command slot exists");
            slot.driver.close_step(maximum_bytes)
        };
        if terminal {
            self.unlink_close(index);
            let terminal = self.slots[index].take().expect("terminal command slot exists");
            self.occupied -= 1;
            drop(terminal);
        }
        (self.occupied == 0, 1, released)
    }

    pub fn terminal_is_empty(&self) -> bool {
        self.occupied == 0 && self.close_head.is_none() && self.close_tail.is_none()
    }

    pub fn has_close_work(&self) -> bool {
        self.close_head.is_some()
    }

    pub fn contains(&self, key: u64, generation: u64) -> bool {
        self.index_of(key, generation).is_ok()
    }

    pub fn is_active(&self, key: u64, generation: u64) -> bool {
        self.index_of(key, generation).ok().and_then(|index| self.slots[index].as_ref()).is_some_and(|slot| slot.state == CommandDriverRetentionState::Active)
    }

    fn slot_mut(&mut self, key: u64, generation: u64) -> Result<&mut CommandDriverRetentionSlot, semio_framework_diagnostic::Fault> {
        let index = self.index_of(key, generation)?;
        Ok(self.slots[index].as_mut().expect("retained command slot exists"))
    }

    fn index_of(&self, key: u64, generation: u64) -> Result<usize, semio_framework_diagnostic::Fault> {
        let index = key as usize % CAPACITY;
        match self.slots[index].as_ref() {
            Some(slot) if slot.key == key && slot.generation == generation => Ok(index),
            _ => Err(semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.command-driver-stale"), "retained command driver identity or generation is stale")),
        }
    }

    fn link_close(&mut self, index: usize) {
        let previous = self.close_tail;
        let index_u16 = u16::try_from(index).expect("command registry capacity is u16-bounded");
        {
            let slot = self.slots[index].as_mut().expect("retained command slot exists");
            slot.close_previous = previous;
            slot.close_next = None;
        }
        if let Some(previous) = previous {
            self.slots[usize::from(previous)].as_mut().expect("previous close slot exists").close_next = Some(index_u16);
        } else {
            self.close_head = Some(index_u16);
        }
        self.close_tail = Some(index_u16);
    }

    fn unlink_close(&mut self, index: usize) {
        let (previous, next) = {
            let slot = self.slots[index].as_ref().expect("retained command slot exists");
            (slot.close_previous, slot.close_next)
        };
        if let Some(previous) = previous {
            self.slots[usize::from(previous)].as_mut().expect("previous close slot exists").close_next = next;
        } else {
            self.close_head = next;
        }
        if let Some(next) = next {
            self.slots[usize::from(next)].as_mut().expect("next close slot exists").close_previous = previous;
        } else {
            self.close_tail = previous;
        }
        let slot = self.slots[index].as_mut().expect("retained command slot exists");
        slot.close_previous = None;
        slot.close_next = None;
    }
}

impl CommandBatchDriver {
    pub fn new(owner: u64, batch: CommandBatch) -> Self {
        Self { owner, batch, command_index: 0, page_index: 0, admitted_page_count: 0, admitted_kind: 0, faulted: false, waiting: false }
    }

    pub fn next_page(&mut self) -> Result<Option<(CommandPageCursor, FixedCommandPage)>, semio_framework_diagnostic::Fault> {
        if self.faulted || self.waiting {
            return Ok(None);
        }
        let Some(command) = self.batch.commands.front() else {
            return Ok(None);
        };
        if self.admitted_page_count == 0 {
            self.admitted_page_count = command.page_count;
            self.admitted_kind = command.kind;
        }
        let bytes = self.batch.pages.front().ok_or_else(|| semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.command-owner-empty"), "nonterminal command owner has no page"))?.clone();
        let cursor = CommandPageCursor {
            owner: self.owner,
            generation: self.batch.generation,
            command_index: self.command_index,
            command_count: u32::try_from(self.batch.commands.len()).unwrap_or(u32::MAX).saturating_add(self.command_index),
            instance: command.instance,
            seq: command.seq,
            kind: self.admitted_kind,
            page_index: self.page_index,
            page_count: self.admitted_page_count,
            item_count: command.item_count,
            metadata: command.metadata,
        };
        Ok(Some((cursor, bytes)))
    }

    pub fn observe(&mut self, status: &CommandIngressStatus, maximum_release_bytes: usize) -> Result<CommandBatchProgress, semio_framework_diagnostic::Fault> {
        let (cursor, shape) = match status {
            CommandIngressStatus::Idle => {
                return Ok(if self.batch.commands.is_empty() {
                    CommandBatchProgress::Complete
                } else if self.faulted {
                    CommandBatchProgress::Faulted
                } else if self.waiting {
                    CommandBatchProgress::Waiting
                } else {
                    CommandBatchProgress::PageReady
                });
            }
            CommandIngressStatus::PageAccepted(cursor) | CommandIngressStatus::Backpressure(cursor) => (cursor, CursorShape::Page),
            CommandIngressStatus::CommandPending(cursor) | CommandIngressStatus::CommandComplete(cursor) => (cursor, CursorShape::Terminal),
            CommandIngressStatus::Fault { cursor, .. } => (cursor, CursorShape::Fault),
        };
        self.validate_cursor(cursor, shape)?;
        match status {
            CommandIngressStatus::Backpressure(_) => Ok(CommandBatchProgress::PageReady),
            CommandIngressStatus::PageAccepted(_) => {
                let Some(command) = self.batch.commands.front_mut() else {
                    return Err(semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.command-owner-missing"), "accepted page has no exact host owner"));
                };
                let page_len =
                    self.batch.pages.front().map(FixedCommandPage::len).ok_or_else(|| semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.command-owner-missing"), "accepted page has no exact retained batch page"))?;
                if page_len > maximum_release_bytes {
                    return Err(semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.command-release-budget"), "accepted page exceeds its exact release grant"));
                }
                let page = self.batch.pages.pop_front().expect("accepted retained batch page was present");
                let released = page.len();
                self.batch.bytes -= released;
                drop(page);
                command.remaining_pages = command
                    .remaining_pages
                    .checked_sub(1)
                    .ok_or_else(|| semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.command-page-underflow"), "accepted page arrived after the retained command page owner was empty"))?;
                let empty = command.remaining_pages == 0;
                self.page_index = self.page_index.saturating_add(1);
                if empty {
                    self.waiting = true;
                    Ok(CommandBatchProgress::Waiting)
                } else {
                    Ok(CommandBatchProgress::PageReady)
                }
            }
            CommandIngressStatus::CommandPending(_) => {
                self.waiting = true;
                Ok(CommandBatchProgress::Waiting)
            }
            CommandIngressStatus::CommandComplete(_) => {
                let Some(command) = self.batch.commands.front() else {
                    return Err(semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.command-owner-missing"), "terminal command has no exact host owner"));
                };
                if command.remaining_pages > 1 {
                    return Err(semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.command-terminal-pages"), "terminal acknowledgement arrived before every exact page was released"));
                }
                if command.remaining_pages == 1 {
                    let page_len = self
                        .batch
                        .pages
                        .front()
                        .map(FixedCommandPage::len)
                        .ok_or_else(|| semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.command-owner-missing"), "terminal command has no exact retained batch page"))?;
                    if page_len > maximum_release_bytes {
                        return Err(semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.command-release-budget"), "terminal page exceeds its exact release grant"));
                    }
                    let page = self.batch.pages.pop_front().expect("terminal retained batch page was present");
                    self.batch.bytes -= page.len();
                    drop(page);
                }
                let _terminal = self.batch.commands.pop_front().expect("terminal command was present");
                self.command_index = self.command_index.saturating_add(1);
                self.page_index = 0;
                self.admitted_page_count = 0;
                self.admitted_kind = 0;
                self.waiting = false;
                Ok(if self.batch.commands.is_empty() { CommandBatchProgress::Complete } else { CommandBatchProgress::PageReady })
            }
            CommandIngressStatus::Fault { .. } => {
                self.faulted = true;
                Ok(CommandBatchProgress::Faulted)
            }
            CommandIngressStatus::Idle => unreachable!(),
        }
    }

    pub fn close_step(&mut self, maximum_bytes: usize) -> (bool, usize) {
        let Some(command) = self.batch.commands.front_mut() else {
            return (self.batch.pages.is_empty(), 0);
        };
        if command.remaining_pages == 0 {
            let _terminal = self.batch.commands.pop_front().expect("empty retained command shell was present");
            self.command_index = self.command_index.saturating_add(1);
            self.page_index = 0;
            self.admitted_page_count = 0;
            self.admitted_kind = 0;
            self.waiting = false;
            return (self.batch.terminal_is_empty(), 0);
        }
        let Some(page_len) = self.batch.pages.front().map(FixedCommandPage::len) else {
            return (false, 0);
        };
        if page_len > maximum_bytes {
            return (false, 0);
        }
        let page = self.batch.pages.pop_front().expect("retained batch close page was present");
        let released = page.len();
        self.batch.bytes -= released;
        drop(page);
        command.remaining_pages -= 1;
        let empty = command.remaining_pages == 0;
        if empty {
            let _terminal = self.batch.commands.pop_front().expect("empty command was present");
            self.command_index = self.command_index.saturating_add(1);
            self.page_index = 0;
            self.admitted_page_count = 0;
            self.admitted_kind = 0;
            self.waiting = false;
        }
        (self.batch.terminal_is_empty(), released)
    }

    pub fn terminal_is_empty(&self) -> bool {
        self.batch.terminal_is_empty()
    }

    pub fn generation(&self) -> u64 {
        self.batch.generation
    }

    pub fn remaining_pages(&self) -> usize {
        self.batch.pages.len()
    }

    pub fn remaining_bytes(&self) -> usize {
        self.batch.bytes
    }

    /// 🎯️ A terminal status carries `last_page_index + 1`, and a guest that consumed a command's LAST
    /// page and ran it to completion inside ONE turn publishes only that terminal — the per-page
    /// `PageAccepted` the host would otherwise have stepped through never exists. (`⚛️reactor/🔄️turn`'s
    /// single-page fast path does exactly this for every `page_count == 1` command, i.e. every ordinary
    /// mutation.) So a terminal cursor is validated against `page_index + remaining_pages`, which is
    /// the same number in both shapes, and a fault's cursor is accepted at either end of that range —
    /// a fault must attribute itself to its owner, never be replaced by a cursor complaint that hides
    /// the guest's own message (ticket 26/09/18 slice A2).
    fn validate_cursor(&self, cursor: &CommandPageCursor, shape: CursorShape) -> Result<(), semio_framework_diagnostic::Fault> {
        let Some(command) = self.batch.commands.front() else {
            return Err(semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.command-owner-missing"), "ingress status has no exact host owner"));
        };
        let terminal_page_index = self.page_index.saturating_add(command.remaining_pages);
        let page_index_matches = match shape {
            CursorShape::Page => cursor.page_index == self.page_index,
            CursorShape::Terminal => cursor.page_index == terminal_page_index,
            CursorShape::Fault => cursor.page_index == self.page_index || cursor.page_index == terminal_page_index,
        };
        let mismatch = if cursor.owner != self.owner {
            Some(("owner", u64::from(cursor.owner), self.owner))
        } else if cursor.generation != self.batch.generation {
            Some(("generation", cursor.generation, self.batch.generation))
        } else if cursor.command_index != self.command_index {
            Some(("commandIndex", u64::from(cursor.command_index), u64::from(self.command_index)))
        } else if cursor.instance != command.instance {
            Some(("instance", u64::from(cursor.instance), u64::from(command.instance)))
        } else if cursor.seq != command.seq {
            Some(("seq", cursor.seq, command.seq))
        } else if cursor.kind != self.admitted_kind {
            Some(("kind", u64::from(cursor.kind), u64::from(self.admitted_kind)))
        } else if !page_index_matches {
            Some(("pageIndex", u64::from(cursor.page_index), u64::from(if matches!(shape, CursorShape::Page) { self.page_index } else { terminal_page_index })))
        } else if cursor.page_count != self.admitted_page_count {
            Some(("pageCount", u64::from(cursor.page_count), u64::from(self.admitted_page_count)))
        } else if cursor.item_count != command.item_count {
            Some(("itemCount", u64::from(cursor.item_count), u64::from(command.item_count)))
        } else if cursor.metadata != command.metadata {
            Some(("metadata", u64::from(cursor.metadata), u64::from(command.metadata)))
        } else {
            None
        };
        if let Some((field, reported, expected)) = mismatch {
            return Err(semio_framework_diagnostic::Fault::new(
                semio_framework_diagnostic::FaultOrigin::Framework,
                semio_framework_diagnostic::FaultCode::new("plugin.command-cursor-mismatch"),
                format!("ingress status does not identify the exact retained host owner: {field} is {reported}, the retained owner's is {expected}"),
            ));
        }
        Ok(())
    }
}

/// 🪢️ `serde` kept alongside `ToValue`/`FromValue`: `kernel::Event`/`TurnResult` carry this type
/// across the plugin-host `serde_json` wire (`🔌️plugin/🖥️host/🧵️shard/🦀️.rs`'s
/// `serde_json::to_vec(&result.command_ingress)`) and stay on that encoding, not `DslValue` — both
/// derives must produce the same shape, so `#[serde(rename_all = "camelCase")]` mirrors `#[value(…)]`.
#[derive(Clone, Debug, PartialEq, serde::Serialize, serde::Deserialize, semio_framework_value_derive::ToValue, semio_framework_value_derive::FromValue)]
#[serde(rename_all = "camelCase")]
#[value(rename_all = "camelCase")]
pub struct CommandPageCursor {
    pub owner: u64,
    pub generation: u64,
    pub command_index: u32,
    pub command_count: u32,
    pub instance: u32,
    pub seq: u64,
    pub kind: u8,
    pub page_index: u32,
    pub page_count: u32,
    pub item_count: u32,
    pub metadata: u32,
}

/// 🪢️ `serde` kept alongside `ToValue`/`FromValue` — same wire-sharing reason as
/// `CommandPageCursor` above. No `#[serde(tag = …)]`: `#[value(rename_all = "camelCase")]` with no
/// `tag` derives externally-tagged (`✨️derive/🦀️.rs`'s documented default for a tag-less,
/// mixed-variant enum), which is also serde's own default enum representation — the two already
/// agree without a matching attribute.
#[derive(Clone, Debug, PartialEq, serde::Serialize, serde::Deserialize, semio_framework_value_derive::ToValue, semio_framework_value_derive::FromValue)]
#[serde(rename_all = "camelCase")]
#[value(rename_all = "camelCase")]
pub enum CommandIngressStatus {
    Idle,
    PageAccepted(CommandPageCursor),
    Backpressure(CommandPageCursor),
    CommandPending(CommandPageCursor),
    CommandComplete(CommandPageCursor),
    Fault { cursor: CommandPageCursor, fault: Vec<u8> },
}
//#endregion 🔖️PagedCommandIngress

//#region 🔖️PresenceRosterWire
pub const PRESENCE_ROSTER_MAXIMUM_ITEMS: usize = 64;
pub const PRESENCE_ROSTER_MAXIMUM_ENTRY_BYTES: usize = 4_096;
pub const PRESENCE_ROSTER_MAXIMUM_BYTES: usize = PRESENCE_ROSTER_MAXIMUM_ITEMS * PRESENCE_ROSTER_MAXIMUM_ENTRY_BYTES;

#[derive(Debug, PartialEq)]
pub struct PresenceRosterWire {
    entries: [Option<Box<[u8]>>; PRESENCE_ROSTER_MAXIMUM_ITEMS],
    len: usize,
    bytes: usize,
}

#[derive(Debug)]
pub struct PresenceRosterPushRejected {
    pub entry: Vec<u8>,
    pub reason: &'static str,
}

impl PresenceRosterWire {
    pub fn empty() -> Self {
        Self { entries: std::array::from_fn(|_| None), len: 0, bytes: 0 }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn byte_len(&self) -> usize {
        self.bytes
    }

    pub fn try_push(&mut self, entry: Vec<u8>) -> Result<(), PresenceRosterPushRejected> {
        if self.len == PRESENCE_ROSTER_MAXIMUM_ITEMS {
            return Err(PresenceRosterPushRejected { entry, reason: "presence roster exceeds its fixed item authority" });
        }
        if entry.len() > PRESENCE_ROSTER_MAXIMUM_ENTRY_BYTES || self.bytes.checked_add(entry.len()).is_none_or(|bytes| bytes > PRESENCE_ROSTER_MAXIMUM_BYTES) {
            return Err(PresenceRosterPushRejected { entry, reason: "presence roster exceeds its fixed byte authority" });
        }
        let bytes = entry.len();
        self.entries[self.len] = Some(entry.into_boxed_slice());
        self.len += 1;
        self.bytes += bytes;
        Ok(())
    }

    pub fn pop_back(&mut self) -> Option<Box<[u8]>> {
        if self.len == 0 {
            return None;
        }
        self.len -= 1;
        let entry = self.entries[self.len].take().expect("occupied presence roster slot");
        self.bytes -= entry.len();
        Some(entry)
    }

    pub fn iter(&self) -> impl Iterator<Item = &[u8]> {
        self.entries[..self.len].iter().filter_map(|entry| entry.as_deref())
    }

    pub fn last(&self) -> Option<&[u8]> {
        self.len.checked_sub(1).and_then(|index| self.entries[index].as_deref())
    }
}

impl Default for PresenceRosterWire {
    fn default() -> Self {
        Self::empty()
    }
}
//#endregion 🔖️PresenceRosterWire

//#region 🔖️PresenceCommandCursor
pub const PRESENCE_COMMAND_MAXIMUM_BYTES: usize = PRESENCE_ROSTER_MAXIMUM_BYTES + PRESENCE_ROSTER_MAXIMUM_ITEMS * 10 + 32;

pub struct PresenceCommandCursor {
    page: Option<FixedCommandPage>,
    remaining: usize,
    seq: u64,
    own_color: Option<u8>,
    next_page: u32,
}

impl PresenceCommandCursor {
    pub fn retain_rejected(page: FixedCommandPage, seq: u64) -> Self {
        Self { page: Some(page), remaining: 0, seq, own_color: None, next_page: 1 }
    }

    pub fn admit_page(seq: u64, own_color: Option<u8>, item_count: u32, page: FixedCommandPage) -> Result<Self, (crate::os_spr::ProtocolError, FixedCommandPage)> {
        if item_count as usize > PRESENCE_ROSTER_MAXIMUM_ITEMS || page.len() > PRESENCE_ROSTER_MAXIMUM_ENTRY_BYTES || (item_count != 0 && page.is_empty()) || (item_count == 0 && !page.is_empty()) {
            return Err((malformed("channel presence page", 0, "Presence page violates its exact item or 4096-byte authority"), page));
        }
        Ok(Self { page: Some(page), remaining: item_count as usize, seq, own_color, next_page: 1 })
    }

    pub fn push_page(&mut self, page_index: u32, page: FixedCommandPage) -> Result<(), (crate::os_spr::ProtocolError, FixedCommandPage)> {
        if self.page.is_some() || self.remaining == 0 || page_index != self.next_page || page.is_empty() || page.len() > PRESENCE_ROSTER_MAXIMUM_ENTRY_BYTES {
            return Err((malformed("channel presence page", page_index as u64, "page is out of order, saturated, empty, or oversized"), page));
        }
        self.page = Some(page);
        self.next_page = self.next_page.saturating_add(1);
        Ok(())
    }

    pub fn seq(&self) -> u64 {
        self.seq
    }

    pub fn own_color(&self) -> Option<u8> {
        self.own_color
    }

    pub fn take_next(&mut self) -> Result<Option<FixedCommandPage>, crate::os_spr::ProtocolError> {
        if self.remaining == 0 {
            return Ok(None);
        }
        let entry = self.page.take().ok_or_else(|| malformed("channel presence command owner", self.next_page as u64, "next page has not been admitted"))?;
        self.remaining -= 1;
        Ok(Some(entry))
    }

    pub fn next_len(&self) -> Result<Option<usize>, crate::os_spr::ProtocolError> {
        if self.remaining == 0 {
            return Ok(None);
        }
        Ok(self.page.as_ref().map(FixedCommandPage::len))
    }

    pub fn close_release(&mut self, maximum_bytes: usize) -> (bool, usize) {
        let Some(page_len) = self.page.as_ref().map(FixedCommandPage::len) else {
            return (self.remaining == 0, 0);
        };
        if page_len > maximum_bytes {
            return (false, 0);
        }
        let page = self.page.take().expect("presence page was present");
        let released = page.len();
        drop(page);
        self.remaining = 0;
        (true, released)
    }

    pub fn terminal_is_empty(&self) -> bool {
        self.page.is_none() && self.remaining == 0
    }

    pub fn waiting_for_page(&self) -> bool {
        self.page.is_none() && self.remaining != 0
    }
}
//#endregion 🔖️PresenceCommandCursor

//#region 🔖️PagedAppCommandDecode
const APP_COMMAND_FIELD_MAXIMUM_BYTES: usize = COMMAND_MAXIMUM_BYTES;

/// 🧮️ `AppCommand::PureCommand`'s seven byte fields, in `encode_app_command`'s own order: `command`,
/// then the `document`/`config`/`draft` pack+spr pairs. One field per retained decode step, so a
/// mutation's payload never costs more than one bounded read per host turn.
const PURE_COMMAND_FIELDS: usize = 7;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum DocumentArchiveDecodePhase {
    ParentPack,
    ParentSpr,
    MemberCount,
    Ordinal,
    ReferenceArtifactId,
    ReferenceKind,
    ReferenceStandard,
    ReferenceSubset,
    OwnerParentArtifactId,
    OwnerParentKind,
    OwnerParentStandard,
    OwnerParentSubset,
    OwnerSlot,
    OwnerChildId,
    EnvelopePack,
    Complete,
}

#[derive(Debug, Default)]
struct PartialDocumentArchiveMember {
    ordinal: u32,
    reference: DocumentArchiveArtifactRef,
    owner: DocumentArchiveOwnerRef,
    envelope_pack: Vec<u8>,
}

#[derive(Debug)]
struct PagedDocumentArchiveDecode {
    archive: DocumentArchivePack,
    partial: PartialDocumentArchiveMember,
    remaining: usize,
    phase: DocumentArchiveDecodePhase,
    rejected: Option<Vec<u8>>,
    closing_member: Option<OwnedDocumentMemberPackEntry>,
    close_field: u8,
}

impl PagedDocumentArchiveDecode {
    fn new() -> Self {
        Self {
            archive: DocumentArchivePack::default(),
            partial: PartialDocumentArchiveMember::default(),
            remaining: 0,
            phase: DocumentArchiveDecodePhase::ParentPack,
            rejected: None,
            closing_member: None,
            close_field: 0,
        }
    }

    fn closing(archive: DocumentArchivePack) -> Self {
        Self {
            archive,
            partial: PartialDocumentArchiveMember::default(),
            remaining: 0,
            phase: DocumentArchiveDecodePhase::Complete,
            rejected: None,
            closing_member: None,
            close_field: 0,
        }
    }

    fn read_string(&mut self, reader: &mut PagedCommandReader, label: &'static str) -> Result<String, semio_framework_diagnostic::Fault> {
        let bytes = reader.read_bounded_bytes(APP_COMMAND_FIELD_MAXIMUM_BYTES)?;
        String::from_utf8(bytes).map_err(|error| {
            self.rejected = Some(error.into_bytes());
            semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.document-archive-utf8"), label)
        })
    }

    fn step(&mut self, reader: &mut PagedCommandReader) -> Result<Option<DocumentArchivePack>, semio_framework_diagnostic::Fault> {
        if self.rejected.is_some() {
            return Err(semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.document-archive-closing"), "rejected document archive must be closed before another decode step"));
        }
        match self.phase {
            DocumentArchiveDecodePhase::ParentPack => {
                self.archive.parent_pack = reader.read_bounded_bytes(APP_COMMAND_FIELD_MAXIMUM_BYTES)?;
                self.phase = DocumentArchiveDecodePhase::ParentSpr;
            }
            DocumentArchiveDecodePhase::ParentSpr => {
                self.archive.parent_spr = reader.read_bounded_bytes(APP_COMMAND_FIELD_MAXIMUM_BYTES)?;
                self.phase = DocumentArchiveDecodePhase::MemberCount;
            }
            DocumentArchiveDecodePhase::MemberCount => {
                let count = usize::try_from(reader.read_varint()?).map_err(|_| semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.document-archive-members"), "document archive member count is not representable"))?;
                if count > DOCUMENT_ARCHIVE_MAXIMUM_MEMBERS {
                    return Err(semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.document-archive-members"), "document archive exceeds its fixed 1024-member authority"));
                }
                self.archive.members.try_reserve_exact(count).map_err(|_| semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.document-archive-allocation"), "document archive member roster could not reserve its exact bounded authority"))?;
                self.remaining = count;
                self.phase = if count == 0 { DocumentArchiveDecodePhase::Complete } else { DocumentArchiveDecodePhase::Ordinal };
            }
            DocumentArchiveDecodePhase::Ordinal => {
                self.partial.ordinal = u32::try_from(reader.read_varint()?).map_err(|_| semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.document-archive-ordinal"), "document archive member ordinal exceeds u32"))?;
                self.phase = DocumentArchiveDecodePhase::ReferenceArtifactId;
            }
            DocumentArchiveDecodePhase::ReferenceArtifactId => {
                self.partial.reference.artifact_id = self.read_string(reader, "document archive reference artifact id is not UTF-8")?;
                self.phase = DocumentArchiveDecodePhase::ReferenceKind;
            }
            DocumentArchiveDecodePhase::ReferenceKind => {
                self.partial.reference.artifact_kind = self.read_string(reader, "document archive reference kind is not UTF-8")?;
                self.phase = DocumentArchiveDecodePhase::ReferenceStandard;
            }
            DocumentArchiveDecodePhase::ReferenceStandard => {
                self.partial.reference.standard = self.read_string(reader, "document archive reference standard is not UTF-8")?;
                self.phase = DocumentArchiveDecodePhase::ReferenceSubset;
            }
            DocumentArchiveDecodePhase::ReferenceSubset => {
                self.partial.reference.subset = self.read_string(reader, "document archive reference subset is not UTF-8")?;
                self.phase = DocumentArchiveDecodePhase::OwnerParentArtifactId;
            }
            DocumentArchiveDecodePhase::OwnerParentArtifactId => {
                self.partial.owner.parent.artifact_id = self.read_string(reader, "document archive owner parent artifact id is not UTF-8")?;
                self.phase = DocumentArchiveDecodePhase::OwnerParentKind;
            }
            DocumentArchiveDecodePhase::OwnerParentKind => {
                self.partial.owner.parent.artifact_kind = self.read_string(reader, "document archive owner parent kind is not UTF-8")?;
                self.phase = DocumentArchiveDecodePhase::OwnerParentStandard;
            }
            DocumentArchiveDecodePhase::OwnerParentStandard => {
                self.partial.owner.parent.standard = self.read_string(reader, "document archive owner parent standard is not UTF-8")?;
                self.phase = DocumentArchiveDecodePhase::OwnerParentSubset;
            }
            DocumentArchiveDecodePhase::OwnerParentSubset => {
                self.partial.owner.parent.subset = self.read_string(reader, "document archive owner parent subset is not UTF-8")?;
                self.phase = DocumentArchiveDecodePhase::OwnerSlot;
            }
            DocumentArchiveDecodePhase::OwnerSlot => {
                self.partial.owner.slot = self.read_string(reader, "document archive owner slot is not UTF-8")?;
                self.phase = DocumentArchiveDecodePhase::OwnerChildId;
            }
            DocumentArchiveDecodePhase::OwnerChildId => {
                self.partial.owner.child_id = self.read_string(reader, "document archive owner child id is not UTF-8")?;
                self.phase = DocumentArchiveDecodePhase::EnvelopePack;
            }
            DocumentArchiveDecodePhase::EnvelopePack => {
                self.partial.envelope_pack = reader.read_bounded_bytes(APP_COMMAND_FIELD_MAXIMUM_BYTES)?;
                let partial = std::mem::take(&mut self.partial);
                self.archive.members.push(OwnedDocumentMemberPackEntry { ordinal: partial.ordinal, reference: partial.reference, owner: partial.owner, envelope_pack: partial.envelope_pack });
                self.remaining -= 1;
                self.phase = if self.remaining == 0 { DocumentArchiveDecodePhase::Complete } else { DocumentArchiveDecodePhase::Ordinal };
            }
            DocumentArchiveDecodePhase::Complete => return Ok(Some(std::mem::take(&mut self.archive))),
        }
        if self.phase == DocumentArchiveDecodePhase::Complete {
            Ok(Some(std::mem::take(&mut self.archive)))
        } else {
            Ok(None)
        }
    }

    fn close_string(value: &mut String, maximum_bytes: usize) -> Option<usize> {
        if value.is_empty() {
            return None;
        }
        let bytes = value.len();
        if bytes > maximum_bytes {
            return Some(0);
        }
        let value = std::mem::take(value);
        drop(value);
        Some(bytes)
    }

    fn close_bytes(value: &mut Vec<u8>, maximum_bytes: usize) -> Option<usize> {
        if value.is_empty() {
            return None;
        }
        if value.len() > maximum_bytes {
            return Some(0);
        }
        let value = std::mem::take(value);
        let bytes = value.len();
        drop(value);
        Some(bytes)
    }

    fn close_step(&mut self, maximum_bytes: usize) -> (bool, usize) {
        if let Some(bytes) = self.rejected.as_ref() {
            if bytes.len() > maximum_bytes {
                return (false, 0);
            }
            let bytes = self.rejected.take().expect("rejected archive field remains retained");
            let released = bytes.len();
            drop(bytes);
            return (false, released);
        }
        for field in [
            &mut self.partial.reference.artifact_id,
            &mut self.partial.reference.artifact_kind,
            &mut self.partial.reference.standard,
            &mut self.partial.reference.subset,
            &mut self.partial.owner.parent.artifact_id,
            &mut self.partial.owner.parent.artifact_kind,
            &mut self.partial.owner.parent.standard,
            &mut self.partial.owner.parent.subset,
            &mut self.partial.owner.slot,
            &mut self.partial.owner.child_id,
        ] {
            if let Some(released) = Self::close_string(field, maximum_bytes) {
                return (false, released);
            }
        }
        if let Some(released) = Self::close_bytes(&mut self.partial.envelope_pack, maximum_bytes) {
            return (false, released);
        }
        if self.closing_member.is_none() {
            self.closing_member = self.archive.members.pop();
            self.close_field = 0;
        }
        if let Some(entry) = self.closing_member.as_mut() {
            let field = match self.close_field {
                0 => Some(&mut entry.reference.artifact_id),
                1 => Some(&mut entry.reference.artifact_kind),
                2 => Some(&mut entry.reference.standard),
                3 => Some(&mut entry.reference.subset),
                4 => Some(&mut entry.owner.parent.artifact_id),
                5 => Some(&mut entry.owner.parent.artifact_kind),
                6 => Some(&mut entry.owner.parent.standard),
                7 => Some(&mut entry.owner.parent.subset),
                8 => Some(&mut entry.owner.slot),
                9 => Some(&mut entry.owner.child_id),
                _ => None,
            };
            if let Some(field) = field {
                match Self::close_string(field, maximum_bytes) {
                    Some(0) => return (false, 0),
                    Some(released) => {
                        self.close_field += 1;
                        return (false, released);
                    }
                    None => {}
                }
                self.close_field += 1;
                return (false, 0);
            }
            if let Some(released) = Self::close_bytes(&mut entry.envelope_pack, maximum_bytes) {
                return (false, released);
            }
            drop(self.closing_member.take());
            return (false, 0);
        }
        if let Some(released) = Self::close_bytes(&mut self.archive.parent_spr, maximum_bytes) {
            return (false, released);
        }
        if let Some(released) = Self::close_bytes(&mut self.archive.parent_pack, maximum_bytes) {
            return (false, released);
        }
        (true, 0)
    }
}

/// 🧮️ `AppCommand::TransactionPrepare`'s `prepared_ops` roster authority — the same fixed shape
/// `DOCUMENT_ARCHIVE_MAXIMUM_MEMBERS` gives an archive's member list, declared on BOTH sides
/// (`encode_app_command` refuses to write more, [`PagedRouteFieldsDecode`] refuses to admit more) so
/// a guest never reserves an unbounded op roster out of a host-supplied count.
const TRANSACTION_PREPARED_OPS_MAXIMUM: usize = 1024;

/// 🧭️ One route-specific command's flat field plan, in `encode_app_command`'s own write order:
/// how many length-prefixed fields precede the `prepared_ops` roster, whether the roster is written
/// at all, and how many fields follow it. The decoder below and the encoder above are twins — this
/// table is the ONE place their field counts are stated, so a new field on either side is a
/// one-line change on both.
const fn route_field_plan(tag: u8) -> Option<(usize, bool, usize)> {
    match tag {
        10 => Some((3, false, 0)),
        11 => Some((2, false, 0)),
        12 => Some((1, false, 0)),
        17 => Some((3, true, 3)),
        18..=21 => Some((1, false, 0)),
        _ => None,
    }
}

/// 🧾️ The retained decoder every transaction and media route shares: one bounded field read per
/// step, an exact reservation for the `prepared_ops` roster, and a close path that releases what it
/// has accumulated one field at a time. `AppCommand::Presence` is deliberately NOT here — it is
/// admitted by its own reserved `PresenceCommandCursor` ingress (one exact page per peer), which the
/// generic cursor refuses by kind before this decoder is ever reached.
#[derive(Debug)]
struct PagedRouteFieldsDecode {
    tag: u8,
    leading: usize,
    has_ops: bool,
    trailing: usize,
    fields: Vec<Vec<u8>>,
    ops: Vec<Vec<u8>>,
    ops_remaining: Option<usize>,
}

impl PagedRouteFieldsDecode {
    fn new(tag: u8, plan: (usize, bool, usize)) -> Self {
        let (leading, has_ops, trailing) = plan;
        Self { tag, leading, has_ops, trailing, fields: Vec::with_capacity(leading + trailing), ops: Vec::new(), ops_remaining: None }
    }

    fn text(fields: &mut std::vec::IntoIter<Vec<u8>>) -> Result<String, Vec<u8>> {
        let bytes = fields.next().expect("retained route field");
        String::from_utf8(bytes).map_err(std::string::FromUtf8Error::into_bytes)
    }

    fn step(&mut self, seq: u64, reader: &mut PagedCommandReader) -> Result<Option<AppCommand>, semio_framework_diagnostic::Fault> {
        if self.fields.len() < self.leading {
            self.fields.push(reader.read_bounded_bytes(APP_COMMAND_FIELD_MAXIMUM_BYTES)?);
        } else if self.has_ops && self.ops_remaining.is_none() {
            let count = usize::try_from(reader.read_varint()?).map_err(|_| semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.transaction-prepared-ops"), "transaction prepared-ops count is not representable"))?;
            if count > TRANSACTION_PREPARED_OPS_MAXIMUM {
                return Err(semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.transaction-prepared-ops"), "transaction prepare exceeds its fixed 1024 prepared-op authority"));
            }
            self.ops.try_reserve_exact(count).map_err(|_| semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.transaction-prepared-ops-allocation"), "transaction prepared-op roster could not reserve its exact bounded authority"))?;
            self.ops_remaining = Some(count);
        } else if self.ops_remaining.is_some_and(|count| self.ops.len() < count) {
            self.ops.push(reader.read_bounded_bytes(APP_COMMAND_FIELD_MAXIMUM_BYTES)?);
        } else if self.fields.len() < self.leading + self.trailing {
            self.fields.push(reader.read_bounded_bytes(APP_COMMAND_FIELD_MAXIMUM_BYTES)?);
        }
        if self.fields.len() < self.leading + self.trailing || (self.has_ops && !self.ops_remaining.is_some_and(|count| self.ops.len() == count)) {
            return Ok(None);
        }
        Ok(Some(self.finish(seq)?))
    }

    fn finish(&mut self, seq: u64) -> Result<AppCommand, semio_framework_diagnostic::Fault> {
        let ops = std::mem::take(&mut self.ops);
        let mut fields = std::mem::take(&mut self.fields).into_iter();
        let built = match self.tag {
            10 => Self::text(&mut fields).map(|port| AppCommand::MediaIn { seq, port, descriptor: fields.next().expect("retained media descriptor"), data: fields.next().expect("retained media data") }),
            11 => Self::text(&mut fields).map(|port| AppCommand::MediaOut { seq, port, request: fields.next().expect("retained media request") }),
            12 => Self::text(&mut fields).map(|port| AppCommand::MediaFingerprint { seq, port }),
            17 => Self::text(&mut fields).and_then(|txn_id| {
                let mutation_id = Self::text(&mut fields)?;
                let payload = fields.next().expect("retained transaction payload");
                let label = Self::text(&mut fields)?;
                let origin = fields.next().expect("retained transaction origin");
                Ok(AppCommand::TransactionPrepare { seq, txn_id, mutation_id, payload, prepared_ops: ops, label, origin, prepared_child_ops: fields.next().expect("retained transaction child op groups") })
            }),
            18 => Self::text(&mut fields).map(|txn_id| AppCommand::TransactionCommit { seq, txn_id }),
            19 => Self::text(&mut fields).map(|txn_id| AppCommand::TransactionRollback { seq, txn_id }),
            20 => Self::text(&mut fields).map(|group_id| AppCommand::TransactionUndo { seq, group_id }),
            21 => Self::text(&mut fields).map(|group_id| AppCommand::TransactionRedo { seq, group_id }),
            _ => unreachable!("route field plan admitted this tag exactly"),
        };
        match built {
            Ok(command) => Ok(command),
            Err(rejected) => {
                self.fields = std::iter::once(rejected).chain(fields).collect();
                Err(semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.command-field-utf8"), "route command identity is not valid UTF-8"))
            }
        }
    }

    fn close_step(&mut self, maximum_bytes: usize) -> (bool, usize) {
        for retained in [&mut self.ops, &mut self.fields] {
            if let Some(bytes) = retained.last() {
                if bytes.len() > maximum_bytes {
                    return (false, 0);
                }
                let bytes = retained.pop().expect("retained route field was present");
                let released = bytes.len();
                drop(bytes);
                return (false, released);
            }
        }
        (true, 0)
    }
}

#[derive(Debug, Default)]
struct PagedMediaExportHandleDecode {
    stage: u8,
    app_instance_id: u32,
    parent_document_id: Option<String>,
    operation_id: u64,
    base_revision: u64,
    rejected: Option<Vec<u8>>,
}

impl PagedMediaExportHandleDecode {
    fn step(&mut self, reader: &mut PagedCommandReader) -> Result<Option<MediaExportHandleWire>, semio_framework_diagnostic::Fault> {
        match self.stage {
            0 => {
                self.app_instance_id = u32::try_from(reader.read_varint()?).map_err(|_| semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.media-export-app-instance"), "media export app instance exceeds u32"))?;
                self.stage = 1;
                Ok(None)
            }
            1 => {
                let bytes = reader.read_bounded_bytes(APP_COMMAND_FIELD_MAXIMUM_BYTES)?;
                self.parent_document_id = match String::from_utf8(bytes) {
                    Ok(value) => Some(value),
                    Err(error) => {
                        self.rejected = Some(error.into_bytes());
                        return Err(semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.command-field-utf8"), "media export parent document id is not valid UTF-8"));
                    }
                };
                self.stage = 2;
                Ok(None)
            }
            2 => {
                self.operation_id = reader.read_varint()?;
                self.stage = 3;
                Ok(None)
            }
            3 => {
                self.base_revision = reader.read_varint()?;
                self.stage = 4;
                Ok(None)
            }
            4 => Ok(Some(MediaExportHandleWire {
                app_instance_id: self.app_instance_id,
                parent_document_id: self.parent_document_id.take().expect("retained media export parent document id"),
                operation_id: self.operation_id,
                base_revision: self.base_revision,
                generation: reader.read_varint()?,
            })),
            _ => unreachable!("media export handle decoder completed once"),
        }
    }

    fn close_step(&mut self, maximum_bytes: usize) -> (bool, usize) {
        if let Some(bytes) = self.rejected.as_ref() {
            if bytes.len() > maximum_bytes {
                return (false, 0);
            }
            let bytes = self.rejected.take().expect("rejected media export field");
            let released = bytes.len();
            drop(bytes);
            return (false, released);
        }
        let Some(parent_document_id) = self.parent_document_id.take() else { return (true, 0) };
        let bytes = parent_document_id.into_bytes();
        if bytes.len() > maximum_bytes {
            self.parent_document_id = Some(String::from_utf8(bytes).expect("retained media export document id remains UTF-8"));
            return (false, 0);
        }
        let released = bytes.len();
        drop(bytes);
        (false, released)
    }
}

#[derive(Debug)]
enum PagedAppCommandDecodeState {
    Header,
    ConfigCommand { seq: u64 },
    CommandPayload { seq: u64 },
    CommandView { seq: u64, command: Option<Vec<u8>> },
    CommandText { seq: u64 },
    ContextMenu { seq: u64 },
    ArtifactCommand { seq: u64 },
    LoadDocumentPack { seq: u64 },
    LoadDocumentSpr { seq: u64, pack: Option<Vec<u8>> },
    ReadDocument { seq: u64 },
    LoadConfigPack { seq: u64 },
    LoadConfigSpr { seq: u64, pack: Option<Vec<u8>> },
    ReadConfig { seq: u64 },
    ReadChildren { seq: u64 },
    ReadHistory { seq: u64 },
    ReadConflicts { seq: u64 },
    LocalInteractionQuery { seq: u64 },
    LoadWindowConfigWindowId { seq: u64 },
    LoadWindowConfigKind { seq: u64, window_id: Option<String> },
    LoadWindowConfigPack { seq: u64, window_id: Option<String>, window_kind_id: Option<String> },
    ReadWindowConfigs { seq: u64 },
    PureCommandFields { seq: u64, fields: Vec<Vec<u8>> },
    RouteFields { seq: u64, decode: PagedRouteFieldsDecode },
    ReadDocumentArchive { seq: u64 },
    ReadDocumentIdentity { seq: u64 },
    LoadDocumentArchive { seq: u64, decode: PagedDocumentArchiveDecode },
    DocumentArchiveOperation { seq: u64, kind: u8 },
    MediaExportSubmitPort { seq: u64 },
    MediaExportSubmitDocument { seq: u64, port: Option<String> },
    MediaExportSubmitRevision { seq: u64, port: Option<String>, expected_parent_document_id: Option<String> },
    MediaExportHandle { seq: u64, kind: u8, decode: PagedMediaExportHandleDecode },
    RejectedFields { fields: Vec<Vec<u8>> },
    Terminal,
    Faulted,
}

#[derive(Debug)]
pub struct PagedAppCommandDecodeCursor {
    reader: PagedCommandReader,
    state: PagedAppCommandDecodeState,
}

#[derive(Debug)]
pub struct DecodedAppCommandOwner {
    command: Option<AppCommand>,
    close_stage: u8,
    archive_close: Option<PagedDocumentArchiveDecode>,
}

impl DecodedAppCommandOwner {
    pub fn new(command: AppCommand) -> Self {
        Self { command: Some(command), close_stage: 0, archive_close: None }
    }

    pub fn take_for_dispatch(&mut self) -> Option<AppCommand> {
        self.command.take()
    }

    pub fn close_step(&mut self, maximum_bytes: usize) -> (bool, usize, usize) {
        let Some(command) = self.command.as_mut() else {
            return (true, 0, 0);
        };
        // 🔒️ `close_stage == 0` is the latch. Without it a drained archive was rebuilt from the
        // emptied `DocumentArchivePack` on the very next turn, reported terminal, was dropped, and
        // was rebuilt again — so `LoadDocumentArchive` never reached the shell release below and no
        // decoded archive owner ever became terminal.
        if self.archive_close.is_none() && self.close_stage == 0 {
            if let AppCommand::LoadDocumentArchive { archive, .. } = command {
                self.archive_close = Some(PagedDocumentArchiveDecode::closing(std::mem::take(archive)));
            }
        }
        if let Some(archive) = self.archive_close.as_mut() {
            let (empty, released) = archive.close_step(maximum_bytes);
            if !empty || released != 0 {
                return (false, usize::from(released != 0), released);
            }
            drop(self.archive_close.take());
            self.close_stage = self.close_stage.saturating_add(1);
            return (false, 1, 0);
        }
        // 🧾️ A prepared-op roster is a LIST, not a fixed field slot, so it drains before the flat
        // stages below rather than inside them — one op per step, and an op too large for this
        // step's grant stays retained instead of being released unbounded.
        if let AppCommand::TransactionPrepare { prepared_ops, .. } = command {
            if let Some(op) = prepared_ops.last() {
                if op.len() > maximum_bytes {
                    return (false, 0, 0);
                }
                let op = prepared_ops.pop().expect("retained prepared op was present");
                let released = op.len();
                drop(op);
                return (false, 1, released);
            }
        }
        let field = match (self.close_stage, command) {
            (0, AppCommand::ConfigCommand { command, .. }) | (0, AppCommand::ContextMenu { request: command, .. }) | (0, AppCommand::ArtifactCommand { command, .. }) | (0, AppCommand::Command { command, .. }) => Some(std::mem::take(command)),
            (0, AppCommand::CommandText { line, .. }) => Some(std::mem::take(line).into_bytes()),
            (0, AppCommand::LoadDocument { pack, .. }) | (0, AppCommand::LoadConfig { pack, .. }) => Some(std::mem::take(pack)),
            (0, AppCommand::LoadWindowConfig { entry, .. }) => Some(std::mem::take(&mut entry.window_id).into_bytes()),
            (1, AppCommand::Command { view_state, .. }) => Some(std::mem::take(view_state)),
            (1, AppCommand::LoadDocument { spr, .. }) | (1, AppCommand::LoadConfig { spr, .. }) => Some(std::mem::take(spr)),
            (1, AppCommand::LoadWindowConfig { entry, .. }) => Some(std::mem::take(&mut entry.window_kind_id).into_bytes()),
            (2, AppCommand::LoadWindowConfig { entry, .. }) => Some(std::mem::take(&mut entry.envelope_pack)),
            (0, AppCommand::MediaIn { data, .. }) => Some(std::mem::take(data)),
            (1, AppCommand::MediaIn { descriptor, .. }) => Some(std::mem::take(descriptor)),
            (2, AppCommand::MediaIn { port, .. }) => Some(std::mem::take(port).into_bytes()),
            (0, AppCommand::MediaOut { request, .. }) => Some(std::mem::take(request)),
            (1, AppCommand::MediaOut { port, .. }) | (0, AppCommand::MediaFingerprint { port, .. }) => Some(std::mem::take(port).into_bytes()),
            (0, AppCommand::TransactionPrepare { payload, .. }) => Some(std::mem::take(payload)),
            (1, AppCommand::TransactionPrepare { origin, .. }) => Some(std::mem::take(origin)),
            (2, AppCommand::TransactionPrepare { txn_id, .. }) => Some(std::mem::take(txn_id).into_bytes()),
            (3, AppCommand::TransactionPrepare { mutation_id, .. }) => Some(std::mem::take(mutation_id).into_bytes()),
            (4, AppCommand::TransactionPrepare { label, .. }) => Some(std::mem::take(label).into_bytes()),
            (5, AppCommand::TransactionPrepare { prepared_child_ops, .. }) => Some(std::mem::take(prepared_child_ops)),
            (0, AppCommand::TransactionCommit { txn_id, .. }) | (0, AppCommand::TransactionRollback { txn_id, .. }) => Some(std::mem::take(txn_id).into_bytes()),
            (0, AppCommand::TransactionUndo { group_id, .. }) | (0, AppCommand::TransactionRedo { group_id, .. }) => Some(std::mem::take(group_id).into_bytes()),
            (0, AppCommand::SubmitMediaExport { port, .. }) => Some(std::mem::take(port).into_bytes()),
            (1, AppCommand::SubmitMediaExport { expected_parent_document_id, .. }) => Some(std::mem::take(expected_parent_document_id).into_bytes()),
            (0, AppCommand::PollMediaExport { handle, .. }) | (0, AppCommand::CancelMediaExport { handle, .. }) | (0, AppCommand::TakeMediaExportChunk { handle, .. }) => Some(std::mem::take(&mut handle.parent_document_id).into_bytes()),
            _ => None,
        };
        if let Some(field) = field {
            if field.len() > maximum_bytes {
                match (self.close_stage, self.command.as_mut().expect("decoded command owner was present")) {
                    (0, AppCommand::ConfigCommand { command, .. }) | (0, AppCommand::ContextMenu { request: command, .. }) | (0, AppCommand::ArtifactCommand { command, .. }) | (0, AppCommand::Command { command, .. }) => *command = field,
                    (0, AppCommand::CommandText { line, .. }) => *line = String::from_utf8(field).expect("decoded command text remains valid UTF-8"),
                    (0, AppCommand::LoadDocument { pack, .. }) | (0, AppCommand::LoadConfig { pack, .. }) => *pack = field,
                    (0, AppCommand::LoadWindowConfig { entry, .. }) => entry.window_id = String::from_utf8(field).expect("decoded window id remains valid UTF-8"),
                    (1, AppCommand::Command { view_state, .. }) => *view_state = field,
                    (1, AppCommand::LoadDocument { spr, .. }) | (1, AppCommand::LoadConfig { spr, .. }) => *spr = field,
                    (1, AppCommand::LoadWindowConfig { entry, .. }) => entry.window_kind_id = String::from_utf8(field).expect("decoded window kind id remains valid UTF-8"),
                    (2, AppCommand::LoadWindowConfig { entry, .. }) => entry.envelope_pack = field,
                    (0, AppCommand::MediaIn { data, .. }) => *data = field,
                    (1, AppCommand::MediaIn { descriptor, .. }) => *descriptor = field,
                    (2, AppCommand::MediaIn { port, .. }) => *port = String::from_utf8(field).expect("decoded media port remains valid UTF-8"),
                    (0, AppCommand::MediaOut { request, .. }) => *request = field,
                    (1, AppCommand::MediaOut { port, .. }) | (0, AppCommand::MediaFingerprint { port, .. }) => *port = String::from_utf8(field).expect("decoded media port remains valid UTF-8"),
                    (0, AppCommand::TransactionPrepare { payload, .. }) => *payload = field,
                    (1, AppCommand::TransactionPrepare { origin, .. }) => *origin = field,
                    (2, AppCommand::TransactionPrepare { txn_id, .. }) => *txn_id = String::from_utf8(field).expect("decoded transaction id remains valid UTF-8"),
                    (3, AppCommand::TransactionPrepare { mutation_id, .. }) => *mutation_id = String::from_utf8(field).expect("decoded mutation id remains valid UTF-8"),
                    (4, AppCommand::TransactionPrepare { label, .. }) => *label = String::from_utf8(field).expect("decoded transaction label remains valid UTF-8"),
                    (5, AppCommand::TransactionPrepare { prepared_child_ops, .. }) => *prepared_child_ops = field,
                    (0, AppCommand::TransactionCommit { txn_id, .. }) | (0, AppCommand::TransactionRollback { txn_id, .. }) => *txn_id = String::from_utf8(field).expect("decoded transaction id remains valid UTF-8"),
                    (0, AppCommand::TransactionUndo { group_id, .. }) | (0, AppCommand::TransactionRedo { group_id, .. }) => *group_id = String::from_utf8(field).expect("decoded transaction group id remains valid UTF-8"),
                    (0, AppCommand::SubmitMediaExport { port, .. }) => *port = String::from_utf8(field).expect("decoded media export port remains valid UTF-8"),
                    (1, AppCommand::SubmitMediaExport { expected_parent_document_id, .. }) => *expected_parent_document_id = String::from_utf8(field).expect("decoded media export parent document id remains valid UTF-8"),
                    (0, AppCommand::PollMediaExport { handle, .. }) | (0, AppCommand::CancelMediaExport { handle, .. }) | (0, AppCommand::TakeMediaExportChunk { handle, .. }) => handle.parent_document_id = String::from_utf8(field).expect("decoded media export parent document id remains valid UTF-8"),
                    _ => unreachable!("decoded command close field has an exact restoration target"),
                }
                return (false, 0, 0);
            }
            let released = field.len();
            drop(field);
            self.close_stage = self.close_stage.saturating_add(1);
            return (false, 1, released);
        }
        let command = self.command.take().expect("decoded command shell was present");
        drop(command);
        (true, 1, 0)
    }

    pub fn terminal_is_empty(&self) -> bool {
        self.command.is_none()
    }
}

/// 🧭️ Which page index an ingress cursor is expected to carry — see `validate_cursor`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum CursorShape {
    Page,
    Terminal,
    Fault,
}

impl PagedAppCommandDecodeCursor {
    pub fn new(command: PagedCommand) -> Self {
        Self { reader: PagedCommandReader::new(command), state: PagedAppCommandDecodeState::Header }
    }

    pub fn kind(&self) -> u8 {
        self.reader.kind()
    }

    pub fn step(&mut self) -> Result<Option<AppCommand>, semio_framework_diagnostic::Fault> {
        let state = std::mem::replace(&mut self.state, PagedAppCommandDecodeState::Faulted);
        let outcome = match state {
            PagedAppCommandDecodeState::Header => {
                let tag = self.reader.read_byte()?;
                let seq = self.reader.read_varint()?;
                self.state = match tag {
                    0 => PagedAppCommandDecodeState::ConfigCommand { seq },
                    1 => PagedAppCommandDecodeState::CommandPayload { seq },
                    2 => PagedAppCommandDecodeState::CommandText { seq },
                    3 => PagedAppCommandDecodeState::ContextMenu { seq },
                    4 => PagedAppCommandDecodeState::ArtifactCommand { seq },
                    6 => PagedAppCommandDecodeState::LoadDocumentPack { seq },
                    7 => PagedAppCommandDecodeState::ReadDocument { seq },
                    8 => PagedAppCommandDecodeState::LoadConfigPack { seq },
                    9 => PagedAppCommandDecodeState::ReadConfig { seq },
                    13 => PagedAppCommandDecodeState::PureCommandFields { seq, fields: Vec::with_capacity(PURE_COMMAND_FIELDS) },
                    15 => PagedAppCommandDecodeState::ReadChildren { seq },
                    16 => PagedAppCommandDecodeState::ReadHistory { seq },
                    27 => PagedAppCommandDecodeState::ReadConflicts { seq },
                    29 => PagedAppCommandDecodeState::LocalInteractionQuery { seq },
                    30 => PagedAppCommandDecodeState::LoadWindowConfigWindowId { seq },
                    31 => PagedAppCommandDecodeState::ReadWindowConfigs { seq },
                    32 => PagedAppCommandDecodeState::LoadDocumentArchive { seq, decode: PagedDocumentArchiveDecode::new() },
                    33 => PagedAppCommandDecodeState::ReadDocumentArchive { seq },
                    41 => PagedAppCommandDecodeState::ReadDocumentIdentity { seq },
                    34..=36 => PagedAppCommandDecodeState::DocumentArchiveOperation { seq, kind: tag },
                    37 => PagedAppCommandDecodeState::MediaExportSubmitPort { seq },
                    38..=40 => PagedAppCommandDecodeState::MediaExportHandle { seq, kind: tag, decode: PagedMediaExportHandleDecode::default() },
                    tag if route_field_plan(tag).is_some() => {
                        PagedAppCommandDecodeState::RouteFields { seq, decode: PagedRouteFieldsDecode::new(tag, route_field_plan(tag).expect("route field plan was just matched")) }
                    }
                    _ => {
                        return Err(semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.command-route-state-machine-required"), "this AppCommand kind requires its route-specific retained decoder before admission"));
                    }
                };
                None
            }
            PagedAppCommandDecodeState::ConfigCommand { seq } => {
                let command = self.reader.read_bounded_bytes(APP_COMMAND_FIELD_MAXIMUM_BYTES)?;
                Some(AppCommand::ConfigCommand { seq, command })
            }
            PagedAppCommandDecodeState::CommandPayload { seq } => {
                let command = self.reader.read_bounded_bytes(APP_COMMAND_FIELD_MAXIMUM_BYTES)?;
                self.state = PagedAppCommandDecodeState::CommandView { seq, command: Some(command) };
                None
            }
            PagedAppCommandDecodeState::CommandView { seq, mut command } => {
                let view_state = match self.reader.read_bounded_bytes(APP_COMMAND_FIELD_MAXIMUM_BYTES) {
                    Ok(view_state) => view_state,
                    Err(fault) => {
                        self.state = PagedAppCommandDecodeState::CommandView { seq, command };
                        return Err(fault);
                    }
                };
                Some(AppCommand::Command { seq, command: command.take().expect("retained command payload"), view_state })
            }
            PagedAppCommandDecodeState::CommandText { seq } => {
                let bytes = self.reader.read_bounded_bytes(APP_COMMAND_FIELD_MAXIMUM_BYTES)?;
                let line = match String::from_utf8(bytes) {
                    Ok(line) => line,
                    Err(error) => {
                        self.state = PagedAppCommandDecodeState::RejectedFields { fields: vec![error.into_bytes()] };
                        return Err(semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.command-field-utf8"), "paged command text is not valid UTF-8"));
                    }
                };
                Some(AppCommand::CommandText { seq, line })
            }
            PagedAppCommandDecodeState::ContextMenu { seq } => {
                let request = self.reader.read_bounded_bytes(APP_COMMAND_FIELD_MAXIMUM_BYTES)?;
                Some(AppCommand::ContextMenu { seq, request })
            }
            PagedAppCommandDecodeState::ArtifactCommand { seq } => {
                let command = self.reader.read_bounded_bytes(APP_COMMAND_FIELD_MAXIMUM_BYTES)?;
                Some(AppCommand::ArtifactCommand { seq, command })
            }
            PagedAppCommandDecodeState::LoadDocumentPack { seq } => {
                let pack = self.reader.read_bounded_bytes(APP_COMMAND_FIELD_MAXIMUM_BYTES)?;
                self.state = PagedAppCommandDecodeState::LoadDocumentSpr { seq, pack: Some(pack) };
                None
            }
            PagedAppCommandDecodeState::LoadDocumentSpr { seq, mut pack } => {
                let spr = match self.reader.read_bounded_bytes(APP_COMMAND_FIELD_MAXIMUM_BYTES) {
                    Ok(spr) => spr,
                    Err(fault) => {
                        self.state = PagedAppCommandDecodeState::LoadDocumentSpr { seq, pack };
                        return Err(fault);
                    }
                };
                Some(AppCommand::LoadDocument { seq, pack: pack.take().expect("retained document pack"), spr })
            }
            PagedAppCommandDecodeState::ReadDocument { seq } => Some(AppCommand::ReadDocument { seq }),
            PagedAppCommandDecodeState::LoadConfigPack { seq } => {
                let pack = self.reader.read_bounded_bytes(APP_COMMAND_FIELD_MAXIMUM_BYTES)?;
                self.state = PagedAppCommandDecodeState::LoadConfigSpr { seq, pack: Some(pack) };
                None
            }
            PagedAppCommandDecodeState::LoadConfigSpr { seq, mut pack } => {
                let spr = match self.reader.read_bounded_bytes(APP_COMMAND_FIELD_MAXIMUM_BYTES) {
                    Ok(spr) => spr,
                    Err(fault) => {
                        self.state = PagedAppCommandDecodeState::LoadConfigSpr { seq, pack };
                        return Err(fault);
                    }
                };
                Some(AppCommand::LoadConfig { seq, pack: pack.take().expect("retained config pack"), spr })
            }
            PagedAppCommandDecodeState::ReadConfig { seq } => Some(AppCommand::ReadConfig { seq }),
            PagedAppCommandDecodeState::ReadChildren { seq } => Some(AppCommand::ReadChildren { seq }),
            PagedAppCommandDecodeState::ReadHistory { seq } => Some(AppCommand::ReadHistory { seq }),
            PagedAppCommandDecodeState::ReadConflicts { seq } => Some(AppCommand::ReadConflicts { seq }),
            PagedAppCommandDecodeState::ReadDocumentIdentity { seq } => Some(AppCommand::ReadDocumentIdentity { seq }),
            PagedAppCommandDecodeState::LocalInteractionQuery { seq } => {
                let bytes = self.reader.read_bounded_bytes(142)?;
                let command = protocol::decode_local_interaction_query_command(&bytes).map_err(|reason| semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("local-interaction.command-wire"), reason))?;
                Some(AppCommand::LocalInteractionQuery { seq, command })
            }
            PagedAppCommandDecodeState::LoadWindowConfigWindowId { seq } => {
                let bytes = self.reader.read_bounded_bytes(APP_COMMAND_FIELD_MAXIMUM_BYTES)?;
                let window_id = match String::from_utf8(bytes) {
                    Ok(window_id) => window_id,
                    Err(error) => {
                        self.state = PagedAppCommandDecodeState::RejectedFields { fields: vec![error.into_bytes()] };
                        return Err(semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.command-field-utf8"), "window config window id is not valid UTF-8"));
                    }
                };
                self.state = PagedAppCommandDecodeState::LoadWindowConfigKind { seq, window_id: Some(window_id) };
                None
            }
            PagedAppCommandDecodeState::LoadWindowConfigKind { seq, mut window_id } => {
                let bytes = match self.reader.read_bounded_bytes(APP_COMMAND_FIELD_MAXIMUM_BYTES) {
                    Ok(bytes) => bytes,
                    Err(fault) => {
                        self.state = PagedAppCommandDecodeState::LoadWindowConfigKind { seq, window_id };
                        return Err(fault);
                    }
                };
                let window_kind_id = match String::from_utf8(bytes) {
                    Ok(window_kind_id) => window_kind_id,
                    Err(error) => {
                        self.state = PagedAppCommandDecodeState::RejectedFields {
                            fields: vec![window_id.take().expect("retained window id").into_bytes(), error.into_bytes()],
                        };
                        return Err(semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.command-field-utf8"), "window config kind id is not valid UTF-8"));
                    }
                };
                self.state = PagedAppCommandDecodeState::LoadWindowConfigPack { seq, window_id, window_kind_id: Some(window_kind_id) };
                None
            }
            PagedAppCommandDecodeState::LoadWindowConfigPack { seq, mut window_id, mut window_kind_id } => {
                let envelope_pack = match self.reader.read_bounded_bytes(APP_COMMAND_FIELD_MAXIMUM_BYTES) {
                    Ok(envelope_pack) => envelope_pack,
                    Err(fault) => {
                        self.state = PagedAppCommandDecodeState::LoadWindowConfigPack { seq, window_id, window_kind_id };
                        return Err(fault);
                    }
                };
                Some(AppCommand::LoadWindowConfig {
                    seq,
                    entry: WindowConfigPackEntry {
                        window_id: window_id.take().expect("retained window id"),
                        window_kind_id: window_kind_id.take().expect("retained window kind id"),
                        envelope_pack,
                    },
                })
            }
            PagedAppCommandDecodeState::ReadWindowConfigs { seq } => Some(AppCommand::ReadWindowConfigs { seq }),
            PagedAppCommandDecodeState::PureCommandFields { seq, mut fields } => {
                let field = match self.reader.read_bounded_bytes(APP_COMMAND_FIELD_MAXIMUM_BYTES) {
                    Ok(field) => field,
                    Err(fault) => {
                        self.state = PagedAppCommandDecodeState::PureCommandFields { seq, fields };
                        return Err(fault);
                    }
                };
                fields.push(field);
                if fields.len() < PURE_COMMAND_FIELDS {
                    self.state = PagedAppCommandDecodeState::PureCommandFields { seq, fields };
                    return Ok(None);
                }
                let mut fields = fields.into_iter();
                let mut next = || fields.next().expect("retained pure-command field");
                Some(AppCommand::PureCommand { seq, command: next(), document: next(), document_spr: next(), config: next(), config_spr: next(), draft: next(), draft_spr: next() })
            }
            PagedAppCommandDecodeState::RouteFields { seq, mut decode } => match decode.step(seq, &mut self.reader) {
                Ok(Some(command)) => Some(command),
                Ok(None) => {
                    self.state = PagedAppCommandDecodeState::RouteFields { seq, decode };
                    None
                }
                Err(fault) => {
                    self.state = PagedAppCommandDecodeState::RouteFields { seq, decode };
                    return Err(fault);
                }
            },
            PagedAppCommandDecodeState::ReadDocumentArchive { seq } =>Some(AppCommand::ReadDocumentArchive { seq }),
            PagedAppCommandDecodeState::LoadDocumentArchive { seq, mut decode } => match decode.step(&mut self.reader) {
                Ok(Some(archive)) => Some(AppCommand::LoadDocumentArchive { seq, archive }),
                Ok(None) => {
                    self.state = PagedAppCommandDecodeState::LoadDocumentArchive { seq, decode };
                    None
                }
                Err(fault) => {
                    self.state = PagedAppCommandDecodeState::LoadDocumentArchive { seq, decode };
                    return Err(fault);
                }
            },
            PagedAppCommandDecodeState::DocumentArchiveOperation { seq, kind } => {
                let operation = self.reader.read_varint()?;
                Some(match kind {
                    34 => AppCommand::PollDocumentArchiveLoad { seq, operation },
                    35 => AppCommand::CancelDocumentArchiveLoad { seq, operation },
                    36 => AppCommand::AcknowledgeDocumentArchiveLoad { seq, operation },
                    _ => unreachable!("archive operation command tag was admitted exactly"),
                })
            }
            PagedAppCommandDecodeState::MediaExportSubmitPort { seq } => {
                let bytes = self.reader.read_bounded_bytes(APP_COMMAND_FIELD_MAXIMUM_BYTES)?;
                let port = match String::from_utf8(bytes) {
                    Ok(value) => value,
                    Err(error) => {
                        self.state = PagedAppCommandDecodeState::RejectedFields { fields: vec![error.into_bytes()] };
                        return Err(semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.command-field-utf8"), "media export port is not valid UTF-8"));
                    }
                };
                self.state = PagedAppCommandDecodeState::MediaExportSubmitDocument { seq, port: Some(port) };
                None
            }
            PagedAppCommandDecodeState::MediaExportSubmitDocument { seq, mut port } => {
                let bytes = match self.reader.read_bounded_bytes(APP_COMMAND_FIELD_MAXIMUM_BYTES) {
                    Ok(bytes) => bytes,
                    Err(fault) => {
                        self.state = PagedAppCommandDecodeState::MediaExportSubmitDocument { seq, port };
                        return Err(fault);
                    }
                };
                let expected_parent_document_id = match String::from_utf8(bytes) {
                    Ok(value) => value,
                    Err(error) => {
                        self.state = PagedAppCommandDecodeState::RejectedFields { fields: vec![port.take().expect("retained media export port").into_bytes(), error.into_bytes()] };
                        return Err(semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.command-field-utf8"), "media export parent document id is not valid UTF-8"));
                    }
                };
                self.state = PagedAppCommandDecodeState::MediaExportSubmitRevision { seq, port, expected_parent_document_id: Some(expected_parent_document_id) };
                None
            }
            PagedAppCommandDecodeState::MediaExportSubmitRevision { seq, mut port, mut expected_parent_document_id } => Some(AppCommand::SubmitMediaExport {
                seq,
                port: port.take().expect("retained media export port"),
                expected_parent_document_id: expected_parent_document_id.take().expect("retained media export parent document id"),
                expected_base_revision: self.reader.read_varint()?,
            }),
            PagedAppCommandDecodeState::MediaExportHandle { seq, kind, mut decode } => match decode.step(&mut self.reader) {
                Ok(Some(handle)) => Some(match kind {
                    38 => AppCommand::PollMediaExport { seq, handle },
                    39 => AppCommand::CancelMediaExport { seq, handle },
                    40 => AppCommand::TakeMediaExportChunk { seq, handle },
                    _ => unreachable!("media export operation tag was admitted exactly"),
                }),
                Ok(None) => {
                    self.state = PagedAppCommandDecodeState::MediaExportHandle { seq, kind, decode };
                    None
                }
                Err(fault) => {
                    self.state = PagedAppCommandDecodeState::MediaExportHandle { seq, kind, decode };
                    return Err(fault);
                }
            },
            PagedAppCommandDecodeState::RejectedFields { fields } => {
                self.state = PagedAppCommandDecodeState::RejectedFields { fields };
                return Err(semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.command-decode-closing"), "rejected paged command must be closed before it can be stepped again"));
            }
            PagedAppCommandDecodeState::Terminal | PagedAppCommandDecodeState::Faulted => {
                return Err(semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.command-decode-terminal"), "paged command decoder was stepped after terminal"));
            }
        };
        if let Some(command) = outcome {
            if !self.reader.terminal_is_empty() {
                let fields = match command {
                    AppCommand::ConfigCommand { command, .. } | AppCommand::ContextMenu { request: command, .. } | AppCommand::ArtifactCommand { command, .. } => vec![command],
                    AppCommand::Command { command, view_state, .. } => vec![command, view_state],
                    AppCommand::CommandText { line, .. } => vec![line.into_bytes()],
                    AppCommand::LoadDocument { pack, spr, .. } | AppCommand::LoadConfig { pack, spr, .. } => vec![pack, spr],
                    AppCommand::LoadWindowConfig { entry, .. } => vec![entry.window_id.into_bytes(), entry.window_kind_id.into_bytes(), entry.envelope_pack],
                    AppCommand::ReadDocument { .. }
                    | AppCommand::ReadConfig { .. }
                    | AppCommand::ReadChildren { .. }
                    | AppCommand::ReadHistory { .. }
                    | AppCommand::ReadConflicts { .. }
                    | AppCommand::LocalInteractionQuery { .. }
                    | AppCommand::ReadDocumentIdentity { .. }
                    | AppCommand::ReadWindowConfigs { .. }
                    | AppCommand::PollDocumentArchiveLoad { .. }
                    | AppCommand::CancelDocumentArchiveLoad { .. }
                    | AppCommand::AcknowledgeDocumentArchiveLoad { .. } => Vec::new(),
                    AppCommand::ReadDocumentArchive { .. } => Vec::new(),
                    AppCommand::LoadDocumentArchive { archive, .. } => document_archive_into_fields(archive),
                    AppCommand::MediaIn { port, descriptor, data, .. } => vec![port.into_bytes(), descriptor, data],
                    AppCommand::MediaOut { port, request, .. } => vec![port.into_bytes(), request],
                    AppCommand::MediaFingerprint { port, .. } => vec![port.into_bytes()],
                    AppCommand::TransactionPrepare { txn_id, mutation_id, payload, prepared_ops, label, origin, prepared_child_ops, .. } => {
                        let mut fields = vec![txn_id.into_bytes(), mutation_id.into_bytes(), payload, label.into_bytes(), origin, prepared_child_ops];
                        fields.extend(prepared_ops);
                        fields
                    }
                    AppCommand::TransactionCommit { txn_id, .. } | AppCommand::TransactionRollback { txn_id, .. } => vec![txn_id.into_bytes()],
                    AppCommand::TransactionUndo { group_id, .. } | AppCommand::TransactionRedo { group_id, .. } => vec![group_id.into_bytes()],
                    AppCommand::SubmitMediaExport { port, expected_parent_document_id, .. } => vec![port.into_bytes(), expected_parent_document_id.into_bytes()],
                    AppCommand::PollMediaExport { handle, .. } | AppCommand::CancelMediaExport { handle, .. } | AppCommand::TakeMediaExportChunk { handle, .. } => vec![handle.parent_document_id.into_bytes()],
                    AppCommand::Presence { .. } => unreachable!("Presence is never decoded by the generic paged cursor"),
                    _ => unreachable!("route-specific AppCommand is never decoded by the generic paged cursor"),
                };
                self.state = PagedAppCommandDecodeState::RejectedFields { fields };
                return Err(semio_framework_diagnostic::Fault::new(semio_framework_diagnostic::FaultOrigin::Framework, semio_framework_diagnostic::FaultCode::new("plugin.command-decode-trailing"), "paged command carries trailing bytes after its terminal field"));
            }
            self.state = PagedAppCommandDecodeState::Terminal;
            Ok(Some(command))
        } else {
            Ok(None)
        }
    }

    pub fn close_step(&mut self, maximum_bytes: usize) -> (bool, usize) {
        if let PagedAppCommandDecodeState::LoadDocumentArchive { decode, .. } = &mut self.state {
            let (empty, released) = decode.close_step(maximum_bytes);
            if !empty || released != 0 {
                return (false, released);
            }
        }
        if let PagedAppCommandDecodeState::RouteFields { decode, .. } = &mut self.state {
            let (empty, released) = decode.close_step(maximum_bytes);
            if !empty || released != 0 {
                return (false, released);
            }
        }
        if let PagedAppCommandDecodeState::MediaExportHandle { decode, .. } = &mut self.state {
            let (empty, released) = decode.close_step(maximum_bytes);
            if !empty || released != 0 {
                return (false, released);
            }
        }
        if let PagedAppCommandDecodeState::CommandView { command, .. } = &mut self.state {
            if let Some(bytes) = command.as_ref() {
                if bytes.len() > maximum_bytes {
                    return (false, 0);
                }
                let bytes = command.take().expect("retained command payload");
                let released = bytes.len();
                drop(bytes);
                return (false, released);
            }
        }
        if let Some(retained) = match &mut self.state {
            PagedAppCommandDecodeState::LoadDocumentSpr { pack, .. } | PagedAppCommandDecodeState::LoadConfigSpr { pack, .. } => Some(pack),
            _ => None,
        } {
            if let Some(bytes) = retained.as_ref() {
                if bytes.len() > maximum_bytes {
                    return (false, 0);
                }
                let bytes = retained.take().expect("retained pack was present");
                let released = bytes.len();
                drop(bytes);
                return (false, released);
            }
        }
        if let PagedAppCommandDecodeState::LoadWindowConfigKind { window_id, .. } = &mut self.state {
            if let Some(text) = window_id.take() {
                let bytes = text.into_bytes();
                if bytes.len() > maximum_bytes {
                    *window_id = Some(String::from_utf8(bytes).expect("retained window config identity remains valid UTF-8"));
                    return (false, 0);
                }
                let released = bytes.len();
                drop(bytes);
                return (false, released);
            }
        }
        if let PagedAppCommandDecodeState::LoadWindowConfigPack { window_id, window_kind_id, .. } = &mut self.state {
            let retained = if window_id.is_some() { window_id } else { window_kind_id };
            if let Some(text) = retained.take() {
                let bytes = text.into_bytes();
                if bytes.len() > maximum_bytes {
                    *retained = Some(String::from_utf8(bytes).expect("retained window config identity remains valid UTF-8"));
                    return (false, 0);
                }
                let released = bytes.len();
                drop(bytes);
                return (false, released);
            }
        }
        if let Some(retained) = match &mut self.state {
            PagedAppCommandDecodeState::MediaExportSubmitDocument { port, .. } => Some(port),
            PagedAppCommandDecodeState::MediaExportSubmitRevision { port, expected_parent_document_id, .. } => Some(if port.is_some() { port } else { expected_parent_document_id }),
            _ => None,
        } {
            if let Some(text) = retained.take() {
                let bytes = text.into_bytes();
                if bytes.len() > maximum_bytes {
                    *retained = Some(String::from_utf8(bytes).expect("retained media export identity remains valid UTF-8"));
                    return (false, 0);
                }
                let released = bytes.len();
                drop(bytes);
                return (false, released);
            }
        }
        if let PagedAppCommandDecodeState::RejectedFields { fields } = &mut self.state {
            if let Some(bytes) = fields.last() {
                if bytes.len() > maximum_bytes {
                    return (false, 0);
                }
            }
            if let Some(bytes) = fields.pop() {
                let released = bytes.len();
                drop(bytes);
                return (false, released);
            }
        }
        let (empty, released) = self.reader.close_step(maximum_bytes);
        if empty {
            self.state = PagedAppCommandDecodeState::Terminal;
        }
        (empty, released)
    }

    pub fn terminal_is_empty(&self) -> bool {
        matches!(self.state, PagedAppCommandDecodeState::Terminal) && self.reader.terminal_is_empty()
    }
}
//#endregion 🔖️PagedAppCommandDecode

//#region 🔖️AppCommand
/// 📨️ One frame a client (UI or headless runner) sends to the app engine.
#[derive(Debug, PartialEq)]
#[expect(clippy::large_enum_variant, reason = "Presence commands transfer the admitted fixed roster slots inline without another channel allocation.")]
pub enum AppCommand {
    ConfigCommand {
        seq: u64,
        command: Vec<u8>,
    },
    Command {
        seq: u64,
        command: Vec<u8>,
        /// 🗣️ Packed `ViewModel` (see `crate::os_store::pack_rt`) the client wants this command evaluated against.
        view_state: Vec<u8>,
    },
    CommandText {
        seq: u64,
        line: String,
    },
    ContextMenu {
        seq: u64,
        request: Vec<u8>,
    },
    ArtifactCommand {
        seq: u64,
        command: Vec<u8>,
    },
    ApplyEnvelopes {
        seq: u64,
        envelopes: Vec<crate::os_spr::causal::MutationEnvelope>,
    },
    LoadDocument {
        seq: u64,
        pack: Vec<u8>,
        spr: Vec<u8>,
    },
    ReadDocument {
        seq: u64,
    },
    LoadConfig {
        seq: u64,
        pack: Vec<u8>,
        spr: Vec<u8>,
    },
    ReadConfig {
        seq: u64,
    },
    /// 🪟️ Restores one exact concrete window's persisted-local config envelope.
    LoadWindowConfig {
        seq: u64,
        entry: WindowConfigPackEntry,
    },
    /// 🪟️ Reads every exact concrete window config envelope owned by this app instance.
    ReadWindowConfigs {
        seq: u64,
    },
    MediaIn {
        seq: u64,
        port: String,
        descriptor: Vec<u8>,
        data: Vec<u8>,
    },
    MediaOut {
        seq: u64,
        port: String,
        request: Vec<u8>,
    },
    MediaFingerprint {
        seq: u64,
        port: String,
    },
    /// 🧾 Host-authoritative command: document/config/draft packs travel with the command; guest
    /// returns `AppFrame::Emit` ops only (host applies). CHANNEL_VERSION 5 wire addition.
    PureCommand {
        seq: u64,
        command: Vec<u8>,
        document: Vec<u8>,
        document_spr: Vec<u8>,
        config: Vec<u8>,
        config_spr: Vec<u8>,
        draft: Vec<u8>,
        draft_spr: Vec<u8>,
    },
    /// 🧸️ Restores a composing document's owned children into the engine, each as its own live
    /// store. Sent after `LoadDocument` (the parent must exist before its children can be adopted).
    /// CHANNEL_VERSION 6 wire addition.
    LoadChildren {
        seq: u64,
        entries: Vec<ChildPackEntry>,
    },
    /// 🧸️ Asks the engine for every owned child's current envelope, for persistence — the child-side
    /// counterpart of `ReadDocument`. CHANNEL_VERSION 6 wire addition.
    ReadChildren {
        seq: u64,
    },
    /// 🧾️ Reads a complete history projection after initial connection or cursor resynchronization.
    ReadHistory {
        seq: u64,
    },
    /// 🤝️ Phase-1 prepare for one transaction member — flat fields carry EITHER the owner-mutation
    /// form (`mutation_id`+`payload` set, `prepared_ops` empty) OR the pre-planned form
    /// (`prepared_ops`+`label`+`origin` set, `mutation_id` empty); see contract-freeze.md §2 of
    /// `.🧬semio/🦑️repo/🎫️tickets/🎆️26/🌙️08/☀️16/PLUGIN-DEPENDENCIES-ARTIFACT-CONTRIBUTIONS-AND-COMPOSITE-MUTATIONS/`.
    /// CHANNEL_VERSION 9 wire addition.
    TransactionPrepare {
        seq: u64,
        txn_id: String,
        mutation_id: String,
        payload: Vec<u8>,
        prepared_ops: Vec<Vec<u8>>,
        label: String,
        origin: Vec<u8>,
        /// 🧩️ The pre-planned form's owned-child op groups (CHANNEL_VERSION 18 trailing addition): the composing
        /// guest's own `ChildEmit` list as one wire pack, exactly as its `AppFrame::Emit.child_ops` preview produced
        /// it; empty when the gesture touches no owned child. The channel carries it opaque.
        prepared_child_ops: Vec<u8>,
    },
    /// ✅️ Phase-2 commit for one transaction member. CHANNEL_VERSION 9 wire addition.
    TransactionCommit {
        seq: u64,
        txn_id: String,
    },
    /// ↩️ Aborts a not-yet-committed transaction member. CHANNEL_VERSION 9 wire addition.
    TransactionRollback {
        seq: u64,
        txn_id: String,
    },
    /// ⏪️ Fans a group undo out to one already-committed transaction member. CHANNEL_VERSION 9 wire addition.
    TransactionUndo {
        seq: u64,
        group_id: String,
    },
    /// ⏩️ Fans a group redo out to one already-committed transaction member. CHANNEL_VERSION 9 wire addition.
    TransactionRedo {
        seq: u64,
        group_id: String,
    },
    /// 📂️ Opens an artifact in its resolved (or explicitly named) viewer/editor surface — see
    /// contract-freeze.md §3 of `.🧬semio/🦑️repo/🎫️tickets/🎆️26/🌙️08/☀️16/ARTIFACT-VIEWERS-AND-EDITORS-PER-SUBSET/`.
    /// Empty `plugin_id`/`app_id` means "resolve via `OpeningResolver`". CHANNEL_VERSION 10 wire addition.
    OpenArtifact {
        seq: u64,
        artifact_ref: String,
        role: u8,
        plugin_id: String,
        app_id: String,
    },
    /// 🎚️ Pins a viewer/editor default for one `(artifact_kind, standard, subset, role)` coordinate,
    /// persisted event-sourced in the OS `🎚️config` opening-preferences facet. CHANNEL_VERSION 10 wire addition.
    SetDefaultApp {
        seq: u64,
        artifact_kind: String,
        standard: String,
        subset: String,
        role: u8,
        plugin_id: String,
        app_id: String,
    },
    /// 🎚️ Clears a previously pinned default, falling back to the `OpeningResolver`'s owner/router
    /// order. CHANNEL_VERSION 10 wire addition.
    ClearDefaultApp {
        seq: u64,
        artifact_kind: String,
        standard: String,
        subset: String,
        role: u8,
    },
    /// ⚖️ Pins this connection's local/authority `MergePolicy` (`0`=`LaissezFaire`, `1`=`Normal`,
    /// `2`=`Vigilant`) — never carried on a `MutationEnvelope`/`BackboneMessage`, see
    /// contract-freeze.md §C3/C8 of `.🧬semio/🦑️repo/🎫️tickets/🎆️26/🌙️08/☀️16/MUTATION-OUTCOMES-MERGE-POLICIES-AND-FIRST-CLASS-CONFLICTS/`.
    /// CHANNEL_VERSION 11 wire addition.
    SetMergePolicy {
        seq: u64,
        policy: u8,
    },
    /// ⚔️ Resolves one open `Conflict` (`0`=`Accept`, `1`=`Discard`) — see contract-freeze.md §C5/C6.
    /// CHANNEL_VERSION 11 wire addition.
    ResolveConflict {
        seq: u64,
        conflict_id: String,
        resolution: u8,
    },
    /// ⚔️ Reads every open `Conflict` for the current artifact. CHANNEL_VERSION 11 wire addition.
    ReadConflicts {
        seq: u64,
    },
    /// 👥️ Pushes the document-wide presence roster into this app instance — the ONLY plugin ingress
    /// for peers (contract-freeze §C7.6 of ticket
    /// `.🧬semio/🦑️repo/🎫️tickets/🎆️26/🌙️08/☀️17/SHARED-PRESENCE-SESSION-COLORS-AND-UNIVERSAL-ARTIFACT-CREATION`).
    /// `own_color` is this actor's hub-assigned palette index (`None` for a folder-only session with
    /// no hub); `peers` are `encode_presence_peer` blobs, the whole roster with the wrapper's own
    /// actor already dropped. Reply is a plain `AppFrame::Done`. CHANNEL_VERSION 12 wire addition.
    Presence {
        seq: u64,
        own_color: Option<u8>,
        peers: PresenceRosterWire,
    },
    /// 🏠️ Fixed request/token commands; page data travels only on the reply lane.
    LocalInteractionQuery {
        seq: u64,
        command: protocol::LocalInteractionQueryCommand,
    },
    /// 🗃️ Restores one root envelope and its complete recursive owned-member closure through one
    /// retained publication transaction. CHANNEL_VERSION 16 wire addition.
    LoadDocumentArchive {
        seq: u64,
        archive: DocumentArchivePack,
    },
    /// 🗃️ Reads one generation-fenced root envelope and complete recursive owned-member closure.
    /// CHANNEL_VERSION 16 wire addition.
    ReadDocumentArchive {
        seq: u64,
    },
    /// 📊️ Reads one retained archive operation without transferring or releasing its owner.
    PollDocumentArchiveLoad {
        seq: u64,
        operation: u64,
    },
    /// 🛑️ Marks one retained archive operation cancelled; maintenance owns cleanup.
    CancelDocumentArchiveLoad {
        seq: u64,
        operation: u64,
    },
    /// 📨️ Releases one terminal archive operation after its exact result was observed.
    AcknowledgeDocumentArchiveLoad {
