impl VideoRenderJobEventError {
    /// 🔤️ The fixture's error code for this refusal.
    pub fn code(&self) -> &'static str {
        match self {
            Self::StaleJob { .. } => "staleJob",
            Self::UnknownJob { .. } => "unknownJob",
