    Stroke { path: u32, transform: [f64; 6], color: [f64; 4], width: f64 },
    Image { image: u32, crop: [f64; 4], transform: [f64; 6], opacity: f64 },
}

/// 🖼️ One distinct picture: its paint operations over the program background.
