[package]
workspace = "../../.."
name = "semio-framework"
version = "0.1.0"
edition = "2021"
rust-version.workspace = true
description = "Render-independent framework kernel: Platform, ActionBus, declarative UiTree, layouts"

[package.metadata.semio]
channel-version-consumers = "🔨️modules/🛂️manifest/🔖️channel-version/📇️consumers.json"
role = "framework"
id = "framework"

[lints]
workspace = true
[lib]
path = "🦀️.rs"

[dependencies]
semio-framework-io-schema = { path = "../../🔨️modules/🚪️io/🧬️schema/📦️packages/🦀️rust" }
semio-framework-pack-json = { path = "../../🔨️modules/🎒️pack/🔤️json/📦️packages/🦀️rust" }
semio-framework-diagnostic = { path = "../../🔨️modules/⚠️diagnostic/📦️packages/🦀️rust" }
semio-framework-dsl = { path = "../../🔨️modules/🗣️dsl/📦️packages/🦀️rust" }
semio-framework-ui-locale = { path = "../../🔨️modules/🖱️ui/🌐️locale/📦️packages/🦀️rust" }
semio-framework-schema-registry = { path = "../../🔨️modules/🧬️schema/📇️registry/📦️packages/🦀️rust" }
semio-framework-value = { path = "../../🔨️modules/🌱️value/📦️packages/🦀️rust" }
semio-framework-ui-contract = { path = "../../🔨️modules/🖱️ui/🧬️contract/📦️packages/🦀️rust", package = "semio-framework-ui-contract" }
semio-framework-actor = { workspace = true }
semio-framework-job = { path = "../../🔨️modules/🧵️job/📦️packages/🦀️rust", package = "semio-framework-job" }
# ⏯️ `ToolRunDefinition` on `ToolDefinition`/`UtilityDefinition` and the reserved tool run actions (manifest region `🔖️ToolRun`).
semio-framework-tool-run = { workspace = true }
serde = { workspace = true }
serde_json = { workspace = true }
ui_wgpu = { path = "../../🔨️modules/🖱️ui/📦️packages/🦀️rust", package = "semio-framework-ui", features = ["wgpu"] }
semio-framework-hash = { path = "../../🔨️modules/🔏️hash/📦️packages/🦀️rust", package = "semio-framework-hash" }
# ⬇️ `kernel::media_export_bytes` — the first-party RFC 4648 codec that turns a
# `Effect::DownloadMediaExport` envelope into the bytes a shell saves. No runtime `base64` crate.
semio-framework-io-base64 = { path = "../../🔨️modules/🚪️io/🔤️base64/📦️packages/🦀️rust", package = "semio-framework-io-base64" }
# 📥️ `kernel::IMPORT_CHUNK_BYTES` derives the import chunk extent from the guest's own contiguous
# request ceiling rather than restating it. `semio-framework-trace` is a zero-dependency pure-std
# crate of exactly such bounds. Workspace-internal — the external dependency count is unchanged.
semio-framework-trace = { workspace = true }
semio-framework-mesh-engine = { path = "../../🔨️modules/🏗️mesh-engine/📦️packages/🦀️rust", package = "semio-framework-mesh-engine" }
# 🎯️ OS kernel owns spr/dsl types — aliases avoid dual trees / cycle with old implementations.
semio-framework-os-kernel = { path = "../../🛍️products/💻️os/📦️packages/🦀️rust", package = "semio-framework-os-kernel" }
semio-framework-value-derive = { path = "../../🔨️modules/🌱️value/✨️derive/📦️packages/🦀️rust", package = "semio-framework-value-derive" }
# 🧬️ `register_scope_schema_exports`/`resolve_schema_export` — the `(scope id, export id, format id)`
# registry this crate's mounted `interaction::schema` leaf declares its named exports into.
semio-framework-schema = { workspace = true }

[dev-dependencies]
semio-framework-async-macros = { path = "../../🔨️modules/⏳️async/✨️macros/📦️packages/🦀️rust" }
# 🔬️ Third-party oracle for `kernel::media_export_bytes`'s base64 lane — dev-only, never a runtime dep.
base64 = "0.22.1"

[features]
# 🧬️ Generates the TypeScript mirror for boundary/protocol types (see `<owner>/🤖️generated/🪪️manifest/🟦️.ts`);
# never enabled by default so schema projection never affects the plain build/test path.
typegen = []

