    /// 💡️ Complete, bounded native inference invocation.
    pub struct ArtifactInferenceExecutionRequest<'a> {
        pub policy: &'a [u8],
        pub budgets: &'a WireArtifactInferenceBudget,
        pub cancellation_id: &'a str,
        pub previous_state: Option<&'a [u8]>,
