        /// ⏯️ The declared label and `ToolRunDefinition` of one tool or utility.
        pub(crate) fn tool_run(&self, id: &str) -> Option<&(LocalizedLabel, semio_framework::ToolRunDefinition)> {
            self.tool_runs.get(id)
