    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    enum BoundedStoreInitializationPhase {
        ValidateEnvelope,
        ValidateEdit { index: usize },
        CloneInitial,
        FoldSupersessions,
        SeedHistory { edit: usize, lane: u8, index: usize },
        FindApplied { position: usize },
        ApplyForward { position: usize, edit: usize, mutation: usize },
        HashInverse { position: usize, edit: usize, mutation: usize },
        CommitApplied { position: usize, edit: usize },
        FindRedo { position: usize },
        HashRedo { position: usize, edit: usize, lane: u8, mutation: usize },
        CommitRedo { position: usize, edit: usize },
        BuildCandidate,
        RetireCancelled,
        RetireFault,
        Complete,
        Cancelled,
        Fault,
    }

    /// 🌱️ Retained persisted-document initialization for an explicitly bounded app — the document
    /// twin of [`bounded_document_store_owners`]: every edit id is validated and indexed once (one step each — linear in
    /// the history, never pairwise), the envelope's initial snapshot is cloned in one page, every applied and redo edit is
    /// found through that index in one step, every applied edit replays one mutation per step (`progress` counts them),
    /// and every displaced owner retires through the same bounded factories.
    struct BoundedStoreInitializationAuthority<P, M>
    where
        P: Clone + protocol::ToValue + protocol::FromValue + ArtifactPack + Send + Sync + 'static,
        M: Clone + protocol::ToValue + protocol::FromValue + Mutation<P> + OpBinary + OpText + Send + 'static,
    {
        operation: semio_framework_job::OperationId,
        generation: semio_framework_job::Generation,
        schema: &'static str,
        envelope: std::mem::ManuallyDrop<Option<store::ArtifactEnvelope<P, M>>>,
        runtime: std::mem::ManuallyDrop<Option<store::ArtifactStoreInitializationRuntime<P>>>,
        candidate: std::mem::ManuallyDrop<Option<ArtifactStore<P, M>>>,
        active: std::mem::ManuallyDrop<Option<Box<dyn store::ErasedSnapshotRetirement>>>,
        envelope_retirement: std::mem::ManuallyDrop<Option<Box<dyn store::ErasedSnapshotRetirement>>>,
        edit_digest: std::mem::ManuallyDrop<Option<store::ArtifactStoreInitializationDigest>>,
        edit_index: store::ArtifactStoreInitializationEditIndex,
        folded: u64,
        fold_total: u64,
        phase: BoundedStoreInitializationPhase,
        cancel_requested: bool,
        fault: Option<Vec<u8>>,
        terminal_handoff: bool,
    }

    impl<P, M> BoundedStoreInitializationAuthority<P, M>
    where
        P: Clone + protocol::ToValue + protocol::FromValue + ArtifactPack + Send + Sync + 'static,
        M: Clone + protocol::ToValue + protocol::FromValue + Mutation<P> + OpBinary + OpText + Send + 'static,
    {
        fn applied_id(&self, position: usize) -> Option<&str> {
            let envelope = self.envelope.as_ref()?;
            match &envelope.cursor {
                Some(cursor) => cursor.applied_edit_ids.get(position).map(String::as_str),
                None => envelope.vcs.edits.get(position).map(|edit| edit.id.as_str()),
            }
        }

        fn redo_id(&self, position: usize) -> Option<&str> {
            self.envelope.as_ref()?.cursor.as_ref()?.redo_edit_ids.get(position).map(String::as_str)
        }

        /// 🔢️ How many operations the applied history replays: the forwards of every applied edit the index names.
        fn applied_operation_count(&self) -> u64 {
            let Some(envelope) = self.envelope.as_ref() else { return 0 };
            (0..).map_while(|position| self.applied_id(position)).filter_map(|id| self.edit_index.position(id)).filter_map(|edit| envelope.vcs.edits.get(edit)).map(|edit| edit.forwards.len() as u64).sum()
        }

        fn fail(&mut self, code: &'static [u8]) {
            self.fault = Some(code.to_vec());
            self.phase = BoundedStoreInitializationPhase::RetireFault;
        }

        fn begin_edit_digest(&mut self, edit: usize) {
            let entry = self.envelope.as_ref().and_then(|envelope| envelope.vcs.edits.get(edit)).expect("bounded initializer edit remains retained");
            let mut digest = store::ArtifactStoreInitializationDigest::new(b"bounded.edit");
            digest.observe(entry.id.as_bytes());
            digest.observe(&entry.sequence_number.to_be_bytes());
            digest.observe(entry.started_at.as_bytes());
            *self.edit_digest = Some(digest);
        }

        fn hash_operation(&mut self, operation: &M) -> Option<usize> {
            match operation.encode_op() {
                Ok(encoded) if encoded.len() <= store::ARTIFACT_ENVELOPE_DECODE_PAGE_BYTES => {
                    self.edit_digest.as_mut().expect("bounded initializer edit digest remains retained").observe(&encoded);
                    Some(encoded.len())
                }
                _ => None,
            }
        }

        fn pump_active(&mut self) -> Result<bool, semio_framework_value::ValueError> {
            let Some(active) = self.active.as_mut() else { return Ok(false) };
            match active.close_step(1, store::ARTIFACT_ENVELOPE_DECODE_PAGE_BYTES)? {
                store::SnapshotRetirementStep::Pending { released_items, released_bytes } if released_items <= 1 && released_bytes <= store::ARTIFACT_ENVELOPE_DECODE_PAGE_BYTES => Ok(true),
                store::SnapshotRetirementStep::Pending { .. } => Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "bounded store initializer retirement exceeded its exact grant")),
                store::SnapshotRetirementStep::Blocked => Ok(true),
                store::SnapshotRetirementStep::Complete if active.terminal_is_empty() => {
                    drop(self.active.take());
                    Ok(true)
                }
                store::SnapshotRetirementStep::Complete => Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "bounded store initializer retirement reported a false terminal")),
            }
        }

        fn pump_terminal_retirement(&mut self) -> Result<bool, semio_framework_value::ValueError> {
            if self.pump_active()? {
                return Ok(false);
            }
            if let Some(runtime) = self.runtime.as_mut() {
                match runtime.close_step(&BoundedConfigRetirementFactory::<P>::new(), 1, store::ARTIFACT_ENVELOPE_DECODE_PAGE_BYTES)? {
                    store::SnapshotRetirementStep::Complete if runtime.terminal_is_empty() => {
                        drop(self.runtime.take());
                        return Ok(false);
                    }
                    store::SnapshotRetirementStep::Complete => return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "bounded initialization runtime reported a false terminal")),
                    _ => return Ok(false),
                }
            }
            if self.envelope_retirement.is_none() {
                if let Some(envelope) = self.envelope.take() {
                    let mut owners = bounded_document_store_owners::<P, M>();
                    if owners.close_uninstalled_owners_step(1)? != store::SnapshotRetirementStep::Complete || !owners.uninstalled_owners_terminal_is_empty() {
                        return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "uninstalled bounded document store disposer did not close exactly"));
                    }
                    *self.envelope_retirement = Some(owners.retire_envelope(envelope));
                    return Ok(false);
                }
            }
            if let Some(retirement) = self.envelope_retirement.as_mut() {
                return match retirement.close_step(1, store::ARTIFACT_ENVELOPE_DECODE_PAGE_BYTES)? {
                    store::SnapshotRetirementStep::Complete if retirement.terminal_is_empty() => {
                        drop(self.envelope_retirement.take());
                        Ok(true)
                    }
                    store::SnapshotRetirementStep::Complete => Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "bounded initialization envelope retirement reported a false terminal")),
                    _ => Ok(false),
                };
            }
            Ok(true)
        }

        fn finish_terminal(&mut self) {
            drop(self.edit_digest.take());
            self.terminal_handoff = true;
        }

        fn terminal_is_empty_inner(&self) -> bool {
            self.terminal_handoff && self.envelope.is_none() && self.runtime.is_none() && self.candidate.is_none() && self.active.is_none() && self.envelope_retirement.is_none() && self.edit_digest.is_none()
        }

        fn fault_outcome(&self, cx: &mut semio_framework_job::StepContext<'_>) -> semio_framework_job::StepOutcome {
            let source = self.fault.as_deref().unwrap_or(b"bounded-store.initializer-fault");
            let detail = cx.payload_from_bytes(semio_framework_job::JobPayloadStream::Fault, source).unwrap_or_else(|_| semio_framework_job::RetainedJobPayload::empty(semio_framework_job::JobPayloadStream::Fault));
            semio_framework_job::StepOutcome::Fault(semio_framework_job::JobFault { detail })
        }
    }

    impl<P, M> ArtifactStoreInitializationAuthority<P, M> for BoundedStoreInitializationAuthority<P, M>
    where
        P: Clone + protocol::ToValue + protocol::FromValue + ArtifactPack + Send + Sync + 'static,
        M: Clone + protocol::ToValue + protocol::FromValue + Mutation<P> + OpBinary + OpText + Send + 'static,
    {
        fn step(&mut self, cx: &mut semio_framework_job::StepContext<'_>) -> semio_framework_job::StepOutcome {
            if cx.operation() != self.operation || cx.generation() != self.generation {
                self.fail(b"bounded-store.initializer-stale-authority");
            }
            if self.cancel_requested && !matches!(self.phase, BoundedStoreInitializationPhase::RetireCancelled | BoundedStoreInitializationPhase::Cancelled) {
                self.phase = BoundedStoreInitializationPhase::RetireCancelled;
            }
            if let Err(error) = self.pump_active() {
                self.fault = Some(error.into_message().into_bytes());
                self.phase = BoundedStoreInitializationPhase::RetireFault;
            } else if self.active.is_some() {
                return semio_framework_job::StepOutcome::Yield;
            }
            let commit = || {
                semio_framework_job::StepOutcome::Complete(semio_framework_job::CommitCandidate {
                    state: semio_framework_job::RetainedJobPayload::empty(semio_framework_job::JobPayloadStream::CommitState),
                    output: semio_framework_job::RetainedJobPayload::empty(semio_framework_job::JobPayloadStream::CommitOutput),
                })
            };
            match self.phase {
                BoundedStoreInitializationPhase::ValidateEnvelope => {
                    match self.envelope.as_ref() {
                        None => self.fail(b"bounded-store.initializer-envelope-missing"),
                        Some(envelope) if envelope.schema != self.schema || envelope.id.is_empty() || envelope.id.len() > store::ARTIFACT_ENVELOPE_DECODE_PAGE_BYTES => self.fail(b"bounded-store.initializer-envelope-invalid"),
                        Some(_) => self.phase = BoundedStoreInitializationPhase::ValidateEdit { index: 0 },
                    }
                    cx.consume_fuel(1);
                    semio_framework_job::StepOutcome::Yield
                }
                BoundedStoreInitializationPhase::ValidateEdit { index } => {
                    let edits = &self.envelope.as_ref().expect("validated bounded envelope remains retained").vcs.edits;
                    match self.edit_index.admit(edits, index, store::ARTIFACT_ENVELOPE_DECODE_PAGE_BYTES) {
                        store::ArtifactStoreInitializationEditAdmission::Complete => self.phase = BoundedStoreInitializationPhase::CloneInitial,
                        store::ArtifactStoreInitializationEditAdmission::Admitted => self.phase = BoundedStoreInitializationPhase::ValidateEdit { index: index + 1 },
                        store::ArtifactStoreInitializationEditAdmission::Oversized | store::ArtifactStoreInitializationEditAdmission::Duplicate => self.fail(b"bounded-store.initializer-duplicate-or-hostile-edit"),
                    }
                    cx.consume_fuel(1);
                    semio_framework_job::StepOutcome::Yield
                }
                BoundedStoreInitializationPhase::CloneInitial => {
                    let envelope = self.envelope.as_ref().expect("bounded envelope remains retained during initial clone");
                    let pack = envelope.vcs.initial_snapshot.encode_pack();
                    let mut digest = store::ArtifactStoreInitializationDigest::new(b"bounded.initial");
                    digest.observe(&pack);
                    *self.runtime = Some(store::ArtifactStoreInitializationRuntime::new(&envelope.id, &envelope.schema, envelope.vcs.initial_snapshot.clone(), digest.finish()));
                    self.phase = BoundedStoreInitializationPhase::FoldSupersessions;
                    self.fold_total = self.applied_operation_count();
                    cx.consume_fuel(pack.len().max(1) as u64);
                    semio_framework_job::StepOutcome::Yield
                }
                BoundedStoreInitializationPhase::FoldSupersessions => {
                    let envelope = self.envelope.as_ref().expect("bounded envelope remains retained while its supersessions fold");
                    let events = envelope.vcs.edits.len().saturating_add(envelope.transitions.len());
                    match store::fold_envelope_history(envelope) {
                        Ok(fold) => match self.runtime.as_mut().expect("bounded runtime remains retained while supersessions fold").set_supersessions(fold.supersessions) {
                            Ok(()) => self.phase = BoundedStoreInitializationPhase::SeedHistory { edit: 0, lane: 0, index: 0 },
                            Err(error) => {
                                self.fault = Some(error.into_bytes());
                                self.phase = BoundedStoreInitializationPhase::RetireFault;
                            }
                        },
                        Err(_) => self.fail(b"bounded-store.initializer-history-fold"),
                    }
                    cx.consume_fuel(events.max(1) as u64);
                    semio_framework_job::StepOutcome::Yield
                }
                BoundedStoreInitializationPhase::SeedHistory { edit, lane, index } => {
                    let envelope = self.envelope.as_ref().expect("bounded envelope remains retained while causal history is seeded");
                    let Some(entry) = envelope.vcs.edits.get(edit) else {
                        self.phase = BoundedStoreInitializationPhase::FindApplied { position: 0 };
                        return semio_framework_job::StepOutcome::Yield;
                    };
                    let runtime = self.runtime.as_mut().expect("bounded runtime remains retained while history is seeded");
                    let seeded = match lane {
                        0 => runtime.seed_mutation(protocol::MutationId(entry.id.clone())).map(|()| {
                            runtime.observe_sequence(entry.sequence_number);
                            BoundedStoreInitializationPhase::SeedHistory { edit, lane: 1, index: 0 }
                        }),
                        1 if index < entry.forwards.len() => {
                            let id = entry.mutation_meta.get(index).and_then(|meta| meta.mutation_id.clone()).or_else(|| entry.forwards[index].mutation_id()).unwrap_or_else(|| protocol::MutationId(format!("{}#{index}", entry.id)));
                            runtime.seed_edit_operation(&entry.id, id).map(|()| BoundedStoreInitializationPhase::SeedHistory { edit, lane, index: index + 1 })
                        }
                        1 => Ok(BoundedStoreInitializationPhase::SeedHistory { edit, lane: 2, index: 0 }),
                        2 if index < entry.mutation_meta.len() => {
                            runtime.observe_timestamp(entry.mutation_meta[index].timestamp.clone());
                            Ok(BoundedStoreInitializationPhase::SeedHistory { edit, lane, index: index + 1 })
                        }
                        _ => Ok(BoundedStoreInitializationPhase::SeedHistory { edit: edit + 1, lane: 0, index: 0 }),
                    };
                    match seeded {
                        Ok(next) => self.phase = next,
                        Err(error) => {
                            self.fault = Some(error.into_bytes());
                            self.phase = BoundedStoreInitializationPhase::RetireFault;
                        }
                    }
                    cx.consume_fuel(1);
                    semio_framework_job::StepOutcome::Yield
                }
                BoundedStoreInitializationPhase::FindApplied { position } => {
                    let Some(id) = self.applied_id(position).map(str::to_owned) else {
                        let checkpoint = self.envelope.as_ref().and_then(|envelope| envelope.cursor.as_ref().and_then(|cursor| cursor.checkpoint_id.clone()).or_else(|| envelope.vcs.checkpoints.last().map(|checkpoint| checkpoint.id.clone())));
                        self.runtime.as_mut().expect("bounded runtime remains retained").set_current_checkpoint_id(checkpoint);
                        self.phase = BoundedStoreInitializationPhase::FindRedo { position: 0 };
                        return semio_framework_job::StepOutcome::Yield;
                    };
                    match self.edit_index.position(&id) {
                        None => self.fail(b"bounded-store.initializer-applied-edit-missing"),
                        Some(edit) => {
                            self.begin_edit_digest(edit);
                            self.phase = BoundedStoreInitializationPhase::ApplyForward { position, edit, mutation: 0 };
                        }
                    }
                    cx.consume_fuel(1);
                    semio_framework_job::StepOutcome::Yield
                }
                BoundedStoreInitializationPhase::ApplyForward { position, edit, mutation } => {
                    let envelope = self.envelope.as_ref().expect("bounded envelope remains retained while its forwards fold");
                    let entry = envelope.vcs.edits.get(edit).expect("bounded applied edit remains retained");
                    let Some(original) = entry.forwards.get(mutation) else {
                        self.phase = BoundedStoreInitializationPhase::HashInverse { position, edit, mutation: 0 };
                        return semio_framework_job::StepOutcome::Yield;
                    };
                    let mutation_id = entry.mutation_meta.get(mutation).and_then(|meta| meta.mutation_id.clone()).or_else(|| original.mutation_id()).unwrap_or_else(|| protocol::MutationId(format!("{}#{mutation}", entry.id)));
                    let supersessions = self.runtime.as_ref().expect("bounded runtime remains retained while forwards fold").supersessions();
                    let Some(operation) = store::effective_operation::<P, M>(original, mutation as u32, mutation_id, &envelope.schema, supersessions).operation().cloned() else {
                        self.phase = BoundedStoreInitializationPhase::ApplyForward { position, edit, mutation: mutation + 1 };
                        self.folded += 1;
                        cx.consume_fuel(1);
                        return semio_framework_job::StepOutcome::Yield;
                    };
                    let Some(bytes) = self.hash_operation(&operation) else {
                        <M as Mutation<P>>::retire_cold(operation);
                        self.fail(b"bounded-store.initializer-forward-encoding");
                        return semio_framework_job::StepOutcome::Yield;
                    };
                    let current = self.runtime.as_mut().and_then(store::ArtifactStoreInitializationRuntime::current_mut).expect("bounded runtime current snapshot remains retained");
                    let (next, _) = store::fold_operation::<P, M>(current, &operation, mutation as u32);
                    <M as Mutation<P>>::retire_cold(operation);
                    if let Some(next) = next {
                        let previous = std::mem::replace(current, next);
                        *self.active = Some(store::ArtifactOwnedValueRetirementFactory::retire_owned(&BoundedConfigRetirementFactory::<P>::new(), previous));
                    }
                    self.phase = BoundedStoreInitializationPhase::ApplyForward { position, edit, mutation: mutation + 1 };
                    self.folded += 1;
                    cx.consume_fuel(bytes.max(1) as u64);
                    semio_framework_job::StepOutcome::Yield
                }
                BoundedStoreInitializationPhase::HashInverse { position, edit, mutation } => {
                    let Some(operation) = self.envelope.as_ref().and_then(|envelope| envelope.vcs.edits.get(edit)).expect("bounded applied edit remains retained").inverse.get(mutation).cloned() else {
                        self.phase = BoundedStoreInitializationPhase::CommitApplied { position, edit };
                        return semio_framework_job::StepOutcome::Yield;
                    };
                    match self.hash_operation(&operation) {
                        Some(bytes) => {
                            self.phase = BoundedStoreInitializationPhase::HashInverse { position, edit, mutation: mutation + 1 };
                            cx.consume_fuel(bytes.max(1) as u64);
                        }
                        None => self.fail(b"bounded-store.initializer-inverse-encoding"),
                    }
                    semio_framework_job::StepOutcome::Yield
                }
                BoundedStoreInitializationPhase::CommitApplied { position, edit } => {
                    let entry = self.envelope.as_ref().and_then(|envelope| envelope.vcs.edits.get(edit)).expect("bounded applied edit remains retained");
                    let (id, actor) = (entry.id.clone(), entry.actor.clone());
                    let digest = self.edit_digest.take().expect("bounded applied edit digest remains retained").finish();
                    let runtime = self.runtime.as_mut().expect("bounded runtime remains retained");
                    match runtime.push_applied(id, digest) {
                        Ok(()) => {
                            runtime.set_local_actor_id(actor);
                            self.phase = BoundedStoreInitializationPhase::FindApplied { position: position + 1 };
                        }
                        Err(error) => {
                            self.fault = Some(error.into_bytes());
                            self.phase = BoundedStoreInitializationPhase::RetireFault;
                        }
                    }
                    cx.consume_fuel(1);
                    semio_framework_job::StepOutcome::Yield
                }
                BoundedStoreInitializationPhase::FindRedo { position } => {
                    let Some(id) = self.redo_id(position).map(str::to_owned) else {
                        self.edit_index.clear();
                        self.phase = BoundedStoreInitializationPhase::BuildCandidate;
                        return semio_framework_job::StepOutcome::Yield;
                    };
                    match self.edit_index.position(&id) {
                        None => self.fail(b"bounded-store.initializer-redo-edit-missing"),
                        Some(edit) => {
                            self.begin_edit_digest(edit);
                            self.phase = BoundedStoreInitializationPhase::HashRedo { position, edit, lane: 0, mutation: 0 };
                        }
                    }
                    cx.consume_fuel(1);
                    semio_framework_job::StepOutcome::Yield
                }
                BoundedStoreInitializationPhase::HashRedo { position, edit, lane, mutation } => {
                    let entry = self.envelope.as_ref().and_then(|envelope| envelope.vcs.edits.get(edit)).expect("bounded redo edit remains retained");
                    let operation = if lane == 0 { entry.forwards.get(mutation) } else { entry.inverse.get(mutation) }.cloned();
                    let Some(operation) = operation else {
                        self.phase = if lane == 0 { BoundedStoreInitializationPhase::HashRedo { position, edit, lane: 1, mutation: 0 } } else { BoundedStoreInitializationPhase::CommitRedo { position, edit } };
                        return semio_framework_job::StepOutcome::Yield;
                    };
                    match self.hash_operation(&operation) {
                        Some(bytes) => {
                            self.phase = BoundedStoreInitializationPhase::HashRedo { position, edit, lane, mutation: mutation + 1 };
                            cx.consume_fuel(bytes.max(1) as u64);
                        }
                        None => self.fail(b"bounded-store.initializer-redo-encoding"),
                    }
                    semio_framework_job::StepOutcome::Yield
                }
                BoundedStoreInitializationPhase::CommitRedo { position, edit } => {
                    let id = self.envelope.as_ref().and_then(|envelope| envelope.vcs.edits.get(edit)).expect("bounded redo edit remains retained").id.clone();
                    let digest = self.edit_digest.take().expect("bounded redo digest remains retained").finish();
                    match self.runtime.as_mut().expect("bounded runtime remains retained").push_redo(id, digest) {
                        Ok(()) => self.phase = BoundedStoreInitializationPhase::FindRedo { position: position + 1 },
                        Err(error) => {
                            self.fault = Some(error.into_bytes());
                            self.phase = BoundedStoreInitializationPhase::RetireFault;
                        }
                    }
                    cx.consume_fuel(1);
                    semio_framework_job::StepOutcome::Yield
                }
                BoundedStoreInitializationPhase::BuildCandidate => {
                    let Some(candidate_generation) = self.generation.0.checked_add(1) else {
                        self.fail(b"bounded-store.initializer-generation-exhausted");
                        return semio_framework_job::StepOutcome::Yield;
                    };
                    let envelope = self.envelope.take().expect("bounded envelope remains retained until atomic store construction");
                    let runtime = self.runtime.take().expect("bounded runtime remains retained until atomic store construction");
                    *self.candidate = Some(ArtifactStore::from_initialized_runtime_with_owners(envelope, runtime, candidate_generation, bounded_document_store_owners::<P, M>()));
                    self.phase = BoundedStoreInitializationPhase::Complete;
                    commit()
                }
                BoundedStoreInitializationPhase::RetireCancelled | BoundedStoreInitializationPhase::RetireFault => match self.pump_terminal_retirement() {
                    Ok(false) => semio_framework_job::StepOutcome::Yield,
                    Ok(true) => {
                        self.finish_terminal();
                        if self.phase == BoundedStoreInitializationPhase::RetireCancelled {
                            self.phase = BoundedStoreInitializationPhase::Cancelled;
                            semio_framework_job::StepOutcome::Cancelled
                        } else {
                            self.phase = BoundedStoreInitializationPhase::Fault;
                            self.fault_outcome(cx)
                        }
                    }
                    Err(error) => {
                        self.fault = Some(error.into_message().into_bytes());
                        semio_framework_job::StepOutcome::Yield
                    }
                },
                BoundedStoreInitializationPhase::Complete => commit(),
                BoundedStoreInitializationPhase::Cancelled => semio_framework_job::StepOutcome::Cancelled,
                BoundedStoreInitializationPhase::Fault => self.fault_outcome(cx),
            }
        }

        fn request_cancel(&mut self) {
            self.cancel_requested = true;
        }

        fn begin_close(&mut self) {
            self.cancel_requested = true;
            if !matches!(self.phase, BoundedStoreInitializationPhase::Cancelled | BoundedStoreInitializationPhase::Fault) {
                self.phase = BoundedStoreInitializationPhase::RetireCancelled;
            }
        }

        fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            self.begin_close();
            if maximum_items == 0 || maximum_bytes < store::ARTIFACT_ENVELOPE_DECODE_PAGE_BYTES {
                return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            }
            match self.pump_terminal_retirement() {
                Ok(false) => Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 }),
                Ok(true) => {
                    self.finish_terminal();
                    Ok(PluginCloseStep::Complete)
                }
                Err(error) => Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-store.initializer-close"), format!("bounded store initializer close failed: {}", error.into_message()))),
            }
        }

        fn progress(&self) -> (u64, u64) {
            (self.folded, self.fold_total)
        }

        fn take_candidate(&mut self) -> Option<ArtifactStore<P, M>> {
            if self.phase != BoundedStoreInitializationPhase::Complete || self.terminal_handoff {
                return None;
            }
            let candidate = self.candidate.take()?;
            self.finish_terminal();
            Some(candidate)
        }

        fn terminal_is_empty(&self) -> bool {
            self.terminal_is_empty_inner()
        }
    }

    impl<P, M> Drop for BoundedStoreInitializationAuthority<P, M>
    where
        P: Clone + protocol::ToValue + protocol::FromValue + ArtifactPack + Send + Sync + 'static,
        M: Clone + protocol::ToValue + protocol::FromValue + Mutation<P> + OpBinary + OpText + Send + 'static,
    {
        fn drop(&mut self) {
            assert!(std::thread::panicking() || self.terminal_is_empty_inner(), "bounded store initialization authority reached Drop before exact candidate handoff or retained rejection close");
        }
    }

    /// 🌱️ Persisted-document initialization authority for an explicitly bounded document store —
    /// what `ArtifactApp::build_document_store_initialization_job` returns for an app whose owners
    /// come from [`bounded_document_store_owners`], so a whole-document load can replace its store.
    pub fn bounded_document_store_initialization_job<P, M>(
        envelope: store::ArtifactEnvelope<P, M>,
        schema: &'static str,
        operation: semio_framework_job::OperationId,
        generation: semio_framework_job::Generation,
    ) -> ArtifactStoreInitializationJob<P, M>
    where
        P: Clone + protocol::ToValue + protocol::FromValue + ArtifactPack + Send + Sync + 'static,
        M: Clone + protocol::ToValue + protocol::FromValue + Mutation<P> + OpBinary + OpText + Send + 'static,
    {
        ArtifactStoreInitializationJob::new(Box::new(BoundedStoreInitializationAuthority {
            operation,
            generation,
            schema,
            envelope: std::mem::ManuallyDrop::new(Some(envelope)),
            runtime: std::mem::ManuallyDrop::new(None),
            candidate: std::mem::ManuallyDrop::new(None),
            active: std::mem::ManuallyDrop::new(None),
            envelope_retirement: std::mem::ManuallyDrop::new(None),
            edit_digest: std::mem::ManuallyDrop::new(None),
            edit_index: store::ArtifactStoreInitializationEditIndex::default(),
            folded: 0,
            fold_total: 0,
            phase: BoundedStoreInitializationPhase::ValidateEnvelope,
            cancel_requested: false,
            fault: None,
            terminal_handoff: false,
        }))
    }
    //#endregion 🎛️BoundedConfigStoreOwners

    /// 🧹️ Explicit adapter from an app-owned document-store close catalog to the
    /// plugin close protocol. Apps must return this adapter themselves; the framework never installs
    /// one from type bounds or a permissive default.
    pub struct ArtifactDocumentStoreDisposer<P, Mutation>(std::marker::PhantomData<fn() -> (P, Mutation)>);

    impl<P, Mutation> Default for ArtifactDocumentStoreDisposer<P, Mutation> {
        fn default() -> Self {
            Self::new()
        }
    }

    impl<P, Mutation> ArtifactDocumentStoreDisposer<P, Mutation> {
        pub fn new() -> Self {
            Self(std::marker::PhantomData)
        }
    }

    impl<P, Mutation> ArtifactOwnedDisposer<ArtifactStore<P, Mutation>> for ArtifactDocumentStoreDisposer<P, Mutation>
    where
        P: Clone + protocol::ToValue + protocol::FromValue + ArtifactPack + Send + Sync + 'static,
        Mutation: Clone + protocol::ToValue + protocol::FromValue + store::Mutation<P> + OpBinary + OpText + Send + 'static,
    {
        fn close_step(&mut self, owner: &mut ArtifactStore<P, Mutation>, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            match owner.close_owned_store_step(maximum_items.min(1), maximum_bytes).map_err(|error| plugin_sdk_fault(error.to_string()))? {
                store::SnapshotRetirementStep::Pending { released_items, released_bytes } if released_items <= 1 && released_bytes <= maximum_bytes => Ok(PluginCloseStep::Pending { released_items, released_bytes }),
                store::SnapshotRetirementStep::Pending { .. } => Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.document-store-close-over-budget"), "document store close exceeded its exact one-owner grant")),
                store::SnapshotRetirementStep::Blocked => Ok(PluginCloseStep::Blocked { reason: "document store close awaits a retained reader or owner" }),
                store::SnapshotRetirementStep::Complete => Ok(PluginCloseStep::Complete),
            }
        }

        fn terminal_is_empty(&self, owner: &ArtifactStore<P, Mutation>) -> bool {
            owner.close_owned_store_terminal_is_empty()
        }
    }

    /// 🏗️ Domain-owned persistent initializer for one completed envelope. A terminal
    /// success retains exactly one fully prepared store until the wrapper takes it; fault/cancel may
    /// become terminal only after the envelope and every partial owner have been cursor-retired.
    pub trait ArtifactStoreInitializationAuthority<P, Mutation>: Send
    where
        P: Clone + protocol::ToValue + protocol::FromValue,
        Mutation: Clone + protocol::ToValue + protocol::FromValue + store::Mutation<P>,
    {
        fn step(&mut self, cx: &mut semio_framework_job::StepContext<'_>) -> semio_framework_job::StepOutcome;
        /// 📈️ `(operations folded, operations to fold)` of the history this initializer replays; `(0, 0)` when it counts
        /// none.
        fn progress(&self) -> (u64, u64) {
            (0, 0)
        }
        fn request_cancel(&mut self);
        fn take_candidate(&mut self) -> Option<ArtifactStore<P, Mutation>>;
        #[inline(never)]
        fn take_boxed_candidate(&mut self) -> Option<Box<ArtifactStore<P, Mutation>>> {
            self.take_candidate().map(Box::new)
        }
        fn begin_close(&mut self);
        fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault>;
        fn terminal_is_empty(&self) -> bool;
    }

    pub struct ArtifactStoreInitializationJob<P, Mutation>
    where
        P: Clone + protocol::ToValue + protocol::FromValue,
        Mutation: Clone + protocol::ToValue + protocol::FromValue + store::Mutation<P>,
    {
        authority: std::mem::ManuallyDrop<Option<Box<dyn ArtifactStoreInitializationAuthority<P, Mutation>>>>,
        cancel_requested: std::sync::Arc<std::sync::atomic::AtomicBool>,
        terminal_handoff: bool,
    }

    impl<P, Mutation> ArtifactStoreInitializationJob<P, Mutation>
    where
        P: Clone + protocol::ToValue + protocol::FromValue,
        Mutation: Clone + protocol::ToValue + protocol::FromValue + store::Mutation<P>,
    {
        pub fn new(authority: Box<dyn ArtifactStoreInitializationAuthority<P, Mutation>>) -> Self {
            Self { authority: std::mem::ManuallyDrop::new(Some(authority)), cancel_requested: std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false)), terminal_handoff: false }
        }

        fn cancel_signal(&self) -> std::sync::Arc<std::sync::atomic::AtomicBool> {
            std::sync::Arc::clone(&self.cancel_requested)
        }

        fn request_cancel_now(&self) {
            self.cancel_requested.store(true, std::sync::atomic::Ordering::Release);
        }

        fn take_candidate(&mut self) -> Option<Box<ArtifactStore<P, Mutation>>> {
            let candidate = self.authority.as_mut()?.take_boxed_candidate()?;
            self.terminal_handoff = true;
            if self.authority.as_ref().is_some_and(|authority| authority.terminal_is_empty()) {
                drop(self.authority.take());
            }
            Some(candidate)
        }

        /// 📈️ The initializer's `(operations folded, operations to fold)`; `(0, 0)` once it handed its store off.
        pub(crate) fn progress(&self) -> (u64, u64) {
            self.authority.as_ref().map_or((0, 0), |authority| authority.progress())
        }

        fn release_terminal_failure(&mut self) -> bool {
            if !self.authority.as_ref().is_some_and(|authority| authority.terminal_is_empty()) {
                return false;
            }
            drop(self.authority.take());
            self.terminal_handoff = true;
            true
        }

        fn terminal_is_empty(&self) -> bool {
            self.authority.is_none() && self.terminal_handoff
        }
    }

    impl<P, Mutation> semio_framework_job::InteractiveJob for ArtifactStoreInitializationJob<P, Mutation>
    where
        P: Clone + protocol::ToValue + protocol::FromValue + Send,
        Mutation: Clone + protocol::ToValue + protocol::FromValue + store::Mutation<P> + Send,
    {
        fn step(&mut self, cx: &mut semio_framework_job::StepContext<'_>) -> semio_framework_job::StepOutcome {
            match self.authority.as_mut() {
                Some(authority) => {
                    if self.cancel_requested.load(std::sync::atomic::Ordering::Acquire) {
                        authority.request_cancel();
                    }
                    authority.step(cx)
                }
                None if self.terminal_handoff => semio_framework_job::StepOutcome::Complete(semio_framework_job::CommitCandidate {
                    state: semio_framework_job::RetainedJobPayload::empty(semio_framework_job::JobPayloadStream::CommitState),
                    output: semio_framework_job::RetainedJobPayload::empty(semio_framework_job::JobPayloadStream::CommitOutput),
                }),
                None => semio_framework_job::StepOutcome::Fault(semio_framework_job::JobFault { detail: retained_job_payload(cx, semio_framework_job::JobPayloadStream::Fault, b"artifact-store.initializer-owner-missing") }),
            }
        }

        fn begin_close(&mut self) {
            self.request_cancel_now();
            if let Some(authority) = self.authority.as_mut() {
                authority.begin_close();
            }
        }

        fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> semio_framework_job::InteractiveJobCloseStep {
            self.begin_close();
            let Some(authority) = self.authority.as_mut() else {
                return if self.terminal_handoff { semio_framework_job::InteractiveJobCloseStep::Complete } else { semio_framework_job::InteractiveJobCloseStep::Blocked };
            };
            match authority.close_step(maximum_items, maximum_bytes) {
                Ok(PluginCloseStep::Pending { released_items, released_bytes }) => semio_framework_job::InteractiveJobCloseStep::Pending { released_items, released_bytes },
                Ok(PluginCloseStep::AwaitingInput { .. } | PluginCloseStep::Blocked { .. }) | Err(_) => semio_framework_job::InteractiveJobCloseStep::Blocked,
                Ok(PluginCloseStep::Complete) if authority.terminal_is_empty() => {
                    if maximum_items == 0 {
                        return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 0, released_bytes: 0 };
                    }
                    drop(self.authority.take());
                    self.terminal_handoff = true;
                    semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 1, released_bytes: 0 }
                }
                Ok(PluginCloseStep::Complete) => semio_framework_job::InteractiveJobCloseStep::Blocked,
            }
        }

        fn terminal_is_empty(&self) -> bool {
            ArtifactStoreInitializationJob::terminal_is_empty(self)
        }
    }

    impl<P, Mutation> Drop for ArtifactStoreInitializationJob<P, Mutation>
    where
        P: Clone + protocol::ToValue + protocol::FromValue,
        Mutation: Clone + protocol::ToValue + protocol::FromValue + store::Mutation<P>,
    {
        fn drop(&mut self) {
            assert!(std::thread::panicking() || self.authority.is_none() && self.terminal_handoff, "artifact store initialization job reached Drop before exact candidate handoff or terminal retained close");
        }
    }

    fn drive_artifact_owned_disposer<T>(lane: &'static str, owner: &mut T, disposer: &mut std::mem::ManuallyDrop<ArtifactDisposal<T>>, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
        let Some(disposer_ref) = disposer.as_mut() else {
            return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-owned-disposer-missing"), format!("app owner did not provide the required bounded disposer for {lane}")));
        };
        let step = disposer_ref.close_step(owner, maximum_items, maximum_bytes)?;
        if step != PluginCloseStep::Complete {
            return Ok(step);
        }
        if !disposer_ref.terminal_is_empty(owner) {
            return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-owned-terminal-not-empty"), format!("bounded disposer for {lane} reported Complete before its exact owner shell was empty")));
        }
        drop(disposer.take());
        Ok(PluginCloseStep::Complete)
    }

    pub(crate) fn retained_job_payload(cx: &mut semio_framework_job::StepContext<'_>, stream: semio_framework_job::JobPayloadStream, bytes: &[u8]) -> semio_framework_job::RetainedJobPayload {
        match cx.payload_from_bytes(stream, bytes) {
            Ok(payload) => payload,
            Err(rejected) => {
                drop(rejected.into_source());
                semio_framework_job::RetainedJobPayload::empty(stream)
            }
        }
    }

    trait ErasedArtifactSnapshotDisposer: Send {
        fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault>;
        fn terminal_is_empty(&self) -> bool;
    }

    struct TypedArtifactSnapshotDisposer<T> {
        snapshot: Option<std::sync::Arc<T>>,
        disposer: Box<dyn ArtifactSnapshotDisposer<T>>,
    }

    impl<T: Send + Sync + 'static> ErasedArtifactSnapshotDisposer for TypedArtifactSnapshotDisposer<T> {
        fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            self.disposer.close_step(&mut self.snapshot, maximum_items, maximum_bytes)
        }

        fn terminal_is_empty(&self) -> bool {
            self.disposer.terminal_is_empty(&self.snapshot)
        }
    }

    #[derive(Clone)]
    pub struct ArtifactSnapshotCloseLease<T> {
        identity: std::sync::Weak<T>,
        runtime_retained: std::sync::Arc<std::sync::atomic::AtomicBool>,
    }

    impl<T> ArtifactSnapshotCloseLease<T> {
        fn new(external_owner: &std::sync::Arc<T>, disposer: Box<dyn ArtifactSnapshotDisposer<T>>) -> (Self, ArtifactSnapshotCloseRetention)
        where
            T: Send + Sync + 'static,
        {
            let runtime_retained = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(true));
            let retention = ArtifactSnapshotCloseRetention { inner: std::mem::ManuallyDrop::new(Some(Box::new(TypedArtifactSnapshotDisposer { snapshot: Some(external_owner.clone()), disposer }))), runtime_retained: runtime_retained.clone() };
            (Self { identity: std::sync::Arc::downgrade(external_owner), runtime_retained }, retention)
        }

        pub fn can_release(&self, snapshot: &std::sync::Arc<T>) -> bool {
            self.runtime_retained.load(std::sync::atomic::Ordering::Acquire) && self.identity.ptr_eq(&std::sync::Arc::downgrade(snapshot))
        }
    }

    struct ArtifactSnapshotCloseRetention {
        inner: std::mem::ManuallyDrop<Option<Box<dyn ErasedArtifactSnapshotDisposer>>>,
        runtime_retained: std::sync::Arc<std::sync::atomic::AtomicBool>,
    }

    impl ArtifactSnapshotCloseRetention {
        fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            let Some(inner) = self.inner.as_mut() else { return Ok(PluginCloseStep::Complete) };
            let step = ErasedArtifactSnapshotDisposer::close_step(&mut **inner, maximum_items, maximum_bytes)?;
            if step == PluginCloseStep::Complete {
                if !ErasedArtifactSnapshotDisposer::terminal_is_empty(&**inner) {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.snapshot-terminal-not-empty"), "snapshot disposer reported Complete before its exact terminal shell was empty"));
                }
                drop(self.inner.take());
            }
            Ok(step)
        }

        fn terminal_is_empty(&self) -> bool {
            self.inner.is_none()
        }
    }

    impl Drop for ArtifactSnapshotCloseRetention {
        fn drop(&mut self) {
            self.runtime_retained.store(false, std::sync::atomic::Ordering::Release);
            debug_assert!(std::thread::panicking() || self.inner.is_none(), "incomplete snapshot retirement reached Drop without bounded disposal");
        }
    }

    /// 📬️ Single-assignment result cell for one owned media-export operation.
    #[derive(Clone)]
    pub struct ArtifactMediaExportCompletion {
        inner: std::sync::Arc<std::sync::Mutex<Option<Result<ArtifactMediaExportResult, MediaError>>>>,
    }

    impl ArtifactMediaExportCompletion {
        fn new() -> Self {
            Self { inner: std::sync::Arc::new(std::sync::Mutex::new(None)) }
        }

        pub fn complete(&self, result: Result<ArtifactMediaExportResult, MediaError>) -> Result<(), Fault> {
            let error_bytes = match &result {
                Ok(_) | Err(MediaError::NotImplemented) => 0,
                Err(MediaError::UnknownPort(port)) => port.len(),
                Err(MediaError::Incompatible { port, .. }) => port.len(),
                Err(MediaError::Payload(port, message)) => port.len().saturating_add(message.len()),
            };
            if error_bytes > ARTIFACT_OUTPUT_METADATA_BYTES {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.media-completion-metadata"), "media completion error metadata exceeds its exact byte cap"));
            }
            let mut value = self.inner.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
            if value.is_some() {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.duplicate-media-output"), "media export job attempted to complete more than once"));
            }
            *value = Some(result);
            Ok(())
        }

        fn take(&self) -> Result<Option<Result<ArtifactMediaExportResult, MediaError>>, Fault> {
            self.inner.try_lock().map(|mut value| value.take()).map_err(|_| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.media-completion-busy"), "media completion authority is busy or poisoned"))
        }

        pub fn close_take(&self) -> Result<bool, Fault> {
            let mut authority = self.inner.try_lock().map_err(|_| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.media-completion-busy"), "media completion disposal authority is busy or poisoned"))?;
            if authority.as_ref().is_some_and(|result| result.as_ref().is_ok_and(|result| result.chunks.chunks_remaining() != 0)) {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.media-completion-terminal-not-empty"), "media completion cannot be released before its exact result chunks are empty"));
            }
            let value = authority.take();
            drop(authority);
            let present = value.is_some();
            drop(value);
            Ok(present)
        }

        fn close_step(&self, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            if maximum_items == 0 {
                return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            }
            let mut authority = self.inner.try_lock().map_err(|_| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.media-completion-busy"), "media completion disposal authority is busy or poisoned"))?;
            if let Some(Ok(result)) = authority.as_ref() {
                if result.chunks.chunks_remaining() != 0 {
                    if maximum_bytes < ARTIFACT_OUTPUT_CHUNK_BYTES {
                        return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                    }
                    let chunk =
                        result.chunks.close_take_chunk()?.ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.media-completion-chunk-authority"), "media completion chunk count changed during one fixed disposal step"))?;
                    drop(authority);
                    return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: chunk.len() });
                }
            }
            let value = authority.take();
            drop(authority);
            drop(value);
            Ok(PluginCloseStep::Complete)
        }

        fn terminal_is_empty(&self) -> Result<bool, Fault> {
            self.inner.try_lock().map(|value| value.is_none()).map_err(|_| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.media-completion-busy"), "media completion terminal authority is busy or poisoned"))
        }
    }

    struct ArtifactMediaExportCreditState {
        bytes: std::sync::atomic::AtomicUsize,
        exceeded: std::sync::atomic::AtomicBool,
    }

    /// 🧮️ Shared O(1) output credit. Producers add each encoded chunk while they already own it;
    /// terminal polling reads the accumulated count without rescanning or reallocating the Media.
    #[derive(Clone)]
    pub struct ArtifactMediaExportCredit {
        maximum: usize,
        state: std::sync::Arc<ArtifactMediaExportCreditState>,
    }

    impl ArtifactMediaExportCredit {
        fn new(maximum: usize) -> Self {
            Self { maximum, state: std::sync::Arc::new(ArtifactMediaExportCreditState { bytes: std::sync::atomic::AtomicUsize::new(0), exceeded: std::sync::atomic::AtomicBool::new(false) }) }
        }

        pub fn credit(&self, bytes: usize) -> Result<usize, Fault> {
            let result = self.state.bytes.try_update(std::sync::atomic::Ordering::SeqCst, std::sync::atomic::Ordering::SeqCst, |current| current.checked_add(bytes).filter(|next| *next <= self.maximum)).map(|previous| previous + bytes);
            match result {
                Ok(total) => Ok(total),
                Err(_) => {
                    self.state.exceeded.store(true, std::sync::atomic::Ordering::SeqCst);
                    Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.media-output-limit"), format!("media export output exceeds {} bytes", self.maximum)))
                }
            }
        }

        pub fn bytes(&self) -> usize {
            self.state.bytes.load(std::sync::atomic::Ordering::SeqCst)
        }

        fn exceeded(&self) -> bool {
            self.state.exceeded.load(std::sync::atomic::Ordering::SeqCst)
        }

        fn validate_terminal(&self) -> Result<usize, Fault> {
            let bytes = self.bytes();
            if self.exceeded() || bytes > self.maximum {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.media-output-limit"), format!("media export output exceeds {} bytes", self.maximum)));
            }
            Ok(bytes)
        }
    }

    fn validate_media_export_structure(result: &ArtifactMediaExportResult, operation_chunks: &ArtifactOutputChunks, credited_bytes: usize, maximum: usize) -> Result<(), Fault> {
        let actual_bytes = result.schema.len().checked_add(result.chunks.bytes()).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.media-output-overflow"), "media export structural payload byte count overflowed"))?;
        if !result.chunks.same_operation(operation_chunks) || !result.chunks.is_sealed() || actual_bytes != credited_bytes || actual_bytes > maximum {
            return Err(Fault::new(
                FaultOrigin::Framework,
                FaultCode::new("interactive-job.media-output-structure"),
                format!("media export structural payload is {actual_bytes} bytes but producer sealed {credited_bytes} bytes against a {maximum}-byte cap"),
            ));
        }
        Ok(())
    }

