    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub struct ArtifactEnvelopeDecodeOperationHandle {
        pub operation: semio_framework_job::OperationId,
        pub generation: semio_framework_job::Generation,
    }

    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub enum ArtifactEnvelopeDecodeOperationPoll {
        Pending,
        Progress,
        Ready,
        Cancelled,
        Fault,
    }

    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    enum ActiveArtifactEnvelopeDecodeState {
        Active,
        Ready,
        ClosingCancelled,
        ClosingFault,
        Complete,
    }

    struct ActiveArtifactEnvelopeDecode<P: Send + 'static, Mutation: Send + 'static> {
        operation: semio_framework_job::OperationId,
        generation: semio_framework_job::Generation,
        cancel: semio_framework_job::CancelToken,
        session: std::mem::ManuallyDrop<Option<semio_framework_job::MountedWorkerJobSession<store::ArtifactEnvelopeDecodeAuthority<P, Mutation>>>>,
        session_rejected: std::mem::ManuallyDrop<Option<semio_framework_job::WorkerJobSessionAdmissionRejected<store::ArtifactEnvelopeDecodeAuthority<P, Mutation>>>>,
        retained_outcome: std::mem::ManuallyDrop<Option<semio_framework_job::StepOutcome>>,
        terminal_state: Option<ActiveArtifactEnvelopeDecodeState>,
        rejected: std::mem::ManuallyDrop<Option<Box<dyn store::ErasedSnapshotRetirement>>>,
        completion: std::sync::Arc<store::ArtifactEnvelopeDecodeCompletion>,
        completed_close_requested: bool,
        state: ActiveArtifactEnvelopeDecodeState,
    }

    impl<P, Mutation> ActiveArtifactEnvelopeDecode<P, Mutation>
    where
        P: Send + 'static,
        Mutation: Send + 'static,
    {
        fn admitted(operation: semio_framework_job::OperationId, generation: semio_framework_job::Generation, decode: store::ArtifactEnvelopeDecodeAuthority<P, Mutation>, completion: std::sync::Arc<store::ArtifactEnvelopeDecodeCompletion>) -> Self {
            let cancel = semio_framework_job::CancelToken::root_now();
            let params = semio_framework_job::BatchJobParams {
                operation,
                generation,
                cancel: cancel.clone(),
                config: semio_framework_job::BatchDriveConfig { site: "artifact_envelope_decode", stage: semio_framework_job::InteractiveStage::InteractiveStep, fuel_per_step: 64, step_budget_us: semio_framework_job::INTERACTIVE_LANE_WALL_US },
                now_us: semio_framework_job::default_now_us,
            };
            let (session, session_rejected) = match semio_framework_job::MountedWorkerJobSession::try_new(decode, params) {
                Ok(session) => (Some(session), None),
                Err(rejected) => (None, Some(rejected)),
            };
            Self {
                operation,
                generation,
                cancel,
                session: std::mem::ManuallyDrop::new(session),
                session_rejected: std::mem::ManuallyDrop::new(session_rejected),
                retained_outcome: std::mem::ManuallyDrop::new(None),
                terminal_state: None,
                rejected: std::mem::ManuallyDrop::new(None),
                completion,
                completed_close_requested: false,
                state: ActiveArtifactEnvelopeDecodeState::Active,
            }
        }

        fn rejected(operation: semio_framework_job::OperationId, generation: semio_framework_job::Generation, rejected: Box<dyn store::ErasedSnapshotRetirement>, completion: std::sync::Arc<store::ArtifactEnvelopeDecodeCompletion>) -> Self {
            Self {
                operation,
                generation,
                cancel: semio_framework_job::CancelToken::root_now(),
                session: std::mem::ManuallyDrop::new(None),
                session_rejected: std::mem::ManuallyDrop::new(None),
                retained_outcome: std::mem::ManuallyDrop::new(None),
                terminal_state: None,
                rejected: std::mem::ManuallyDrop::new(Some(rejected)),
                completion,
                completed_close_requested: false,
                state: ActiveArtifactEnvelopeDecodeState::ClosingFault,
            }
        }

        fn request_completed_close(&mut self, completed: &store::ArtifactEnvelopeCompletedRecordRegistry<P, Mutation>) -> Result<bool, Fault> {
            let Some(ticket) = self.completion.ticket() else { return Ok(true) };
            if !self.completed_close_requested {
                match completed.try_request_close(ticket) {
                    Ok(()) => self.completed_close_requested = true,
                    Err(store::ArtifactEnvelopeCompletedRecordFault::Contended) => return Ok(false),
                    Err(store::ArtifactEnvelopeCompletedRecordFault::Stale) if completed.ticket_reclaimed(ticket) => return Ok(true),
                    Err(_) => return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.completed-close"), "completed envelope result lost its exact close authority")),
                }
            }
            Ok(completed.ticket_reclaimed(ticket))
        }

        /// 🔎 The detail page is the only record of WHY a live decode failed; it retires
        /// with the outcome, so it is reported here before the close loop releases it.
        fn drive(
            &mut self,
            pool: &semio_framework_async::WorkerPool,
            live_generation: semio_framework_job::Generation,
            completed: &store::ArtifactEnvelopeCompletedRecordRegistry<P, Mutation>,
            maximum_items: usize,
            maximum_bytes: usize,
        ) -> Result<PluginCloseStep, Fault> {
            if maximum_items == 0 {
                return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            }
            if let Some(rejected) = self.session_rejected.as_mut() {
                return match rejected.close_step(maximum_items.min(1), maximum_bytes) {
                    semio_framework_job::InteractiveJobCloseStep::Pending { released_items, released_bytes } => Ok(PluginCloseStep::Pending { released_items, released_bytes }),
                    semio_framework_job::InteractiveJobCloseStep::Blocked => Ok(PluginCloseStep::Blocked { reason: "envelope worker admission rejection is temporarily blocked" }),
                    semio_framework_job::InteractiveJobCloseStep::Complete if rejected.terminal_is_empty() => {
                        drop(self.session_rejected.take());
                        self.state = ActiveArtifactEnvelopeDecodeState::ClosingFault;
                        Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                    }
                    semio_framework_job::InteractiveJobCloseStep::Complete => {
                        Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.session-rejected-false-terminal"), "rejected envelope worker session reported Complete without terminal-empty authority"))
                    }
                };
            }
            if let Some(rejected) = self.rejected.as_mut() {
                let step = rejected.close_step(maximum_items.min(1), maximum_bytes).map_err(|error| plugin_sdk_fault(error.to_string()))?;
                return match step {
                    store::SnapshotRetirementStep::Complete if rejected.terminal_is_empty() => {
                        drop(self.rejected.take());
                        self.state = ActiveArtifactEnvelopeDecodeState::Complete;
                        Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                    }
                    store::SnapshotRetirementStep::Complete => Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.rejected-false-terminal"), "rejected envelope owner reported Complete without terminal-empty authority")),
                    store::SnapshotRetirementStep::Pending { released_items, released_bytes } => Ok(PluginCloseStep::Pending { released_items, released_bytes }),
                    store::SnapshotRetirementStep::Blocked => Ok(PluginCloseStep::Blocked { reason: "rejected envelope owner is temporarily blocked" }),
                };
            }
            if live_generation != self.generation && self.state == ActiveArtifactEnvelopeDecodeState::Active {
                self.cancel.cancel_now();
            }
            if self.state == ActiveArtifactEnvelopeDecodeState::Ready && self.cancel.is_cancelled_now() {
                self.state = ActiveArtifactEnvelopeDecodeState::ClosingCancelled;
            }
            if matches!(self.state, ActiveArtifactEnvelopeDecodeState::ClosingCancelled | ActiveArtifactEnvelopeDecodeState::ClosingFault) {
                if self.request_completed_close(completed)? {
                    self.state = ActiveArtifactEnvelopeDecodeState::Complete;
                    return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                }
                return Ok(PluginCloseStep::Blocked { reason: "cancelled envelope output awaits the completed-record close pump" });
            }
            if self.state == ActiveArtifactEnvelopeDecodeState::Complete {
                if self.session.as_ref().is_some_and(|session| session.terminal_is_empty()) {
                    drop(self.session.take());
                    self.terminal_state = None;
                    return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                }
                if self.decode_worker_owners_are_terminal() {
                    return Ok(PluginCloseStep::Complete);
                }
            }
            if self.state == ActiveArtifactEnvelopeDecodeState::Ready && self.terminal_state.is_none() && self.retained_outcome.is_none() && self.session.is_none() {
                return Ok(PluginCloseStep::Blocked { reason: "decoded envelope awaits exact consumer publication" });
            }
            if self.state == ActiveArtifactEnvelopeDecodeState::Ready {
                if let Some(session) = self.session.as_mut() {
                    if session.terminal_is_empty() {
                        drop(self.session.take());
                        self.terminal_state = None;
                        return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                    }
                }
            }
            if let Some(outcome) = self.retained_outcome.as_mut() {
                return match outcome.close_step(maximum_items.min(1), maximum_bytes) {
                    semio_framework_job::JobPayloadCloseStep::Pending { released_items, released_bytes } => Ok(PluginCloseStep::Pending { released_items, released_bytes }),
                    semio_framework_job::JobPayloadCloseStep::Complete if outcome.terminal_is_empty() => {
                        drop(self.retained_outcome.take());
                        if self.terminal_state.is_none() {
                            self.session
                                .as_mut()
                                .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.session-missing"), "live envelope decode lost its retained worker session"))?
                                .resume()
                                .map_err(|_| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.resume"), "envelope worker outcome lost its exact resume authority"))?;
                        }
                        Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                    }
                    semio_framework_job::JobPayloadCloseStep::Complete => Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.outcome-false-terminal"), "envelope worker outcome reported Complete without terminal-empty payload")),
                };
            }
            if let Some(target) = self.terminal_state {
                let session = self.session.as_mut().ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.session-missing"), "terminal envelope decode lost its retained worker session"))?;
                session.begin_close();
                return match session.close_step(maximum_items.min(1), maximum_bytes) {
                    semio_framework_job::WorkerJobCloseStep::Pending { released_items, released_bytes } => Ok(PluginCloseStep::Pending { released_items, released_bytes }),
                    semio_framework_job::WorkerJobCloseStep::Blocked => Ok(PluginCloseStep::Blocked { reason: "terminal envelope worker close is temporarily blocked" }),
                    semio_framework_job::WorkerJobCloseStep::Complete if session.terminal_is_empty() => {
                        drop(self.session.take());
                        self.terminal_state = None;
                        if self.state != ActiveArtifactEnvelopeDecodeState::Ready {
                            self.state = target;
                        }
                        Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                    }
                    semio_framework_job::WorkerJobCloseStep::Complete => {
                        Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.session-false-terminal"), "terminal envelope worker session reported Complete without terminal-empty authority"))
                    }
                };
            }
            let session = self.session.as_mut().ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.session-missing"), "live envelope decode lost its retained worker session"))?;
            match session.pump_one_for_interactive_turn(pool, semio_framework_async::Lane::Interactive) {
                Ok(semio_framework_job::WorkerJobPoll::Outcome | semio_framework_job::WorkerJobPoll::Terminal) => {
                    let outcome = session.take_checked_out_outcome().ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.outcome-missing"), "envelope worker checkout lost its exact outcome"))?;
                    self.terminal_state = match &outcome {
                        semio_framework_job::StepOutcome::Complete(_) if self.completion.ticket().is_some() => {
                            self.state = ActiveArtifactEnvelopeDecodeState::Ready;
                            Some(ActiveArtifactEnvelopeDecodeState::Ready)
                        }
                        semio_framework_job::StepOutcome::Cancelled => Some(ActiveArtifactEnvelopeDecodeState::ClosingCancelled),
                        semio_framework_job::StepOutcome::Fault(fault) => {
                            eprintln!("[TRACE] live envelope decode faulted: {}", String::from_utf8_lossy(fault.detail.page(0).unwrap_or(&[])));
                            Some(ActiveArtifactEnvelopeDecodeState::ClosingFault)
                        }
                        semio_framework_job::StepOutcome::Complete(_) => Some(ActiveArtifactEnvelopeDecodeState::ClosingFault),
                        _ => None,
                    };
                    *self.retained_outcome = Some(outcome);
                    Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                }
                Ok(semio_framework_job::WorkerJobPoll::Submitted | semio_framework_job::WorkerJobPoll::Idle) => Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 }),
                Ok(_) => Ok(PluginCloseStep::Blocked { reason: "envelope worker awaits its mounted wake" }),
                Err(_) => Ok(PluginCloseStep::Blocked { reason: "envelope worker lane is saturated or contended" }),
            }
        }

        fn decode_worker_owners_are_terminal(&self) -> bool {
            self.session.is_none() && self.retained_outcome.is_none() && self.session_rejected.is_none() && self.rejected.is_none() && self.terminal_state.is_none()
        }

        /// 🧹️ Closes the parked worker session/outcome ladder after [`Self::state`] reached
        /// [`ActiveArtifactEnvelopeDecodeState::Ready`] so store replacement can retire the decode owner.
        fn force_worker_session_terminal(&mut self, maximum_items: usize, maximum_bytes: usize, budget: usize) -> bool {
            for _ in 0..budget {
                if let Some(target) = self.terminal_state {
                    let Some(session) = self.session.as_mut() else {
                        return false;
                    };
                    session.begin_close();
                    match session.close_step(maximum_items.min(1), maximum_bytes) {
                        semio_framework_job::WorkerJobCloseStep::Pending { .. } => continue,
                        semio_framework_job::WorkerJobCloseStep::Blocked => continue,
                        semio_framework_job::WorkerJobCloseStep::Complete if session.terminal_is_empty() => {
                            drop(self.session.take());
                            self.terminal_state = None;
                            if self.state != ActiveArtifactEnvelopeDecodeState::Ready {
                                self.state = target;
                            }
                        }
                        semio_framework_job::WorkerJobCloseStep::Complete => continue,
                    }
                    continue;
                }
                if let Some(outcome) = self.retained_outcome.as_mut() {
                    match outcome.close_step(maximum_items.min(1), maximum_bytes) {
                        semio_framework_job::JobPayloadCloseStep::Pending { .. } => continue,
                        semio_framework_job::JobPayloadCloseStep::Complete if outcome.terminal_is_empty() => {
                            drop(self.retained_outcome.take());
                            if self.terminal_state.is_none() {
                                if let Some(session) = self.session.as_mut() {
                                    let _ = session.resume();
                                }
                            }
                        }
                        semio_framework_job::JobPayloadCloseStep::Complete => return false,
                    }
                    continue;
                }
                if let Some(session) = self.session.as_mut() {
                    if session.terminal_is_empty() {
                        drop(self.session.take());
                        self.terminal_state = None;
                        continue;
                    }
                    let poll = session.poll();
                    if session.checked_out_outcome().is_some() || poll == semio_framework_job::WorkerJobPoll::CheckedOut {
                        session.begin_close();
                    } else if !matches!(poll, semio_framework_job::WorkerJobPoll::Closing | semio_framework_job::WorkerJobPoll::TerminalEmpty) {
                        session.begin_close();
                    }
                    match session.close_step(maximum_items.min(1), maximum_bytes) {
                        semio_framework_job::WorkerJobCloseStep::Pending { .. } => continue,
                        semio_framework_job::WorkerJobCloseStep::Blocked => continue,
                        semio_framework_job::WorkerJobCloseStep::Complete => {
                            if session.terminal_is_empty() {
                                drop(self.session.take());
                                self.terminal_state = None;
                            }
                        }
                    }
                    continue;
                }
                return self.decode_worker_owners_are_terminal();
            }
            self.decode_worker_owners_are_terminal()
        }

        /// 🏃️ Whether one more `drive` can advance this decode. A `Ready` decode still runs until its
        /// worker session, retained outcome, and terminal close target are empty — only then does it
        /// park awaiting exact consumer publication.
        fn has_runnable_work(&self) -> bool {
            if self.state == ActiveArtifactEnvelopeDecodeState::Ready {
                return self.terminal_state.is_some() || self.retained_outcome.is_some() || self.session.as_ref().is_some_and(|session| !session.terminal_is_empty());
            }
            self.state != ActiveArtifactEnvelopeDecodeState::Ready
        }

        /// 📊️ A decode cancelled after its worker finished is Cancelled, never Ready: maintenance closes
        /// its completed record, so no consumer may admit it in between.
        fn poll(&self) -> ArtifactEnvelopeDecodeOperationPoll {
            match self.state {
                ActiveArtifactEnvelopeDecodeState::Active => ArtifactEnvelopeDecodeOperationPoll::Pending,
                ActiveArtifactEnvelopeDecodeState::Ready if self.cancel.is_cancelled_now() => ArtifactEnvelopeDecodeOperationPoll::Cancelled,
                ActiveArtifactEnvelopeDecodeState::Ready => ArtifactEnvelopeDecodeOperationPoll::Ready,
                ActiveArtifactEnvelopeDecodeState::ClosingCancelled => ArtifactEnvelopeDecodeOperationPoll::Cancelled,
                ActiveArtifactEnvelopeDecodeState::ClosingFault => ArtifactEnvelopeDecodeOperationPoll::Fault,
                ActiveArtifactEnvelopeDecodeState::Complete if self.cancel.is_cancelled_now() => ArtifactEnvelopeDecodeOperationPoll::Cancelled,
                ActiveArtifactEnvelopeDecodeState::Complete => ArtifactEnvelopeDecodeOperationPoll::Fault,
            }
        }

        fn terminal_is_empty(&self, completed: &store::ArtifactEnvelopeCompletedRecordRegistry<P, Mutation>) -> bool {
            let output_terminal = self.completion.ticket().is_none_or(|ticket| completed.ticket_reclaimed(ticket));
            self.state == ActiveArtifactEnvelopeDecodeState::Complete && self.session.is_none() && self.session_rejected.is_none() && self.retained_outcome.is_none() && self.rejected.is_none() && output_terminal
        }
    }

    impl<P: Send + 'static, Mutation: Send + 'static> Drop for ActiveArtifactEnvelopeDecode<P, Mutation> {
        fn drop(&mut self) {
            assert!(
                std::thread::panicking() || self.session.is_none() && self.session_rejected.is_none() && self.retained_outcome.is_none() && self.rejected.is_none() && self.state == ActiveArtifactEnvelopeDecodeState::Complete,
                "active envelope decode reached Drop before its worker and rejected owner were terminal empty"
            );
        }
    }

    struct ActiveArtifactEnvelopeIngress {
        pages: std::mem::ManuallyDrop<Option<store::OwnedSchemaDecodePages>>,
        closing: bool,
    }

    impl ActiveArtifactEnvelopeIngress {
        fn new(pages: store::OwnedSchemaDecodePages) -> Self {
            Self { pages: std::mem::ManuallyDrop::new(Some(pages)), closing: false }
        }

        fn take_pages(&mut self) -> Option<store::OwnedSchemaDecodePages> {
            self.pages.take()
        }

        fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> PluginCloseStep {
            let Some(pages) = self.pages.as_mut() else { return PluginCloseStep::Complete };
            if maximum_items == 0 {
                return PluginCloseStep::Pending { released_items: 0, released_bytes: 0 };
            }
            if let Some(page) = pages.close_take_page() {
                let released_bytes = page.len();
                if released_bytes > maximum_bytes {
                    pages.admit_page(page).expect("an exact ingress page returns to its pre-admitted slot when the close byte grant is insufficient");
                    return PluginCloseStep::Pending { released_items: 0, released_bytes: 0 };
                }
                return PluginCloseStep::Pending { released_items: 1, released_bytes };
            }
            let pages = self.pages.take().expect("terminal ingress pages remain retained");
            assert!(pages.terminal_is_empty());
            drop(pages);
            PluginCloseStep::Complete
        }

        fn terminal_is_empty(&self) -> bool {
            self.pages.is_none()
        }
    }

    impl Drop for ActiveArtifactEnvelopeIngress {
        fn drop(&mut self) {
            assert!(std::thread::panicking() || self.terminal_is_empty(), "artifact envelope ingress reached Drop before every admitted page was transferred or bounded-closed");
        }
    }

    /// 🔐️ Performs the sole document-store swap only inside its fresh authority decision.
    #[expect(clippy::result_large_err, reason = "A rejected publication returns the unchanged candidate store, preserving its existing bounded retirement authority.")]
    pub fn publish_document_store_candidate_if_authoritative<P, Mutation>(
        live: &mut ArtifactStore<P, Mutation>,
        candidate: ArtifactStore<P, Mutation>,
        validate: impl FnOnce() -> Result<(), Fault>,
    ) -> Result<ArtifactStore<P, Mutation>, (Fault, ArtifactStore<P, Mutation>)>
    where
        P: Clone + protocol::ToValue + protocol::FromValue + ArtifactPack + Send + Sync + 'static,
        Mutation: Clone + protocol::ToValue + protocol::FromValue + store::Mutation<P> + OpBinary + OpText + Send + 'static,
    {
        if let Err(fault) = validate() {
            return Err((fault, candidate));
        }
        Ok(std::mem::replace(live, candidate))
    }

    /// 🔄️ Publishes the replacement owner's heap candidate without moving either complete Store
    /// through the maintenance stack; the returned box owns the displaced live Store in place.
    fn publish_boxed_document_store_candidate_if_authoritative<P, Mutation>(
        live: &mut ArtifactStore<P, Mutation>,
        mut candidate: Box<ArtifactStore<P, Mutation>>,
        validate: impl FnOnce() -> Result<(), Fault>,
    ) -> Result<Box<ArtifactStore<P, Mutation>>, (Fault, Box<ArtifactStore<P, Mutation>>)>
    where
        P: Clone + protocol::ToValue + protocol::FromValue + ArtifactPack + Send + Sync + 'static,
        Mutation: Clone + protocol::ToValue + protocol::FromValue + store::Mutation<P> + OpBinary + OpText + Send + 'static,
    {
        if let Err(fault) = validate() {
            return Err((fault, candidate));
        }
        std::mem::swap(live, candidate.as_mut());
        Ok(candidate)
    }

    struct CompositionPinsRetirement {
        pins: std::mem::ManuallyDrop<Option<Vec<vcs::CompositionPin>>>,
        active: std::mem::ManuallyDrop<Option<vcs::CompositionPin>>,
        field: u8,
    }

    impl CompositionPinsRetirement {
        fn new(pins: Vec<vcs::CompositionPin>) -> Self {
            Self { pins: std::mem::ManuallyDrop::new(Some(pins)), active: std::mem::ManuallyDrop::new(None), field: 0 }
        }

        fn active_string_mut(&mut self) -> Option<&mut String> {
            let pin = self.active.as_mut()?;
            match self.field {
                0 => Some(&mut pin.child_ref.artifact_id),
                1 => Some(&mut pin.child_ref.dialect.artifact_kind),
                2 => Some(&mut pin.child_ref.dialect.standard),
                3 => Some(&mut pin.child_ref.dialect.subset),
                4 => Some(&mut pin.checkpoint_id),
                _ => None,
            }
        }

        fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> PluginCloseStep {
            if maximum_items == 0 {
                return PluginCloseStep::Pending { released_items: 0, released_bytes: 0 };
            }
            if self.active.is_none() {
                if let Some(pin) = self.pins.as_mut().and_then(Vec::pop) {
                    *self.active = Some(pin);
                    self.field = 0;
                } else if let Some(pins) = self.pins.take() {
                    drop(pins);
                    return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
                } else {
                    return PluginCloseStep::Complete;
                }
            }
            while self.field < 5 && self.active_string_mut().is_some_and(|value| value.is_empty()) {
                self.field += 1;
            }
            if let Some(value) = self.active_string_mut() {
                let bytes = value.chars().next_back().map_or(0, char::len_utf8);
                if bytes > maximum_bytes {
                    return PluginCloseStep::Pending { released_items: 0, released_bytes: 0 };
                }
                value.pop();
                return PluginCloseStep::Pending { released_items: 0, released_bytes: bytes };
            }
            drop(self.active.take());
            PluginCloseStep::Pending { released_items: 1, released_bytes: 0 }
        }

        fn terminal_is_empty(&self) -> bool {
            self.pins.is_none() && self.active.is_none()
        }
    }

    impl Drop for CompositionPinsRetirement {
        fn drop(&mut self) {
            assert!(std::thread::panicking() || self.terminal_is_empty(), "composition-pin retirement reached Drop before every displaced identity owner was bounded-closed");
        }
    }

    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub(crate) enum ActiveArtifactStoreReplacementState {
        Initializing,
        AwaitingMembers,
        OpeningMembers,
        ClosingRejectedMember,
        ValidatingClosure,
        PreparingCandidateViews,
        CandidateReady,
        RetiringRejectedMembers,
        RetiringCommittedMembers,
        RetiringCommittedStore,
        RetiringRejectedCandidate,
        Complete,
    }

    /// 🧭️ Which leg of a document-archive replacement refused the candidate, and with what
    /// evidence. An atomic replacement validates three of them in order — the owned-member set
    /// (`members`), the recursive ownership `closure`, and the `retained-publication` guard plus the
    /// app's own publication `authority` — and every one of them used to collapse into a single
    /// `faulted: bool` whose only explanation was a `#[cfg(test)]` `eprintln!`. A headless host
    /// therefore saw one opaque sentence for eleven distinct causes. This carries the cause to the
    /// wire instead: {@link ArtifactStoreReplacementRefusal::into_fault} mints the leg-specific
    /// {@link FaultCode} and detail that `Effect::LoadDocument` reports to the shell.
    /// 🔖️ A bounded inline copy of a job fault's first detail page — the initializer's own
    /// refusal slug (e.g. `bounded-store.initializer-envelope-invalid`), which the replacement used
    /// to drop on the floor. Fixed capacity, no allocation, `Copy`: it rides the refusal record.
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub(crate) struct ArtifactStoreRefusalCode {
        bytes: [u8; 96],
        len: u8,
    }

    impl ArtifactStoreRefusalCode {
        const EMPTY: Self = Self { bytes: [0; 96], len: 0 };

        fn from_page(page: &[u8]) -> Self {
            let mut bytes = [0u8; 96];
            let len = page.len().min(bytes.len());
            bytes[..len].copy_from_slice(&page[..len]);
            Self { bytes, len: len as u8 }
        }

        fn text(&self) -> &str {
            std::str::from_utf8(&self.bytes[..self.len as usize]).unwrap_or("<non-utf8 refusal page>")
        }
    }

    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub(crate) enum ArtifactStoreReplacementRefusal {
        Invariant { leg: ArtifactStoreReplacementLeg, detail: &'static str },
        InitializerAdmissionRejected,
        InitializerFailed(ArtifactStoreRefusalCode),
        Cancelled,
        MemberOpenRejected { ordinal: usize, diagnostic: store::MemberOpenDiagnostic },
        MemberIdentityMismatch { ordinal: usize, expected: usize },
        MemberFactoryRefused { ordinal: usize },
        ClosureRejected { diagnostic: store::OwnedDocumentClosureDiagnostic },
        ClosureMemberCount { members: usize, children: usize },
        PublicationGuard(ArtifactStoreReplacementPublicationGuard),
        PublicationAuthorityRejected,
    }

    /// 🦵️ The named leg a refusal belongs to — the same three the host message lists.
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub(crate) enum ArtifactStoreReplacementLeg {
        Initializer,
        Members,
        Closure,
        CandidateViews,
        RetainedPublication,
    }

    impl ArtifactStoreReplacementLeg {
        fn slug(self) -> &'static str {
            match self {
                Self::Initializer => "initializer",
                Self::Members => "members",
                Self::Closure => "closure",
                Self::CandidateViews => "candidate-views",
                Self::RetainedPublication => "retained-publication",
            }
        }
    }

    /// 🚦️ Every input the `CandidateReady` publication guard reads, as it read them.
    /// A bare "guard rejected" is unactionable; which of the seven conditions tripped is the answer.
    #[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
    pub(crate) struct ArtifactStoreReplacementPublicationGuard {
        pub(crate) closing: bool,
        pub(crate) cancelled: bool,
        pub(crate) parent_generation: u64,
        pub(crate) live_generation: u64,
        pub(crate) base_child_generation: u64,
        pub(crate) child_generation: u64,
        pub(crate) complete_candidate: bool,
        pub(crate) retirement_admitted: bool,
        pub(crate) next_generation: bool,
    }

    impl ArtifactStoreReplacementRefusal {
        fn leg(self) -> ArtifactStoreReplacementLeg {
            match self {
                Self::Invariant { leg, .. } => leg,
                Self::InitializerAdmissionRejected | Self::InitializerFailed(_) => ArtifactStoreReplacementLeg::Initializer,
                Self::Cancelled | Self::MemberOpenRejected { .. } | Self::MemberIdentityMismatch { .. } | Self::MemberFactoryRefused { .. } => ArtifactStoreReplacementLeg::Members,
                Self::ClosureRejected { .. } | Self::ClosureMemberCount { .. } => ArtifactStoreReplacementLeg::Closure,
                Self::PublicationGuard(_) | Self::PublicationAuthorityRejected => ArtifactStoreReplacementLeg::RetainedPublication,
            }
        }

        fn slug(self) -> &'static str {
            match self {
                Self::Invariant { .. } => "invariant",
                Self::InitializerAdmissionRejected => "initializer-admission-rejected",
                Self::InitializerFailed(_) => "initializer-failed",
                Self::Cancelled => "cancelled",
                Self::MemberOpenRejected { .. } => "member-open-rejected",
                Self::MemberIdentityMismatch { .. } => "member-identity-mismatch",
                Self::MemberFactoryRefused { .. } => "member-factory-refused",
                Self::ClosureRejected { .. } => "closure-rejected",
                Self::ClosureMemberCount { .. } => "closure-member-count",
                Self::PublicationGuard(_) => "publication-guard",
                Self::PublicationAuthorityRejected => "publication-authority-rejected",
            }
        }

        fn detail(self) -> String {
            match self {
                Self::Invariant { detail, .. } => detail.to_string(),
                Self::InitializerAdmissionRejected => "the app's document-store initialization job was refused admission to the interactive worker lane".to_string(),
                Self::InitializerFailed(code) => format!("the app's document-store initialization job faulted or was cancelled before it produced a candidate, reporting `{}`; its `build_document_store_initialization_job` refused this envelope, or the envelope's schema/id/history failed that job's own validation", code.text()),
                Self::Cancelled => "the replacement was cancelled before its member set reached candidate readiness".to_string(),
                Self::MemberOpenRejected { ordinal, diagnostic } => format!("owned member {ordinal} was rejected by its typed open ({diagnostic:?})"),
                Self::MemberIdentityMismatch { ordinal, expected } => format!("owned member open returned ordinal {ordinal} while the sealed set expected {expected}, or its artifact/owner reference changed across the open"),
                Self::MemberFactoryRefused { ordinal } => format!("the app's member factory refused the admitted open request for ordinal {ordinal}"),
                Self::ClosureRejected { diagnostic } => format!("recursive ownership closure validation rejected the candidate ({diagnostic:?})"),
                Self::ClosureMemberCount { members, children } => format!("closure validation reached {members} members while the candidate registry owns {children}; the archive's member roster is not the parent's exact owned closure"),
                Self::PublicationGuard(guard) => format!(
                    "the retained publication guard refused the ready candidate: closing={} cancelled={} parent-generation={} live-generation={} base-child-generation={} child-generation={} complete-candidate={} retirement-admitted={} next-generation={}",
                    guard.closing,
                    guard.cancelled,
                    guard.parent_generation,
                    guard.live_generation,
                    guard.base_child_generation,
                    guard.child_generation,
                    guard.complete_candidate,
                    guard.retirement_admitted,
                    guard.next_generation,
                ),
                Self::PublicationAuthorityRejected => "the app's `validate_document_store_publication` refused the exact candidate".to_string(),
            }
        }

        /// 🧯️ The typed fault the host reports instead of the one-sentence collapse.
        pub(crate) fn into_fault(self) -> Fault {
            let leg = self.leg();
            Fault::new(FaultOrigin::Plugin, FaultCode::new(format!("plugin.internal.document-archive-replacement.{}", self.slug())), format!("document archive replacement failed its {} leg: {}", leg.slug(), self.detail()))
        }
    }

