    //#region 🔖️Surfaces
    use semio_framework::{surface_app_id, AppRole};

    /// 🎭️ Authoring traits for artifact surfaces split by mutation capability (ticket
    /// 26/08/16/ARTIFACT-VIEWERS-AND-EDITORS-PER-SUBSET contract §2.1/§2.2/§2.4). `ArtifactEditor`
    /// and `ArtifactViewer` replace `ArtifactApp` as the trait an app AUTHOR implements; the runtime
    /// `ArtifactApp` trait above is unchanged and is satisfied by the `EditorApp`/`ViewerApp` adapters
    /// below through pure delegation — nothing here alters runtime dispatch.
    //#region 🔖️ArtifactEditor
    /// 👁️✏️ Authoring trait for a mutation-capable surface — a structural copy of `ArtifactApp`'s
    /// members (contract §2.1) plus `ROLE`/`DIALECT`; `APP_ID` is intentionally absent, the runtime id
    /// being derived from `DIALECT`+`ROLE` via `surface_app_id` (contract §7.4) instead of hand-written.
    /// `EditorApp<E>` below is the sole `ArtifactApp` implementor for any `E: ArtifactEditor`.
    /// ✏️🧩️ The concrete runtime app an editor surface instantiates — the roster read off `E` itself, so
    /// a fleet variant spelled this way can never register `E` over a roster it does not compose with.
    pub type EditorSurfaceApp<E> = VcsArtifactApp<EditorApp<E>, <E as ArtifactEditor>::Members>;

    /// 👁️🧩️ Viewer twin of [`EditorSurfaceApp`].
    pub type ViewerSurfaceApp<V> = VcsArtifactApp<ViewerApp<V>, <V as ArtifactViewer>::Members>;

    pub trait ArtifactEditor: Default + Send + 'static {
        /// 🎭️ Always `Editor` in practice — defaulted so implementors never restate it.
        const ROLE: AppRole = AppRole::Editor;
        /// 🧩️ The closed member roster every surface of this editor runs over — the ONE place a bundle
        /// reads it from, so `genesis_member_schema::<Self::Members>` resolves every dialect
        /// `genesis_child_pack` derives no matter which plugin registers the surface. `NoMembers` (the
        /// default) is right for an editor that composes no children; an editor that does state its own.
        type Members: store::SpaceMember + store::MemberFactory + Send + 'static = store::NoMembers;
        const DIALECT: Dialect;
        /// 🧬️ Supplies the editor's bounded projection of real parent child fields.
        fn child_restore_projection(_snapshot: &Self::Snapshot) -> Result<store::ChildRestoreProjection<'_>, Fault> {
            Err(plugin_sdk_fault("editor did not declare a loaded-parent child projection"))
        }
        /// 🌱️ The editor's derivable-child genesis — see `ArtifactApp::genesis_child_pack`.
        fn genesis_child_pack(_snapshot: &Self::Snapshot, _slot: &str, _child_id: &str) -> Option<Vec<u8>> {
            None
        }
        const REQUIRES_DOCUMENT_STORE_PUBLICATION_AUTHORITY: bool = false;
        /// 📜️ Stable document schema id — prefer this over `artifact_schema(&self)`.
        const DOCUMENT_SCHEMA: &'static str;
        /// 📚️ Examples authored for this editor's dialect. `PluginBuilder::editor` stamps this
        /// catalogue onto the plugin manifest; the navbar dropdown is `examples_for_app` over that
        /// manifest, so a plugin never passes the list itself.
        fn examples() -> Vec<ExampleSource> {
            Vec::new()
        }
        type Snapshot: Clone + PartialEq + protocol::ToValue + protocol::FromValue + Send + Sync + store::ArtifactDsl + ArtifactPack + semio_framework_schema_composition::ArtifactCompositionFields + 'static;
        type Mutation: protocol::SemanticMutation<Self::Snapshot> + PartialEq + Send + ::protocol::OpText + ::protocol::OpBinary + 'static;
        type Config: Clone + Default + PartialEq + protocol::ToValue + protocol::FromValue + Send + Sync + store::ConfigRecord + ArtifactPack + 'static;
        type ConfigMutation: ::protocol::Mutation<Self::Config> + PartialEq + Send + ::protocol::OpText + ::protocol::OpBinary + 'static;
        type Draft: Clone + Default + PartialEq + protocol::ToValue + protocol::FromValue + Send + Sync + store::ArtifactDsl + ArtifactPack + 'static;
        type DraftMutation: ::protocol::Mutation<Self::Draft> + PartialEq + Send + ::protocol::OpText + ::protocol::OpBinary + 'static;
        type Presence: Clone + Default + PartialEq + protocol::ToValue + protocol::FromValue + Send + Sync + store::ArtifactDsl + ArtifactPack + 'static;
