            let mut examples = E::examples();
            if examples.is_empty() {
                examples = declarations::subset_examples(&E::DIALECT);
            }
            if examples.is_empty() {
                return None;
            }
            if example_id.is_empty() {
                return Some(Ok(<E::Snapshot as store::ArtifactDsl>::print_dsl(&E::initial_snapshot())));
