        runtime.plugin.borrow().as_ref().map_or_else(
            || PluginManifest {
                plugin_id: "empty".into(),
                label: "Empty".into(),
                version: "0.0.0".into(),
                apps: vec![],
                examples: vec![],
                capabilities: vec![],
                topic_contributions: vec![],
                commands: vec![],
                artifact_kinds: vec![],
                hosted_artifact_kinds: Vec::new(),
                dependencies: vec![],
                contributions: vec![],
            },
            Plugin::manifest,
        )
    }

