    /// 🪪️ Preflights every runtime row before factory work and publishes its allocation-bound lifecycle together.
    pub(crate) async fn plugin_open_actor_instance<PA: PluginApp>(runtime: &PluginRuntime<PA>, request: semio_framework::kernel::ActorInstanceOpenRequest, app_id: &str, actor: &str) -> Result<(), Fault> {
        let actor = RuntimeActorAuthority::new(actor)?;
        let mut lifetimes = runtime.guest_lifetimes.try_borrow_mut().map_err(|_| plugin_internal_fault("lifecycle authority busy"))?;
        let slot = lifetimes.get_mut(request.instance_id).filter(|slot| slot.cell.matches_open(request)).ok_or_else(|| plugin_internal_fault("exact opening lifecycle missing"))?;
        if slot.native_created || slot.cell.owner().is_some() {
            return Err(plugin_internal_fault("native opening already captured"));
        }
        let mut instances = runtime.instances.try_borrow_mut().map_err(|_| plugin_internal_fault("runtime instance authority busy"))?;
        let mut quarantine = runtime.close_quarantine.try_borrow_mut().map_err(|_| plugin_internal_fault("runtime quarantine authority busy"))?;
        let mut actors = runtime.instance_actors.try_borrow_mut().map_err(|_| plugin_internal_fault("runtime actor authority busy"))?;
        let mut document_backbones = runtime.document_backbones.try_borrow_mut().map_err(|_| plugin_internal_fault("document backbone binding authority busy"))?;
        if !instances.can_insert(request.instance_id) || !quarantine.can_insert(request.instance_id) || !actors.can_insert(request.instance_id) || !document_backbones.can_insert(request.instance_id) {
            return Err(plugin_internal_fault("native opening slot collided"));
        }
        if let Some(fault) = runtime.plugin_assembly_error.try_borrow().map_err(|_| plugin_internal_fault("plugin assembly authority busy"))?.clone() {
            return Err(fault);
        }
        let program = runtime.plugin.try_borrow().map_err(|_| plugin_internal_fault("plugin factory authority busy"))?;
        let program = program.as_ref().ok_or_else(|| plugin_internal_fault("plugin not initialized"))?;
        let mut app = program.create_app(app_id).ok_or_else(|| plugin_internal_fault("unknown app"))?;
        ::semio_framework_async::poll::resolve_ready(app.bind_instance_id(request.instance_id));
        let cell = std::sync::Arc::new(RuntimeAppCell::new(AppInstance { id: request.instance_id, app, surface_contexts: Default::default() }));
        let lease = PluginInstanceCloseLease::from_cell(request.instance_id, &cell);
        let owner = crate::reactor::instance_lifetime::NativeLifetimeOwner::from_lease(slot.cell.lifetime(), lease).expect("preflighted exact native lifetime");
        slot.cell.install_owner(owner).unwrap_or_else(|_| panic!("preflighted opening owner slot"));
        instances.insert_admitted(request.instance_id, cell);
        actors.insert_admitted(request.instance_id, actor);
        slot.native_created = true;
        Ok(())
    }

    pub async fn plugin_create_app<PA: PluginApp>(runtime: &PluginRuntime<PA>, app_id: &str) -> Result<u32, Fault> {
        plugin_create_app_with_id(runtime, NEXT_INSTANCE_ID.fetch_add(1, Ordering::SeqCst), app_id).await
    }

    /// 🧬️ A2 (design-abi.md §2): `Event::InstanceOpen` carries a host-assigned `PluginInstanceId`
    /// (WIT `instance-id`) — the actor no longer allocates its own; it must open the app under
    /// EXACTLY the id the host names. `⚛️reactor::poll`'s `InstanceOpen` routing calls this instead
    /// of `plugin_create_app`. `plugin_create_app` (unchanged signature, still used by every
    /// pre-existing caller) now delegates here with a locally-allocated id, so nothing observing
    /// its old auto-increment behavior breaks.
    ///
    /// 🌉️ `slot.borrow()` is a `Ref` from `LocalKey::with`'s sync `FnOnce(&T) -> R` closure,
    /// which cannot itself be `async` — bridged via `resolve_ready` exactly like every other
    /// E4/E5-adjacent sync-context call in this file (`Plugin::create_app`'s body does no real
    /// awaiting; see the framework io module's `resolve_ready` doc comment).
    pub async fn plugin_create_app_with_id<PA: PluginApp>(runtime: &PluginRuntime<PA>, id: u32, app_id: &str) -> Result<u32, Fault> {
        if let Some(fault) = runtime.plugin_assembly_error.borrow().clone() {
            return Err(fault);
        }
        if !runtime.instances.try_borrow_mut().map_err(|_| plugin_internal_fault("runtime instance authority is busy"))?.can_insert(id)
            || !runtime.close_quarantine.try_borrow_mut().map_err(|_| plugin_internal_fault("runtime close quarantine is busy"))?.can_insert(id)
        {
            return Err(plugin_internal_fault(format!("fixed instance authority is saturated, collided, or quarantined: {id}")));
        }
        {
            let program = runtime.plugin.borrow();
            let program = program.as_ref().ok_or_else(|| plugin_internal_fault("plugin not initialized"))?;
            let mut app = program.create_app(app_id).ok_or_else(|| plugin_internal_fault(format!("unknown app: {app_id}")))?;
            ::semio_framework_async::poll::resolve_ready(app.bind_instance_id(id));
            ::semio_framework_async::poll::resolve_ready(with_instances_mut(runtime, |list| {
                list.insert_admitted(id, std::sync::Arc::new(RuntimeAppCell::new(AppInstance { id, app, surface_contexts: Default::default() })));
                Ok(())
            }))?;
            Ok(id)
        }
    }

    /// 🚪️ Items one app close step may retire. Priced per PAGE, not per item: the app close ladder
    /// walks FIXED slot geometry (`TOOL_CANCELLATION_SLOTS + ARTIFACT_LIVE_OUTPUT_SLOTS` = 1 088
    /// cancellation slots, then five 64-slot output cursors), and at one item per step that geometry
    /// alone cost 1 088 close steps — each one a pool pump the guest only gets 64 of per reactor turn
    /// on wasm, i.e. a browser worker round trip every 64 slots. The stages that own real per-item
    /// work (a media export's own byte budget, one download segment and one chunk) keep their own
    /// `.min(1)` grant, so this page only collapses the cursor SWEEPS.
    const RUNTIME_CLOSE_ITEMS_PER_STEP: usize = 1_024;
    /// 🚪️ Bytes one app close/maintenance step may retire — one PAGE, the same unit the reactor turn's
    /// own retirement ladder is priced in (`PATCH_RETIREMENT_BYTES_PER_UNIT`). At 4 096 it was exactly
    /// `ARTIFACT_OUTPUT_CHUNK_BYTES`, so a retained item larger than one output chunk — a tessellated
    /// preview mesh in a displaced window transient — could not be released by ANY number of steps and
    /// the ladder answered `Pending { 0, 0 }` until the structural accountant killed the close with
    /// `plugin.internal.zero-progress` (reproduced by the close-cost fixture's eight-document session,
    /// ticket 26/09/09).
    pub(crate) const RUNTIME_CLOSE_BYTES_PER_STEP: usize = 32 * 1_024;
    const RUNTIME_CLOSE_INNER_GRANT_US: u64 = 2_000;
    const RUNTIME_CLOSE_ZERO_PROGRESS_LIMIT: u8 = 8;
    /// ⏱️ Real time a close ladder must spend making no progress before the structural accountant is
    /// allowed to call it stalled — the SECOND half of the zero-progress verdict, next to the step
    /// count above.
    ///
    /// 🐛️ The count alone was the whole rule, and a count is not a duration: eight consecutive steps
    /// that each observe an empty ladder cost microseconds, so a close that had nothing left to retire
    /// faulted with `plugin.internal.zero-progress` reporting `elapsed 0us` against an `8000us`
    /// ceiling — a stall credit judged exhausted before any time had passed (six-pane demonstrator
    /// boot, ticket 26/08/28, `📓️fix-2026-09-16-concurrent-boot-timeout-and-close-fault.md`). A ladder
    /// that is genuinely wedged still burns this credit within a few reactor turns; one that is merely
    /// finishing never does.
    const RUNTIME_CLOSE_STALL_CREDIT_US: u64 = semio_framework_trace::INTERACTIVE_STEP_CEILING_US;

    struct RuntimeLiveCleanupPump<PA: PluginApp> {
        session: Option<semio_framework_job::BatchJobSession<RuntimeLiveCleanupJob<PA>>>,
        rejected: Option<semio_framework_job::WorkerJobSessionAdmissionRejected<RuntimeLiveCleanupJob<PA>>>,
        outcome: Option<semio_framework_job::StepOutcome>,
        terminal: bool,
        pending_status: RuntimeMaintenanceStatus,
        closing: bool,
        faulted: bool,
    }

    impl<PA: PluginApp> RuntimeLiveCleanupPump<PA> {
        fn new() -> Self {
            Self { session: None, rejected: None, outcome: None, terminal: false, pending_status: RuntimeMaintenanceStatus::Ready, closing: false, faulted: false }
        }

        fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> semio_framework_job::InteractiveJobCloseStep {
            self.closing = true;
            if let Some(outcome) = self.outcome.as_mut() {
                let step = outcome.close_step(maximum_items, maximum_bytes);
                let retired = outcome.terminal_is_empty();
                if retired {
                    self.outcome = None;
                }
                return match step {
                    semio_framework_job::JobPayloadCloseStep::Pending { released_items, released_bytes } => semio_framework_job::InteractiveJobCloseStep::Pending { released_items, released_bytes },
                    semio_framework_job::JobPayloadCloseStep::Complete => semio_framework_job::InteractiveJobCloseStep::Pending { released_items: usize::from(retired), released_bytes: 0 },
                };
            }
            if let Some(rejected) = self.rejected.as_mut() {
                let step = rejected.close_step(maximum_items, maximum_bytes);
                let retired = rejected.terminal_is_empty();
                if retired {
                    self.rejected = None;
                }
                return match step {
                    semio_framework_job::InteractiveJobCloseStep::Complete if retired => semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 1, released_bytes: 0 },
                    step => step,
                };
            }
            if let Some(session) = self.session.as_mut() {
                session.begin_close();
                let step = session.close_step(maximum_items, maximum_bytes);
                let retired = session.terminal_is_empty();
                if retired {
                    self.session = None;
                }
                return match step {
                    semio_framework_job::WorkerJobCloseStep::Pending { released_items, released_bytes } => semio_framework_job::InteractiveJobCloseStep::Pending { released_items, released_bytes },
                    semio_framework_job::WorkerJobCloseStep::Blocked => semio_framework_job::InteractiveJobCloseStep::Blocked,
                    semio_framework_job::WorkerJobCloseStep::Complete => semio_framework_job::InteractiveJobCloseStep::Pending { released_items: usize::from(retired), released_bytes: 0 },
                };
            }
            semio_framework_job::InteractiveJobCloseStep::Complete
        }

        fn terminal_is_empty(&self) -> bool {
            self.closing && self.session.is_none() && self.rejected.is_none() && self.outcome.is_none()
        }
    }

    struct RuntimeCloseCleanupPump<PA: PluginApp> {
        session: Option<semio_framework_job::BatchJobSession<RuntimeCloseCleanupJob<PA>>>,
        rejected: Option<semio_framework_job::WorkerJobSessionAdmissionRejected<RuntimeCloseCleanupJob<PA>>>,
        outcome: Option<semio_framework_job::StepOutcome>,
        terminal: bool,
        complete: bool,
        blocked: bool,
        pending_status: RuntimeCloseStatus,
        faulted: bool,
    }

    impl<PA: PluginApp> RuntimeCloseCleanupPump<PA> {
        fn new() -> Self {
            Self { session: None, rejected: None, outcome: None, terminal: false, complete: false, blocked: false, pending_status: RuntimeCloseStatus::Ready, faulted: false }
        }
    }

    struct RuntimeLiveCleanupJob<PA: PluginApp> {
        instance_id: u32,
        cell: Option<std::sync::Weak<RuntimeAppCell<PA>>>,
        progress: Option<crate::app::PluginCloseStep>,
        contended: bool,
        closing: bool,
    }

    impl<PA: PluginApp> semio_framework_job::InteractiveJob for RuntimeLiveCleanupJob<PA> {
        fn step(&mut self, cx: &mut semio_framework_job::StepContext<'_>) -> semio_framework_job::StepOutcome {
            cx.set_stage("plugin-runtime-live-cleanup");
            self.progress = None;
            self.contended = false;
            if cx.is_cancelled() {
                return semio_framework_job::StepOutcome::Cancelled;
            }
            let Some(cell) = self.cell.as_ref().and_then(std::sync::Weak::upgrade) else {
                return semio_framework_job::StepOutcome::Cancelled;
            };
            let mut instance = match cell.background_instance() {
                Ok(instance) => instance,
                Err(RuntimeInstanceRefusal::Contended) => {
                    self.contended = true;
                    return semio_framework_job::StepOutcome::Yield;
                }
                Err(RuntimeInstanceRefusal::Poisoned) => {
                    return semio_framework_job::StepOutcome::Fault(semio_framework_job::JobFault { detail: retained_job_payload(cx, semio_framework_job::JobPayloadStream::Fault, b"plugin live cleanup authority is poisoned") });
                }
            };
            cx.consume_fuel(1);
            #[cfg(any(test, target_arch = "wasm32"))]
            cell.maintenance_probe_entries.fetch_add(1, Ordering::Relaxed);
            let traced = semio_framework_trace::runtime_diagnostics_enabled();
            let maintenance_started_us = traced.then(semio_framework_job::default_now_us).flatten();
            let maintenance = instance.app.maintenance_step(1, RUNTIME_CLOSE_BYTES_PER_STEP);
            cell.maintenance_pressure.store(instance.app.maintenance_under_pressure(), Ordering::Relaxed);
            if let (Some(started_us), Some(finished_us)) = (maintenance_started_us, maintenance_started_us.and_then(|_| semio_framework_job::default_now_us())) {
                if finished_us.saturating_sub(started_us) >= 2_000 {
                    eprintln!("[TRACE] maintenance stage={} elapsed_us={} outcome={:?}", crate::app::LAST_MAINTENANCE_STAGE.load(Ordering::Relaxed), finished_us - started_us, maintenance.as_ref().map(|_| ()).map_err(|fault| fault.message.clone()));
                }
            }
            match maintenance {
                Ok(progress @ crate::app::PluginCloseStep::Pending { released_items, released_bytes }) if released_items <= 1 && released_bytes <= RUNTIME_CLOSE_BYTES_PER_STEP => {
                    self.progress = Some(progress);
                    semio_framework_job::StepOutcome::CheckpointReady(semio_framework_job::Checkpoint {
                        state: retained_job_payload(cx, semio_framework_job::JobPayloadStream::CheckpointState, &self.instance_id.to_le_bytes()),
                        applied_progress: released_items as u64,
                    })
                }
                Ok(crate::app::PluginCloseStep::Pending { .. }) => {
                    semio_framework_job::StepOutcome::Fault(semio_framework_job::JobFault { detail: retained_job_payload(cx, semio_framework_job::JobPayloadStream::Fault, b"plugin live cleanup step exceeded its exact item or byte contract") })
                }
                Ok(progress @ crate::app::PluginCloseStep::Blocked { .. }) => {
                    self.progress = Some(progress);
                    semio_framework_job::StepOutcome::Yield
                }
                Ok(progress @ crate::app::PluginCloseStep::AwaitingInput { .. }) => {
                    self.progress = Some(progress);
                    semio_framework_job::StepOutcome::Yield
                }
                Ok(crate::app::PluginCloseStep::Complete) => {
                    self.progress = Some(crate::app::PluginCloseStep::Complete);
                    semio_framework_job::StepOutcome::Complete(semio_framework_job::CommitCandidate {
                        state: retained_job_payload(cx, semio_framework_job::JobPayloadStream::CommitState, &self.instance_id.to_le_bytes()),
                        output: semio_framework_job::RetainedJobPayload::empty(semio_framework_job::JobPayloadStream::CommitOutput),
                    })
                }
                Err(error) => semio_framework_job::StepOutcome::Fault(semio_framework_job::JobFault { detail: retained_job_payload(cx, semio_framework_job::JobPayloadStream::Fault, error.message.as_bytes()) }),
            }
        }

        fn begin_close(&mut self) {
            self.closing = true;
        }

        fn close_step(&mut self, maximum_items: usize, _maximum_bytes: usize) -> semio_framework_job::InteractiveJobCloseStep {
            self.closing = true;
            if self.cell.is_some() {
                if maximum_items == 0 {
                    return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 0, released_bytes: 0 };
                }
                drop(self.cell.take());
                return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            semio_framework_job::InteractiveJobCloseStep::Complete
        }

        fn terminal_is_empty(&self) -> bool {
            self.closing && self.cell.is_none()
        }
    }

    fn runtime_live_cleanup_nonterminal_status(contended: bool, progress: Option<crate::app::PluginCloseStep>, stalled_steps: &AtomicU32) -> RuntimeMaintenanceStatus {
        if contended {
            return RuntimeMaintenanceStatus::Ready;
        }
        if matches!(progress, Some(crate::app::PluginCloseStep::AwaitingInput { .. })) {
            stalled_steps.store(0, Ordering::SeqCst);
            return RuntimeMaintenanceStatus::Ready;
        }
        let zero_progress = matches!(progress, Some(crate::app::PluginCloseStep::Pending { released_items: 0, released_bytes: 0 } | crate::app::PluginCloseStep::Blocked { .. }));
        if !zero_progress {
            stalled_steps.store(0, Ordering::SeqCst);
            return RuntimeMaintenanceStatus::Ready;
        }
        let stalled = stalled_steps.fetch_add(1, Ordering::SeqCst).saturating_add(1);
        if stalled >= RUNTIME_MAINTENANCE_ZERO_PROGRESS_LIMIT {
            RuntimeMaintenanceStatus::Fault(RuntimeCleanupFault::ZeroProgress)
        } else {
            RuntimeMaintenanceStatus::Ready
        }
    }

    /// ⏱️ Publishes one maintenance turn: the measured wall cost is recorded next to the status so
    /// the decode site can name the overrun in microseconds, and a clock failure or a ceiling
    /// overrun outranks whatever the pump itself concluded.
    fn runtime_live_cleanup_publish_turn<PA: PluginApp>(cell: &RuntimeAppCell<PA>, status: RuntimeMaintenanceStatus, elapsed: Result<u64, RuntimeCleanupFault>) {
        let verdict = match elapsed {
            Err(cause) => RuntimeMaintenanceStatus::Fault(cause),
            Ok(elapsed_us) if semio_framework_trace::interactive_step_contract_violated(elapsed_us) => {
                if semio_framework_trace::runtime_diagnostics_enabled() {
                    eprintln!("[TRACE] cooperative maintenance callback overran the interactive ceiling for instance {} (elapsed {elapsed_us}us) — recorded, not fatal: the callback clock measures wall time including descheduling and the pumped foreign job step; the job-level step contract quarantines slow steps", cell.id);
                }
                status
            }
            Ok(_) => status,
        };
        cell.maintenance_fault_us.store(elapsed.unwrap_or(RUNTIME_CLEANUP_UNMEASURED_US), Ordering::SeqCst);
        cell.maintenance_status.store(verdict.repr(), Ordering::SeqCst);
    }

    fn run_runtime_live_cleanup_turn<PA: PluginApp + 'static>(cell: &std::sync::Arc<RuntimeAppCell<PA>>, generation: semio_framework_job::Generation) {
        let mut now_us = semio_framework_job::default_now_us;
        let clock = runtime_callback_clock_begin(&mut now_us);
        if cell.maintenance_status.compare_exchange(RuntimeMaintenanceStatus::Queued.repr(), RuntimeMaintenanceStatus::Running.repr(), Ordering::SeqCst, Ordering::SeqCst).is_err() {
            return;
        }
        let clock = match clock {
            Ok(clock) => clock,
            Err(cause) => return runtime_live_cleanup_publish_turn(cell, RuntimeMaintenanceStatus::Ready, Err(cause)),
        };
        let status = match cell.maintenance_pump.try_lock() {
            Ok(mut pump) => runtime_live_cleanup_pump_one(cell, generation, &mut pump),
            Err(_) => RuntimeMaintenanceStatus::Ready,
        };
        runtime_live_cleanup_publish_turn(cell, status, runtime_callback_clock_elapsed(&mut now_us, clock));
    }

    fn runtime_live_cleanup_pump_one<PA: PluginApp + 'static>(cell: &std::sync::Arc<RuntimeAppCell<PA>>, generation: semio_framework_job::Generation, pump: &mut RuntimeLiveCleanupPump<PA>) -> RuntimeMaintenanceStatus {
        if pump.closing {
            let _ = pump.close_step(1, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES);
            return RuntimeMaintenanceStatus::Fault(RuntimeCleanupFault::AlreadyClosing);
        }
        if let Some(rejected) = pump.rejected.as_mut() {
            let _ = rejected.close_step(1, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES);
            if rejected.terminal_is_empty() {
                pump.rejected = None;
                return RuntimeMaintenanceStatus::Fault(RuntimeCleanupFault::AdmissionRejected);
            }
            return RuntimeMaintenanceStatus::Ready;
        }
        if let Some(outcome) = pump.outcome.as_mut() {
            let _ = outcome.close_step(1, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES);
            if !outcome.terminal_is_empty() {
                return RuntimeMaintenanceStatus::Ready;
            }
            pump.outcome = None;
            if pump.terminal {
                if let Some(session) = pump.session.as_mut() {
                    session.begin_close();
                }
            } else if pump.session.as_mut().is_some_and(|session| session.resume().is_err()) {
                return RuntimeMaintenanceStatus::Fault(RuntimeCleanupFault::Resume);
            } else {
                return pump.pending_status;
            }
        }
        if pump.terminal {
            let Some(session) = pump.session.as_mut() else {
                pump.terminal = false;
                return pump.pending_status;
            };
            let _ = session.close_step(1, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES);
            if session.terminal_is_empty() {
                pump.session = None;
                pump.terminal = false;
                return if pump.faulted { RuntimeMaintenanceStatus::Fault(RuntimeCleanupFault::PriorOutcome) } else { pump.pending_status };
            }
            return RuntimeMaintenanceStatus::Ready;
        }
        if pump.session.is_none() {
            let job = RuntimeLiveCleanupJob { instance_id: cell.id, cell: Some(std::sync::Arc::downgrade(cell)), progress: None, contended: false, closing: false };
            let params = semio_framework_job::BatchJobParams {
                operation: semio_framework_job::OperationId((1u64 << 62) | cell.id as u64),
                generation,
                cancel: semio_framework_job::CancelToken::root_now(),
                config: semio_framework_job::BatchDriveConfig { site: "plugin_runtime_live_cleanup", stage: semio_framework_job::InteractiveStage::InteractiveStep, fuel_per_step: 1, step_budget_us: RUNTIME_CLOSE_INNER_GRANT_US },
                now_us: semio_framework_job::default_now_us,
            };
            match semio_framework_job::BatchJobSession::try_new(job, params) {
                Ok(session) => pump.session = Some(session),
                Err(rejected) => {
                    pump.rejected = Some(rejected);
                    return RuntimeMaintenanceStatus::Ready;
                }
            }
        }
        let Some(session) = pump.session.as_mut() else { return RuntimeMaintenanceStatus::Fault(RuntimeCleanupFault::MissingSession) };
        if session.step().is_err() {
            return RuntimeMaintenanceStatus::Fault(RuntimeCleanupFault::AbiMismatch);
        }
        if !session.checkout_outcome() {
            return RuntimeMaintenanceStatus::Fault(RuntimeCleanupFault::Checkout);
        }
        let Some(job) = session.checked_out_job_mut() else { return RuntimeMaintenanceStatus::Fault(RuntimeCleanupFault::CheckedOutJob) };
        pump.pending_status = runtime_live_cleanup_nonterminal_status(job.contended, job.progress, &cell.maintenance_stalled_steps);
        #[cfg(test)]
        if matches!(job.progress, Some(crate::app::PluginCloseStep::AwaitingInput { .. })) {
            cell.maintenance_probe_input_waits.fetch_add(1, Ordering::SeqCst);
        }
        let Some(outcome) = session.take_outcome() else { return RuntimeMaintenanceStatus::Fault(RuntimeCleanupFault::TakeOutcome) };
        pump.terminal = outcome.is_terminal();
        let faulted = matches!(outcome, semio_framework_job::StepOutcome::Fault(_) | semio_framework_job::StepOutcome::Cancelled);
        pump.faulted = faulted;
        pump.outcome = Some(outcome);
        RuntimeMaintenanceStatus::Ready
    }

    struct RuntimeCloseCleanupJob<PA: PluginApp> {
        state: Option<std::sync::Weak<RuntimeCloseWorkerState<PA>>>,
        progress: Option<crate::app::PluginCloseStep>,
        contended: bool,
        closing: bool,
    }

    impl<PA: PluginApp> semio_framework_job::InteractiveJob for RuntimeCloseCleanupJob<PA> {
        /// 🧹️ The live-maintenance session's own retirement is walked in BULK, not one item per
        /// job step: a job step is a pool pump, and the guest only gets a bounded number of
        /// those per reactor turn, so one item per step made the live pump's retained payload
        /// cost one browser round trip per item — the O(session) half of the 62–87 s close
        /// measured on 6018 (`🗑️generated/journey-5/console.txt`). Cut short by this step's own
        /// microsecond grant, so the batch is bounded in COST, never in items.
        fn step(&mut self, cx: &mut semio_framework_job::StepContext<'_>) -> semio_framework_job::StepOutcome {
            let Some(state) = self.state.as_ref().and_then(std::sync::Weak::upgrade) else {
                return semio_framework_job::StepOutcome::Cancelled;
            };
            runtime_close_phase(&state, 8);
            cx.set_stage("plugin-runtime-close-cleanup");
            runtime_close_phase(&state, 9);
            self.progress = None;
            self.contended = false;
            if cx.is_cancelled() {
                return semio_framework_job::StepOutcome::Cancelled;
            }
            let cell = {
                let cell = match state.cell.try_lock() {
                    Ok(cell) => cell,
                    Err(std::sync::TryLockError::WouldBlock) => {
                        self.contended = true;
                        return semio_framework_job::StepOutcome::Yield;
                    }
                    Err(std::sync::TryLockError::Poisoned(_)) => {
                        return semio_framework_job::StepOutcome::Fault(semio_framework_job::JobFault { detail: retained_job_payload(cx, semio_framework_job::JobPayloadStream::Fault, b"plugin close cell authority is poisoned") });
                    }
                };
                let Some(cell) = cell.as_ref() else {
                    self.progress = Some(crate::app::PluginCloseStep::Complete);
                    return semio_framework_job::StepOutcome::Complete(semio_framework_job::CommitCandidate {
                        state: retained_job_payload(cx, semio_framework_job::JobPayloadStream::CommitState, &state.instance_id.to_le_bytes()),
                        output: semio_framework_job::RetainedJobPayload::empty(semio_framework_job::JobPayloadStream::CommitOutput),
                    });
                };
                cell.clone()
            };
            {
                let mut maintenance = match cell.maintenance_pump.try_lock() {
                    Ok(maintenance) => maintenance,
                    Err(std::sync::TryLockError::WouldBlock) => {
                        self.contended = true;
                        return semio_framework_job::StepOutcome::Yield;
                    }
                    Err(std::sync::TryLockError::Poisoned(_)) => {
                        return semio_framework_job::StepOutcome::Fault(semio_framework_job::JobFault { detail: retained_job_payload(cx, semio_framework_job::JobPayloadStream::Fault, b"plugin maintenance session authority is poisoned") });
                    }
                };
                runtime_close_phase(&state, 10);
                let mut progress = maintenance.close_step(RUNTIME_CLOSE_ITEMS_PER_STEP, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES);
                let mut released_items = 0usize;
                let mut released_bytes = 0usize;
                while let semio_framework_job::InteractiveJobCloseStep::Pending { released_items: items, released_bytes: bytes } = progress {
                    released_items = released_items.saturating_add(items);
                    released_bytes = released_bytes.saturating_add(bytes);
                    if (items == 0 && bytes == 0) || maintenance.terminal_is_empty() || cx.deadline_exceeded() {
                        break;
                    }
                    progress = maintenance.close_step(RUNTIME_CLOSE_ITEMS_PER_STEP, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES);
                }
                runtime_close_phase(&state, 11);
                match progress {
                    semio_framework_job::InteractiveJobCloseStep::Pending { .. } => {
                        self.progress = Some(crate::app::PluginCloseStep::Pending { released_items, released_bytes });
                    }
                    semio_framework_job::InteractiveJobCloseStep::Blocked => self.contended = true,
                    semio_framework_job::InteractiveJobCloseStep::Complete => {}
                }
                if !maintenance.terminal_is_empty() {
                    cx.consume_fuel(1);
                    return semio_framework_job::StepOutcome::Yield;
                }
            }
            let mut instance = match cell.background_instance() {
                Ok(instance) => instance,
                Err(RuntimeInstanceRefusal::Contended) => {
                    self.contended = true;
                    return semio_framework_job::StepOutcome::Yield;
                }
                Err(RuntimeInstanceRefusal::Poisoned) => {
                    return semio_framework_job::StepOutcome::Fault(semio_framework_job::JobFault { detail: retained_job_payload(cx, semio_framework_job::JobPayloadStream::Fault, b"plugin app close authority is poisoned") });
                }
            };
            cx.consume_fuel(1);
            runtime_close_phase(&state, 12);
            #[cfg(test)]
            state.physical_close_calls.fetch_add(1, Ordering::SeqCst);
            let progress = instance.app.close_step(RUNTIME_CLOSE_ITEMS_PER_STEP, RUNTIME_CLOSE_BYTES_PER_STEP);
            runtime_close_phase(&state, 13);
            let outcome = match progress {
                Ok(progress @ crate::app::PluginCloseStep::Pending { released_items, released_bytes }) if released_items <= RUNTIME_CLOSE_ITEMS_PER_STEP && released_bytes <= RUNTIME_CLOSE_BYTES_PER_STEP => {
                    self.progress = Some(progress);
                    semio_framework_job::StepOutcome::CheckpointReady(semio_framework_job::Checkpoint {
                        state: retained_job_payload(cx, semio_framework_job::JobPayloadStream::CheckpointState, &state.instance_id.to_le_bytes()),
                        applied_progress: released_items as u64,
                    })
                }
                Ok(crate::app::PluginCloseStep::Pending { .. }) => {
                    semio_framework_job::StepOutcome::Fault(semio_framework_job::JobFault { detail: retained_job_payload(cx, semio_framework_job::JobPayloadStream::Fault, b"plugin close step exceeded its item or byte contract") })
                }
                Ok(progress @ crate::app::PluginCloseStep::Blocked { reason }) => {
                    runtime_close_pending_authority(reason);
                    self.progress = Some(progress);
                    semio_framework_job::StepOutcome::Yield
                }
                Ok(progress @ crate::app::PluginCloseStep::AwaitingInput { reason }) => {
                    runtime_close_pending_authority(reason);
                    self.progress = Some(progress);
                    semio_framework_job::StepOutcome::Yield
                }
                Ok(crate::app::PluginCloseStep::Complete) => {
                    if !instance.app.close_terminal_is_empty() {
                        return semio_framework_job::StepOutcome::Fault(semio_framework_job::JobFault {
                            detail: retained_job_payload(cx, semio_framework_job::JobPayloadStream::Fault, b"plugin close reported Complete without a terminal-empty app witness"),
                        });
                    }
                    self.progress = Some(crate::app::PluginCloseStep::Complete);
                    semio_framework_job::StepOutcome::Complete(semio_framework_job::CommitCandidate {
                        state: retained_job_payload(cx, semio_framework_job::JobPayloadStream::CommitState, &state.instance_id.to_le_bytes()),
                        output: semio_framework_job::RetainedJobPayload::empty(semio_framework_job::JobPayloadStream::CommitOutput),
                    })
                }
                Err(error) => semio_framework_job::StepOutcome::Fault(semio_framework_job::JobFault { detail: retained_job_payload(cx, semio_framework_job::JobPayloadStream::Fault, error.message.as_bytes()) }),
            };
            runtime_close_phase(&state, 14);
            outcome
        }

        fn begin_close(&mut self) {
            self.closing = true;
        }

        fn close_step(&mut self, maximum_items: usize, _maximum_bytes: usize) -> semio_framework_job::InteractiveJobCloseStep {
            self.closing = true;
            if self.state.is_some() {
                if maximum_items == 0 {
                    return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 0, released_bytes: 0 };
                }
                drop(self.state.take());
                return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            semio_framework_job::InteractiveJobCloseStep::Complete
        }

        fn terminal_is_empty(&self) -> bool {
            self.closing && self.state.is_none()
        }
    }

    fn runtime_close_pool() -> semio_framework_async::WorkerPool {
        let cores = std::thread::available_parallelism().map_or(1, std::num::NonZeroUsize::get);
        semio_framework_async::process_worker_pool(semio_framework_async::WorkerPoolConfig::new(semio_framework_async::ProcessKind::InteractiveNative, cores))
    }

    /// 🩺️ The structural accountant's verdict on ONE close-ladder step, priced in BOTH currencies it
    /// claims to spend: consecutive fruitless steps AND the real microseconds they burned.
    ///
    /// `progress` is what the ladder READ this step. `None` means the step recorded no reading at all —
    /// it was cancelled, or it never reached the ladder — which is an absence of evidence, not evidence
    /// of a stall, so it buys no stall debt; a cancelled or faulted outcome is terminal through
    /// `RuntimeCleanupFault::PriorOutcome` instead. Only an observed `Pending { 0, 0 }` — the ladder
    /// answered, and answered that it released nothing — is a stalled step.
    ///
    /// The fault needs both: `RUNTIME_CLOSE_ZERO_PROGRESS_LIMIT` consecutive stalled steps, and
    /// `RUNTIME_CLOSE_STALL_CREDIT_US` of real elapsed time since the ladder last moved. `stall_since_us`
    /// carries that instant (`0` = not stalling); the returned reading is the credit actually spent, so
    /// the emitted message quotes a measured stall rather than the unrelated cost of its last turn.
    fn runtime_close_stall_verdict(contended: bool, progress: Option<crate::app::PluginCloseStep>, stalled_steps: &AtomicU8, stall_since_us: &AtomicU64, now_us: Option<u64>) -> (RuntimeCloseStatus, u64) {
        let clear = || {
            stalled_steps.swap(0, Ordering::SeqCst);
            stall_since_us.store(0, Ordering::SeqCst);
        };
        if contended {
            return (RuntimeCloseStatus::Ready, 0);
        }
        if matches!(progress, Some(crate::app::PluginCloseStep::Blocked { .. } | crate::app::PluginCloseStep::AwaitingInput { .. })) {
            clear();
            return (RuntimeCloseStatus::ExternalWait, 0);
        }
        if !matches!(progress, Some(crate::app::PluginCloseStep::Pending { released_items: 0, released_bytes: 0 })) {
            clear();
            return (RuntimeCloseStatus::Ready, 0);
        }
        let stalled = stalled_steps.try_update(Ordering::SeqCst, Ordering::SeqCst, |seen| Some(seen.saturating_add(1))).unwrap_or(u8::MAX).saturating_add(1);
        let Some(now_us) = now_us else { return (RuntimeCloseStatus::Ready, 0) };
        let since_us = match stall_since_us.compare_exchange(0, now_us.max(1), Ordering::SeqCst, Ordering::SeqCst) {
            Ok(_) => now_us.max(1),
            Err(previous) => previous,
        };
        let credit_us = now_us.saturating_sub(since_us);
        if stalled >= RUNTIME_CLOSE_ZERO_PROGRESS_LIMIT && credit_us >= RUNTIME_CLOSE_STALL_CREDIT_US {
            (RuntimeCloseStatus::Fault(RuntimeCleanupFault::ZeroProgress), credit_us)
        } else {
            (RuntimeCloseStatus::Ready, credit_us)
        }
    }

    fn run_runtime_close_turn_inner<PA: PluginApp + 'static>(state: &std::sync::Arc<RuntimeCloseWorkerState<PA>>) -> Option<RuntimeCloseStatus> {
        if state.status.compare_exchange(RuntimeCloseStatus::Queued.repr(), RuntimeCloseStatus::Running.repr(), Ordering::SeqCst, Ordering::SeqCst).is_err() {
            return None;
        }
        let retained = state.deadline_resume.load(Ordering::SeqCst);
        if retained != u8::MAX {
            return Some(RuntimeCloseStatus::from_repr(retained));
        }
        #[cfg(test)]
        {
            state.callback_phase_started_us.store(semio_framework_job::default_now_us().unwrap_or(0), Ordering::SeqCst);
            for elapsed in &state.callback_phase_us {
                elapsed.store(0, Ordering::SeqCst);
            }
        }
        let status = match state.pump.try_lock() {
            Ok(mut pump) => {
                let status = runtime_close_cleanup_pump_one(state, &mut pump);
                runtime_close_phase(state, 20);
                drop(pump);
                runtime_close_phase(state, 21);
                status
            }
            Err(_) => RuntimeCloseStatus::Ready,
        };
        runtime_close_phase(state, 6);
        let candidate = if status == RuntimeCloseStatus::Complete { runtime_close_retire_cell(state) } else { status };
        runtime_close_phase(state, 7);
        Some(candidate)
    }

    fn runtime_close_retire_cell<PA: PluginApp>(state: &RuntimeCloseWorkerState<PA>) -> RuntimeCloseStatus {
        let mut owner = match state.cell.try_lock() {
            Ok(owner) => owner,
            Err(std::sync::TryLockError::WouldBlock) => return RuntimeCloseStatus::Ready,
            Err(std::sync::TryLockError::Poisoned(_)) => return runtime_close_fault(state, RuntimeCleanupFault::OwnerPoisoned),
        };
        let Some(cell) = owner.as_ref() else { return RuntimeCloseStatus::Complete };
        {
            let instance = match cell.background_instance() {
                Ok(instance) => instance,
                Err(RuntimeInstanceRefusal::Contended) => return RuntimeCloseStatus::Ready,
                Err(RuntimeInstanceRefusal::Poisoned) => return runtime_close_fault(state, RuntimeCleanupFault::InstancePoisoned),
            };
            if !instance.app.close_terminal_is_empty() {
                return runtime_close_fault(state, RuntimeCleanupFault::InstanceNotDrained);
            }
            let maintenance = match cell.maintenance_pump.try_lock() {
                Ok(maintenance) => maintenance,
                Err(std::sync::TryLockError::WouldBlock) => return RuntimeCloseStatus::Ready,
                Err(std::sync::TryLockError::Poisoned(_)) => return runtime_close_fault(state, RuntimeCleanupFault::MaintenancePoisoned),
            };
            if !maintenance.terminal_is_empty() {
                return runtime_close_fault(state, RuntimeCleanupFault::MaintenanceNotDrained);
            }
        }
        let detached = owner.take().expect("captured owner remains under the same guard");
        match std::sync::Arc::try_unwrap(detached) {
            Ok(cell) => {
                drop(cell);
                RuntimeCloseStatus::Complete
            }
            Err(detached) => {
                **owner = Some(detached);
                RuntimeCloseStatus::ExternalWait
            }
        }
    }

    /// ⏳️ A close authority that is not yet releasable is a WAIT, never a fault: the ladder keeps
    /// stepping until its external owner lets go (mirrors the live cleanup job, which has always
    /// yielded on `Blocked`). Reported on a doubling cadence so a genuinely stuck owner is visible
    /// without flooding a close that clears after a few turns.
    fn runtime_close_pending_authority(reason: &'static str) {
        let seen = RUNTIME_CLOSE_PENDING_AUTHORITY_TURNS.fetch_add(1, Ordering::Relaxed).saturating_add(1);
        if seen.is_power_of_two() {
            debug_runtime_line(format_args!("[TRACE] runtime close pending authority turn={seen} reason={reason}"));
        }
    }

    static RUNTIME_CLOSE_PENDING_AUTHORITY_TURNS: AtomicU64 = AtomicU64::new(0);

    fn runtime_close_fault<PA: PluginApp>(state: &RuntimeCloseWorkerState<PA>, cause: RuntimeCleanupFault) -> RuntimeCloseStatus {
        #[cfg(test)]
        state.last_fault_origin.store(cause as u8, Ordering::SeqCst);
        #[cfg(not(test))]
        let _ = state;
        RuntimeCloseStatus::Fault(cause)
    }

    fn runtime_close_phase<PA: PluginApp>(state: &RuntimeCloseWorkerState<PA>, phase: usize) {
        #[cfg(test)]
        if let Some(now) = semio_framework_job::default_now_us() {
            state.callback_phase_us[phase].store(now.saturating_sub(state.callback_phase_started_us.load(Ordering::SeqCst)), Ordering::SeqCst);
        }
        #[cfg(not(test))]
        let _ = (state, phase);
    }

    fn runtime_close_cleanup_pump_one<PA: PluginApp + 'static>(state: &std::sync::Arc<RuntimeCloseWorkerState<PA>>, pump: &mut RuntimeCloseCleanupPump<PA>) -> RuntimeCloseStatus {
        runtime_close_phase(state, 0);
        if let Some(rejected) = pump.rejected.as_mut() {
            let _ = rejected.close_step(1, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES);
            runtime_close_phase(state, 5);
            if rejected.terminal_is_empty() {
                pump.rejected = None;
                return runtime_close_fault(state, RuntimeCleanupFault::AdmissionRejected);
            }
            return RuntimeCloseStatus::Ready;
        }
        if let Some(outcome) = pump.outcome.as_mut() {
            let _ = outcome.close_step(1, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES);
            runtime_close_phase(state, 5);
            runtime_close_phase(state, 15);
            let terminal = outcome.terminal_is_empty();
            runtime_close_phase(state, 16);
            if !terminal {
                return RuntimeCloseStatus::Ready;
            }
            pump.outcome = None;
            runtime_close_phase(state, 17);
            if pump.terminal {
                if let Some(session) = pump.session.as_mut() {
                    session.begin_close();
                }
            } else {
                runtime_close_phase(state, 18);
                let failed = pump.session.as_mut().is_some_and(|session| session.resume().is_err());
                runtime_close_phase(state, 19);
                return if failed { runtime_close_fault(state, RuntimeCleanupFault::Resume) } else { pump.pending_status };
            }
        }
        if pump.terminal {
            let Some(session) = pump.session.as_mut() else { return runtime_close_fault(state, RuntimeCleanupFault::MissingSession) };
            let _ = session.close_step(1, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES);
            runtime_close_phase(state, 5);
            if !session.terminal_is_empty() {
                return RuntimeCloseStatus::Ready;
            }
            pump.session = None;
            pump.terminal = false;
            if pump.faulted {
                return runtime_close_fault(state, RuntimeCleanupFault::PriorOutcome);
            }
            if pump.blocked {
                return RuntimeCloseStatus::ExternalWait;
            }
            if pump.complete {
                return RuntimeCloseStatus::Complete;
            }
            return pump.pending_status;
        }
        if pump.session.is_none() {
            runtime_close_phase(state, 1);
            let job = RuntimeCloseCleanupJob { state: Some(std::sync::Arc::downgrade(state)), progress: None, contended: false, closing: false };
            let params = semio_framework_job::BatchJobParams {
                operation: semio_framework_job::OperationId((1u64 << 63) | state.instance_id as u64),
                generation: state.generation,
                cancel: semio_framework_job::CancelToken::root_now(),
                config: semio_framework_job::BatchDriveConfig { site: "plugin_runtime_close_cleanup", stage: semio_framework_job::InteractiveStage::InteractiveStep, fuel_per_step: 1, step_budget_us: RUNTIME_CLOSE_INNER_GRANT_US },
                now_us: semio_framework_job::default_now_us,
            };
            match semio_framework_job::BatchJobSession::try_new(job, params) {
                Ok(session) => pump.session = Some(session),
                Err(rejected) => {
                    pump.rejected = Some(rejected);
                    return RuntimeCloseStatus::Ready;
                }
            }
            runtime_close_phase(state, 2);
        }
        let Some(session) = pump.session.as_mut() else { return runtime_close_fault(state, RuntimeCleanupFault::MissingSession) };
        runtime_close_phase(state, 22);
        let stepped = session.step();
        runtime_close_phase(state, 23);
        if stepped.is_err() {
            return runtime_close_fault(state, RuntimeCleanupFault::AbiMismatch);
        }
        runtime_close_phase(state, 3);
        if !session.checkout_outcome() {
            return runtime_close_fault(state, RuntimeCleanupFault::Checkout);
        }
        let Some(job) = session.checked_out_job_mut() else { return runtime_close_fault(state, RuntimeCleanupFault::CheckedOutJob) };
        pump.complete = job.progress == Some(crate::app::PluginCloseStep::Complete);
        pump.blocked = matches!(job.progress, Some(crate::app::PluginCloseStep::Blocked { .. }));
        let (status, credit_us) = runtime_close_stall_verdict(job.contended, job.progress, &state.stalled_steps, &state.stall_since_us, semio_framework_job::default_now_us());
        pump.pending_status = status;
        if let Some(cause) = pump.pending_status.cause() {
            state.stall_credit_spent_us.store(credit_us, Ordering::SeqCst);
            runtime_close_fault(state, cause);
        }
        let Some(outcome) = session.take_outcome() else { return runtime_close_fault(state, RuntimeCleanupFault::TakeOutcome) };
        runtime_close_phase(state, 4);
        pump.terminal = outcome.is_terminal();
        let faulted = matches!(outcome, semio_framework_job::StepOutcome::Fault(_) | semio_framework_job::StepOutcome::Cancelled);
        pump.faulted = faulted;
        #[cfg(test)]
        if let semio_framework_job::StepOutcome::Fault(fault) = &outcome {
            if let Some(bytes) = fault.detail.single_page() {
                let mut last_fault = state.last_fault.lock().unwrap();
                let count = bytes.len().min(last_fault.len());
                last_fault[..count].copy_from_slice(&bytes[..count]);
            }
        }
        pump.outcome = Some(outcome);
        RuntimeCloseStatus::Ready
    }

