        pub completion: ArtifactToolCompletion<A>,
    }

    pub trait ArtifactSnapshotDisposer<T>: Send {
        fn close_step(&mut self, snapshot: &mut Option<std::sync::Arc<T>>, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault>;
        fn terminal_is_empty(&self, snapshot: &Option<std::sync::Arc<T>>) -> bool;
    }

    /// 🧹️ Optional exact-owner disposer retained until the associated artifact value is empty.
    pub type ArtifactDisposal<T> = Option<Box<dyn ArtifactOwnedDisposer<T>>>;

    /// 📬️ Mutation emission paired with its operation failure, without changing ownership.
    pub type ArtifactMutationOutcome<M, C = NoConfigMutation, D = NoDraftMutation, E = Fault> = Result<Emit<M, C, D>, E>;

    /// 🏗️ Admits initialization or returns the original document envelope.
    pub type ArtifactInitializationAdmission<S, M> = Result<ArtifactStoreInitializationJob<S, M>, ArtifactEnvelope<S, M>>;

    /// 📬️ Completed document mutations paired with their ephemeral output.
    type ArtifactToolEmission<A> = (ArtifactMutationOutcome<<A as ArtifactApp>::Mutation, <A as ArtifactApp>::ConfigMutation, <A as ArtifactApp>::DraftMutation>, EphemeralEmit<A>);

    /// 📖️ Non-capturing provider of one document schema, its semantic mutation roster and, row for row, each
    /// kind's leaf payload JSON Schema (`Mutation::INPUT_SCHEMAS`; shorter or empty when the aggregate publishes none).
    pub type OwnerMutationRoster = fn() -> (&'static str, &'static [protocol::SemanticDescriptor], &'static [&'static str]);

    pub trait ArtifactOwnedDisposer<T>: Send {
        fn close_step(&mut self, owner: &mut T, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault>;
        fn terminal_is_empty(&self, owner: &T) -> bool;
    }

    //#region 🎛️BoundedConfigStoreOwners
    struct BoundedConfigValueRetirement<T> {
        value: std::mem::ManuallyDrop<Option<T>>,
    }

    impl<T: Send + 'static> store::ErasedSnapshotRetirement for BoundedConfigValueRetirement<T> {
        fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<store::SnapshotRetirementStep, semio_framework_value::ValueError> {
            if maximum_items == 0 || maximum_bytes < store::ARTIFACT_ENVELOPE_DECODE_PAGE_BYTES {
                return Ok(store::SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
            }
            if let Some(value) = self.value.take() {
                drop(value);
                return Ok(store::SnapshotRetirementStep::Pending { released_items: 1, released_bytes: store::ARTIFACT_ENVELOPE_DECODE_PAGE_BYTES });
            }
            Ok(store::SnapshotRetirementStep::Complete)
        }

        fn terminal_is_empty(&self) -> bool {
            self.value.is_none()
        }
    }

    impl<T> Drop for BoundedConfigValueRetirement<T> {
        fn drop(&mut self) {
            assert!(std::thread::panicking() || self.value.is_none(), "bounded config value retirement reached Drop before exact terminal emptiness");
        }
    }

    struct BoundedConfigRetirementFactory<T>(std::marker::PhantomData<fn() -> T>);

    impl<T> BoundedConfigRetirementFactory<T> {
        fn new() -> Self {
            Self(std::marker::PhantomData)
        }
    }

    impl<T: Send + 'static> store::ArtifactOwnedValueRetirementFactory<T> for BoundedConfigRetirementFactory<T> {
        fn retire_owned(&self, value: T) -> Box<dyn store::ErasedSnapshotRetirement> {
            Box::new(BoundedConfigValueRetirement { value: std::mem::ManuallyDrop::new(Some(value)) })
        }
    }

    impl<T: Send + Sync + 'static> store::SnapshotRetirementFactory<T> for BoundedConfigRetirementFactory<T> {
        fn retire(&self, snapshot: std::sync::Arc<T>) -> Box<dyn store::ErasedSnapshotRetirement> {
            Box::new(BoundedConfigValueRetirement { value: std::mem::ManuallyDrop::new(Some(snapshot)) })
        }
    }

    /// 🎛️ Exact one-page retirement catalog for explicitly bounded app configuration stores.
    pub fn bounded_config_store_owners<C, M>() -> store::DocumentStoreOwners<C, M>
    where
        C: Clone + protocol::ToValue + protocol::FromValue + ArtifactPack + Send + Sync + 'static,
        M: Clone + protocol::ToValue + protocol::FromValue + Mutation<C> + OpBinary + OpText + Send + 'static,
    {
        store::bounded_artifact_store_owners::<C, M>()
    }

    /// 🎛️ Exact one-item PUBLICATION authority for an explicitly bounded app configuration store —
    /// the publication twin of [`bounded_config_store_owners`], which only supplies retirement.
    /// Without one, `ArtifactApp::build_config_store_one_item_preparation_factory` stays `None` and
    /// EVERY tool declaring the `config` publication lane fails closed with
    /// `interactive-job.publication-authority-missing` (ticket 26/09/09/PROCEDURAL-3D-END-TO-END:
    /// that is exactly what made every generation3d viewer action undispatchable).
    ///
    /// `prefix` labels the minted edit ids; `maximum_bytes` is the admission envelope a single
    /// encoded config mutation may occupy.
    pub fn bounded_config_store_one_item_preparation_factory<C, M>(prefix: &'static str, maximum_bytes: usize) -> std::sync::Arc<dyn store::ArtifactStoreOneItemPreparationFactory<C, M>>
    where
        C: Clone + Send + Sync + 'static,
        M: Clone + OpBinary + Mutation<C> + Send + Sync + 'static,
    {
        std::sync::Arc::new(BoundedConfigPreparationFactory::<C, M> { prefix, maximum_bytes, marker: std::marker::PhantomData })
    }

    struct BoundedConfigPreparationFactory<C, M> {
        prefix: &'static str,
        maximum_bytes: usize,
        marker: std::marker::PhantomData<fn() -> (C, M)>,
    }

    struct BoundedConfigPreparation<C, M> {
        prefix: &'static str,
        maximum_bytes: usize,
        base: Option<store::SnapshotRead<C>>,
        mutation: Option<M>,
        description: Option<String>,
        authority: Option<std::sync::Arc<store::ArtifactStoreOneItemLiveAuthority>>,
        prepared: Option<store::ArtifactStoreOneItemPrepared<C, M>>,
        checkpoint: store::ArtifactStoreOneItemCheckpoint,
        retained_bytes: usize,
        cancelled: bool,
        closing: bool,
    }

    fn bounded_config_mutation_retained_bytes<M: OpBinary>(prefix: &str, mutation: &M) -> Result<usize, String> {
        ::protocol::OpBinary::encode_op(mutation).map(|bytes| bytes.len()).map_err(|_| format!("{prefix}-mutation-encode-failed"))
    }

    /// 🧺️ The ONE fold-contract declaration every bounded config lane makes: the mutation's own
    /// forward row plus its schema-declared inverse rows ([`store::ArtifactStoreOneItemFootprint::for_leaf`],
    /// design §20.5), so `ArtifactStore::fold_batch_item` measures exactly what the lane declares.
    fn admit_bounded_config_mutation<C, M: OpBinary + Mutation<C>>(prefix: &str, maximum_bytes: usize, mutation: &M) -> Result<store::ArtifactStoreOneItemFootprint, String> {
        let retained_bytes = bounded_config_mutation_retained_bytes(prefix, mutation)?;
        if retained_bytes > maximum_bytes {
            return Err(format!("{prefix}-mutation-envelope"));
        }
        Ok(store::ArtifactStoreOneItemFootprint::for_leaf::<C, M>(mutation, retained_bytes))
    }

    impl<C, M> store::ArtifactStoreOneItemPreparationFactory<C, M> for BoundedConfigPreparationFactory<C, M>
    where
        C: Clone + Send + Sync + 'static,
        M: Clone + OpBinary + Mutation<C> + Send + Sync + 'static,
    {
        fn preflight(&self, mutation: &M, description: Option<&str>, lane: HistoryLane) -> Result<store::ArtifactStoreOneItemFootprint, String> {
            if lane != HistoryLane::Document || description.is_some_and(|value| value.len() > store::ARTIFACT_STORE_ONE_ITEM_ID_BYTES) {
                return Err(format!("{}-lane-or-description-envelope", self.prefix));
            }
            admit_bounded_config_mutation::<C, M>(self.prefix, self.maximum_bytes, mutation)
        }

        fn begin(&self, request: store::ArtifactStoreOneItemPreparationRequest<C, M>) -> Result<Box<dyn store::ArtifactStoreOneItemPreparation<C, M>>, store::ArtifactStoreOneItemPreparationRequest<C, M>> {
            let retained_bytes = bounded_config_mutation_retained_bytes(self.prefix, &request.mutation).unwrap_or(self.maximum_bytes.saturating_add(1));
            if request.lane != HistoryLane::Document
                || request.operation != request.authority.operation()
                || request.generation != request.authority.generation()
                || request.base_revision != request.authority.base_revision()
                || request.authority.actor().len() > store::ARTIFACT_STORE_ONE_ITEM_ID_BYTES
                || retained_bytes > self.maximum_bytes
            {
                return Err(request);
            }
            Ok(Box::new(BoundedConfigPreparation::<C, M> {
                prefix: self.prefix,
                maximum_bytes: self.maximum_bytes,
                base: Some(request.base),
                mutation: Some(request.mutation),
                description: request.description,
                authority: Some(request.authority),
                prepared: None,
                checkpoint: store::ArtifactStoreOneItemCheckpoint::default(),
                retained_bytes,
                cancelled: false,
                closing: false,
            }))
        }
    }

    impl<C, M> store::ArtifactStoreOneItemPreparation<C, M> for BoundedConfigPreparation<C, M>
    where
        C: Clone + Send + Sync + 'static,
        M: Clone + OpBinary + Mutation<C> + Send + Sync + 'static,
    {
        fn advance(&mut self, grant: store::ArtifactStoreOneItemGrant) -> Result<store::ArtifactStoreOneItemPreparationStep, String> {
            if !grant.permits_one() || self.cancelled {
                return Ok(store::ArtifactStoreOneItemPreparationStep::Blocked);
            }
            if self.prepared.is_some() {
                return Ok(store::ArtifactStoreOneItemPreparationStep::Prepared(self.checkpoint));
            }
            let base = self.base.as_ref().ok_or_else(|| format!("{}-base-owner-missing", self.prefix))?;
            let mutation = self.mutation.take().ok_or_else(|| format!("{}-mutation-owner-missing", self.prefix))?;
            admit_bounded_config_mutation::<C, M>(self.prefix, self.maximum_bytes, &mutation)?;
            let inverse = Mutation::inverse(&mutation, base.get());
            let diff = Mutation::diff(&mutation, base.get()).into_parts().0;
            let post = MutationDiff::apply(&diff, base.get()).map_err(|_| format!("{}-diff-apply-failed", self.prefix))?;
            let authority = self.authority.as_ref().ok_or_else(|| format!("{}-authority-missing", self.prefix))?;
            let edit = authority.next_edit(mutation, inverse);
            let prepared = authority.prepare_one_item(edit, std::sync::Arc::new(post))?;
            self.checkpoint = store::ArtifactStoreOneItemCheckpoint { cursor: 1, completed_items: 1, completed_bytes: self.retained_bytes as u64, digest: prepared.edit_digest() };
            self.prepared = Some(prepared);
            Ok(store::ArtifactStoreOneItemPreparationStep::Prepared(self.checkpoint))
        }

        fn checkpoint(&self) -> store::ArtifactStoreOneItemCheckpoint {
            self.checkpoint
        }

        fn prepared(&self) -> Option<&store::ArtifactStoreOneItemPrepared<C, M>> {
            self.prepared.as_ref()
        }

        fn take_prepared(&mut self) -> Option<store::ArtifactStoreOneItemPrepared<C, M>> {
            self.prepared.take()
        }

        fn cancel(&mut self) {
            self.cancelled = true;
        }

        fn begin_close(&mut self) {
            self.closing = true;
        }

        fn close_step(&mut self, grant: store::ArtifactStoreOneItemGrant) -> Result<store::SnapshotRetirementStep, semio_framework_value::ValueError> {
            if !self.closing || grant.maximum_items == 0 {
                return Ok(store::SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
            }
            if self.prepared.take().is_some() || self.mutation.take().is_some() {
                return Ok(store::SnapshotRetirementStep::Pending { released_items: 1, released_bytes: self.retained_bytes });
            }
            if self.description.take().is_some() {
                return Ok(store::SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if let Some(base) = self.base.take() {
                if !base.return_to_registry() {
                    return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, format!("{}-base-retirement-rejected", self.prefix)));
                }
                return Ok(store::SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if self.authority.take().is_some() {
                return Ok(store::SnapshotRetirementStep::Pending { released_items: 1, released_bytes: store::ARTIFACT_STORE_ONE_ITEM_ID_BYTES });
            }
            Ok(store::SnapshotRetirementStep::Complete)
        }

        fn terminal_is_empty(&self) -> bool {
            self.closing && self.base.is_none() && self.mutation.is_none() && self.description.is_none() && self.authority.is_none() && self.prepared.is_none()
        }
    }

