        /// 📃️ One bounded unit of the live local-interaction query. Its own captured roots are the
        /// only ownership it advances: the Store-side reclamation of the leases it hands back is
        /// [`Self::advance_snapshot_read_returns_one`]'s cooperative-maintenance business, because a
        /// registry's one-slot-per-step cleanup cursor is bounded by the registry's fixed capacity
        /// and would otherwise put a whole capacity's worth of probes inside a host continuation
        /// budget before a read could publish its terminal reply.
        fn advance_local_interaction_query_one(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            if maximum_items == 0 {
                return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            }
            match self.local_interaction_query.as_mut() {
                None => Ok(PluginCloseStep::Complete),
                Some(query) => query.advance(store::ArtifactStoreOneItemGrant { maximum_items: 1, maximum_bytes }).map_err(|error| plugin_sdk_fault(error.to_string())).map(|step| match step {
                    crate::local_interaction::live::LocalInteractionLiveStep::Complete => PluginCloseStep::Complete,
                    crate::local_interaction::live::LocalInteractionLiveStep::Blocked => PluginCloseStep::Blocked { reason: "local interaction query awaits admission, ACK, or exact root return" },
                    crate::local_interaction::live::LocalInteractionLiveStep::Advanced { emitted_bytes, retired_bytes, released_items } => {
                        self.local_interaction_emitted_bytes += emitted_bytes as u128;
                        self.local_interaction_retired_bytes += retired_bytes as u128;
                        PluginCloseStep::Pending { released_items, released_bytes: retired_bytes }
                    }
                }),
            }
        }

        /// ♻️ One bounded unit of the fixed document/config/interaction returned-read rotation: each
        /// pump either drains the disposer it owns or probes its Store for the next returned lease.
        fn advance_snapshot_read_returns_one(&mut self, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            let stage = self.snapshot_read_return_stage;
            self.snapshot_read_return_stage = (stage + 1) % 3;
            match stage {
                0 => self.document_snapshot_read_returns.drive(|| self.store.take_returned_snapshot_read_retirement().map_err(|error| error.into_fault()), 1, maximum_bytes),
                1 => self.config_snapshot_read_returns.drive(|| self.config_store.take_returned_snapshot_read_retirement().map_err(|error| error.into_fault()), 1, maximum_bytes),
                _ => self.interaction_snapshot_read_returns.drive(|| self.interaction_store.take_returned_snapshot_read_retirement().map_err(|error| error.into_fault()), 1, maximum_bytes),
            }
        }

        /// ♻️ Reclaims the document Store's returned snapshot reads before a batched publication folds its next item:
        /// `true` once no returned root is left (or the one left is still shared elsewhere), `false` when `steps` ran
        /// out first and the caller must yield instead of folding.
        ///
        /// 🐛️ Every batch item is prepared against a registry lease on the previous item's post root, and the registry
        /// keeps that root alive after the lease returns until a pump takes it. The maintenance rotation reclaims one
        /// returned read per rotation at one item per step, while a publication folds an item every turn — so a
        /// 408-placement fill finalize (816 ops over a 409-object puzzle 3d document) retained one ~5 MB root per
        /// folded op and trapped the guest at its 512 MiB ceiling (`memory allocation of 1232 bytes failed`, ticket
        /// 26/09/13/INTERACTIVE-TOOLS-VISIBLE-PROCESS). Draining here bounds a publication to the staged root plus the
        /// base its current item reads, whatever the batch size.
        ///
        /// A disposer that waits on outside ownership cannot be hurried here; the publication must not stall on it.
        pub(crate) fn reclaim_document_snapshot_read_returns(&mut self, steps: usize) -> Result<bool, Fault> {
            for _ in 0..steps {
                match self.document_snapshot_read_returns.drive(|| self.store.take_returned_snapshot_read_retirement().map_err(|error| error.into_fault()), PUBLICATION_SNAPSHOT_READ_RECLAIM_ITEMS, PUBLICATION_SNAPSHOT_READ_RECLAIM_BYTES)? {
                    PluginCloseStep::Pending { .. } => {}
                    _ => return Ok(true),
                }
            }
            Ok(self.document_snapshot_read_returns.terminal_is_empty() && self.store.returned_snapshot_read_count() == 0)
        }

        /// 🪹️ No returned-read disposer is held by any of the three fixed capture-store pumps.
        fn snapshot_read_returns_terminal_is_empty(&self) -> bool {
            self.document_snapshot_read_returns.terminal_is_empty() && self.config_snapshot_read_returns.terminal_is_empty() && self.interaction_snapshot_read_returns.terminal_is_empty()
        }

        /// 🕰️ The fixed maintenance stage the NEXT [`PluginApp::maintenance_step`] call will run.
        /// A step-budget law reads this before each unit so an over-budget unit names its own stage
        /// instead of the stale round-robin cursor an idle early return leaves behind.
        pub fn next_maintenance_stage(&self) -> u8 {
            self.maintenance_stage
        }

        /// 🎟️ Pre-admits the exact page and byte extent before a producer constructs any
        /// envelope input owner. Occupied fixed slots and allocation failure leave no input owner.
        pub fn begin_artifact_envelope_ingress(&mut self, maximum_pages: usize, maximum_bytes: usize) -> Result<ArtifactEnvelopeDecodeOperationHandle, Fault> {
            let generation = self.artifact_generation_now();
            let Some(slot) = (0..ARTIFACT_LIVE_OUTPUT_SLOTS).find(|slot| self.envelope_ingress.slot_is_vacant(*slot) && self.envelope_decode_jobs.slot_is_vacant(*slot) && self.store_replacement_jobs.slot_is_vacant(*slot)) else {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.ingress-saturated"), "every fixed artifact envelope ingress slot already owns a live operation"));
            };
            let operation = semio_framework_job::allocate_operation_id_in_slot(ARTIFACT_LIVE_OUTPUT_SLOTS as u64, slot as u64);
            let pages = store::OwnedSchemaDecodePages::try_with_credits(store::OwnedSchemaDecodeCredits { maximum_pages, maximum_bytes })
                .map_err(|fault| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.ingress-credits"), format!("artifact envelope ingress credits were rejected: {fault:?}")))?;
            self.envelope_ingress.insert_admitted(operation.0, ActiveArtifactEnvelopeIngress::new(pages));
            Ok(ArtifactEnvelopeDecodeOperationHandle { operation, generation })
        }

        /// 📦️ Admits one already-decoded authoritative `.pack` + `.spr` envelope directly
        /// into the app-owned retained initializer. This path preserves the binary document format;
        /// the fresh JSON envelope decoder remains a separate ingress contract.
        #[expect(clippy::result_large_err, reason = "Refusal returns the exact decoded envelope so its domain retirement catalog can close every nested owner.")]
        fn begin_persisted_document_store_replacement(&mut self, envelope: ArtifactEnvelope<A::Snapshot, A::Mutation>) -> Result<ArtifactEnvelopeDecodeOperationHandle, (Fault, ArtifactEnvelope<A::Snapshot, A::Mutation>)> {
            let generation = self.artifact_generation_now();
            let expected_dialect: ArtifactDialect = A::DIALECT.into();
            if envelope.schema != A::DOCUMENT_SCHEMA || envelope.dialect.as_ref() != Some(&expected_dialect) {
                return Err((Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-store.persisted-envelope-identity"), "persisted document envelope does not match the app's exact schema and dialect"), envelope));
            }
            let Some(slot) = (0..ARTIFACT_LIVE_OUTPUT_SLOTS).find(|slot| self.envelope_ingress.slot_is_vacant(*slot) && self.envelope_decode_jobs.slot_is_vacant(*slot) && self.store_replacement_jobs.slot_is_vacant(*slot)) else {
                return Err((Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-store.persisted-ingress-saturated"), "every fixed persisted document replacement slot already owns a live operation"), envelope));
            };
            let operation = semio_framework_job::allocate_operation_id_in_slot(ARTIFACT_LIVE_OUTPUT_SLOTS as u64, slot as u64);
            let job = match A::build_document_store_initialization_job(envelope, operation, generation) {
                Ok(job) => job,
                Err(envelope) => {
                    return Err((Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-store.persisted-initializer-refused"), "app refused the persisted document's retained initialization authority"), envelope));
                }
            };
            self.store_replacement_jobs.insert_admitted(operation.0, ActiveArtifactStoreReplacement::new(operation, generation, self.child_content_generation, job));
            Ok(ArtifactEnvelopeDecodeOperationHandle { operation, generation })
        }

        /// 🔎️ Rejects stale, closed, full, or over-byte page ingress before the producer copies its raw owner.
        pub fn preflight_artifact_envelope_ingress_page(&self, handle: ArtifactEnvelopeDecodeOperationHandle, page_bytes: usize) -> Result<(), Fault> {
            if self.artifact_generation_now() != handle.generation {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.ingress-stale"), "artifact envelope generation changed before page preflight"));
            }
            let ingress = self.envelope_ingress.get(handle.operation.0).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.ingress-handle"), "unknown artifact envelope ingress handle"))?;
            if ingress.closing {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.ingress-closing"), "artifact envelope ingress is closing"));
            }
            ingress
                .pages
                .as_ref()
                .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.ingress-owner"), "artifact envelope ingress lost its exact page authority"))?
                .preflight_page_bytes(page_bytes)
                .map_err(|fault| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.ingress-page"), format!("artifact envelope page preflight was rejected before owner construction: {fault:?}")))
        }

        /// 📨️ Runs the bounded page producer only after the same mutable ingress authority accepts its extent.
        pub fn construct_and_admit_artifact_envelope_ingress_page<Build>(&mut self, handle: ArtifactEnvelopeDecodeOperationHandle, page_bytes: usize, build: Build) -> Result<(), Fault>
        where
            Build: FnOnce() -> store::ArtifactEnvelopeDecodePage,
        {
            self.preflight_artifact_envelope_ingress_page(handle, page_bytes)?;
            let ingress = self.envelope_ingress.get_mut(handle.operation.0).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.ingress-handle"), "unknown artifact envelope ingress handle after preflight"))?;
            let pages = ingress.pages.as_mut().ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.ingress-owner"), "artifact envelope ingress lost its exact page authority after preflight"))?;
            build().admit_preflighted_into(pages);
            Ok(())
        }

        /// 📥️ Moves one exact fixed page into a pre-admitted operation or returns that page
        /// untouched with the fault. No page clone or aggregate command buffer is constructed.
        #[expect(clippy::result_large_err, reason = "Refusal returns the original fixed-capacity input so its caller can retry or retire that exact owner without an extra allocation.")]
        pub fn admit_artifact_envelope_ingress_page(&mut self, handle: ArtifactEnvelopeDecodeOperationHandle, page: store::ArtifactEnvelopeDecodePage) -> Result<(), (Fault, store::ArtifactEnvelopeDecodePage)> {
            if self.artifact_generation_now() != handle.generation {
                return Err((Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.ingress-stale"), "artifact envelope generation changed before page admission"), page));
            }
            let Some(ingress) = self.envelope_ingress.get_mut(handle.operation.0) else {
                return Err((Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.ingress-handle"), "unknown artifact envelope ingress handle"), page));
            };
            if ingress.closing {
                return Err((Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.ingress-closing"), "artifact envelope ingress is closing"), page));
            }
            let Some(pages) = ingress.pages.as_mut() else {
                return Err((Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.ingress-owner"), "artifact envelope ingress lost its exact page authority"), page));
            };
            page.admit_into(pages).map_err(|(fault, page)| (Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.ingress-page"), format!("artifact envelope page was rejected untouched: {fault:?}")), page))
        }

        /// 🔒️ Seals and transfers the exact page authority into the retained decoder. A
        /// saturated decoder keeps the sealed ingress owner in its original fixed slot for retry.
        pub fn seal_artifact_envelope_ingress(&mut self, handle: ArtifactEnvelopeDecodeOperationHandle) -> Result<bool, Fault> {
            if self.artifact_generation_now() != handle.generation {
                self.cancel_artifact_envelope_load(handle)?;
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.ingress-stale"), "artifact envelope generation changed before sealing"));
            }
            if !self.envelope_decode_jobs.can_insert(handle.operation.0) {
                return Ok(false);
            }
            {
                let ingress = self.envelope_ingress.get_mut(handle.operation.0).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.ingress-handle"), "unknown artifact envelope ingress handle"))?;
                if ingress.closing {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.ingress-closing"), "artifact envelope ingress is closing"));
                }
                let pages = ingress.pages.as_mut().ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.ingress-owner"), "artifact envelope ingress lost its exact page authority"))?;
                if !pages.is_sealed() {
                    pages.seal().map_err(|fault| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.ingress-seal"), format!("artifact envelope ingress could not seal: {fault:?}")))?;
                }
            }
            let mut ingress = self.envelope_ingress.remove(handle.operation.0).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.ingress-owner"), "artifact envelope ingress changed before exact transfer"))?;
            let pages = ingress.take_pages().ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.ingress-owner"), "artifact envelope ingress lost its exact transfer owner"))?;
            match self.submit_artifact_envelope_decode(handle.operation, handle.generation, pages) {
                Ok(submitted) if submitted == handle => {
                    drop(ingress);
                    Ok(true)
                }
                Ok(_) => unreachable!("exact envelope transfer preserves its operation and generation"),
                Err(pages) => {
                    *ingress.pages = Some(pages);
                    self.envelope_ingress.insert_admitted(handle.operation.0, ingress);
                    Ok(false)
                }
            }
        }

        /// 🔄️ Advances decode-to-initializer handoff without running either job inline. A decode that
        /// has not reached [`ArtifactEnvelopeDecodeOperationPoll::Ready`] reports its OWN poll — the
        /// store replacement it will hand to does not exist yet, and reading that absent job here
        /// turned every in-progress decode into a terminal `Fault` for all eight plugin loops
        /// (ticket 26/09/09/PROCEDURAL-3D-END-TO-END).
        pub fn advance_artifact_envelope_load(&mut self, handle: ArtifactEnvelopeDecodeOperationHandle) -> Result<ArtifactEnvelopeDecodeOperationPoll, Fault> {
            if let Some(active) = self.store_replacement_jobs.get(handle.operation.0) {
                if active.operation != handle.operation || active.generation != handle.generation {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-store.replacement-stale-handle"), "store replacement handle is stale"));
                }
                return Ok(self.poll_artifact_store_replacement(handle));
            }
            if let Some(active) = self.envelope_decode_jobs.get(handle.operation.0) {
                if active.operation != handle.operation || active.generation != handle.generation {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.stale-handle"), "envelope decode handle is stale"));
                }
                let decode = active.poll();
                if decode != ArtifactEnvelopeDecodeOperationPoll::Ready {
                    return Ok(decode);
                }
                if !self.drain_ready_envelope_decode_worker_owners(handle)? {
                    return Ok(ArtifactEnvelopeDecodeOperationPoll::Progress);
                }
                if !self.try_begin_artifact_store_replacement(handle)? {
                    return Ok(ArtifactEnvelopeDecodeOperationPoll::Progress);
                }
                return Ok(self.poll_artifact_store_replacement(handle));
            }
            if self.envelope_ingress.get(handle.operation.0).is_some() {
                return Ok(ArtifactEnvelopeDecodeOperationPoll::Pending);
            }
            Ok(ArtifactEnvelopeDecodeOperationPoll::Fault)
        }

        pub fn cancel_artifact_envelope_load(&mut self, handle: ArtifactEnvelopeDecodeOperationHandle) -> Result<(), Fault> {
            if let Some(ingress) = self.envelope_ingress.get_mut(handle.operation.0) {
                ingress.closing = true;
                return Ok(());
            }
            if self.envelope_decode_jobs.get(handle.operation.0).is_some() {
                return self.cancel_artifact_envelope_decode(handle);
            }
            if self.store_replacement_jobs.get(handle.operation.0).is_some() {
                return self.cancel_artifact_store_replacement(handle);
            }
            Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.load-stale-handle"), "unknown artifact envelope load handle"))
        }

        /// 📥️ Admits one exact fixed-page envelope owner into app maintenance. A missing
        /// domain catalog or occupied operation slot returns every page untouched.
        pub fn submit_artifact_envelope_decode(
            &mut self,
            operation: semio_framework_job::OperationId,
            generation: semio_framework_job::Generation,
            pages: store::OwnedSchemaDecodePages,
        ) -> Result<ArtifactEnvelopeDecodeOperationHandle, store::OwnedSchemaDecodePages> {
            if !self.envelope_decode_jobs.can_insert(operation.0) {
                return Err(pages);
            }
            let Some(bundle) = A::build_envelope_decode_owner_bundle() else { return Err(pages) };
            let completion = store::ArtifactEnvelopeDecodeCompletion::new();
            let fields = bundle.begin_fresh_decoder(operation, generation, std::sync::Arc::clone(&self.envelope_completed_records), std::sync::Arc::clone(&completion));
            self.admit_artifact_envelope_decode_owner(operation, generation, pages, fields, completion)
        }

        /// 📥️ Admits one exact envelope decode against a caller-supplied field owner. The domain
        /// route builds that owner from its declared catalog; the framework's own decode-ladder laws
        /// supply a bare one so the ladder is provable without a domain field catalog.
        pub(crate) fn admit_artifact_envelope_decode_owner(
            &mut self,
            operation: semio_framework_job::OperationId,
            generation: semio_framework_job::Generation,
            pages: store::OwnedSchemaDecodePages,
            fields: Box<dyn store::ArtifactEnvelopeFieldDecoder<A::Snapshot, A::Mutation>>,
            completion: std::sync::Arc<store::ArtifactEnvelopeDecodeCompletion>,
        ) -> Result<ArtifactEnvelopeDecodeOperationHandle, store::OwnedSchemaDecodePages> {
            if !self.envelope_decode_jobs.can_insert(operation.0) {
                return Err(pages);
            }
            let record = store::artifact_envelope_decode_record(operation, generation, pages)?;
            let active = match store::ArtifactEnvelopeDecodeAuthority::try_new(record, &self.envelope_field_decoders, fields) {
                Ok(decode) => ActiveArtifactEnvelopeDecode::admitted(operation, generation, decode, completion),
                Err((record, _fault, fields)) => ActiveArtifactEnvelopeDecode::rejected(operation, generation, Box::new(store::ArtifactEnvelopeUnadmittedDecodeRejected::new(record, fields)), completion),
            };
            self.envelope_decode_jobs.insert_admitted(operation.0, active);
            Ok(ArtifactEnvelopeDecodeOperationHandle { operation, generation })
        }

        pub fn poll_artifact_envelope_decode(&self, handle: ArtifactEnvelopeDecodeOperationHandle) -> ArtifactEnvelopeDecodeOperationPoll {
            self.envelope_decode_jobs.get(handle.operation.0).filter(|active| active.operation == handle.operation && active.generation == handle.generation).map_or(ArtifactEnvelopeDecodeOperationPoll::Fault, ActiveArtifactEnvelopeDecode::poll)
        }

        /// 🧹️ Whether the decode worker session/outcome ladder is fully retired for one live handle.
        pub fn artifact_envelope_decode_worker_owners_are_terminal(&self, handle: ArtifactEnvelopeDecodeOperationHandle) -> bool {
            self.envelope_decode_jobs.get(handle.operation.0).filter(|active| active.operation == handle.operation && active.generation == handle.generation).is_none_or(ActiveArtifactEnvelopeDecode::decode_worker_owners_are_terminal)
        }

        pub(crate) fn drain_ready_envelope_decode_worker_owners(&mut self, handle: ArtifactEnvelopeDecodeOperationHandle) -> Result<bool, Fault> {
            for _ in 0..4096 {
                if self.envelope_decode_jobs.get(handle.operation.0).is_none() {
                    return Ok(true);
                }
                if self.artifact_envelope_decode_worker_owners_are_terminal(handle) {
                    return Ok(true);
                }
                let _ = self.envelope_decode_jobs.get_mut(handle.operation.0).map(|active| active.force_worker_session_terminal(1, store::ARTIFACT_ENVELOPE_DECODE_PAGE_BYTES, 256));
                for _ in 0..8 {
                    self.drive_artifact_envelope_decode_worker()?;
                    let _ = self.drive_envelope_decode_jobs(1, store::ARTIFACT_ENVELOPE_DECODE_PAGE_BYTES, false)?;
                }
                let _ = semio_framework_job::pump_worker_job_retirements(8, 1, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES);
            }
            Ok(self.artifact_envelope_decode_worker_owners_are_terminal(handle))
        }

        /// 📤️ Applies the sole non-suspending completed-record publication after exact live
        /// generation validation. Backpressure leaves both the record and active operation retained.
        pub fn try_publish_artifact_envelope_decode(&mut self, handle: ArtifactEnvelopeDecodeOperationHandle, target: &mut dyn store::ArtifactEnvelopeCompletedRecordTarget<A::Snapshot, A::Mutation>) -> Result<bool, Fault> {
            if semio_framework_job::Generation(self.store.generation_now()) != handle.generation {
                self.cancel_artifact_envelope_decode(handle)?;
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.stale-publication"), "decoded envelope generation changed before exact publication"));
            }
            let active = self
                .envelope_decode_jobs
                .get_mut(handle.operation.0)
                .filter(|active| active.operation == handle.operation && active.generation == handle.generation)
                .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.stale-handle"), "unknown or stale envelope decode handle"))?;
            if active.state != ActiveArtifactEnvelopeDecodeState::Ready || active.cancel.is_cancelled_now() {
                return Ok(false);
            }
            let ticket = active.completion.ticket().ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.output-missing"), "ready envelope decode has no exact completed-record ticket"))?;
            match self.envelope_completed_records.try_publish_to(ticket, target) {
                Ok(false) | Err(store::ArtifactEnvelopeCompletedRecordFault::Contended) => Ok(false),
                Ok(true) => {
                    active.state = ActiveArtifactEnvelopeDecodeState::Complete;
                    if !active.terminal_is_empty(&self.envelope_completed_records) {
                        return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.publication-terminal"), "published envelope operation retained a nonterminal owner"));
                    }
                    let active =
                        self.envelope_decode_jobs.remove(handle.operation.0).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.publication-owner"), "published envelope operation changed before exact removal"))?;
                    drop(active);
                    Ok(true)
                }
                Err(_) => Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.publication-ticket"), "completed envelope ticket was stale or invalid")),
            }
        }

        pub fn cancel_artifact_envelope_decode(&mut self, handle: ArtifactEnvelopeDecodeOperationHandle) -> Result<(), Fault> {
            let active = self
                .envelope_decode_jobs
                .get_mut(handle.operation.0)
                .filter(|active| active.operation == handle.operation && active.generation == handle.generation)
                .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.stale-handle"), "unknown or stale envelope decode handle"))?;
            active.cancel.cancel_now();
            Ok(())
        }

        /// 🏗️ Atomically transfers one decoded envelope into the app-owned retained store
        /// initializer. Capacity or factory rejection leaves the completed record in its exact slot.
        pub fn try_begin_artifact_store_replacement(&mut self, handle: ArtifactEnvelopeDecodeOperationHandle) -> Result<bool, Fault> {
            if semio_framework_job::Generation(self.store.generation_now()) != handle.generation {
                self.cancel_artifact_envelope_decode(handle)?;
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-store.replacement-stale-admission"), "store replacement generation changed before initializer admission"));
            }
            if !self.store_replacement_jobs.can_insert(handle.operation.0) {
                return Ok(false);
            }
            let ticket = self
                .envelope_decode_jobs
                .get(handle.operation.0)
                .filter(|active| active.operation == handle.operation && active.generation == handle.generation && active.state == ActiveArtifactEnvelopeDecodeState::Ready && !active.cancel.is_cancelled_now())
                .and_then(|active| active.completion.ticket())
                .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-store.replacement-output-not-ready"), "decoded envelope is not ready for retained store initialization"))?;
            let child_content_generation = self.child_content_generation;
            let mut target = ArtifactStoreReplacementAdmissionTarget::<A, M> { jobs: &mut self.store_replacement_jobs, operation: handle.operation, generation: handle.generation, child_content_generation, marker: std::marker::PhantomData };
            match self.envelope_completed_records.try_publish_to(ticket, &mut target) {
                Ok(false) | Err(store::ArtifactEnvelopeCompletedRecordFault::Contended) => Ok(false),
                Ok(true) => {
                    if !self.drain_ready_envelope_decode_worker_owners(handle)? {
                        return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-store.replacement-decode-terminal"), "decoded envelope retained an owner after initializer transfer"));
                    }
                    let active = self
                        .envelope_decode_jobs
                        .get_mut(handle.operation.0)
                        .filter(|active| active.operation == handle.operation && active.generation == handle.generation)
                        .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-store.replacement-decode-owner"), "decoded envelope owner changed during exact initializer admission"))?;
                    if !active.decode_worker_owners_are_terminal() {
                        return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-store.replacement-decode-terminal"), "decoded envelope retained an owner after initializer transfer"));
                    }
                    active.state = ActiveArtifactEnvelopeDecodeState::Complete;
                    let active =
                        self.envelope_decode_jobs.remove(handle.operation.0).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-store.replacement-decode-owner"), "terminal decoded envelope changed before exact removal"))?;
                    drop(active);
                    Ok(true)
                }
                Err(_) => Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-store.replacement-completed-ticket"), "decoded envelope completed-record ticket was stale or invalid")),
            }
        }

        /// 🌳️ Pre-admits the exact recursive member count after the retained parent initializer
        /// is terminal and before any member input may enter the candidate transaction.
        pub fn try_begin_owned_document_members(&mut self, handle: ArtifactEnvelopeDecodeOperationHandle, expected: usize, expires_at_us: u64) -> Result<bool, Fault> {
            let active = self
                .store_replacement_jobs
                .get_mut(handle.operation.0)
                .filter(|active| active.operation == handle.operation && active.generation == handle.generation)
                .ok_or_else(|| plugin_sdk_fault("owned document member ingress has no matching replacement authority"))?;
            active.begin_members(expected, expires_at_us)
        }

        /// 📥️ Transfers one admitted member-open request into its exact retained ordinal.
        #[expect(clippy::result_large_err, reason = "Rejected admission returns the exact retained member request and identity owner unchanged.")]
        pub fn admit_owned_document_member(&mut self, handle: ArtifactEnvelopeDecodeOperationHandle, ingress: OwnedDocumentMemberIngress) -> Result<(), (Fault, OwnedDocumentMemberIngress)> {
            let Some(active) = self.store_replacement_jobs.get_mut(handle.operation.0).filter(|active| active.operation == handle.operation && active.generation == handle.generation) else {
                return Err((plugin_sdk_fault("owned document member ingress has no matching replacement authority"), ingress));
            };
            active.admit_member(ingress)
        }

        /// 🔒️ Freezes the complete ordinal set so bounded typed opens can begin.
        pub fn seal_owned_document_members(&mut self, handle: ArtifactEnvelopeDecodeOperationHandle) -> Result<(), Fault> {
            let active = self
                .store_replacement_jobs
                .get_mut(handle.operation.0)
                .filter(|active| active.operation == handle.operation && active.generation == handle.generation)
                .ok_or_else(|| plugin_sdk_fault("owned document member seal has no matching replacement authority"))?;
            active.seal_members()
        }

        pub fn poll_artifact_store_replacement(&self, handle: ArtifactEnvelopeDecodeOperationHandle) -> ArtifactEnvelopeDecodeOperationPoll {
            self.store_replacement_jobs.get(handle.operation.0).filter(|active| active.operation == handle.operation && active.generation == handle.generation).map_or(ArtifactEnvelopeDecodeOperationPoll::Fault, |active| match active.state {
                ActiveArtifactStoreReplacementState::Initializing
                | ActiveArtifactStoreReplacementState::AwaitingMembers
                | ActiveArtifactStoreReplacementState::OpeningMembers
                | ActiveArtifactStoreReplacementState::ValidatingClosure
                | ActiveArtifactStoreReplacementState::PreparingCandidateViews
                | ActiveArtifactStoreReplacementState::CandidateReady => ArtifactEnvelopeDecodeOperationPoll::Pending,
                ActiveArtifactStoreReplacementState::ClosingRejectedMember
                | ActiveArtifactStoreReplacementState::RetiringRejectedMembers
                | ActiveArtifactStoreReplacementState::RetiringCommittedMembers
                | ActiveArtifactStoreReplacementState::RetiringCommittedStore
                | ActiveArtifactStoreReplacementState::RetiringRejectedCandidate => ArtifactEnvelopeDecodeOperationPoll::Progress,
                ActiveArtifactStoreReplacementState::Complete if active.committed && active.refusal.is_none() => ArtifactEnvelopeDecodeOperationPoll::Ready,
                ActiveArtifactStoreReplacementState::Complete if active.cancel.is_cancelled_now() => ArtifactEnvelopeDecodeOperationPoll::Cancelled,
                ActiveArtifactStoreReplacementState::Complete => ArtifactEnvelopeDecodeOperationPoll::Fault,
            })
        }

        /// 🧭️ The exact leg that refused this replacement, minted as a typed fault. Read BEFORE
        /// {@link acknowledge_artifact_store_replacement} retires the operation — after that the
        /// evidence is gone and only the generic collapse remains.
        pub fn artifact_store_replacement_refusal(&self, handle: ArtifactEnvelopeDecodeOperationHandle) -> Option<Fault> {
            self.store_replacement_jobs.get(handle.operation.0).filter(|active| active.operation == handle.operation && active.generation == handle.generation).and_then(|active| active.refusal).map(ArtifactStoreReplacementRefusal::into_fault)
        }

        pub fn acknowledge_artifact_store_replacement(&mut self, handle: ArtifactEnvelopeDecodeOperationHandle) -> Result<bool, Fault> {
            let Some(active) = self.store_replacement_jobs.get(handle.operation.0) else { return Ok(false) };
            if active.operation != handle.operation || active.generation != handle.generation || !active.terminal_is_empty() {
                return Ok(false);
            }
            let active = self
                .store_replacement_jobs
                .remove(handle.operation.0)
                .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-store.replacement-terminal-owner"), "terminal store replacement changed before exact acknowledgement"))?;
            drop(active);
            Ok(true)
        }

        pub fn cancel_artifact_store_replacement(&mut self, handle: ArtifactEnvelopeDecodeOperationHandle) -> Result<(), Fault> {
            let active = self
                .store_replacement_jobs
                .get_mut(handle.operation.0)
                .filter(|active| active.operation == handle.operation && active.generation == handle.generation)
                .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-store.replacement-stale-handle"), "unknown or stale store replacement handle"))?;
            if !active.committed {
                active.request_cancel();
            }
            Ok(())
        }

        /// 🧩️ The app's own projection answers, never the structural one: `A::child_restore_projection`
        /// is what every composing app implements so its diagnostic names the refused row, and an app
        /// that composes its children differently answers for itself. The structural call here erased
        /// the `ChildRestoreProjectionError` behind one flat string, which made a live-load refusal
        /// unattributable from the plugin side (gismap, ticket 26/09/19 engineering §9).
        fn drive_store_replacement_jobs(&mut self, maximum_items: usize, maximum_bytes: usize, closing: bool) -> Result<PluginCloseStep, Fault> {
            let cursor = if closing { &mut self.close_store_replacement_cursor } else { &mut self.maintenance_store_replacement_cursor };
            let Some((index, operation_id)) = self.store_replacement_jobs.next_id_from(*cursor) else {
                return Ok(PluginCloseStep::Complete);
            };
            *cursor = (index + 1) % ARTIFACT_LIVE_OUTPUT_SLOTS;
            let pool = semio_framework_async::process_worker_pool(semio_framework_async::WorkerPoolConfig::new(semio_framework_async::ProcessKind::InteractiveNative, std::thread::available_parallelism().map_or(1, std::num::NonZeroUsize::get)));
            if closing {
                if let Some(active) = self.store_replacement_jobs.get_mut(operation_id) {
                    active.request_cancel();
                }
            }
            let state = self
                .store_replacement_jobs
                .get(operation_id)
                .map(|active| active.state)
                .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-store.replacement-owner"), "store replacement changed during one fixed maintenance step"))?;
            if state == ActiveArtifactStoreReplacementState::Initializing {
                return self
                    .store_replacement_jobs
                    .get_mut(operation_id)
                    .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-store.replacement-owner"), "store initializer changed before one worker step"))?
                    .drive_initializer(&pool);
            }
            if matches!(
                state,
                ActiveArtifactStoreReplacementState::AwaitingMembers
                    | ActiveArtifactStoreReplacementState::OpeningMembers
                    | ActiveArtifactStoreReplacementState::ClosingRejectedMember
                    | ActiveArtifactStoreReplacementState::ValidatingClosure
                    | ActiveArtifactStoreReplacementState::PreparingCandidateViews
            ) && self.store_replacement_jobs.get(operation_id).is_some_and(|active| active.cancel.is_cancelled_now())
            {
                let active = self.store_replacement_jobs.get_mut(operation_id).ok_or_else(|| plugin_sdk_fault("cancelled owned document replacement changed before retained member retirement"))?;
                active.refuse(ArtifactStoreReplacementRefusal::Cancelled);
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if state == ActiveArtifactStoreReplacementState::AwaitingMembers {
                let active = self.store_replacement_jobs.get_mut(operation_id).ok_or_else(|| plugin_sdk_fault("awaiting owned document replacement changed before member admission"))?;
                if active.member_ingress.is_some() {
                    return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                }
                let candidate = active.retained_store.as_ref().ok_or_else(|| plugin_sdk_fault("awaiting owned document replacement lost its parent candidate"))?;
                let projection = A::child_restore_projection(candidate.snapshot_ref())?;
                if projection.get(0).is_none() {
                    active.begin_members(0, u64::MAX)?;
                    active.seal_members()?;
                    return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                }
                self.complete_store_replacement_genesis(operation_id)?;
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if state == ActiveArtifactStoreReplacementState::OpeningMembers {
                return self.store_replacement_jobs.get_mut(operation_id).ok_or_else(|| plugin_sdk_fault("opening owned document replacement changed before one member step"))?.drive_member_open(maximum_items, maximum_bytes);
            }
            if state == ActiveArtifactStoreReplacementState::ClosingRejectedMember {
                let active = self.store_replacement_jobs.get_mut(operation_id).ok_or_else(|| plugin_sdk_fault("rejected member open changed before bounded close"))?;
                active.state = ActiveArtifactStoreReplacementState::RetiringRejectedMembers;
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if state == ActiveArtifactStoreReplacementState::ValidatingClosure {
                return self.store_replacement_jobs.get_mut(operation_id).ok_or_else(|| plugin_sdk_fault("owned document closure changed before one validation step"))?.drive_closure(maximum_items, maximum_bytes);
            }
            if state == ActiveArtifactStoreReplacementState::PreparingCandidateViews {
                return self.store_replacement_jobs.get_mut(operation_id).ok_or_else(|| plugin_sdk_fault("owned document candidate views changed before one preparation step"))?.drive_candidate_views(maximum_items, maximum_bytes);
            }
            if matches!(state, ActiveArtifactStoreReplacementState::RetiringRejectedMembers | ActiveArtifactStoreReplacementState::RetiringCommittedMembers) {
                let active = self.store_replacement_jobs.get_mut(operation_id).ok_or_else(|| plugin_sdk_fault("rejected owned document changed before member retirement"))?;
                if active.retained_store.is_some() && active.retained_disposer.is_none() {
                    *active.retained_disposer = Some(A::build_document_store_disposer().ok_or_else(|| plugin_sdk_fault("app did not supply the required rejected-candidate disposer"))?);
                }
                return active.drive_rejected_members(&self.child_content_root, maximum_items, maximum_bytes);
            }
            if state == ActiveArtifactStoreReplacementState::CandidateReady {
                let replacement_content_retirements = ArtifactFixedRegistry::new();
                let live_generation = semio_framework_job::Generation(self.store.generation_now());
                let next_content_generation = self.child_content_generation.checked_add(1);
                let active = self.store_replacement_jobs.get_mut(operation_id).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-store.replacement-owner"), "ready store candidate changed before exact commit validation"))?;
                let disposer = A::build_document_store_disposer().ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-store.replacement-disposer-missing"), "app did not supply the required displaced-store disposer"))?;
                let complete_candidate = active.candidate_children.as_ref().is_some_and(|children| active.candidate_source_generation == children.len() as u64)
                    && active.candidate_content.is_some()
                    && active.candidate_composition.is_some()
                    && active.view_member_ordinal == active.candidate_children.as_ref().map_or(usize::MAX, ChildMemberRegistry::len);
                if closing
                    || active.cancel.is_cancelled_now()
                    || active.generation != live_generation
                    || active.base_child_content_generation != self.child_content_generation
                    || !complete_candidate
                    || !replacement_content_retirements.allocation_admitted
                    || next_content_generation.is_none()
                {
                    let guard = ArtifactStoreReplacementPublicationGuard {
                        closing,
                        cancelled: active.cancel.is_cancelled_now(),
                        parent_generation: active.generation.0,
                        live_generation: live_generation.0,
                        base_child_generation: active.base_child_content_generation,
                        child_generation: self.child_content_generation,
                        complete_candidate,
                        retirement_admitted: replacement_content_retirements.allocation_admitted,
                        next_generation: next_content_generation.is_some(),
                    };
                    *active.retained_disposer = Some(disposer);
                    active.refuse(ArtifactStoreReplacementRefusal::PublicationGuard(guard));
                    return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                }
                if A::validate_document_store_publication(active.operation, active.generation, live_generation).is_err() {
                    *active.retained_disposer = Some(disposer);
                    active.refuse(ArtifactStoreReplacementRefusal::PublicationAuthorityRejected);
                    return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                }
                let window_reset = self.prepare_document_window_reset()?;
                let active = self.store_replacement_jobs.get_mut(operation_id).expect("validated replacement remains exclusively owned across non-suspending window preparation");
                let candidate = active.retained_store.take().expect("complete replacement retains its exact parent candidate");
                let candidate_children = active.candidate_children.take().expect("complete replacement retains its exact member registry");
                let candidate_content = active.candidate_content.take().expect("complete replacement retains its exact content view");
                let candidate_composition = active.candidate_composition.take().expect("complete replacement retains its exact coordinator");
                let displaced = match publish_boxed_document_store_candidate_if_authoritative(&mut self.store, candidate, || Ok(())) {
                    Ok(displaced) => displaced,
                    Err(_) => unreachable!("prevalidated publication cannot reject inside its non-suspending commit boundary"),
                };
                self.store.enable_convergence_early_exit();
                self.store.defer_remote_replays(Some(time_travel::time_travel_replay_turn_budget()));
                self.store.defer_local_replays(Some(time_travel::time_travel_replay_turn_budget()));
                let displaced_children = std::mem::replace(&mut self.children, candidate_children);
                let displaced_content = std::mem::replace(&mut *self.child_content_root, candidate_content);
                let displaced_content_retirements = std::mem::replace(&mut self.child_content_retirements, replacement_content_retirements);
                let displaced_composition = std::mem::replace(&mut self.composition, candidate_composition);
                let displaced_pins = std::mem::take(&mut self.pending_child_pins);
                *active.retained_store = Some(displaced);
                *active.candidate_children = Some(displaced_children);
                *active.candidate_content = Some(displaced_content);
                if displaced_content_retirements.is_empty() {
                    drop(displaced_content_retirements);
                } else {
                    *active.displaced_content_retirements = Some(displaced_content_retirements);
                }
                *active.candidate_composition = Some(displaced_composition);
                if !displaced_pins.is_empty() {
                    *active.displaced_pins = Some(CompositionPinsRetirement::new(displaced_pins));
                }
                *active.retained_disposer = Some(disposer);
                active.committed = true;
                active.state = ActiveArtifactStoreReplacementState::RetiringCommittedMembers;
                self.child_content_generation = next_content_generation.expect("candidate generation exhaustion was rejected before commit");
                self.commit_document_window_reset(window_reset);
                self.cache = None;
                self.retire_displaced_document_rows();
                self.time_travel.set_history_unavailable(false);
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if matches!(state, ActiveArtifactStoreReplacementState::RetiringCommittedStore | ActiveArtifactStoreReplacementState::RetiringRejectedCandidate) {
                return self
                    .store_replacement_jobs
                    .get_mut(operation_id)
                    .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-store.replacement-owner"), "retained store changed before one close step"))?
                    .drive_retained_store(maximum_items, maximum_bytes);
            }
            if closing {
                let active = self.store_replacement_jobs.get(operation_id).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-store.replacement-owner"), "terminal store replacement changed before close acknowledgement"))?;
                if !active.terminal_is_empty() {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-store.replacement-terminal-not-empty"), "store replacement reported terminal before every exact owner was empty"));
                }
                let active = self.store_replacement_jobs.remove(operation_id).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-store.replacement-owner"), "terminal store replacement changed before exact close removal"))?;
                drop(active);
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            Ok(PluginCloseStep::Complete)
        }

        fn drive_document_archive_terminal(&mut self, active: &mut ActiveDocumentArchiveLoad<A::Snapshot, A::Mutation>, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            let target = active.terminal_target.ok_or_else(|| plugin_sdk_fault("recursive document archive terminal cleanup has no target"))?;
            if let Some(handle) = active.replacement {
                if self.store_replacement_jobs.get(handle.operation.0).is_some() {
                    if target != ActiveDocumentArchiveLoadState::Ready {
                        self.cancel_artifact_store_replacement(handle)?;
                    }
                    let poll = self.poll_artifact_store_replacement(handle);
                    if matches!(poll, ArtifactEnvelopeDecodeOperationPoll::Ready | ArtifactEnvelopeDecodeOperationPoll::Cancelled | ArtifactEnvelopeDecodeOperationPoll::Fault) && self.acknowledge_artifact_store_replacement(handle)? {
                        active.replacement = None;
                        return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                    }
                    return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                }
                active.replacement = None;
                if target == ActiveDocumentArchiveLoadState::Ready {
                    return Err(plugin_sdk_fault("ready recursive document archive lost its replacement acknowledgement authority"));
                }
            }
            let step = active.close_step(maximum_items, maximum_bytes);
            if step == PluginCloseStep::Complete {
                if !active.terminal_is_empty() {
                    return Err(plugin_sdk_fault("recursive document archive cleanup returned Complete with a live owner"));
                }
                active.state = target;
                active.phase = ActiveDocumentArchiveLoadPhase::Terminal;
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            Ok(step)
        }

        /// 🌱️ Completes an archive's member roster with every child the hydrated candidate parent declares,
        /// the archive omits, and the app derives (`ArtifactApp::genesis_child_pack`) — the content-addressed
        /// members a whole-document load (`Effect::LoadDocument`, which carries pack+spr only) can never
        /// ship. Each minted entry is owner-stamped to the candidate root and takes the next ordinal after the
        /// archived ones; the fixed member and byte authorities are re-checked over the completed roster. A
        /// slot the app cannot derive is left alone, so closure validation still rejects it as `Incomplete`.
        ///
        /// 🔢️ Archived entries are already reversed for ordinal-ordered popping; ordinals stay
        /// `0..n` for them and continue at `n` for every minted member, whatever the pop order.
        fn complete_document_archive_genesis(&mut self, active: &mut ActiveDocumentArchiveLoad<A::Snapshot, A::Mutation>, handle: ArtifactEnvelopeDecodeOperationHandle) -> Result<(), Fault> {
            let archive = active.archive.as_mut().ok_or_else(|| plugin_sdk_fault("recursive document archive member roster owner is absent"))?;
            let candidate = self
                .store_replacement_jobs
                .get(handle.operation.0)
                .filter(|replacement| replacement.operation == handle.operation && replacement.generation == handle.generation)
                .and_then(ActiveArtifactStoreReplacement::candidate_awaiting_members)
                .ok_or_else(|| plugin_sdk_fault("document archive genesis has no hydrated candidate parent awaiting members"))?;
            let dialect = candidate.envelope().dialect.clone().ok_or_else(|| plugin_sdk_fault("document archive genesis requires the candidate parent's exact dialect"))?;
            let parent = ArtifactRef { artifact_id: candidate.envelope().id.clone(), dialect };
            let snapshot = candidate.snapshot_ref();
            let projection = store::ChildRestoreProjection::from_snapshot(snapshot).map_err(|error| plugin_sdk_fault(format!("document archive genesis child projection failed: {error}")))?;
            let mut ordinal = archive.members.len();
            let mut payload_bytes = archive.members.iter().fold(archive.parent_spr.len(), |total, entry| total + entry.envelope_pack.len());
            for index in 0..projection.len() {
                let Some((slot, fields)) = projection.get(index) else { break };
                if archive.members.iter().any(|entry| entry.owner.slot == slot && entry.reference.artifact_id == fields.child_id) {
                    continue;
                }
                let Some(initial_pack) = A::genesis_child_pack(snapshot, slot, fields.child_id) else { continue };
                let dialect = ArtifactDialect { artifact_kind: fields.artifact_kind.to_string(), standard: fields.standard.to_string(), subset: fields.subset.to_string() };
                let schema = genesis_member_schema::<M>(&dialect)?;
                let owner = store::OwnerRef { parent: parent.clone(), slot: slot.to_string(), child_id: fields.child_id.to_string() };
                let envelope_pack = ::semio_framework_async::poll::resolve_ready(store::genesis_member_envelope_pack(schema, &dialect, &owner, &initial_pack)).map_err(|error| plugin_sdk_fault(format!("genesis child {slot}/{} envelope: {error}", fields.child_id)))?;
                if ordinal >= protocol::DOCUMENT_ARCHIVE_MAXIMUM_MEMBERS {
                    return Err(plugin_sdk_fault("document archive genesis exceeds its fixed 1024-member authority"));
                }
                payload_bytes = payload_bytes.checked_add(envelope_pack.len()).filter(|bytes| *bytes <= protocol::DOCUMENT_ARCHIVE_MAXIMUM_BYTES).ok_or_else(|| plugin_sdk_fault("document archive genesis exceeds its fixed byte authority"))?;
                archive.members.push(protocol::OwnedDocumentMemberPackEntry {
                    ordinal: u32::try_from(ordinal).map_err(|_| plugin_sdk_fault("document archive genesis ordinal exceeds u32"))?,
                    reference: protocol::DocumentArchiveArtifactRef { artifact_id: fields.child_id.to_string(), artifact_kind: fields.artifact_kind.to_string(), standard: fields.standard.to_string(), subset: fields.subset.to_string() },
                    owner: protocol::DocumentArchiveOwnerRef {
                        parent: protocol::DocumentArchiveArtifactRef { artifact_id: parent.artifact_id.clone(), artifact_kind: parent.dialect.artifact_kind.clone(), standard: parent.dialect.standard.clone(), subset: parent.dialect.subset.clone() },
                        slot: slot.to_string(),
                        child_id: fields.child_id.to_string(),
                    },
                    envelope_pack,
                });
                ordinal += 1;
                active.total = active.total.saturating_add(1);
            }
            Ok(())
        }

        /// 🌱️ Mints every derivable composed child onto a live envelope replacement's member roster —
        /// the JSON ingress path ships only the parent envelope, so `ArtifactApp::genesis_child_pack`
        /// must supply the same members `seed_genesis_children` opened at boot.
        fn complete_store_replacement_genesis(&mut self, operation_id: u64) -> Result<(), Fault> {
            let active = self.store_replacement_jobs.get(operation_id).ok_or_else(|| plugin_sdk_fault("live store replacement genesis lost its exact replacement authority"))?;
            let handle = ArtifactEnvelopeDecodeOperationHandle { operation: active.operation, generation: active.generation };
            let candidate = active.retained_store.as_ref().ok_or_else(|| plugin_sdk_fault("live store replacement genesis has no hydrated candidate parent"))?;
            let dialect = candidate.envelope().dialect.clone().ok_or_else(|| plugin_sdk_fault("live store replacement genesis requires the candidate parent's exact dialect"))?;
            let parent = ArtifactRef { artifact_id: candidate.envelope().id.clone(), dialect };
            let snapshot = candidate.snapshot_ref();
            let projection = store::ChildRestoreProjection::from_snapshot(snapshot).map_err(|error| plugin_sdk_fault(format!("live store replacement genesis child projection failed: {error}")))?;
            let mut entries = Vec::new();
            let mut ordinal = 0usize;
            for index in 0..projection.len() {
                let Some((slot, fields)) = projection.get(index) else { break };
                let Some(initial_pack) = A::genesis_child_pack(snapshot, slot, fields.child_id) else { continue };
                let dialect = ArtifactDialect { artifact_kind: fields.artifact_kind.to_string(), standard: fields.standard.to_string(), subset: fields.subset.to_string() };
                let schema = genesis_member_schema::<M>(&dialect)?;
                let owner = store::OwnerRef { parent: parent.clone(), slot: slot.to_string(), child_id: fields.child_id.to_string() };
                let envelope_pack = ::semio_framework_async::poll::resolve_ready(store::genesis_member_envelope_pack(schema, &dialect, &owner, &initial_pack)).map_err(|error| plugin_sdk_fault(format!("genesis child {slot}/{} envelope: {error}", fields.child_id)))?;
                if ordinal >= protocol::DOCUMENT_ARCHIVE_MAXIMUM_MEMBERS {
                    return Err(plugin_sdk_fault("live store replacement genesis exceeds its fixed 1024-member authority"));
                }
                entries.push(protocol::OwnedDocumentMemberPackEntry {
                    ordinal: u32::try_from(ordinal).map_err(|_| plugin_sdk_fault("live store replacement genesis ordinal exceeds u32"))?,
                    reference: protocol::DocumentArchiveArtifactRef { artifact_id: fields.child_id.to_string(), artifact_kind: fields.artifact_kind.to_string(), standard: fields.standard.to_string(), subset: fields.subset.to_string() },
                    owner: protocol::DocumentArchiveOwnerRef {
                        parent: protocol::DocumentArchiveArtifactRef { artifact_id: parent.artifact_id.clone(), artifact_kind: parent.dialect.artifact_kind.clone(), standard: parent.dialect.standard.clone(), subset: parent.dialect.subset.clone() },
                        slot: slot.to_string(),
                        child_id: fields.child_id.to_string(),
                    },
                    envelope_pack,
                });
                ordinal += 1;
            }
            let active = self.store_replacement_jobs.get_mut(operation_id).ok_or_else(|| plugin_sdk_fault("live store replacement genesis changed before member admission"))?;
            active.begin_members(entries.len(), u64::MAX)?;
            for entry in entries {
                let mut pending = PendingDocumentArchiveMember::new(entry).map_err(|(fault, _)| fault)?;
                while !pending.fill_one_page(store::OWNED_SCHEMA_DECODE_PAGE_BYTES)? {}
                while pending.retire_source_step(store::OWNED_SCHEMA_DECODE_PAGE_BYTES) != PluginCloseStep::Complete {}
                let ingress = pending.take_ingress(handle).map_err(|(fault, _)| fault)?;
                active.admit_member(ingress).map_err(|(fault, _)| fault)?;
            }
            active.seal_members()?;
            Ok(())
        }

        /// 🧹️ `retire_envelope_uninstalled`, never `retire_envelope` on a temporary catalog: the
        /// fresh catalog's cursor disposer would otherwise reach `Drop` un-driven and abort the
        /// guest, hiding this fault (ticket 26/09/06/ENERGY-PLUGIN-END-TO-END).
        ///
        /// 🧵️ Genesis and `begin_members` happen in ONE step: yielding between them let
        /// `drive_store_replacement_jobs` observe `AwaitingMembers` with no ingress, run
        /// its own `complete_store_replacement_genesis` and seal the roster — after which
        /// the members this lane had just minted into `archive.members` could never be
        /// admitted ("sealed its member roster before the archived members were
        /// admitted", every energy example load; ticket 26/09/06/ENERGY-PLUGIN-END-TO-END).
        /// With the ingress registered here, the replacement lane waits instead.
        ///
        /// 🌱️ A childless candidate is sealed by the replacement lane itself
        /// (`drive_store_replacement_jobs` begins and seals zero members the moment
        /// it observes `AwaitingMembers`), so this load has no roster to admit and
        /// only awaits the replacement's outcome; an archived member left behind
        /// by that seal is a genuine ordering fault.
        fn advance_document_archive_load(&mut self, active: &mut ActiveDocumentArchiveLoad<A::Snapshot, A::Mutation>, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            if active.terminal_target.is_some() {
                return self.drive_document_archive_terminal(active, maximum_items, maximum_bytes);
            }
            if active.state == ActiveDocumentArchiveLoadState::Pending {
                active.state = ActiveDocumentArchiveLoadState::Running;
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            match active.phase {
                ActiveDocumentArchiveLoadPhase::DecodeParent => {
                    let archive = active.archive.as_ref().ok_or_else(|| plugin_sdk_fault("recursive document archive parent input owner is absent"))?;
                    let decoder = active.history.as_mut().ok_or_else(|| plugin_sdk_fault("recursive document archive parent history decoder is absent"))?;
                    match decoder.step(&archive.parent_spr, maximum_bytes, maximum_items.min(1)).map_err(|error| plugin_sdk_fault(format!("document archive parent SPR was rejected: {error}")))? {
                        protocol::RetainedHistoryDecodeStep::Pending { .. } => Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: maximum_bytes.min(archive.parent_spr.len()) }),
                        protocol::RetainedHistoryDecodeStep::Ready => {
                            active.decoded_history = decoder.take_ready();
                            if active.decoded_history.is_none() {
                                return Err(plugin_sdk_fault("ready recursive document archive history retained no decoded owner"));
                            }
                            active.retained = Some(semio_framework_value::retirement::owned_retirement(decoder.take_auxiliary_owners()));
                            let decoder = active.history.take().ok_or_else(|| plugin_sdk_fault("ready recursive document archive history decoder changed before terminal transfer"))?;
                            if !decoder.terminal_is_empty() {
                                active.history = Some(decoder);
                                return Err(plugin_sdk_fault("ready recursive document archive history decoder retained an untransferred owner"));
                            }
                            drop(decoder);
                            active.phase = ActiveDocumentArchiveLoadPhase::RetireParentHistoryAuxiliary;
                            Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                        }
                    }
                }
                ActiveDocumentArchiveLoadPhase::RetireParentHistoryAuxiliary => {
                    let retained = active.retained.as_mut().ok_or_else(|| plugin_sdk_fault("recursive document archive history auxiliary retirement owner is absent"))?;
                    match retained.close_step(maximum_items.min(1), maximum_bytes) {
                        Ok(store::SnapshotRetirementStep::Pending { released_items, released_bytes }) if released_items <= maximum_items.min(1) && released_bytes <= maximum_bytes => Ok(PluginCloseStep::Pending { released_items, released_bytes }),
                        Ok(store::SnapshotRetirementStep::Complete) if retained.terminal_is_empty() => {
                            active.retained = None;
                            active.phase = ActiveDocumentArchiveLoadPhase::HydrateParent;
                            Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                        }
                        Ok(store::SnapshotRetirementStep::Blocked) => Ok(PluginCloseStep::Blocked { reason: "recursive document archive history auxiliary retirement is blocked" }),
                        _ => Err(plugin_sdk_fault("recursive document archive history auxiliary retirement exceeded its grant or returned false terminal")),
                    }
                }
                ActiveDocumentArchiveLoadPhase::HydrateParent => {
                    if active.hydration.is_none() {
                        let owners = A::build_document_store_owners().ok_or_else(|| plugin_sdk_fault("document archive parent requires the app's exact document owner catalog"))?;
                        let archive = active.archive.as_mut().ok_or_else(|| plugin_sdk_fault("recursive document archive parent input owner is absent"))?;
                        let pack = std::mem::take(&mut archive.parent_pack);
                        let history = active.decoded_history.take().ok_or_else(|| plugin_sdk_fault("recursive document archive decoded history owner is absent"))?;
                        let expected = ArtifactRef { artifact_id: history.doc_id.clone(), dialect: A::DIALECT.into() };
                        let owner = self.store.envelope().owner.clone();
                        active.hydration = Some(store::RetainedPersistedDocumentHydration::from_pack(
                            pack,
                            history,
                            expected,
                            owner,
                            A::DOCUMENT_SCHEMA.to_string(),
                            owners,
                            semio_framework_job::OperationId(active.operation),
                            semio_framework_job::Generation(self.store.generation_now()),
                            u64::MAX,
                            store::PersistedDocumentHydrationTarget::Envelope,
                        ));
                        return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                    }
                    let mut sequence = active.hydration_sequence;
                    let fuel = maximum_items.max(maximum_bytes.min(semio_framework_job::JOB_PAYLOAD_PAGE_BYTES)) as u64;
                    let mut cx = semio_framework_job::StepContext::new(
                        semio_framework_job::OperationId(active.operation),
                        semio_framework_job::Generation(self.store.generation_now()),
                        semio_framework_job::StepBudget::new(fuel, u64::MAX),
                        semio_framework_job::CancelToken::root_now(),
                        semio_framework_job::default_now_us,
                        &mut sequence,
                    );
                    let step = active.hydration.as_mut().expect("recursive document parent hydration remains retained").step(&mut cx);
                    active.hydration_sequence = sequence;
                    let envelope = match step {
                        store::PersistedDocumentHydrationStep::Pending(_) => return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 }),
                        store::PersistedDocumentHydrationStep::Rejected(diagnostic) => {
                            return Err(plugin_sdk_fault(format!("document archive parent Pack and SPR hydration was rejected: {diagnostic:?}")));
                        }
                        store::PersistedDocumentHydrationStep::Ready(store::PersistedDocumentHydrationOutput::Envelope(envelope)) => envelope,
                        store::PersistedDocumentHydrationStep::Ready(store::PersistedDocumentHydrationOutput::Store(_)) => {
                            return Err(plugin_sdk_fault("document archive parent hydration returned a store outside its requested envelope boundary"));
                        }
                    };
                    let hydration = active.hydration.take().ok_or_else(|| plugin_sdk_fault("ready recursive document parent hydration owner changed before handoff"))?;
                    if !store::ErasedSnapshotRetirement::terminal_is_empty(&hydration) {
                        active.hydration = Some(hydration);
                        let owners = A::build_document_store_owners().expect("document archive hydration admitted this app's document owner catalog");
                        active.retained = Some(owners.retire_envelope_uninstalled(envelope).map_err(|error| plugin_sdk_fault(error.to_string()))?);
                        return Err(plugin_sdk_fault("ready recursive document parent hydration retained nonterminal ownership"));
                    }
                    drop(hydration);
                    match self.begin_persisted_document_store_replacement(envelope) {
                        Ok(handle) => {
                            active.replacement = Some(handle);
                            active.completed = 1;
                            active.phase = ActiveDocumentArchiveLoadPhase::AwaitingMembers;
                        }
                        Err((fault, envelope)) => {
                            let owners = A::build_document_store_owners().expect("document archive hydration admitted this app's document owner catalog");
                            active.retained = Some(owners.retire_envelope_uninstalled(envelope).map_err(|error| plugin_sdk_fault(error.to_string()))?);
                            return Err(fault);
                        }
                    }
                    Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                }
                ActiveDocumentArchiveLoadPhase::AwaitingMembers => {
                    let handle = active.replacement.ok_or_else(|| plugin_sdk_fault("recursive document archive replacement handle is absent"))?;
                    let state = self.store_replacement_jobs.get(handle.operation.0).map(|replacement| replacement.state);
                    if let Some(fold) = self.store_replacement_jobs.get(handle.operation.0).map(|replacement| replacement.fold_progress) {
                        active.fold = fold;
                    }
                    match state {
                        Some(ActiveArtifactStoreReplacementState::AwaitingMembers) => {
                            if !active.genesis_complete {
                                self.complete_document_archive_genesis(active, handle)?;
                                active.genesis_complete = true;
                            }
                            let expected = active.archive.as_ref().ok_or_else(|| plugin_sdk_fault("recursive document archive member roster owner is absent"))?.members.len();
                            if self.try_begin_owned_document_members(handle, expected, u64::MAX)? {
                                active.phase = ActiveDocumentArchiveLoadPhase::BeginMember;
                                Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                            } else {
                                Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 })
                            }
                        }
                        Some(ActiveArtifactStoreReplacementState::Complete) | None => Err(plugin_sdk_fault("document archive parent initialization failed before retained member admission")),
                        Some(ActiveArtifactStoreReplacementState::Initializing) => Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 }),
                        Some(_) => {
                            let archived = active.archive.as_ref().map_or(0, |archive| archive.members.len());
                            if archived != 0 {
                                return Err(plugin_sdk_fault("document archive replacement sealed its member roster before the archived members were admitted"));
                            }
                            active.genesis_complete = true;
                            active.phase = ActiveDocumentArchiveLoadPhase::AwaitReplacement;
                            Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                        }
                    }
                }
                ActiveDocumentArchiveLoadPhase::BeginMember => {
                    let archive = active.archive.as_mut().ok_or_else(|| plugin_sdk_fault("recursive document archive member roster owner is absent"))?;
                    let Some(entry) = archive.members.pop() else {
                        active.phase = ActiveDocumentArchiveLoadPhase::SealMembers;
                        return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                    };
                    match PendingDocumentArchiveMember::new(entry) {
                        Ok(member) => {
                            active.member = Some(member);
                            active.phase = ActiveDocumentArchiveLoadPhase::FillMember;
                        }
                        Err((fault, entry)) => {
                            archive.members.push(entry);
                            return Err(fault);
                        }
                    }
                    Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                }
                ActiveDocumentArchiveLoadPhase::FillMember => {
                    let member = active.member.as_mut().ok_or_else(|| plugin_sdk_fault("recursive document archive active member owner is absent"))?;
                    if member.fill_one_page(maximum_bytes)? {
                        active.phase = ActiveDocumentArchiveLoadPhase::RetireMemberSource;
                        return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                    }
                    Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 })
                }
                ActiveDocumentArchiveLoadPhase::RetireMemberSource => {
                    let member = active.member.as_mut().ok_or_else(|| plugin_sdk_fault("recursive document archive active member owner is absent"))?;
                    match member.retire_source_step(maximum_bytes) {
                        PluginCloseStep::Complete => {
                            active.phase = ActiveDocumentArchiveLoadPhase::AdmitMember;
                            Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                        }
                        step => Ok(step),
                    }
                }
                ActiveDocumentArchiveLoadPhase::AdmitMember => {
                    let handle = active.replacement.ok_or_else(|| plugin_sdk_fault("recursive document archive replacement handle is absent"))?;
                    let ingress = match active.member.as_mut().ok_or_else(|| plugin_sdk_fault("recursive document archive active member owner is absent"))?.take_ingress(handle) {
                        Ok(ingress) => ingress,
                        Err((fault, ingress)) => {
                            if !ingress.terminal_is_empty() {
                                active.rejected_ingress = Some(ingress);
                            }
                            return Err(fault);
                        }
                    };
                    if let Err((fault, ingress)) = self.admit_owned_document_member(handle, ingress) {
                        active.rejected_ingress = Some(ingress);
                        return Err(fault);
                    }
                    let member = active.member.take().ok_or_else(|| plugin_sdk_fault("recursive document archive transferred member owner changed before exact removal"))?;
                    if !member.terminal_is_empty() {
                        active.member = Some(member);
                        return Err(plugin_sdk_fault("recursive document archive admitted member retained a local owner"));
                    }
                    drop(member);
                    active.completed = active.completed.saturating_add(1);
                    active.phase = ActiveDocumentArchiveLoadPhase::BeginMember;
                    Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                }
                ActiveDocumentArchiveLoadPhase::SealMembers => {
                    let handle = active.replacement.ok_or_else(|| plugin_sdk_fault("recursive document archive replacement handle is absent"))?;
                    self.seal_owned_document_members(handle)?;
                    active.phase = ActiveDocumentArchiveLoadPhase::AwaitReplacement;
                    Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                }
                ActiveDocumentArchiveLoadPhase::AwaitReplacement => {
                    let handle = active.replacement.ok_or_else(|| plugin_sdk_fault("recursive document archive replacement handle is absent"))?;
                    let poll = self.poll_artifact_store_replacement(handle);
                    let target = match poll {
                        ArtifactEnvelopeDecodeOperationPoll::Pending | ArtifactEnvelopeDecodeOperationPoll::Progress => {
                            return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                        }
                        ArtifactEnvelopeDecodeOperationPoll::Ready => ActiveDocumentArchiveLoadState::Ready,
                        ArtifactEnvelopeDecodeOperationPoll::Cancelled => ActiveDocumentArchiveLoadState::Cancelled,
                        ArtifactEnvelopeDecodeOperationPoll::Fault => ActiveDocumentArchiveLoadState::Fault,
                    };
                    let refusal = self.artifact_store_replacement_refusal(handle);
                    if !self.acknowledge_artifact_store_replacement(handle)? {
                        return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                    }
                    active.replacement = None;
                    if target == ActiveDocumentArchiveLoadState::Fault {
                        active.fault = semio_framework_diagnostic::encode_fault_bytes(&refusal.unwrap_or_else(|| plugin_sdk_fault("document archive replacement failed closure, authority, or retained publication validation before it recorded a leg")));
                    }
                    active.request_terminal(target);
                    self.drive_document_archive_terminal(active, maximum_items, maximum_bytes)
                }
                ActiveDocumentArchiveLoadPhase::Terminal => Ok(PluginCloseStep::Complete),
            }
        }

        fn drive_document_archive_load_retirements(&mut self, maximum_items: usize, maximum_bytes: usize, closing: bool) -> Result<PluginCloseStep, Fault> {
            let cursor = if closing { &mut self.close_document_archive_cursor } else { &mut self.maintenance_document_archive_cursor };
            let Some((index, operation)) = self.document_archive_loads.next_id_from(*cursor) else {
                return Ok(PluginCloseStep::Complete);
            };
            *cursor = (index + 1) % ARTIFACT_LIVE_OUTPUT_SLOTS;
            let mut active = self.document_archive_loads.remove(operation).ok_or_else(|| plugin_sdk_fault("recursive document archive retirement authority changed during one bounded step"))?;
            if closing && !active.terminal() {
                active.request_terminal(ActiveDocumentArchiveLoadState::Cancelled);
            }
            let mut step = self.advance_document_archive_load(&mut active, maximum_items, maximum_bytes);
            if step.is_err() {
                let primary = step.expect_err("checked recursive archive step fault");
                active.request_fault(&primary);
                step = self
                    .drive_document_archive_terminal(&mut active, maximum_items, maximum_bytes)
                    .map_err(|cleanup| plugin_sdk_fault(format!("recursive document archive load failed before retained cleanup: {primary:?}; retained cleanup also failed: {cleanup:?}")));
            }
            if closing && active.terminal() && active.terminal_is_empty() {
                drop(active);
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            self.document_archive_loads.insert_admitted(operation, active);
            step
        }

        fn drive_envelope_ingress(&mut self, maximum_items: usize, maximum_bytes: usize, closing: bool) -> Result<PluginCloseStep, Fault> {
            let cursor = if closing { &mut self.close_envelope_ingress_cursor } else { &mut self.maintenance_envelope_ingress_cursor };
            let Some((index, operation_id)) = self.envelope_ingress.next_id_from(*cursor) else {
                return Ok(PluginCloseStep::Complete);
            };
            *cursor = (index + 1) % ARTIFACT_LIVE_OUTPUT_SLOTS;
            let ingress = self.envelope_ingress.get_mut(operation_id).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.ingress-owner"), "artifact envelope ingress changed during one bounded maintenance step"))?;
            if closing {
                ingress.closing = true;
            }
            if !ingress.closing {
                return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            }
            let step = ingress.close_step(maximum_items.min(1), maximum_bytes.min(store::ARTIFACT_ENVELOPE_DECODE_PAGE_BYTES));
            if step == PluginCloseStep::Complete {
                let ingress = self.envelope_ingress.remove(operation_id).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.ingress-owner"), "terminal artifact envelope ingress changed before exact removal"))?;
                if !ingress.terminal_is_empty() {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.ingress-false-terminal"), "artifact envelope ingress reported Complete before every page was released"));
                }
                drop(ingress);
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            Ok(step)
        }

        /// 🧾️ `drive`'s answer was computed BEFORE the two drain pumps above it, and the only thing
        /// a `ClosingCancelled` envelope is waiting for IS the completed-record pump: returning the
        /// pre-pump `Blocked` made a caller that treats `Blocked` as terminal (every bounded close
        /// loop does) abort on a ladder that had already unblocked itself in the same step.
        fn drive_envelope_decode_jobs(&mut self, maximum_items: usize, maximum_bytes: usize, closing: bool) -> Result<PluginCloseStep, Fault> {
            let cursor = if closing { &mut self.close_envelope_decode_cursor } else { &mut self.maintenance_envelope_decode_cursor };
            let Some((index, operation_id)) = self.envelope_decode_jobs.next_id_from(*cursor) else {
                return Ok(PluginCloseStep::Complete);
            };
            *cursor = (index + 1) % ARTIFACT_LIVE_OUTPUT_SLOTS;
            let pool = semio_framework_async::process_worker_pool(semio_framework_async::WorkerPoolConfig::new(semio_framework_async::ProcessKind::InteractiveNative, std::thread::available_parallelism().map_or(1, std::num::NonZeroUsize::get)));
            let live_generation = self
                .envelope_decode_jobs
                .get(operation_id)
                .map(|active| {
                    if closing {
                        active.cancel.cancel_now();
                    }
                    active.generation
                })
                .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.maintenance-owner"), "live envelope operation changed during one fixed maintenance step"))?;
            let mut step = self.envelope_decode_jobs.get_mut(operation_id).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.maintenance-owner"), "live envelope operation changed before worker advancement"))?.drive(
                &pool,
                live_generation,
                &self.envelope_completed_records,
                maximum_items,
                maximum_bytes,
            )?;
            #[cfg(target_arch = "wasm32")]
            if let Some(now_ms) = semio_framework_job::default_now_ms() {
                pool.pump(now_ms);
            }
            for _ in 0..ARTIFACT_LIVE_OUTPUT_SLOTS {
                match self.drive_envelope_field_decoder_returns(maximum_items, maximum_bytes, closing)? {
                    PluginCloseStep::Complete => break,
                    PluginCloseStep::Pending { .. } => {}
                    step => return Ok(step),
                }
            }
            for _ in 0..ARTIFACT_LIVE_OUTPUT_SLOTS {
                match self.drive_envelope_completed_record_returns(maximum_items, maximum_bytes, closing)? {
                    PluginCloseStep::Complete => break,
                    PluginCloseStep::Pending { .. } => {}
                    step => return Ok(step),
                }
            }
            if matches!(step, PluginCloseStep::Blocked { .. }) {
                if let Some(active) = self.envelope_decode_jobs.get_mut(operation_id) {
                    step = active.drive(&pool, live_generation, &self.envelope_completed_records, maximum_items, maximum_bytes)?;
                }
            }
            if self.envelope_decode_jobs.get(operation_id).is_some_and(|active| active.terminal_is_empty(&self.envelope_completed_records)) {
                let active = self.envelope_decode_jobs.remove(operation_id).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.maintenance-owner"), "terminal envelope operation changed before exact removal"))?;
                drop(active);
                return Ok(if self.envelope_decode_jobs.is_empty() { PluginCloseStep::Complete } else { PluginCloseStep::Pending { released_items: 1, released_bytes: 0 } });
            }
            Ok(step)
        }

        /// ⏳️ A follow pass waits on child retirements and the parent has not been followed since — pending, runnable
        /// work until maintenance returned them (see `child_follow_awaits_retirement`).
        fn derivable_follow_awaits_retirement(&self) -> bool {
            self.child_follow_awaits_retirement && self.store.generation_now() != self.followed_parent_generation
        }

        /// ♻️ Whether the next `roots` child-content and `members` child-member retirement generations each find a vacant
        /// slot of their fixed registry.
        fn child_retirements_admit(&self, roots: usize, members: usize) -> bool {
            (1..=roots as u64).all(|offset| self.child_content_generation.checked_add(offset).is_some_and(|generation| self.child_content_retirements.can_insert(generation)))
                && (1..=members as u64).all(|offset| self.child_member_retirement_generation.checked_add(offset).is_some_and(|generation| self.child_member_retirements.can_insert(generation)))
        }

        /// ⏳️ Bounded backpressure of a child publication: while the next `roots` child-content and `members` child-member
        /// retirement generations find no vacant slot, drives the child-root and child-member retirement stages one item at a
        /// time — at most [`CHILD_RETIREMENT_RECLAIM_STEPS`] rounds, ending at the first round that releases nothing — and
        /// answers whether the publication is admissible now. A commit cadence faster than the maintenance rotation (a typing
        /// burst over a content-addressed child) therefore waits on maintenance instead of faulting; `false` means every
        /// retirement ahead of it is still borrowed, and the follow pass and the mounted child publication then wait, in
        /// order, for the borrower to return it.
        fn reclaim_child_retirements(&mut self, roots: usize, members: usize) -> Result<bool, Fault> {
            if roots > ARTIFACT_LIVE_OUTPUT_SLOTS || members > ARTIFACT_LIVE_OUTPUT_SLOTS {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.child-root-retirement-span"), "one child publication span exceeds the fixed retirement authority"));
            }
            for _ in 0..CHILD_RETIREMENT_RECLAIM_STEPS {
                if self.child_retirements_admit(roots, members) {
                    return Ok(true);
                }
                let released = |step: PluginCloseStep| matches!(step, PluginCloseStep::Pending { released_items, released_bytes } if released_items > 0 || released_bytes > 0);
                let root = released(self.child_root_retirement_step(1, crate::plugin_runtime::RUNTIME_CLOSE_BYTES_PER_STEP)?);
                let member = released(self.child_member_retirement_step(1, crate::plugin_runtime::RUNTIME_CLOSE_BYTES_PER_STEP)?);
                if !root && !member {
                    break;
                }
            }
            Ok(self.child_retirements_admit(roots, members))
        }

        /// 🎟️ Admits the next immutable child-content publication once its retirement slot is vacant — reclaimed first when
        /// an older retirement still holds it ([`Self::reclaim_child_retirements`]).
        pub(crate) fn admit_child_content_publication(&mut self) -> Result<u64, Fault> {
            self.admit_child_content_publication_span(1)?;
            Ok(self.child_content_generation + 1)
        }

        /// 🎟️ Admits `count` consecutive child-content publications (see [`Self::admit_child_content_publication`]). Only a
        /// ring of retirements that are every one still borrowed answers the retryable
        /// `interactive-job.child-root-retirement-saturated`.
        fn admit_child_content_publication_span(&mut self, count: usize) -> Result<(), Fault> {
            if self.child_content_generation.checked_add(count as u64).is_none() {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.child-root-generation"), "immutable child-content generation exhausted"));
            }
            if !self.reclaim_child_retirements(count, 0)? {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.child-root-retirement-saturated"), "immutable child-content publication waits on retirements that are all still borrowed").with_retryable(true));
            }
            Ok(())
        }

        pub(crate) async fn publish_child_content_member(&mut self, generation: u64, slot: &str, child_id: &str) -> Result<(), Fault> {
            if generation != self.child_content_generation.saturating_add(1) || !self.child_content_retirements.can_insert(generation) {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.child-root-publication-authority"), "immutable child-content publication lost its exact admitted generation"));
            }
            let entry =
                self.children.get(&(slot.to_string(), child_id.to_string())).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.child-root-member"), "immutable child-content publication lost its exact live member"))?;
            let next = self.child_content_root.with_member(slot, child_id, &entry.reference.dialect, &entry.member).await?;
            let previous = std::mem::replace(&mut *self.child_content_root, next);
            if previous.root.as_ref().is_some_and(|root| root.len != 0) {
                self.child_content_retirements.insert_admitted(generation, ChildContentRetirement::new(previous, false));
            }
            self.child_content_generation = generation;
            Ok(())
        }

        fn peer_roster_slot(generation: u64) -> usize {
            generation as usize % ARTIFACT_LIVE_OUTPUT_SLOTS
        }

        /// 🧭️ The lowest mounted peer roster publication the ordered cursor has already passed. A
        /// publication whose generation is not ahead of `peer_roster_processed_generation` can never be the
        /// rotation's next exact generation again, so without this the maintenance stage answers
        /// `Pending { 0, 0 }` for it forever: it never reaches its outcome slot, `take_presence_outcome`
        /// never answers, and the app's close conjunction — which demands an empty publication registry —
        /// is unreachable. Walking it through the very same validate/outcome ladder lets
        /// `validate_peer_roster_publication` refuse its generation and hand the refusal to its caller.
        fn orphaned_peer_roster_generation(&self) -> Option<u64> {
            let processed = self.peer_roster_processed_generation;
            let mut orphaned: Option<u64> = None;
            self.peer_roster_publications.each_id(|generation| {
                if generation <= processed && orphaned.is_none_or(|lowest| generation < lowest) {
                    orphaned = Some(generation);
                }
            });
            orphaned
        }

        fn validate_peer_roster_publication(&self, seq: u64, generation: u64, cancel: &semio_framework_job::CancelToken) -> Result<ValidatedPeerRosterCommit, Fault> {
            let slot = Self::peer_roster_slot(generation);
            if self.peer_roster_reservations[slot] != Some((generation, seq))
                || generation != self.peer_roster_processed_generation.checked_add(1).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-roster-generation"), "peer roster publication generation exhausted"))?
                || !self.peer_presence_retirements.can_insert(generation)
                || !self.presence_peer_retirements.can_insert(generation)
                || !self.peer_roster_outcomes.can_insert(generation)
                || !self.presence_store.peer_retirement_available()
                || self.presence_store.retirement_started()
            {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-roster-publication-authority"), "peer roster lost its exact generation, outcome, or retirement admission before publication"));
            }
            if ::semio_framework_async::poll::resolve_ready(cancel.is_cancelled()) {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-roster-cancelled"), "peer roster publication was cancelled before atomic commit"));
            }
            Ok(ValidatedPeerRosterCommit { generation })
        }

        #[expect(clippy::result_large_err, reason = "Refusal returns the original fixed-capacity input so its caller can retry or retire that exact owner without an extra allocation.")]
        #[expect(clippy::needless_pass_by_value, reason = "This non-Copy token conveys one-use admission authority and must be consumed by the commit, even though its identity fields are scalar.")]
        fn publish_peer_roster_candidate_admitted(&mut self, admission: ValidatedPeerRosterCommit, candidate: PeerRosterCandidate<A::Presence>) -> Result<(), PeerRosterCandidate<A::Presence>> {
            let PeerRosterCandidate { seq, generation: candidate_generation, cancel, own_color, now_ms, root, typed } = candidate;
            let ValidatedPeerRosterCommit { generation } = admission;
            let _ = now_ms;
            let typed_retirement = match self.presence_store.publish_peer_commit(typed) {
                Ok(retirement) => retirement,
                Err(typed) => return Err(PeerRosterCandidate { seq, generation: candidate_generation, cancel, own_color, now_ms, root, typed }),
            };
            let previous = std::mem::replace(&mut *self.peer_presence, root);
            if previous.is_empty() {
                drop(previous);
            } else {
                self.peer_presence_retirements.insert_admitted(generation, PeerPresenceRootRetirement::new(previous));
            }
            self.own_color = own_color;
            self.peer_presence_generation = generation;
            if let Some(retirement) = typed_retirement {
                self.presence_peer_retirements.insert_admitted(generation, retirement);
            }
            Ok(())
        }

        async fn admit_child_member(&mut self, slot: String, child_id: String, dialect: ArtifactDialect) -> Result<ChildStoreAdmission, Fault> {
            let root_index = self.child_content_root.admit_member(&slot, &child_id)?;
            let parent_dialect: ArtifactDialect = A::DIALECT.into();
            if self.store.envelope().dialect.as_ref() != Some(&parent_dialect) {
                return Err(plugin_sdk_fault("owned member admission requires the parent's exact declared dialect"));
            }
            let generation = self.admit_child_content_publication()?;
            let parent_id = self.store.envelope().id.clone();
            let graph = self.composition.graph_mut().await.admit_owns(&parent_id, &slot, &child_id).await.map_err(|error| plugin_sdk_fault(error.to_string()))?;
            let expected = ArtifactRef { artifact_id: child_id.clone(), dialect };
            let owner = store::OwnerRef { parent: ArtifactRef { artifact_id: parent_id, dialect: parent_dialect }, slot: slot.clone(), child_id: child_id.clone() };
            let key = (slot, child_id);
            let member = self.children.admit(&key)?;
            Ok(ChildStoreAdmission { key, expected, owner, member, graph, root_index, generation })
        }

        async fn prepare_child_member(&self, admission: &ChildStoreAdmission, member: &mut M, restored: bool) -> Result<(ChildContentView, Option<usize>), Fault> {
            let owner = member.owner_ref();
            if member.artifact_ref().as_ref() != Some(&admission.expected) || (owner.as_ref() != Some(&admission.owner) && (restored || owner.is_some())) {
                return Err(plugin_sdk_fault("child member does not match its exact admitted identity and ownership"));
            }
            let pin_index = self.pending_child_pins.iter().position(|pin| pin.child_ref.artifact_id == admission.expected.artifact_id);
            if let Some(index) = pin_index {
                if !restored {
                    return Err(plugin_sdk_fault("direct child registration cannot consume a queued restore checkpoint"));
                }
                let pin = &self.pending_child_pins[index];
                if pin.child_ref != admission.expected {
                    return Err(plugin_sdk_fault("pending child checkpoint belongs to a different exact dialect"));
                }
                let alternative = member.current_alternative_id().await.ok_or_else(|| plugin_sdk_fault("pending child checkpoint has no live alternative authority"))?;
                member.checkout(&pin.checkpoint_id, &alternative).await.map_err(|error| plugin_sdk_fault(error.to_string()))?;
            }
            let root = self.child_content_root.capture_member_admitted(admission.root_index, &admission.key.0, &admission.key.1, &admission.expected.dialect, member).await?;
            Ok((root, pin_index))
        }

        async fn commit_child_member(&mut self, admission: ChildStoreAdmission, mut member: M, root: ChildContentView, pin_index: Option<usize>) {
            member.set_owner(Some(admission.owner.clone())).await;
            self.composition.graph_mut().await.commit_owns_admitted(admission.graph);
            self.children.insert_admitted(admission.member, admission.expected, admission.owner, member);
            let previous = std::mem::replace(&mut *self.child_content_root, root);
            if !previous.is_empty() {
                self.child_content_retirements.insert_admitted(admission.generation, ChildContentRetirement::new(previous, false));
            }
            self.child_content_generation = admission.generation;
            if let Some(index) = pin_index {
                self.pending_child_pins.remove(index);
            }
        }

        #[cfg(test)]
        pub(super) fn test_child_admission_state(&self, abort_generation: u64) -> ChildAdmissionTestState {
            ChildAdmissionTestState {
                children_empty: self.children.is_empty(),
                generation: self.child_content_generation,
                abort_generation: self.child_member_retirement_generation,
                abort_empty: self.child_member_retirements.is_empty(),
                requested_abort_retained: self.child_member_retirements.get(abort_generation).is_some(),
                content_empty: self.child_content_root.is_empty(),
                roots_retiring_empty: self.child_content_retirements.is_empty(),
            }
        }

        /// 🧹 One bounded close step for the head keyed (latest-wins) command. Deliberately its own
        /// `#[inline(never)]` frame: `PendingLatestWinsCommand<A>` and the
        /// `MountedTypedCommandFullOperation<A>` it retires are ~35 KiB apiece, and an unoptimized build
        /// gives every by-value move of them a separate, non-overlapping slot in whatever frame spells
        /// them — inline in `close_step` that stage alone cost more stack than a plugin close ever gets
        /// (ticket 26/09/09/PROCEDURAL-3D-END-TO-END, `📓️selection-overflow-2026-09-09.md`).
        #[inline(never)]
        fn close_latest_wins_command_step(&mut self, operation_id: u64, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            let pending = self.latest_wins_commands.get_mut(operation_id).expect("exact closing keyed command");
            let step = pending.close_step(maximum_items.min(1), maximum_bytes)?;
            if pending.command_owners_are_empty() {
                if let Some(step) = MountedTypedCommandFullOperation::<A>::retire_string_scalar(&mut pending.meta.actor, maximum_bytes) {
                    return Ok(step);
                }
                if let Some(lease) = pending.lease.take() {
                    lease.finish();
                }
                drop(self.latest_wins_commands.remove(operation_id));
                self.typed_operation_reservations[operation_id as usize % ARTIFACT_LIVE_OUTPUT_SLOTS] = None;
                assert_eq!(self.latest_wins_order.pop(), Some(operation_id));
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            Ok(if step == PluginCloseStep::Complete { PluginCloseStep::Pending { released_items: 1, released_bytes: 0 } } else { step })
        }

        /// ♻️ The ONE release site of an admitted typed-operation slot. Every outcome an operation can reach
        /// — settled, faulted, refused, replaced, cancelled — funnels its mounted owner into
        /// [`MountedTypedCommandFullOperationStage::Retiring`], and this is the only code that may remove it
        /// from `tool_operations` and so free its residue class for [`Self::admit_typed_operation_slot`]: one
        /// bounded retirement unit, the terminal-empty witness, then the exact removal. The turn driver
        /// ([`Self::advance_typed_operation_publication_one`]), the cooperative maintenance rotation and the
        /// app close ladder all walk THIS function, so no authority can admit a slot and leave its release to
        /// another (ticket 26/09/02/PUZZLE-3D-END-TO-END wave B8).
        /// 🧾️ The migrated twin of [`Self::dispatch_emit`]'s own command-log append. A typed command's
        /// emit reaches its stores through the mounted publication ladder, which never walks
        /// `dispatch_emit`, so before this every migrated dispatch reached the history panel only as
        /// [`Self::backfill_command_log`]'s anonymous `apply` row — losing the verb, its
        /// declared [`ActionKind`], its own label and its revert target — and a dispatch that published
        /// no durable lane at all (a `Mutation` verb whose reducer emitted nothing, every `View` verb
        /// such as `select`) reached it not at all.
        ///
        /// It runs on the durable RECEIPT, not at retirement, because the operation mints its `Ui` page
        /// between the two and rendering the history body backfills: an edit this row owns would already
        /// be filed under `apply` by the time the slot retired. Only the document lane opens or amends a row: a config-lane
        /// edit is never a history row (design §20.13, L4). A coalesced gesture amends the edit its first dispatch already
        /// logged, so later dispatches append no second row — and they mark that row dirty, so the admitting completion
        /// re-upserts it.
        fn record_typed_operation_lane(&mut self, mounted: &mut MountedTypedCommandFullOperation<A>) {
            if mounted.terminal_fault.is_some() {
                return;
            }
            let Some(edit_id) = self.store.envelope().vcs.edits.last().map(|edit| edit.id.clone()) else { return };
            let logged_seq = self.command_log.iter().find(|entry| entry.edit_id.as_deref() == Some(edit_id.as_str())).map(|entry| entry.seq);
            if let Some(seq) = logged_seq {
                mounted.command_logged = true;
                self.history_dirty_sequences.insert(seq);
                return;
            }
            if mounted.command_logged {
                if let Some(entry) = self.command_log.last_mut().filter(|entry| entry.action_id == mounted.verb) {
                    entry.edit_id = Some(edit_id);
                    self.history_dirty_sequences.insert(entry.seq);
                    self.log_generation += 1;
                }
                return;
            }
            mounted.command_logged = true;
            let kind = self.typed_operation_command_kind(&mounted.verb, true);
            let verb = mounted.verb.clone();
            let label = self.verb_label(&verb);
            self.record_command(&verb, kind, label, Some(edit_id), Vec::new(), None);
        }

        /// 📨️ Delivers `event` to the app: its typed answer ([`ArtifactApp::host_event`]) dispatches to the event's window —
        /// addressed through `meta`'s view when it holds that window, else through the last roster — as an ordinary typed
        /// operation that is never a history row of its own. An event the app ignores, or for a window no view holds,
        /// dispatches nothing.
        async fn deliver_host_event(&mut self, event: HostEvent, meta: &ActionMeta) -> Result<(), Fault> {
            let Some(command) = A::host_event(&event) else { return Ok(()) };
            let window_id = event.window_id();
            let view = meta.view_state.as_ref().and_then(|view| view.for_window_instance(window_id)).or_else(|| ViewModel { window_instances: self.host_event_roster.clone(), ..meta.view_state.as_ref()?.clone() }.for_window_instance(window_id));
            let Some(view) = view else { return Ok(()) };
            let window_meta = ActionMeta { view_state: Some(view), ..meta.clone() };
            let verb = A::command_id(&command).await;
            let payload = ::protocol::OpBinary::encode_op(&command).map_err(|error| error.into_fault())?;
            let admission = self.admit_command_wire(verb, &payload, 1).await?;
            self.delivering_host_event = true;
            let result = Box::pin(self.dispatch_typed_command_inner(Box::new(command), admission, &window_meta)).await;
            self.delivering_host_event = false;
            result.map(|_| ())
        }

        /// 🧰️ Delivers [`HostEvent::UtilityChanged`] for every window whose utility `meta`'s view moved since a dispatch
        /// last showed it — the targeted window reads the per-call overlay, every other one the view's map, and a window
        /// the view names no utility for is unknown, never a switch — and remembers the view's window roster.
        async fn deliver_utility_host_events(&mut self, meta: &ActionMeta) -> Result<(), Fault> {
            let Some(view) = meta.view_state.as_ref().filter(|_| !self.delivering_host_event) else { return Ok(()) };
            if !view.window_instances.is_empty() && self.host_event_roster != view.window_instances {
                self.host_event_roster = view.window_instances.clone();
                self.host_event_utilities.retain(|window_id, _| view.window_instances.iter().any(|window| window.id == *window_id));
            }
            let mut switched = Vec::new();
            for window in &view.window_instances {
                let utility = if view.window_id.as_deref() == Some(window.id.as_str()) { Some(view.active_utility_id.as_deref()) } else { view.active_utility_by_window_id.get(&window.id).map(|utility| Some(utility.as_str())) };
                let Some(utility) = utility else { continue };
                match self.host_event_utilities.get_mut(&window.id) {
                    Some(previous) if previous.as_deref() == utility => {}
                    Some(previous) => {
                        let from = std::mem::replace(previous, utility.map(str::to_string));
                        switched.push(HostEvent::UtilityChanged { window_id: window.id.clone(), from, to: utility.map(str::to_string) });
                    }
                    None => {
                        self.host_event_utilities.insert(window.id.clone(), utility.map(str::to_string));
                    }
                }
            }
            for event in switched {
                self.deliver_host_event(event, meta).await?;
            }
            Ok(())
        }

        /// 🌐️ Delivers one instance-wide event, built per window, to every window of `meta`'s view, else of the last roster.
        pub(crate) async fn deliver_host_event_to_every_window(&mut self, event: impl Fn(String) -> HostEvent, meta: &ActionMeta) -> Result<(), Fault> {
            let roster = meta.view_state.as_ref().map(|view| view.window_instances.as_slice()).filter(|roster| !roster.is_empty()).unwrap_or(&self.host_event_roster);
            let windows: Vec<String> = roster.iter().map(|window| window.id.clone()).collect();
            for window_id in windows {
                self.deliver_host_event(event(window_id), meta).await?;
            }
            Ok(())
        }

        /// 🌐️ Delivers [`HostEvent::BaseMoved`] to every window once a remote edit moved the base, as the local actor.
        async fn deliver_base_moved(&mut self) -> Result<(), Fault> {
            let (Some(instance_id), Some(actor)) = (self.live_runtime_instance_id, self.store.local_actor_id()) else { return Ok(()) };
            let meta = ActionMeta { actor: actor.to_string(), instance_id, view_state: None };
            self.deliver_host_event_to_every_window(|window_id| HostEvent::BaseMoved { window_id }, &meta).await
        }

        /// 📨️ `hostEvent{windowId, kind}`: the host-forwarded window fact, delivered at once; an unknown kind or a
        /// missing window is refused.
        async fn dispatch_host_event_action(&mut self, args: Option<&DslValue>, meta: &ActionMeta) -> Result<InvocationResult, Fault> {
            let text = |key: &str| args.and_then(|value| value.get(key)).and_then(DslValue::as_str);
            let event = text(semio_framework::HOST_EVENT_ARG_WINDOW_ID).zip(text(semio_framework::HOST_EVENT_ARG_KIND)).and_then(|(window_id, kind)| HostEvent::forwarded(window_id, kind));
            let Some(event) = event else {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("hostEvent.invalid"), "hostEvent requires a windowId and a kind of blur, captureLost or retiring"));
            };
            self.deliver_host_event(event, meta).await?;
            Ok(Self::empty_result(semio_framework::HOST_EVENT_ACTION_ID, meta, Vec::new(), Vec::new(), UiDirtyScope::None).await)
        }

        /// 🧾️ A settled typed operation that published no document lane and no shared-config lane still
        /// owes the history panel one row, on the admitting completion: `dispatch_emit`'s empty
        /// `artifact_mutations` branch files the verb under its declared kind (`View` for `select`,
        /// `Mutation` for a reducer that emitted nothing, `edit_id: None`). Recording that row only from
        /// retirement lands it after [`Self::take_typed_operation_completion`] has built `history_patch`,
        /// so the row surfaced on the next command. Both the completion take and
        /// [`Self::retire_typed_operation_unit`] call this; `command_logged` makes the second a no-op.
        /// Silent for a faulted operation, exactly as `dispatch_emit`'s `Err` path is, and for a `View`
        /// whose only durable emission is the per-window config lane — an orbit tick is not a command.
        fn record_settled_typed_operation_command(&mut self, operation_id: u64) {
            if self.host_event_operations.remove(&operation_id) {
                if let Some(operation) = self.tool_operations.get_mut(operation_id) {
                    operation.command_logged = true;
                }
                return;
            }
            let logged = {
                let Some(operation) = self.tool_operations.get(operation_id) else { return };
                if operation.command_logged || operation.terminal_fault.is_some() || operation.published_artifact || operation.published_config {
                    return;
                }
                let kind = self.typed_operation_command_kind(&operation.verb, false);
                if operation.published_window_config && matches!(kind, ActionKind::View) {
                    return;
                }
                (operation.verb.clone(), kind)
            };
            let (verb, kind) = logged;
            if let Some(operation) = self.tool_operations.get_mut(operation_id) {
                operation.command_logged = true;
            }
            self.record_command(&verb, kind, None, None, Vec::new(), None);
        }

        /// 🧾️ The declared [`ActionKind`] one migrated verb logs under — the same three-step resolution
        /// [`Self::dispatch_emit`] runs, with the same last resort: an unresolved verb that reached a
        /// document store is a `Mutation`, one that reached nothing is a `View`.
        fn typed_operation_command_kind(&self, verb: &str, artifact_lane: bool) -> ActionKind {
            match self.invocation_kind {
                Some(kind) => kind,
                None => match self.registry.get(verb).map(|definition| definition.kind) {
                    Some(kind) => kind,
                    None => match self.registry.get_command(verb) {
                        Some(definition) => definition.kind,
                        None if artifact_lane => ActionKind::Mutation,
                        None => ActionKind::View,
                    },
                },
            }
        }

        #[inline(never)]
        fn retire_typed_operation_unit(&mut self, operation_id: u64, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            self.record_settled_typed_operation_command(operation_id);
            let operation = self
                .tool_operations
                .get_mut(operation_id)
                .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.typed-operation-retirement-authority"), "typed operation owner changed during one bounded retirement unit"))?;
            let step = operation.retirement_step(maximum_items.min(1), maximum_bytes)?;
            if step != PluginCloseStep::Complete {
                return Ok(step);
            }
            if !self.tool_operations.get(operation_id).is_some_and(MountedTypedCommandFullOperation::terminal_is_empty) {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.typed-operation-terminal"), "typed operation reported Complete without exact terminal emptiness"));
            }
            let operation =
                self.tool_operations.remove(operation_id).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.typed-operation-retirement-authority"), "terminal typed operation changed before exact removal"))?;
            self.operation_progress_retired |= operation.progress.is_some();
            drop(operation);
            self.typed_inline_interaction_verbs.retain(|(operation, _)| *operation != operation_id);
            Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
        }

        /// ♻️ Drives ONE retiring typed operation for a bounded slice of this turn, the exact twin of the
        /// slice [`Self::drive_typed_operation_worker`] gives a Worker-stage operation — same ladder, same
        /// owner, same `INTERACTIVE_TURN_WORKER_PUMPS`/`INTERACTIVE_TURN_WORKER_WALL_US` bound. Without it a
        /// `Retiring` operation answered `has_runnable_typed_operations` forever while the turn driver advanced nothing
        /// for it: the slot was released only by `maintenance_step` stage 0 of [`MAINTENANCE_STAGES`], one
        /// unit per rotation on the shared live-cleanup job, so a sustained action rate filled all
        /// [`ARTIFACT_LIVE_OUTPUT_SLOTS`] classes and every later action was refused
        /// `interactive-job.typed-operation-capacity`.
        fn retire_typed_operation_run(&mut self, operation_id: u64) -> Result<(), Fault> {
            let started_us = semio_framework_job::default_now_us();
            for _ in 0..INTERACTIVE_TURN_WORKER_PUMPS {
                if !self.tool_operations.get(operation_id).is_some_and(|operation| operation.stage == MountedTypedCommandFullOperationStage::Retiring) {
                    return Ok(());
                }
                if matches!(self.retire_typed_operation_unit(operation_id, 1, TYPED_OPERATION_RESULT_PAGE_BYTES)?, PluginCloseStep::Blocked { .. } | PluginCloseStep::AwaitingInput { .. }) {
                    return Ok(());
                }
                if started_us.is_some_and(|started_us| semio_framework_job::default_now_us().is_some_and(|now_us| now_us.saturating_sub(started_us) >= INTERACTIVE_TURN_WORKER_WALL_US)) {
                    return Ok(());
                }
            }
            Ok(())
        }

        /// 🧹 One bounded close step for the head mounted typed operation — the same frame-isolation
        /// reasoning as [`Self::close_latest_wins_command_step`], for the registry that owns the 35 KiB
        /// `MountedTypedCommandFullOperation<A>` outright.
        #[inline(never)]
        fn close_typed_operation_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            let Some((_, operation_id)) = self.tool_operations.next_id_from(0) else {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-typed-operation-authority"), "typed operation registry changed during bounded close"));
            };
            let stage = self
                .tool_operations
                .get(operation_id)
                .map(|operation| operation.stage)
                .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-typed-operation-authority"), "typed operation owner changed during bounded close"))?;
            if stage == MountedTypedCommandFullOperationStage::Retiring {
                return self.retire_typed_operation_unit(operation_id, maximum_items, maximum_bytes);
            }
            let operation = self.tool_operations.get_mut(operation_id).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-typed-operation-authority"), "typed operation owner changed during bounded close"))?;
            let step = match stage {
                MountedTypedCommandFullOperationStage::Worker => {
                    let pool =
                        semio_framework_async::process_worker_pool(semio_framework_async::WorkerPoolConfig::new(semio_framework_async::ProcessKind::InteractiveNative, std::thread::available_parallelism().map_or(1, std::num::NonZeroUsize::get)));
                    operation.drive_worker_step(&pool, maximum_bytes)?
                }
                MountedTypedCommandFullOperationStage::Publishing => {
                    operation.stage = MountedTypedCommandFullOperationStage::Retiring;
                    PluginCloseStep::Pending { released_items: 1, released_bytes: 0 }
                }
                MountedTypedCommandFullOperationStage::AwaitingAck => {
                    let bytes = operation.result_page.as_ref().map_or(0, |page| page.len);
                    if bytes > maximum_bytes {
                        return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                    }
                    operation.result_page = None;
                    operation.stage = MountedTypedCommandFullOperationStage::Retiring;
                    PluginCloseStep::Pending { released_items: 1, released_bytes: bytes }
                }
                MountedTypedCommandFullOperationStage::Retiring => unreachable!("the retiring stage is released by its one exact retirement site"),
            };
            if step == PluginCloseStep::Complete {
                if !self.tool_operations.get_mut(operation_id).is_some_and(|operation| operation.terminal_is_empty()) {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-typed-operation-terminal"), "typed operation close reported Complete without exact terminal emptiness"));
                }
                let operation =
                    self.tool_operations.remove(operation_id).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.close-typed-operation-authority"), "terminal typed operation changed before exact removal"))?;
                drop(operation);
                self.typed_inline_interaction_verbs.retain(|(operation, _)| *operation != operation_id);
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            Ok(step)
        }

        /// 🍂️ One bounded unit of child-root retirement — the body of stage [`MAINTENANCE_CHILD_ROOT_STAGE`], also run out of
        /// turn under child pressure and by [`Self::reclaim_child_retirements`] (which needs it without the maintenance impl's
        /// `M: Send`).
        fn child_root_retirement_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            let Some((index, generation)) = self.child_content_retirements.next_id_from(self.maintenance_child_root_cursor) else {
                return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            };
            let step = {
                let retirements = &mut self.child_content_retirements;
                let children = &mut self.children;
                let retiring = &mut self.child_member_retirements;
                let current = &*self.child_content_root;
                let owners = retirements.sibling_content_owners(generation);
                retirements
                    .get_mut(generation)
                    .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.maintenance-child-root-authority"), "live child root retirement authority changed during one fixed step"))?
                    .close_step(children, Some(retiring), current, &owners, maximum_items, maximum_bytes)?
            };
            if step != PluginCloseStep::Complete {
                self.maintenance_child_root_cursor = index;
                return Ok(step);
            }
            if !self.child_content_retirements.get(generation).is_some_and(ChildContentRetirement::terminal_is_empty) {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.maintenance-child-root-terminal-not-empty"), "live child root retirement reported Complete without its exact terminal-empty witness"));
            }
            let retirement = self
                .child_content_retirements
                .remove(generation)
                .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.maintenance-child-root-authority"), "terminal live child root retirement changed before exact removal"))?;
            drop(retirement);
            self.maintenance_child_root_cursor = (index + 1) % ARTIFACT_LIVE_OUTPUT_SLOTS;
            Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
        }

        fn child_member_retirement_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            let Some((index, generation)) = self.child_member_retirements.next_id_from(self.child_member_retirement_cursor) else {
                return Ok(PluginCloseStep::Complete);
            };
            self.child_member_retirement_cursor = (index + 1) % ARTIFACT_LIVE_OUTPUT_SLOTS;
            let retirement = self.child_member_retirements.get_mut(generation).expect("exact child-member retirement remains admitted");
            if retirement.entry.as_ref().is_some_and(|entry| !entry.member.snapshot_read_leases_terminal_is_empty()) {
                return Ok(PluginCloseStep::Blocked { reason: "retired child member still lends a snapshot to a retiring child root" });
            }
            let step = retirement.close_step(maximum_items.min(1), maximum_bytes)?;
            if step == PluginCloseStep::Complete {
                assert!(retirement.terminal_is_empty(), "retired child member reports its exact terminal-empty witness");
                drop(self.child_member_retirements.remove(generation));
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            Ok(step)
        }

        fn validate_parent_child_restore(&self, slot: &str, expected: &ArtifactRef) -> Result<(), Fault> {
            let parent_dialect: ArtifactDialect = A::DIALECT.into();
            if self.store.envelope().dialect.as_ref() != Some(&parent_dialect) {
                return Err(plugin_sdk_fault("child restore requires the parent's exact declared dialect"));
            }
            let parent = ArtifactRef { artifact_id: self.store.envelope().id.clone(), dialect: parent_dialect };
            let source = DocumentClosureSourceView::new(self.store.generation_now(), &parent, self.store.snapshot_ref(), &self.children);
            if !store::OwnedDocumentClosureSource::child_projection(&source, None).map_err(|error| plugin_sdk_fault(format!("child restore projection failed: {error:?}")))?.admits_member(slot, expected) {
                return Err(plugin_sdk_fault("child restore is not declared by the loaded parent snapshot"));
            }
            Ok(())
        }

        /// 🌱️ Restores one exact owned member and publishes its graph, map and snapshot together.
        pub async fn open_child(&mut self, slot: impl Into<String>, child_id: impl Into<String>, dialect: ArtifactDialect, envelope_pack: &[u8]) -> Result<(), Fault> {
            let slot = slot.into();
            let child_id = child_id.into();
            let expected = ArtifactRef { artifact_id: child_id.clone(), dialect: dialect.clone() };
            self.validate_parent_child_restore(&slot, &expected)?;
            let parent_generation = self.store.generation_now();
            let abort_generation = self.child_member_retirement_generation.checked_add(1).ok_or_else(|| plugin_sdk_fault("failed child retirement generation exhausted"))?;
            if !self.reclaim_child_retirements(0, 1)? {
                return Err(plugin_sdk_fault("failed child retirement waits on retirements that are all still borrowed").with_retryable(true));
            }
            let admission = self.admit_child_member(slot, child_id, dialect).await?;
            let mut member = match M::open(&admission.expected, Some(&admission.owner), envelope_pack).await {
                Ok(member) => member,
                Err(error) => {
                    assert!(self.children.cancel_admission(&admission.member), "failed child open retains its exact admission until cancellation");
                    return Err(plugin_sdk_fault(error.to_string()));
                }
            };
            let prepared = if self.store.generation_now() != parent_generation {
                Err(plugin_sdk_fault("loaded parent changed during child restore"))
            } else {
                match self.validate_parent_child_restore(&admission.key.0, &admission.expected) {
                    Ok(()) => self.prepare_child_member(&admission, &mut member, true).await,
                    Err(fault) => Err(fault),
                }
            };
            let (root, pin_index) = match prepared {
                Ok(prepared) => prepared,
                Err(fault) => {
                    assert!(self.children.cancel_admission(&admission.member), "failed child preparation returns its exact map admission");
                    self.child_member_retirements.insert_admitted(abort_generation, ChildMemberRetirement::new(ChildMemberEntry { reference: admission.expected, owner: admission.owner, member }));
                    self.child_member_retirement_generation = abort_generation;
                    return Err(fault);
                }
            };
            self.commit_child_member(admission, member, root, pin_index).await;
            Ok(())
        }

        /// 🔎️ The live child store for `(slot, child_id)`, if adopted/created — the read half of
        /// `open_child`/`register_child`.
        pub async fn child_store(&self, slot: &str, child_id: &str) -> Option<&M> {
            self.children.get(&(slot.to_string(), child_id.to_string())).map(|entry| &entry.member)
        }

        /// 📣️ Announces every live composed member's whole event log on the PARENT's backbone
        /// under that member's own `(slot, child_id)` lane. A composed document owns exactly one
        /// replica endpoint — `ArtifactStore::announce_history` covers the parent lane alone, so
        /// without this a joining replica never learns a single child-lane edit and the two replicas
        /// diverge on the very content a composing plugin keeps in its children (measured on
        /// `🌊️flow`'s `content` child, ticket 26/09/19 `📓️flow.md` §5.3).
        async fn announce_member_event_logs(&mut self) -> Result<(), Fault> {
            if self.children.is_empty() {
                return Ok(());
            }
            let mut lanes: Vec<(String, String)> = Vec::with_capacity(self.children.len());
            for entry in self.children.entries() {
                lanes.push((entry.owner.slot.clone(), entry.reference.artifact_id.clone()));
            }
            for (slot, child_id) in lanes {
                let Some(entry) = self.children.get_mut(&(slot.clone(), child_id.clone())) else { continue };
                let payload = store::SpaceMember::event_log_payload(&entry.member).await.map_err(|error| error.into_fault())?;
                self.store.send_member_mutations(&slot, &child_id, payload).await.map_err(|error| error.into_fault())?;
            }
            Ok(())
        }

        /// 📤️ Announces the tail edit of every member a composite gesture just touched, under
        /// that member's own lane. Called from the ONE choke point child edits land at
        /// (`dispatch_emit_group`), so a child-lane edit travels exactly like a parent-lane one.
        async fn announce_member_tail_edits(&mut self, lanes: &[(String, String)]) -> Result<(), Fault> {
            if self.store.backbone_ref().is_none() {
                return Ok(());
            }
            for (slot, child_id) in lanes {
                let Some(entry) = self.children.get_mut(&(slot.clone(), child_id.clone())) else { continue };
                let payload = store::SpaceMember::announce_tail_edit_payload(&mut entry.member).await.map_err(|error| error.into_fault())?;
                self.store.send_member_mutations(slot, child_id, payload).await.map_err(|error| error.into_fault())?;
            }
            Ok(())
        }

        /// 📥️ Routes every member-addressed backbone message the parent store pumped into the
        /// live member that owns that exact lane, and answers how many lanes folded something. Runs after the
        /// derivable children followed the freshly folded parent, so a lane for the child a parent op just named
        /// finds its member. A lane naming a member the CURRENT parent declares but this replica does not hold is
        /// a fault, never a silent drop: the two replicas would otherwise disagree about the document's own
        /// composition. A lane naming a child the parent no longer declares is a superseded content address (a
        /// peer's lane for the child its own later edit — or ours — replaced), and a lane naming a child the
        /// follow pass has not opened yet because it waits on retirements is the child that pass derives: both
        /// carry nothing the composition does not already hold and are skipped.
        async fn fold_member_inbound(&mut self) -> Result<usize, Fault> {
            let inbound = self.store.take_member_inbound();
            if inbound.is_empty() {
                return Ok(0);
            }
            let mut folded = 0usize;
            for (slot, child_id, envelopes) in inbound {
                let Some(entry) = self.children.get_mut(&(slot.clone(), child_id.clone())) else {
                    let projection = store::ChildRestoreProjection::from_snapshot(self.store.snapshot_ref()).map_err(|error| plugin_sdk_fault(format!("member lane projection failed: {error}")))?;
                    if !self.derivable_follow_awaits_retirement() && (0..projection.len()).filter_map(|index| projection.get(index)).any(|(declared, fields)| declared.to_string() == slot && fields.child_id.to_string() == child_id) {
                        return Err(plugin_sdk_fault(format!("backbone member lane {slot}/{child_id} names no live composed member of this replica")));
                    }
                    continue;
                };
                store::SpaceMember::ingest_remote_payload(&mut entry.member, &envelopes).await.map_err(|error| error.into_fault())?;
                folded += 1;
            }
            self.cache = None;
            Ok(folded)
        }

        /// 🌱️ Adopts an already-live `M` member into the child-store map directly — the
        /// counterpart `dispatch_emit_group` uses to absorb a `store::GroupReceipt::created_children`
        /// entry (a `ChildGenesis`-minted member has no prior caller-held reference an `open_child`
        /// call could have produced it from) and the general escape hatch for a caller that already
        /// holds a constructed member from elsewhere (e.g. a host-level `SpaceHost`).
        /// 🌱️ Adopts an already-built child store under `(slot, child_id)`. Like [`Self::open_child`]
        /// it MUST seed the ownership edge into `self.composition`'s graph: `dispatch_group`'s phase 1
        /// ownership check (`CompositionGraph::owner_of`) is fail-closed, so a child present in
        /// `self.children` but absent from the graph is rejected as an `OwnershipViolation` the first
        /// time anything dispatches against it. Registering in one place and validating from the other
        /// is precisely the inconsistency this seeds away.
        pub async fn register_child(&mut self, slot: impl Into<String>, child_id: impl Into<String>, dialect: ArtifactDialect, mut member: M) -> Result<(), ChildMemberRegistrationError<M>> {
            let admission = match self.admit_child_member(slot.into(), child_id.into(), dialect).await {
                Ok(admission) => admission,
                Err(fault) => return Err(ChildMemberRegistrationError { member: Some(member), fault }),
            };
            let (root, pin_index) = match self.prepare_child_member(&admission, &mut member, false).await {
                Ok(prepared) => prepared,
                Err(fault) => {
                    assert!(self.children.cancel_admission(&admission.member), "failed child preparation returns its exact map admission");
                    return Err(ChildMemberRegistrationError { member: Some(member), fault });
                }
            };
            self.commit_child_member(admission, member, root, pin_index).await;
            Ok(())
        }

        //#region 🔖️CheckpointCascade
        /// 📌️ Leaves-first half of a composing document's checkpoint: commits every DIRTY
        /// child (a clean child is already pinned at its current checkpoint, and committing it again
        /// would mint an empty checkpoint per parent commit) and returns the `CompositionPin`s the
        /// parent's own about-to-be-created checkpoint must carry.
        ///
        /// A child with no checkpoint at all after committing contributes no pin rather than
        /// aborting the parent's checkpoint: a pin that named nothing would be worse than an absent
        /// one, and the parent's history is still perfectly valid without it.
        /// 📌️ One checkpoint-cascade unit: commits the child at `slot`/`child_id` when it is dirty,
        /// republishes its content root, and answers the pin its current checkpoint contributes.
        async fn checkpoint_child_unit(&mut self, message: &str, authors: &[vcs::Author], slot: &str, child_id: &str) -> Result<Option<vcs::CompositionPin>, Fault> {
            let publication_generation = self.admit_child_content_publication()?;
            let (dialect, checkpoint_id) = {
                let entry = self.children.get_mut(&(slot.to_string(), child_id.to_string())).ok_or_else(|| plugin_sdk_fault("checkpoint child authority changed during bounded publication"))?;
                if entry.member.is_dirty().await {
                    entry.member.commit_checkpoint(message.to_string(), authors.to_vec()).await.map_err(|error| error.into_fault())?;
                }
                (entry.reference.dialect.clone(), entry.member.current_checkpoint_id().await)
            };
            self.publish_child_content_member(publication_generation, slot, child_id).await?;
            Ok(checkpoint_id.map(|checkpoint_id| vcs::CompositionPin { child_ref: ArtifactRef { artifact_id: child_id.to_string(), dialect }, checkpoint_id }))
        }

        /// 📌️ Records `pins` on the checkpoint the parent's dispatch just created. Runs AFTER
        /// that dispatch because the checkpoint does not exist until then, and `composition_pins`
        /// participates in `content_addressed_checkpoint_id`, so the pins must be present on the
        /// envelope that gets persisted.
        async fn stamp_checkpoint_composition_pins(&mut self, pins: Vec<vcs::CompositionPin>) -> Result<(), Fault> {
            if pins.is_empty() {
                return Ok(());
            }
            if let Some(checkpoint_id) = self.store.current_checkpoint_id().map(str::to_string) {
                self.store.set_checkpoint_composition_pins(&checkpoint_id, pins).await.map_err(|error| error.into_fault())?;
            }
            Ok(())
        }

        /// ⏮️ Checkout half of the cascade: the pins the parent's now-current checkpoint recorded,
        /// each restored by one [`Self::checkout_child_unit`]. A pin naming a child that is not currently
        /// open is QUEUED (`pending_child_pins`) rather than dropped, so a child adopted later still lands
        /// on its pinned state instead of silently staying at head — see `open_child`.
        fn checkout_cascade_pins(&mut self) -> Result<Vec<vcs::CompositionPin>, Fault> {
            let Some(checkpoint_id) = self.store.current_checkpoint_id().map(str::to_string) else { return Ok(Vec::new()) };
            let Some(pins) = self.store.envelope().vcs.checkpoints.iter().find(|checkpoint| checkpoint.id == checkpoint_id).map(|checkpoint| checkpoint.composition_pins.clone()) else { return Ok(Vec::new()) };
            self.pending_child_pins.clear();
            self.admit_child_content_publication_span(pins.len())?;
            Ok(pins)
        }

        /// ⏮️ One checkout-cascade unit: restores one live child to `pin`, or queues the pin.
        async fn checkout_child_unit(&mut self, pin: &vcs::CompositionPin) -> Result<(), Fault> {
            let child_key = self.children.entries().find(|entry| entry.reference.artifact_id == pin.child_ref.artifact_id).map(|entry| (entry.owner.slot.clone(), entry.reference.artifact_id.clone()));
            let Some((slot, child_id)) = child_key else {
                self.pending_child_pins.push(pin.clone());
                return Ok(());
            };
            let publication_generation = self.admit_child_content_publication()?;
            let entry = self.children.get_mut(&(slot.clone(), child_id.clone())).ok_or_else(|| plugin_sdk_fault("checkout child authority changed during bounded publication"))?;
            let alternative_id = entry.member.current_alternative_id().await.unwrap_or_default();
            let _ = entry.member.checkout(&pin.checkpoint_id, &alternative_id).await;
            self.publish_child_content_member(publication_generation, &slot, &child_id).await
        }
        //#endregion 🔖️CheckpointCascade

