    /// 🪪️ Accepts only one server-minted nonzero lowercase artifact identity.
    fn is_server_minted_artifact_document_id_v1(document_id: &str) -> bool {
        let Some(suffix) = document_id.strip_prefix("artifact-") else { return false };
        suffix.len() == 32 && suffix.bytes().all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte)) && suffix.bytes().any(|byte| byte != b'0')
    }

    /// 🪡️ Builds one app-owned initial pair at a server-minted identity while preserving an exact
    /// empty history and cursor. This is the single producer behind `world actor`'s `codec.genesis`
    /// export, so every plugin gets creation authority from the one implementation rather than from
    /// a per-package native factory the host has to link (ticket 26/09/18 slice TC3b).
    pub async fn artifact_app_genesis_pair<A: ArtifactApp>(document_id: &str) -> Result<store::ArtifactPackFiles, store::VcsError> {
        let dialect: ArtifactDialect = A::DIALECT.into();
        if !is_server_minted_artifact_document_id_v1(document_id) {
            return Err(store::VcsError::ValidationFailed("artifact genesis identity is not a server-minted artifact id".into()));
        }
        let mut envelope = create_document_envelope::<A::Snapshot, A::Mutation>(A::DOCUMENT_SCHEMA, document_id, A::initial_snapshot().await, None).into_owners();
        envelope.dialect = Some(dialect.clone());
        let zero_cursor = envelope.cursor.as_ref().is_some_and(|cursor| cursor.applied_edit_ids.is_empty() && cursor.redo_edit_ids.is_empty() && cursor.checkpoint_id.is_none());
        if envelope.id != document_id
            || envelope.dialect.as_ref() != Some(&dialect)
            || !envelope.vcs.edits.is_empty()
            || !envelope.vcs.changes.is_empty()
            || !envelope.vcs.checkpoints.is_empty()
            || !envelope.vcs.alternatives.is_empty()
            || !zero_cursor
        {
            store::ArtifactEnvelope::from_owners(envelope).retire_unadopted();
            return Err(store::VcsError::ValidationFailed("artifact genesis produced nonzero history".into()));
        }
        let printed = store::print_document_pack(&envelope).await;
        store::ArtifactEnvelope::from_owners(envelope).retire_unadopted();
        printed
    }

    /// 🧩️ Applies one `os_spr::encode_ops_vec` batch to an app-owned pair — the guest half of
    /// `world actor`'s `codec.apply-ops` export, structurally the same reduction
    /// `store::ArtifactCodec::apply_ops_binary` performs for a natively linked codec.
    /// 🔭️ The LIVE snapshot of one artifact `pack`/`spr` pair, without loading it into any
    /// instance and without leaving a history shell behind. This is how a READER — an inference
    /// computing over the artifact its caller named, never an editor — gets the document it was
    /// asked about: the pair is the authoritative one, `parse_document_pack` replays it exactly as
    /// `load_document_pack` does, and `into_snapshot` retires the envelope through the store's own
    /// bounded path instead of dropping it (a bare drop aborts the process — every terminal shell
    /// under `ArtifactEnvelope` asserts its owners were retired first).
    pub async fn artifact_pair_snapshot<P, Mutation>(pack: &[u8], spr: &[u8]) -> Result<P, store::VcsError>
    where
        P: Clone + store::ArtifactPack,
        Mutation: store::OpText + store::OpBinary + store::Mutation<P>,
    {
        if pack.is_empty() || spr.is_empty() {
            return Err(store::VcsError::Deserialize("artifact pair carries no pack+spr baseline".into()));
        }
        let parsed: store::ParsedDocumentText<P, Mutation> = store::parse_document_pack(pack, spr).await.map_err(|error| store::VcsError::Deserialize(error.to_string()))?;
        Ok(parsed.into_snapshot())
    }

    /// 🎯️ `encode_ops_vec(&[])` is a framed header, not a zero-length slice — key the empty
    /// path off the DECODED mutation count (native twin, ticket 26/09/18 TC5).
    ///
    /// 🛂️ The throwaway reduction store gets the app's OWN owner catalogue, the same call
    /// `VcsArtifactApp`'s constructor makes for its live document store. `ArtifactStore::new`
    /// installs none, and an uninstalled store cannot retire: the close cursor below answered
    /// `artifact store has no owner-supplied bounded disposer` for the first nonempty batch this
    /// path ever ran (ticket 26/09/18 slice TC3e). The EMPTY batch returns before a store exists,
    /// which is why this went unseen.
    /// 🛂️ Prefer the app's catalogue; fall back to the framework's bounded catalogue so a
    /// throwaway reduction store can always close (native twin, ticket 26/09/18 TC5).
    ///
    /// 🪦️ `?` must never touch this store: a live `ArtifactStore` that reaches `Drop` asserts its
    /// exact terminal-empty shallow-shell witness, so an early return here aborts — the guest, on
    /// wasm32. The reduction's own fault leaves as a VALUE and the close cursor below runs either
    /// way. Measured 2026-09-22 (ticket 26/09/18 slice TC3e): the first NONEMPTY batch this path
    /// ever ran took the process down here, inside `artifact_app_apply_ops`, not in the cursor.
    ///
    /// 🧺️ The same witness `store::ArtifactCodec`'s own `apply_ops_binary` thunk pays (ticket
    /// 26/09/18 slice TC3c §2): this is the guest-side twin that builds a store, prints from it
    /// and lets it fall out of scope, so it drains through the identical close cursor rather than
    /// aborting the guest in `ArtifactStore`'s `Drop`.
    ///
    /// 🪦️ A store that did not reach its witness must never be DROPPED: `ArtifactStore`'s `Drop`
    /// asserts that witness, so dropping it turns a reportable fault into a process abort — on a
    /// `panic = "abort"` wasm32 guest, the whole instance. Retaining it is the same trade
    /// `retain_unclosed_artifact_codec_app` makes one layer up, and a codec instance is thrown
    /// away per call, so the guest's linear memory goes with it.
    pub async fn artifact_app_apply_ops<A: ArtifactApp>(pack: &[u8], spr: &[u8], ops: &[u8]) -> Result<store::ArtifactPackFiles, store::VcsError> {
        if pack.is_empty() || spr.is_empty() {
            return Err(store::VcsError::Deserialize("artifact apply-ops has no pack+spr baseline".into()));
        }
        let parsed: store::ParsedDocumentText<A::Snapshot, A::Mutation> = store::parse_document_pack(pack, spr).await.map_err(|error| store::VcsError::Deserialize(error.to_string()))?;
        let mut envelope = parsed.into_envelope();
        let (applied, redo) = match &envelope.cursor {
            Some(cursor) => (cursor.applied_edit_ids.clone(), cursor.redo_edit_ids.clone()),
            None => (envelope.vcs.edits.iter().map(|edit| edit.id.clone()).collect(), crate::dsl::HistoryPageStack::new()),
        };
        envelope.cursor = Some(store::ArtifactCursor::new(applied, redo, envelope.cursor.as_ref().and_then(|cursor| cursor.checkpoint_id.clone())));
        let mutations: Vec<A::Mutation> = if ops.is_empty() {
            Vec::new()
        } else {
            let blobs = store::os_spr::decode_ops_vec(ops).map_err(|error| store::VcsError::Deserialize(error.to_string()))?;
            let mut decoded = Vec::with_capacity(blobs.len());
            for bytes in &blobs {
                decoded.push(<A::Mutation as OpBinary>::decode_op(bytes).map_err(|error| store::VcsError::Deserialize(error.to_string()))?);
            }
            decoded
        };
        if mutations.is_empty() {
            let printed = store::print_document_pack(&envelope).await;
            envelope.retire_unadopted();
            return printed;
        }
        let mut owner = store::ArtifactStore::<A::Snapshot, A::Mutation>::new(envelope).await?;
        owner.install_document_store_owners_exact(A::build_document_store_owners().unwrap_or_else(store::bounded_artifact_store_owners));
        let printed = match owner.dispatch(store::ArtifactCommand::Apply { mutations, description: None, transaction: None }).await {
            Ok(_) => store::print_document_pack(owner.envelope()).await,
            Err(error) => Err(error),
        };
        let mut closed = Err(store::VcsError::ValidationFailed("artifact app apply-ops store did not reach terminal emptiness within its bounded close budget".into()));
        for _ in 0..store::ARTIFACT_CODEC_APPLY_CLOSE_MAXIMUM_STEPS {
            match owner.close_owned_step(1, store::ARTIFACT_STORE_ONE_ITEM_MAXIMUM_BYTES) {
                Ok(store::SnapshotRetirementStep::Complete) => {
                    closed = if owner.close_owned_terminal_is_empty() { Ok(()) } else { Err(store::VcsError::ValidationFailed("artifact app apply-ops store reported close completion without terminal emptiness".into())) };
                    break;
                }
                Ok(store::SnapshotRetirementStep::Pending { .. }) => continue,
                Ok(store::SnapshotRetirementStep::Blocked) => {
                    closed = Err(store::VcsError::ValidationFailed("artifact app apply-ops store close is blocked by an outstanding snapshot read lease".into()));
                    break;
                }
                Err(error) => {
                    closed = Err(store::VcsError::ValidationFailed(error.into_message()));
                    break;
                }
            }
        }
        if let Err(error) = closed {
            std::mem::forget(owner);
            return Err(error);
        }
        drop(owner);
        printed
    }

    /// 📜️ The fault a `codec.replay-envelopes` refusal crosses the guest boundary as: a ledger whose replay raises an
    /// `Error` or `Fatal` under `MergePolicy::Normal` (the hub check-in strictness, e.g. a blocking supersession) is the
    /// typed `ledger-not-replayable` naming its first blocking messages, so linked and guest codecs answer Check In alike.
    pub fn replay_envelopes_fault(error: store::VcsError) -> Fault {
        match error {
            store::VcsError::Rejected { messages, .. } => {
                let blocking: Vec<String> = messages.iter().filter(|message| protocol::MergePolicy::Normal.rejects(message.level)).take(8).map(|message| format!("{}: {}", message.code.0, message.message)).collect();
                Fault::new(FaultOrigin::Framework, FaultCode::new("ledger-not-replayable"), format!("the ledger does not replay under the check-in policy ({} blocking message(s)): {}", messages.len(), blocking.join("; ")))
            }
            other => other.into_fault(),
        }
    }

    /// 📜️ The guest half of `world actor`'s `codec.replay-envelopes` export: the app's own owner
    /// catalogue around the one kernel fold every codec shares (`store::replay_envelopes_onto_pair`).
    pub async fn artifact_app_replay_envelopes<A: ArtifactApp>(pack: &[u8], spr: &[u8], envelopes: &[u8]) -> Result<store::ArtifactPackFiles, store::VcsError> {
        store::replay_envelopes_onto_pair::<A::Snapshot, A::Mutation>(pack, spr, envelopes, || A::build_document_store_owners().unwrap_or_else(store::bounded_artifact_store_owners)).await
    }

    /// 🧬️ The future one `codec` answer of an [`ArtifactCodecTableV1`] resolves to.
    pub type ArtifactCodecFuture<'a, T> = std::pin::Pin<Box<dyn std::future::Future<Output = Result<T, Fault>> + 'a>>;

    /// 🧬️ One registered app's `world actor` `codec` answers as plain functions of its type, recorded when the app
    /// is registered. Every answer is a pure function of the app's TYPE — its snapshot record shape, its initial
    /// snapshot and dialect, its owner catalogue — never of a constructed instance, so a `codec` call reads this
    /// table and constructs no app: no store around an initial snapshot, no action registry, no window owners,
    /// nothing to drain and close afterwards.
    #[derive(Clone, Copy)]
    pub struct ArtifactCodecTableV1 {
        /// 🧬️ Structural fingerprint of the app's snapshot record shape — the same 32 bytes
        /// `store::ArtifactCodec::pack_schema_hash` carries, read off `Snapshot::record_spec()`. `None` when the
        /// snapshot is a hand-written `ArtifactPack` with no `RecordSpec`, exactly as the native codec table reports
        /// `[0; 32]` for that case.
        /// 🚫️async: E4 fn-pointer slot
        pub pack_schema_hash: fn() -> Option<[u8; 32]>,
        /// 🌱️ The canonical empty document of the app's kind at `document_id`: its initial snapshot, its own
        /// dialect, and an exactly zero history (no edits, changes, checkpoints or alternatives, and an empty cursor).
        /// 🚫️async: E4 fn-pointer slot
        pub genesis: for<'a> fn(&'a str) -> ArtifactCodecFuture<'a, store::ArtifactPackFiles>,
        /// 📥️ `(pack, spr) -> (dsl, ops)` mirror of a pair of the app's kind — the pair-validation fence of a host
        /// whose codec it does not link.
        /// 🚫️async: E4 fn-pointer slot
        pub print_mirror: for<'a> fn(&'a [u8], &'a [u8]) -> ArtifactCodecFuture<'a, store::ArtifactTextFiles>,
        /// 🧩️ Applies one `os_spr::encode_ops_vec` batch to a pair of the app's kind and returns the next pair.
        /// 🚫️async: E4 fn-pointer slot
        pub apply_ops: for<'a> fn(&'a [u8], &'a [u8], &'a [u8]) -> ArtifactCodecFuture<'a, store::ArtifactPackFiles>,
        /// 📜️ Folds one `os_spr::encode_envelopes` ledger stream onto a pair of the app's kind through the replica
        /// merge gate (`store::replay_envelopes_onto_pair`).
        /// 🚫️async: E4 fn-pointer slot
        pub replay_envelopes: for<'a> fn(&'a [u8], &'a [u8], &'a [u8]) -> ArtifactCodecFuture<'a, store::ArtifactPackFiles>,
    }

    /// 🧬️ The [`ArtifactCodecTableV1`] of every app built on `A`.
    pub fn artifact_codec_table<A: ArtifactApp>() -> ArtifactCodecTableV1 {
        fn pack_schema_hash<A: ArtifactApp>() -> Option<[u8; 32]> {
            <A::Snapshot as store::ArtifactPack>::record_spec().map(|spec| store::os_pack::schema_hash(&spec))
        }
        fn genesis<A: ArtifactApp>(document_id: &str) -> ArtifactCodecFuture<'_, store::ArtifactPackFiles> {
            Box::pin(async move { artifact_app_genesis_pair::<A>(document_id).await.map_err(|error| error.into_fault()) })
        }
        fn print_mirror<'a, A: ArtifactApp>(pack: &'a [u8], spr: &'a [u8]) -> ArtifactCodecFuture<'a, store::ArtifactTextFiles> {
            Box::pin(async move {
                let parsed: store::ParsedDocumentText<A::Snapshot, A::Mutation> = store::parse_document_pack(pack, spr).await.map_err(|error| error.into_fault())?;
                let envelope = parsed.into_envelope();
                let mirror = store::print_document_text(&envelope).await;
                envelope.retire_unadopted();
                mirror.map_err(|error| error.into_fault())
            })
        }
        fn apply_ops<'a, A: ArtifactApp>(pack: &'a [u8], spr: &'a [u8], ops: &'a [u8]) -> ArtifactCodecFuture<'a, store::ArtifactPackFiles> {
            Box::pin(async move { artifact_app_apply_ops::<A>(pack, spr, ops).await.map_err(|error| error.into_fault()) })
        }
        fn replay_envelopes<'a, A: ArtifactApp>(pack: &'a [u8], spr: &'a [u8], envelopes: &'a [u8]) -> ArtifactCodecFuture<'a, store::ArtifactPackFiles> {
            Box::pin(async move { artifact_app_replay_envelopes::<A>(pack, spr, envelopes).await.map_err(replay_envelopes_fault) })
        }
        ArtifactCodecTableV1 { pack_schema_hash: pack_schema_hash::<A>, genesis: genesis::<A>, print_mirror: print_mirror::<A>, apply_ops: apply_ops::<A>, replay_envelopes: replay_envelopes::<A> }
    }
