pub mod wasip2 {
    //! 🧩️ WASI P2 bindings for the actor world shared by plugins and extensions.
    //! The package role identifies each guest; reactor, jobs, checkpoint and describe use the same world.
    #![allow(unsafe_op_in_unsafe_fn)]

    use wit_bindgen::generate;

    generate!({
        world: "actor",
        path: "../../🧬️schema",
        pub_export_macro: true,
        default_bindings_module: "$crate::component::wasip2",
        disable_custom_section_link_helpers: true,
    });

    /// 🧩️ Converts a framework fault into the generated actor-world error type.
    /// 🪶️ Converts the schema-declared ABI bounds without platform truncation.
    pub fn sqlite_limits(value: exports::semio::framework::codec::SnapshotLimits) -> crate::sqlite_wire::SnapshotLimits {
        crate::sqlite_wire::SnapshotLimits { max_file_bytes: value.max_file_bytes, max_value_bytes: value.max_value_bytes, max_allocation_bytes: value.max_allocation_bytes, max_schema_bytes: value.max_schema_bytes, max_rows: value.max_rows, max_columns: value.max_columns, max_tables: value.max_tables, max_pages: value.max_pages }
    }

    pub fn plugin_error(fault: &semio_framework::Fault) -> semio::framework::types::PluginError {
        semio::framework::types::PluginError::Fault(semio_framework_diagnostic::encode_fault_bytes(fault))
    }

    #[doc(hidden)]
    #[macro_export]
    macro_rules! __semio_export_component_guest {
        ($guest:ident) => {
            $crate::component::wasip2::export!($guest);
        };
    }

    pub fn component_export_anchor() {}

    pub async fn log(level: &str, message: &str) {
        semio::framework::pure::log(level, message);
    }

    pub async fn now_ms() -> i64 {
        semio::framework::pure::now_ms()
    }

    pub async fn trace_span(name: &str) {
        semio::framework::pure::trace_span(name);
    }
}

//#region 🔖️ComponentPersistentLocal
#[cfg(all(target_arch = "wasm32", target_env = "p2"))]
#[doc(hidden)]
pub mod component_persistent_local {
    use std::{cell::UnsafeCell, mem::MaybeUninit, sync::Once};

    /// 🧵️ Component-async calls receive fresh Rust TLS contexts, so actor state that must survive
    /// from one exported call to the next lives in the component instance's linear-memory global.
    pub struct ComponentPersistentLocal<T> {
        once: Once,
        value: UnsafeCell<MaybeUninit<T>>,
        initialize: fn() -> T,
    }

    impl<T> ComponentPersistentLocal<T> {
        pub const fn new(initialize: fn() -> T) -> Self {
            Self { once: Once::new(), value: UnsafeCell::new(MaybeUninit::uninit()), initialize }
        }

        pub fn with<R>(&'static self, use_value: impl FnOnce(&'static T) -> R) -> R {
            self.once.call_once(|| unsafe {
                (*self.value.get()).write((self.initialize)());
            });
            use_value(unsafe { (&*self.value.get()).assume_init_ref() })
        }
    }

    unsafe impl<T> Sync for ComponentPersistentLocal<T> {}
}

#[doc(hidden)]
#[macro_export]
macro_rules! component_persistent_local {
    ($( $(#[$attribute:meta])* static $name:ident: $value_type:ty = $initialize:expr; )+) => {
        $(
            #[cfg(all(target_arch = "wasm32", target_env = "p2"))]
            $(#[$attribute])*
            static $name: $crate::component_persistent_local::ComponentPersistentLocal<$value_type> =
                $crate::component_persistent_local::ComponentPersistentLocal::new(|| $initialize);
        )+

        #[cfg(not(all(target_arch = "wasm32", target_env = "p2")))]
        std::thread_local! {
            $(
                $(#[$attribute])*
                static $name: $value_type = $initialize;
            )+
        }
    };
}
//#endregion 🔖️ComponentPersistentLocal

