        _editor: std::marker::PhantomData<E>,
    }

    impl<E: ArtifactEditor> Default for EditorApp<E> {
        fn default() -> Self {
            Self { id: surface_app_id(&E::DIALECT.into(), E::ROLE), _editor: std::marker::PhantomData }
        }
    }

    impl<E: ArtifactEditor> EditorApp<E> {
