                },
                WindowMeasure::Slider {
                    id: format!("{id_prefix}-measure-sun-intensity"),
                    label: Some(if is_de { "Intensität" } else { "Intensity" }.into()),
                    value: sun.intensity,
                    min: 0.0,
                    max: 4.0,
                    step: Some(0.05),
