        }
        other => panic!("expected Orbit, got {other:?}"),
    }
    let start = interpolate_tutorial_camera(&prev, &next, 0.0);
    assert_eq!(start, prev.camera);
    let end = interpolate_tutorial_camera(&prev, &next, 1000.0);
    assert_eq!(end, next.camera);
}

