pub const ARTIFACT_BOOTSTRAP_FORMAT_VERSION: u32 = 1;
pub const ARTIFACT_BOOTSTRAP_CHUNK_BYTES: usize = 4 * 1024;
pub const ARTIFACT_BOOTSTRAP_MAX_TOTAL_BYTES: u64 = 64 * 1024 * 1024;
