use std::sync::{Arc, Mutex, MutexGuard};

//#region 🧬️OpaqueSnapshotRead
const SNAPSHOT_READ_LEASE_CAPACITY: usize = 1_024;

#[cfg(test)]
#[path = "🧪️tests/♻️snapshot-read-retirement/🦀️.rs"]
mod snapshot_read_retirement_tests;

struct SnapshotReadLeaseSlot {
    generation: u64,
    owner: Arc<dyn std::any::Any + Send + Sync>,
    returned: Arc<std::sync::atomic::AtomicBool>,
}

struct SnapshotReadLeaseRegistryState {
    slots: Box<[std::mem::MaybeUninit<SnapshotReadLeaseSlot>; SNAPSHOT_READ_LEASE_CAPACITY]>,
    occupied: [u64; SNAPSHOT_READ_LEASE_CAPACITY / 64],
    free: [u16; SNAPSHOT_READ_LEASE_CAPACITY],
    free_read: usize,
    free_len: usize,
    next_generation: u64,
    cleanup_cursor: usize,
}

#[derive(Debug)]
enum SnapshotReadLeaseRefusal { Busy, Poisoned, OwnerTypeChanged }

impl SnapshotReadLeaseRefusal {
    fn into_value_error(self) -> semio_framework_value::ValueError {
        semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, match self {
            Self::Busy => "snapshot read lease registry is busy",
            Self::Poisoned => "snapshot read lease registry is poisoned",
            Self::OwnerTypeChanged => "snapshot read lease owner type changed inside its exact registry",
        })
    }
}

struct SnapshotReadLeaseRegistry {
    state: Mutex<SnapshotReadLeaseRegistryState>,
    returned: std::sync::atomic::AtomicUsize,
    authority_sequence: std::sync::atomic::AtomicU64,
    authority_generation: std::sync::atomic::AtomicU64,
    authority_revision: [std::sync::atomic::AtomicU64; 4],
}

impl SnapshotReadLeaseRegistry {
    fn new() -> Self {
        let mut free = [0; SNAPSHOT_READ_LEASE_CAPACITY];
        for (index, slot) in free.iter_mut().enumerate() {
            *slot = index as u16;
        }
        Self {
            state: Mutex::new(SnapshotReadLeaseRegistryState {
                slots: Box::new([const { std::mem::MaybeUninit::uninit() }; SNAPSHOT_READ_LEASE_CAPACITY]),
                occupied: [0; SNAPSHOT_READ_LEASE_CAPACITY / 64],
                free,
                free_read: 0,
                free_len: SNAPSHOT_READ_LEASE_CAPACITY,
                next_generation: 0,
                cleanup_cursor: 0,
            }),
            returned: std::sync::atomic::AtomicUsize::new(0),
            authority_sequence: std::sync::atomic::AtomicU64::new(0),
            authority_generation: std::sync::atomic::AtomicU64::new(0),
            authority_revision: std::array::from_fn(|_| std::sync::atomic::AtomicU64::new(0)),
        }
    }

    fn publish_authority(&self, generation: u64, revision: [u8; 32]) -> bool {
        let sequence = self.authority_sequence.load(std::sync::atomic::Ordering::Acquire);
        let Some(terminal_sequence) = sequence.checked_add(2) else { return false };
        if sequence & 1 != 0 || self.authority_sequence.compare_exchange(sequence, sequence + 1, std::sync::atomic::Ordering::AcqRel, std::sync::atomic::Ordering::Acquire).is_err() {
            return false;
        }
        self.authority_generation.store(generation, std::sync::atomic::Ordering::Relaxed);
        for (word, bytes) in self.authority_revision.iter().zip(revision.as_chunks::<8>().0.iter()) {
            word.store(u64::from_le_bytes(*bytes), std::sync::atomic::Ordering::Relaxed);
        }
        self.authority_sequence.store(terminal_sequence, std::sync::atomic::Ordering::Release);
        true
    }

    fn authority_matches(&self, generation: u64, revision: [u8; 32]) -> bool {
        let first = self.authority_sequence.load(std::sync::atomic::Ordering::Acquire);
        if first == 0 || first & 1 != 0 || self.authority_generation.load(std::sync::atomic::Ordering::Relaxed) != generation {
            return false;
        }
        for (word, bytes) in self.authority_revision.iter().zip(revision.as_chunks::<8>().0.iter()) {
            if word.load(std::sync::atomic::Ordering::Relaxed) != u64::from_le_bytes(*bytes) {
                return false;
            }
        }
        first == self.authority_sequence.load(std::sync::atomic::Ordering::Acquire)
    }

    fn try_issue<T: Send + Sync + 'static>(self: &Arc<Self>, owner: Arc<T>) -> Result<SnapshotReadLease, Arc<T>> {
        let Ok(mut state) = self.state.try_lock() else {
            return Err(owner);
        };
        if state.free_len == 0 {
            return Err(owner);
        }
        let generation = match state.next_generation.checked_add(1) {
            Some(generation) => generation,
            None => return Err(owner),
        };
        let read = state.free_read;
        let index = state.free[read] as usize;
        state.free_read = (state.free_read + 1) % SNAPSHOT_READ_LEASE_CAPACITY;
        state.free_len -= 1;
        state.next_generation = generation;
        let returned = Arc::new(std::sync::atomic::AtomicBool::new(false));
        state.slots[index].write(SnapshotReadLeaseSlot { generation, owner, returned: returned.clone() });
        state.occupied[index / 64] |= 1 << (index % 64);
        Ok(SnapshotReadLease { registry: self.clone(), index: index as u16, generation, returned })
    }

    fn try_take(&self, index: u16, generation: u64) -> Result<Arc<dyn std::any::Any + Send + Sync>, String> {
        let Ok(mut state) = self.state.try_lock() else {
            return Err("snapshot read lease registry is busy".into());
        };
        let index = index as usize;
        let mask = 1 << (index % 64);
        if state.occupied[index / 64] & mask == 0 {
            return Err("snapshot read lease is no longer registered".into());
        }
        let slot = unsafe { state.slots[index].assume_init_ref() };
        if slot.generation != generation {
            return Err("snapshot read lease generation is stale".into());
        }
        let slot = unsafe { state.slots[index].assume_init_read() };
        state.occupied[index / 64] &= !mask;
        let write = (state.free_read + state.free_len) % SNAPSHOT_READ_LEASE_CAPACITY;
        state.free[write] = index as u16;
        state.free_len += 1;
        if slot.returned.load(std::sync::atomic::Ordering::Acquire) {
            self.returned.fetch_sub(1, std::sync::atomic::Ordering::AcqRel);
        }
        Ok(slot.owner)
    }

    fn contains(&self, index: u16, generation: u64) -> bool {
        let Ok(state) = self.state.try_lock() else {
            return true;
        };
        let index = index as usize;
        let mask = 1 << (index % 64);
        state.occupied[index / 64] & mask != 0 && unsafe { state.slots[index].assume_init_ref() }.generation == generation
    }

    fn terminal_is_empty(&self) -> bool {
        self.returned.load(std::sync::atomic::Ordering::Acquire) == 0 && self.state.try_lock().is_ok_and(|state| state.free_len == SNAPSHOT_READ_LEASE_CAPACITY)
    }

    fn has_returned(&self) -> bool {
        self.returned.load(std::sync::atomic::Ordering::Acquire) != 0
    }

    fn occupied_count(&self) -> usize {
        self.state.try_lock().map_or(SNAPSHOT_READ_LEASE_CAPACITY, |state| SNAPSHOT_READ_LEASE_CAPACITY - state.free_len)
    }

    /// 🪶 Releases a lease whose root is still aliased outside this registry, on the returning
    /// thread and in constant time.
    ///
    /// The retirement pump exists for DISPLACED roots: a returned read whose slot holds the last
    /// `Arc` is the only owner left, so its domain tree must be disposed in bounded steps. A read
    /// that is returned while its root is still live — every `ephemeral` hook capture, every tool
    /// job's presence/transient capture — has nothing to dispose, and the pump discovers that two
    /// turns later with an `Arc::into_inner` that simply fails (see
    /// `ReturnedSnapshotReadRetirement::close_step` and the presence local ladder). Charging a
    /// fair maintenance turn per dispatch to rediscover it starves the registry: a mounted app
    /// that dispatches once per frame issues leases faster than one fair step per frame can
    /// reclaim them, and the fixed slot table runs out mid-run.
    fn try_release_aliased(&self, index: u16, generation: u64) -> bool {
        let Ok(mut state) = self.state.try_lock() else { return false };
        let index = index as usize;
        let mask = 1 << (index % 64);
        if state.occupied[index / 64] & mask == 0 {
            return false;
        }
        let slot = unsafe { state.slots[index].assume_init_ref() };
        if slot.generation != generation || slot.returned.load(std::sync::atomic::Ordering::Acquire) || Arc::strong_count(&slot.owner) == 1 {
            return false;
        }
        let slot = unsafe { state.slots[index].assume_init_read() };
        state.occupied[index / 64] &= !mask;
        let write = (state.free_read + state.free_len) % SNAPSHOT_READ_LEASE_CAPACITY;
        state.free[write] = index as u16;
        state.free_len += 1;
        drop(slot);
        true
    }

    fn try_take_one_returned<T: Send + Sync + 'static>(&self) -> Result<Option<Arc<T>>, SnapshotReadLeaseRefusal> {
        let mut state = match self.state.try_lock() {
            Ok(state) => state,
            Err(std::sync::TryLockError::WouldBlock) => return Err(SnapshotReadLeaseRefusal::Busy),
            Err(std::sync::TryLockError::Poisoned(_)) => return Err(SnapshotReadLeaseRefusal::Poisoned),
        };
        let start = state.cleanup_cursor;
        let Some(index) = (0..=state.occupied.len()).find_map(|offset| {
            let word_index = (start / 64 + offset) % state.occupied.len();
            let mut occupied = state.occupied[word_index];
            if offset == 0 {
                occupied &= u64::MAX << (start % 64);
            } else if offset == state.occupied.len() {
                occupied &= (1u64 << (start % 64)) - 1;
            }
            (occupied != 0).then(|| word_index * 64 + occupied.trailing_zeros() as usize)
        }) else { return Ok(None) };
        state.cleanup_cursor = (index + 1) % SNAPSHOT_READ_LEASE_CAPACITY;
        let mask = 1 << (index % 64);
        if state.occupied[index / 64] & mask == 0 {
            return Ok(None);
        }
        let slot = unsafe { state.slots[index].assume_init_ref() };
        if !slot.returned.load(std::sync::atomic::Ordering::Acquire) {
            return Ok(None);
        }
        if !slot.owner.is::<T>() {
            return Err(SnapshotReadLeaseRefusal::OwnerTypeChanged);
        }
        let slot = unsafe { state.slots[index].assume_init_read() };
        state.occupied[index / 64] &= !mask;
        let write = (state.free_read + state.free_len) % SNAPSHOT_READ_LEASE_CAPACITY;
        state.free[write] = index as u16;
        state.free_len += 1;
        self.returned.fetch_sub(1, std::sync::atomic::Ordering::AcqRel);
        Ok(Some(slot.owner.downcast::<T>().expect("validated snapshot read lease owner type")))
    }
}

impl Drop for SnapshotReadLeaseRegistry {
    fn drop(&mut self) {
        let state = self.state.get_mut().unwrap_or_else(|poisoned| poisoned.into_inner());
        assert!(std::thread::panicking() || state.free_len == SNAPSHOT_READ_LEASE_CAPACITY, "snapshot read lease registry reached Drop before every exact owner was returned and retired: {} of {SNAPSHOT_READ_LEASE_CAPACITY}", state.free_len);
        assert!(
            std::thread::panicking() || self.returned.load(std::sync::atomic::Ordering::Acquire) == 0,
            "snapshot read lease registry reached Drop with returned owners outside the bounded retirement pump"
        );
    }
}

struct SnapshotReadLease {
    registry: Arc<SnapshotReadLeaseRegistry>,
    index: u16,
    generation: u64,
    returned: Arc<std::sync::atomic::AtomicBool>,
}

impl SnapshotReadLease {
    fn return_now(&mut self) -> bool {
        if self.returned.load(std::sync::atomic::Ordering::Acquire) {
            return false;
        }
        if self.registry.try_release_aliased(self.index, self.generation) {
            self.returned.store(true, std::sync::atomic::Ordering::Release);
            return true;
        }
        self.registry.returned.fetch_add(1, std::sync::atomic::Ordering::AcqRel);
        if self.returned.compare_exchange(false, true, std::sync::atomic::Ordering::AcqRel, std::sync::atomic::Ordering::Acquire).is_err() {
            self.registry.returned.fetch_sub(1, std::sync::atomic::Ordering::AcqRel);
            return false;
        }
        true
    }
}

fn return_snapshot_read<T: ?Sized>(owner: &mut Option<Arc<T>>, lease: &mut Option<SnapshotReadLease>, after_alias_release: impl FnOnce()) -> bool {
    let Some(mut lease) = lease.take() else {
        assert!(owner.is_none(), "snapshot read alias requires its exact unreturned registry guard");
        return false;
    };
    drop(owner.take());
    after_alias_release();
    lease.return_now()
}

pub struct SnapshotRead<T: ?Sized> {
    owner: Option<Arc<T>>,
    lease: Option<SnapshotReadLease>,
}

/// 🧾 Exact returned-read ticket retained by a mounted owner until store maintenance reclaims it.
pub struct SnapshotReadReturn {
    registry: Arc<SnapshotReadLeaseRegistry>,
    index: u16,
    generation: u64,
}

impl SnapshotReadReturn {
    pub fn terminal_is_empty(&self) -> bool {
        !self.registry.contains(self.index, self.generation)
    }
}

impl<T: ?Sized> SnapshotRead<T> {
    fn new(owner: Arc<T>, lease: SnapshotReadLease) -> Self {
        Self { owner: Some(owner), lease: Some(lease) }
    }

    /// 👁️ Borrows the captured immutable value without exposing its owner.
    pub fn get(&self) -> &T {
        self.owner.as_deref().expect("live snapshot read owner is present")
    }

    /// 🔐️ Revalidates this lease against the store-owned event authority without reading
    /// a session-local registry. A concurrent publication produces an odd or changed sequence and
    /// therefore fails closed.
    pub fn commit_authority_matches(&self, generation: u64, revision: [u8; 32]) -> bool {
        self.lease.as_ref().is_some_and(|lease| lease.registry.authority_matches(generation, revision))
    }

    /// 🧹 Returns this lease to its exact registry while the registry retains the snapshot
    /// root for its own one-owner maintenance cursor.
    pub fn return_to_registry(mut self) -> bool {
        return_snapshot_read(&mut self.owner, &mut self.lease, || {})
    }

    /// 🧹 Returns this lease and hands the caller an exact generation witness for store retirement.
    pub fn return_to_registry_witness(mut self) -> Option<SnapshotReadReturn> {
        let lease = self.lease.as_ref()?;
        let witness = SnapshotReadReturn { registry: lease.registry.clone(), index: lease.index, generation: lease.generation };
        if !return_snapshot_read(&mut self.owner, &mut self.lease, || {}) {
            return None;
        }
        Some(witness)
    }
}

impl<T: ?Sized> Drop for SnapshotRead<T> {
    fn drop(&mut self) {
        let _ = return_snapshot_read(&mut self.owner, &mut self.lease, || {});
    }
}

impl<T: ?Sized> std::ops::Deref for SnapshotRead<T> {
    type Target = T;

    fn deref(&self) -> &Self::Target {
        self.get()
    }
}

/// 🧰 Type-erased snapshot capability used only until a composition view selects its
/// repository-owned concrete artifact type.
pub struct ErasedSnapshotRead {
    owner: Option<Arc<dyn std::any::Any + Send + Sync>>,
    lease: Option<SnapshotReadLease>,
}

impl ErasedSnapshotRead {
    fn new<T: Send + Sync + 'static>(owner: Arc<T>, lease: SnapshotReadLease) -> Self {
        Self { owner: Some(owner), lease: Some(lease) }
    }

    pub fn typed<T: Send + Sync + 'static>(&self) -> Option<SnapshotReadRef<'_, T>> {
        self.owner.as_deref()?.downcast_ref::<T>().map(|owner| SnapshotReadRef { owner })
    }

    /// 👁️ Borrows one exact concrete owner without exposing or cloning its retained `Arc`.
    pub fn get<T: Send + Sync + 'static>(&self) -> Option<&T> {
        self.owner.as_deref()?.downcast_ref::<T>()
    }

    fn into_typed<T: Send + Sync + 'static>(mut self, registry: &Arc<SnapshotReadLeaseRegistry>) -> Result<Arc<T>, Self> {
        if self.lease.as_ref().is_none_or(|lease| !Arc::ptr_eq(&lease.registry, registry)) || self.owner.as_deref().is_none_or(|owner| !owner.is::<T>()) {
            return Err(self);
        }
        let lease = self.lease.take().expect("validated snapshot read lease is present");
        let owner = self.owner.take().expect("validated snapshot read owner is present").downcast::<T>().expect("validated snapshot read type");
        let guard = match registry.try_take(lease.index, lease.generation) {
            Ok(guard) => guard,
            Err(_) => {
                self.owner = Some(owner);
                self.lease = Some(lease);
                return Err(self);
            }
        };
        drop(guard);
        Ok(owner)
    }
}

impl Drop for ErasedSnapshotRead {
    fn drop(&mut self) {
        let _ = return_snapshot_read(&mut self.owner, &mut self.lease, || {});
    }
}

pub struct SnapshotReadRef<'a, T: ?Sized> {
    owner: &'a T,
}

impl<T: ?Sized> std::ops::Deref for SnapshotReadRef<'_, T> {
    type Target = T;

    fn deref(&self) -> &Self::Target {
        self.owner
    }
}


/// 🧹️ Spends one caller turn's admitted BYTE grant on a retained owner instead of taking a single
/// `close_step` from it. The retirement protocol admits at most ONE structural owner and
/// `maximum_bytes` BYTES per turn, and the owners under a store disposer or a batched item
/// preparation release one string — often one byte — per step. Taking a single step per turn spent
/// a 512-byte grant four bytes at a time, which turned every close into a second byte-at-a-time
/// pass over data the caller's turn budget had already paid for once. The drain stops at the first
/// structural release (that is the one-item half of the grant), and a step that reports no progress
/// is charged one unit, so the loop is bounded by `maximum_bytes` even against an owner that never
/// advances.
fn spend_close_byte_grant(maximum_bytes: usize, mut step_once: impl FnMut(usize) -> Result<SnapshotRetirementStep, semio_framework_value::ValueError>) -> Result<(SnapshotRetirementStep, usize), semio_framework_value::ValueError> {
    let mut remaining = maximum_bytes;
    let mut released = 0usize;
    loop {
        match step_once(remaining)? {
            SnapshotRetirementStep::Pending { released_items: 0, released_bytes } if released_bytes <= remaining => {
                released += released_bytes;
                remaining -= released_bytes.max(1).min(remaining);
                if remaining == 0 {
                    return Ok((SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 }, released));
                }
            }
            step => return Ok((step, released)),
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ArtifactStoreCloseStringLane {
    AppliedEditIds,
    RedoEditIds,
    AppliedRevisionIds,
    RedoRevisionIds,
    CurrentCheckpointId,
    LocalActorId,
    TailUndoEditId,
    Supersessions,
}

/// ✏️ Retires effective supersessions — their ids, actors, scopes, schemas and replacement payloads — one byte grant
/// at a time, like [`ArtifactStoreStringRetirement`] does for one string.
struct ArtifactStoreSupersessionRetirement {
    bytes: Vec<Vec<u8>>,
}

impl ArtifactStoreSupersessionRetirement {
    fn new(supersessions: EffectiveSupersessions) -> Self {
        let mut bytes = Vec::with_capacity(supersessions.len() * 6);
        for (target, supersession) in supersessions {
            let protocol::EffectiveSupersession { transition_id, actor, timestamp: _, scope, replacement } = supersession;
            bytes.push(target.0.into_bytes());
            bytes.push(transition_id.into_bytes());
            bytes.push(actor.into_bytes());
            bytes.extend(scope.map(String::into_bytes));
            if let protocol::InputReplacement::Input { schema, payload } = replacement {
                bytes.push(schema.into_bytes());
                bytes.push(payload);
            }
        }
        Self { bytes }
    }
}

impl ErasedSnapshotRetirement for ArtifactStoreSupersessionRetirement {
    fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<SnapshotRetirementStep, semio_framework_value::ValueError> {
        if maximum_items == 0 {
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
        }
        while self.bytes.last().is_some_and(Vec::is_empty) {
            self.bytes.pop();
        }
        let Some(last) = self.bytes.last_mut() else { return Ok(SnapshotRetirementStep::Complete) };
        if maximum_bytes == 0 {
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
        }
        let released_bytes = maximum_bytes.min(last.len());
        last.truncate(last.len() - released_bytes);
        Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes })
    }

    fn terminal_is_empty(&self) -> bool {
        self.bytes.is_empty()
    }
}

impl Drop for ArtifactStoreSupersessionRetirement {
    fn drop(&mut self) {
        assert!(std::thread::panicking() || self.bytes.is_empty(), "artifact store supersession retirement reached Drop before its exact byte owners were terminal-empty");
    }
}

struct ArtifactStoreStringRetirement {
    bytes: std::mem::ManuallyDrop<Option<Vec<u8>>>,
}

impl ArtifactStoreStringRetirement {
    fn new(value: String) -> Self {
        Self { bytes: std::mem::ManuallyDrop::new(Some(value.into_bytes())) }
    }
}

impl ErasedSnapshotRetirement for ArtifactStoreStringRetirement {
    fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<SnapshotRetirementStep, semio_framework_value::ValueError> {
        if maximum_items == 0 {
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
        }
        let Some(bytes) = self.bytes.as_mut() else { return Ok(SnapshotRetirementStep::Complete) };
        if bytes.is_empty() {
            drop(self.bytes.take());
            return Ok(SnapshotRetirementStep::Complete);
        }
        if maximum_bytes == 0 {
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
        }
        let released_bytes = maximum_bytes.min(bytes.len());
        bytes.truncate(bytes.len() - released_bytes);
        Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes })
    }

    fn terminal_is_empty(&self) -> bool {
        self.bytes.is_none()
    }
}

impl Drop for ArtifactStoreStringRetirement {
    fn drop(&mut self) {
        assert!(std::thread::panicking() || (self.bytes.is_none()), "artifact store string retirement reached Drop before its exact byte owner was terminal-empty");
    }
}

struct ArtifactStoreStringVectorRetirement {
    values: std::mem::ManuallyDrop<Option<crate::os_vcs::HistoryPageStack<String>>>,
    active: std::mem::ManuallyDrop<Option<ArtifactStoreStringRetirement>>,
}

impl ArtifactStoreStringVectorRetirement {
    fn new(values: impl Into<crate::os_vcs::HistoryPageStack<String>>) -> Self {
        Self { values: std::mem::ManuallyDrop::new(Some(values.into())), active: std::mem::ManuallyDrop::new(None) }
    }
}

impl ErasedSnapshotRetirement for ArtifactStoreStringVectorRetirement {
    fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<SnapshotRetirementStep, semio_framework_value::ValueError> {
        if maximum_items == 0 {
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
        }
        if let Some(active) = self.active.as_mut() {
            return match active.close_step(maximum_items, maximum_bytes)? {
                SnapshotRetirementStep::Complete => {
                    if !active.terminal_is_empty() {
                        return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "artifact store string-vector child reported Complete without terminal ownership"));
                    }
                    drop(self.active.take());
                    Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 })
                }
                step => Ok(step),
            };
        }
        let Some(values) = self.values.as_mut() else { return Ok(SnapshotRetirementStep::Complete) };
        if let Some(value) = values.pop() {
            *self.active = Some(ArtifactStoreStringRetirement::new(value));
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
        }
        let values = self.values.take().expect("terminal string-vector owner remains present");
        drop(values);
        Ok(SnapshotRetirementStep::Complete)
    }

    fn terminal_is_empty(&self) -> bool {
        self.values.is_none() && self.active.is_none()
    }
}

impl Drop for ArtifactStoreStringVectorRetirement {
    fn drop(&mut self) {
        assert!(std::thread::panicking() || (self.terminal_is_empty()), "artifact store string-vector retirement reached Drop before its exact terminal-empty witness");
    }
}

