        Self { conflict: std::mem::ManuallyDrop::new(None), message: std::mem::ManuallyDrop::new(None), envelope: std::mem::ManuallyDrop::new(Some(envelope)), bytes: std::mem::ManuallyDrop::new(None) }
    }

