impl<P: Clone, Mutation: self::Mutation<P>> PresenceStore<P, Mutation> {
    /// 🏗️ A roster holding only this actor's own initial presence.
    /// 🚫️async: E1 pure constructor, consumed by `Default::default()` — see R9.
