/// 🧭 Read-visible cursor root; prepared group owners stay private until their shared decision.
pub struct ArtifactCursor {
    owners: std::mem::ManuallyDrop<ArtifactCursorOwners>,
    group: std::mem::ManuallyDrop<Option<ArtifactCursorGroupRoot>>,
}

struct ArtifactCursorGroupRoot {
    visibility: Arc<crate::os_vcs::ArtifactGroupVisibility>,
    owners: ArtifactCursorOwners,
}

impl ArtifactCursor {
    pub fn new(applied_edit_ids: impl Into<crate::os_vcs::HistoryPageStack<String>>, redo_edit_ids: impl Into<crate::os_vcs::HistoryPageStack<String>>, checkpoint_id: Option<String>) -> Self {
        Self::from_owners(ArtifactCursorOwners { applied_edit_ids: applied_edit_ids.into(), redo_edit_ids: redo_edit_ids.into(), checkpoint_id })
    }

    pub fn from_owners(owners: ArtifactCursorOwners) -> Self {
        Self { owners: std::mem::ManuallyDrop::new(owners), group: std::mem::ManuallyDrop::new(None) }
    }

    pub(crate) fn stage_group_owned(&mut self, owners: ArtifactCursorOwners, visibility: &Arc<crate::os_vcs::ArtifactGroupVisibility>) -> Result<(), ArtifactCursorOwners> {
        if self.group.is_some() || !visibility.pending() {
            return Err(owners);
        }
        *self.group = Some(ArtifactCursorGroupRoot { visibility: Arc::clone(visibility), owners });
        Ok(())
    }

    pub(crate) fn adopt_group_owned(&mut self, visibility: &Arc<crate::os_vcs::ArtifactGroupVisibility>) -> Result<ArtifactCursorOwners, ()> {
        if !visibility.committed() || !self.group.as_ref().is_some_and(|group| Arc::ptr_eq(&group.visibility, visibility)) {
            return Err(());
        }
        let group = self.group.take().expect("validated committed cursor root remains owned");
        Ok(std::mem::replace(&mut *self.owners, group.owners))
    }

    pub(crate) fn abort_group_owned(&mut self, visibility: &Arc<crate::os_vcs::ArtifactGroupVisibility>) -> Result<ArtifactCursorOwners, ()> {
        if visibility.pending() || visibility.committed() || !self.group.as_ref().is_some_and(|group| Arc::ptr_eq(&group.visibility, visibility)) {
            return Err(());
        }
        Ok(self.group.take().expect("validated aborted cursor root remains owned").owners)
    }

    fn group_visibility(&self) -> Option<&crate::os_vcs::ArtifactGroupVisibility> {
        self.group.as_ref().map(|group| group.visibility.as_ref())
    }

    fn read_group(&self, decision: Option<&crate::os_vcs::ArtifactGroupReadDecision<'_>>) -> Result<&ArtifactCursorOwners, ()> {
        match self.group.as_ref() {
            Some(group) if decision.ok_or(())?.committed_for(&group.visibility)? => Ok(&group.owners),
            _ => Ok(&*self.owners),
        }
    }
}

impl Default for ArtifactCursor {
    fn default() -> Self {
        Self::from_owners(ArtifactCursorOwners::default())
    }
}

impl std::ops::Deref for ArtifactCursor {
    type Target = ArtifactCursorOwners;

    fn deref(&self) -> &Self::Target {
        self.group.as_ref().filter(|group| group.visibility.committed()).map_or(&*self.owners, |group| &group.owners)
    }
}

impl std::ops::DerefMut for ArtifactCursor {
    fn deref_mut(&mut self) -> &mut Self::Target {
        assert!(self.group.is_none(), "mutable cursor access requires its staged group to be adopted or aborted");
        &mut self.owners
    }
}

impl Clone for ArtifactCursor {
    fn clone(&self) -> Self {
        Self::from_owners((**self).clone())
    }
}

impl std::fmt::Debug for ArtifactCursor {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        (**self).fmt(formatter)
    }
}

impl PartialEq for ArtifactCursor {
    fn eq(&self, other: &Self) -> bool {
        **self == **other
    }
}

impl ToValue for ArtifactCursor {
    fn to_value(&self) -> DslValue {
        (**self).to_value()
    }
}

impl FromValue for ArtifactCursor {
    fn from_value(value: DslValue) -> Result<Self, ValueError> {
        Ok(Self::from_owners(ArtifactCursorOwners::from_value(value)?))
    }
}

/// 🌉️ serde twin of the `ToValue`/`FromValue` pair above — TEST-ONLY
/// (RUNTIME-DEPENDENCY-ELIMINATION-FOR-S-PLUGINS-AND-ARTIFACTS, 26/09/01): `BackboneDocument` in
/// `💻️os/🖥️host`, the only production consumer that forced this to stay unconditional, moved to a
/// hand-written `ToValue`/`FromValue` impl (see `📓️os-kernel-serde-final.md`). Delegates through
/// the same `ArtifactCursorOwners` view (itself now also `cfg_attr(test, …)`-gated) so both
/// encodings emit an identical shape. Hand-written rather than derived because the private fields
/// are `ManuallyDrop` (the staged group root must be adopted or retired before `Drop`), which no
/// derive can see through.
#[cfg(test)]
impl Serialize for ArtifactCursor {
    fn serialize<S: serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        Serialize::serialize(&**self, serializer)
    }
}

/// 🌉️ Mirror of the `Serialize` twin directly above — also test-only.
#[cfg(test)]
impl<'de> Deserialize<'de> for ArtifactCursor {
    fn deserialize<D: serde::Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        ArtifactCursorOwners::deserialize(deserializer).map(Self::from_owners)
    }
}

impl Drop for ArtifactCursor {
    fn drop(&mut self) {
        assert!(std::thread::panicking() || (self.group.is_none()), "artifact cursor reached Drop before its exact staged root was adopted or returned for retirement");
        unsafe { std::mem::ManuallyDrop::drop(&mut self.owners) };
    }
}

//#region 🔖️HistoryLane
/// 🛤️ Which undo/redo cursor a recorded edit belongs to. `Document` is the default — the
/// ordinary main history `Undo`/`Redo` travels. Any other lane (starting with `Interaction`) is a
/// persisted, replayable SIDE history: mutations recorded under it stay in `ArtifactVcs.edits` and
/// `ArtifactEnvelope.lanes` forever (never dropped, never un-persisted), but default `Undo`/`Redo`
/// skip past them to the nearest `Document`-lane entry instead of reverting them — see
/// `ArtifactStore::dispatch`'s `Undo`/`Redo` arms, and `ArtifactCommand::UndoInLane`/`RedoInLane`
/// for the explicit lane-scoped API that CAN walk a non-`Document` lane. Deliberately an
/// extensible general store mechanism — e.g. a future framework-owned selection/interaction state
/// that must survive reload but must never be what a document editor's undo reverts — not a
/// hover/selection special case baked into this crate. See ticket
/// `26/08/14/FIRST-CLASS-HOVER-AND-SELECTION-MECHANISM/📋️master.md` decision 1.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, ToValue, FromValue)]
#[value(rename_all = "camelCase")]
pub enum HistoryLane {
    #[default]
    Document,
    Interaction,
}

impl HistoryLane {
    async fn is_document(&self) -> bool {
        matches!(self, HistoryLane::Document)
    }
}
//#endregion 🔖️HistoryLane

#[derive(Debug, PartialEq)]
pub struct ArtifactEnvelopeOwners<P, Mutation> {
    pub schema: String,
    pub id: String,
    pub vcs: ArtifactVcs<P, Mutation>,
    pub backbone: Option<ArtifactBackboneRef>,
    pub active_alternative_id: Option<String>,
    /// 🎯️ Undo/redo/checkout position, present only once a store has synced it (see
    /// `ArtifactStore::sync_cursor`) — absent for a freshly-constructed envelope or one loaded
    /// from a source that predates this field, in which case position stays runtime-only exactly
    /// as before.
    pub cursor: Option<ArtifactCursor>,
    /// 🗣️ The dialect this envelope's `vcs.initial_snapshot` (and every replayed edit) is
    /// currently in — absent for envelopes minted before dialect-tracking existed, or for document
    /// kinds that never adopted more than one dialect. See `26/08/10` D4 evolution slice; nothing
    /// in `ArtifactStore::dispatch` reads or writes this yet (that wiring is later scope) — it is
    /// purely a persisted fact a future migration-aware caller can act on.
    pub dialect: Option<crate::os_io::ArtifactDialect>,
    /// 🧬️ Set once, the first time this envelope's snapshot was produced by migrating a
    /// prior document's dialect (see `migrate_document` below) rather than being authored directly
    /// in `dialect`. Absent for every envelope that was never migrated.
    pub migrated_from: Option<MigrationProvenance>,
    /// 🏠️ Present exactly when this envelope is a CHILD in a composition — the ownership
    /// stamp naming which parent/slot/`child_id` created it (see `🔖️Composition` below). Placed on
    /// the CHILD's own envelope (not only on the parent's `ArtifactChild` handle) so ownership is
    /// queryable directly from the child side — e.g. "is this document embeddable standalone, or
    /// does deleting it require going through its owner". Absent for every independent artifact
    /// (the overwhelming majority) and for every envelope minted before this ticket.
    pub owner: Option<OwnerRef>,
    /// 🛤️ Sparse `Edit.id → HistoryLane` ledger: only entries recorded under a NON-`Document`
    /// lane are ever inserted (an ordinary document edit never gets a map entry at all), so an id
    /// absent from this map is `HistoryLane::Document` by construction — see
    /// `ArtifactStore::edit_lane`. Additive — absent (empty map) for every envelope minted before
    /// this field existed, all of which therefore decode as if every edit were `Document` lane,
    /// matching prior undo/redo behavior exactly. Lives on the envelope (not on `Edit<Mutation>`
    /// itself, which this crate's per-technology `Mutation` types don't own) so it survives a plain
    /// JSON round trip (`ArtifactStore::envelope_json`) alongside `cursor`/`owner`/`dialect`.
    pub lanes: BTreeMap<String, HistoryLane>,
    /// 👁 Explicit checkpoint this viewer is looking at. `None` is the tip of the active line.
    /// Local to this replica: a collaborator's checkout does not write it.
    pub viewer_checkpoint_id: Option<String>,
    pub edit_messages: ArtifactEditMessageLedger,
    pub conflicts: Vec<crate::os_spr::Conflict>,
    /// 🔀️ Every structural history event — undo, redo, checkpoint commit, branch, checkout,
    /// repin — as one causal `crate::os_spr::HISTORY_TRANSITION_SCHEMA` envelope, in HLC order.
    /// Together with `vcs.edits` this is the document's complete semantic event log. The
    /// change/checkpoint/alternative ledgers are its projection. `active_alternative_id` and
    /// `viewer_checkpoint_id` are this replica's head, persisted local-only, not that projection.
    pub transitions: Vec<crate::os_spr::MutationEnvelope>,
    /// 🗂️ The transitions this history holds ([`crate::os_spr::HistoryShape`]): a config store's history holds undo and
    /// redo only, so its store refuses every other transition at dispatch and at remote admission — the same law its
    /// retained loader applies.
    pub history_shape: crate::os_spr::HistoryShape,
    /// 🎐️ The tool transaction whose edit is open in `vcs.edits` ([`ArtifactCommand::AppendTransaction`]). The store folds
    /// that edit as its applied tail, but neither the shared log ([`ArtifactStore::event_log`]) nor a persisted form
    /// ([`print_document_spr`], [`print_document_text`]) holds it before its commit, so an abort or a lost session leaves
    /// no trace.
    pub open_transaction: Option<OpenToolTransaction>,
}

/// 📸️ One immutable envelope observation; cursor and every history ledger share one captured decision.
pub struct ArtifactEnvelopeRead<'a, P, Mutation> {
    schema: &'a str,
    id: &'a str,
    vcs: crate::os_vcs::ArtifactVcsRead<'a, P, Mutation>,
    backbone: Option<&'a ArtifactBackboneRef>,
    active_alternative_id: Option<&'a String>,
    cursor: Option<&'a ArtifactCursorOwners>,
    dialect: Option<&'a crate::os_io::ArtifactDialect>,
    migrated_from: Option<&'a MigrationProvenance>,
    owner: Option<&'a OwnerRef>,
    lanes: &'a BTreeMap<String, HistoryLane>,
    viewer_checkpoint_id: Option<&'a String>,
    edit_messages: &'a ArtifactEditMessageLedger,
    conflicts: &'a Vec<crate::os_spr::Conflict>,
}

/// 🌉️ Hand-written, not derived: every field but `vcs` is a plain reference or `Option<&T>`, and
/// no blanket `impl<T: ToValue> ToValue for &T` exists in this codebase (see `ArtifactVcsRead`'s
/// own docstring) — mirrors the former `#[derive(Serialize)]`'s `skip_serializing_if` shape by
/// simply omitting the key when the option is `None`/the map is empty.
impl<P: ToValue, Mutation: ToValue> ToValue for ArtifactEnvelopeRead<'_, P, Mutation> {
    fn to_value(&self) -> DslValue {
        let mut entries = vec![("schema".to_string(), self.schema.to_value()), ("id".to_string(), self.id.to_value()), ("vcs".to_string(), self.vcs.to_value())];
        if let Some(backbone) = self.backbone {
            entries.push(("backbone".to_string(), backbone.to_value()));
        }
        if let Some(active_alternative_id) = self.active_alternative_id {
            entries.push(("activeAlternativeId".to_string(), active_alternative_id.to_value()));
        }
        if let Some(cursor) = self.cursor {
            entries.push(("cursor".to_string(), cursor.to_value()));
        }
        if let Some(dialect) = self.dialect {
            entries.push(("dialect".to_string(), dialect.to_value()));
        }
        if let Some(migrated_from) = self.migrated_from {
            entries.push(("migratedFrom".to_string(), migrated_from.to_value()));
        }
        if let Some(owner) = self.owner {
            entries.push(("owner".to_string(), owner.to_value()));
        }
        if !self.lanes.is_empty() {
            entries.push(("lanes".to_string(), self.lanes.to_value()));
        }
        if let Some(viewer_checkpoint_id) = self.viewer_checkpoint_id {
            entries.push(("viewerCheckpointId".to_string(), viewer_checkpoint_id.to_value()));
        }
        entries.push(("editMessages".to_string(), self.edit_messages.to_value()));
        entries.push(("conflicts".to_string(), self.conflicts.to_value()));
        DslValue::Object(entries)
    }
}

impl<P, Mutation> ArtifactEnvelopeOwners<P, Mutation> {
    /// 🖇️ Whether `edit_id` is committed history: every edit but the open tool transaction's, which the shared log and
    /// every persisted form leave out until its commit.
    pub fn holds_committed_edit(&self, edit_id: &str) -> bool {
        self.open_transaction.as_ref().is_none_or(|open| open.edit_id != edit_id)
    }

    /// 📸️ Captures read roots before any serializer can cross a shared group decision.
    pub fn capture_read(&self) -> Result<ArtifactEnvelopeRead<'_, P, Mutation>, &'static str> {
        let history_visibility = self.vcs.group_visibility().map_err(|()| "envelope history contains different group authorities")?;
        let cursor_visibility = self.cursor.as_ref().and_then(ArtifactCursor::group_visibility);
        if history_visibility.zip(cursor_visibility).is_some_and(|(history, cursor)| !std::ptr::eq(history, cursor)) {
            return Err("envelope cursor and history have different group authorities");
        }
        let decision = history_visibility.or(cursor_visibility).map(crate::os_vcs::ArtifactGroupVisibility::capture);
        let vcs = self.vcs.read_group(decision.as_ref()).map_err(|()| "envelope history lost its captured group authority")?;
        let cursor = self.cursor.as_ref().map(|cursor| cursor.read_group(decision.as_ref())).transpose().map_err(|()| "envelope cursor lost its captured group authority")?;
        Ok(ArtifactEnvelopeRead {
            schema: &self.schema,
            id: &self.id,
            vcs,
            backbone: self.backbone.as_ref(),
            active_alternative_id: self.active_alternative_id.as_ref(),
            cursor,
            dialect: self.dialect.as_ref(),
            migrated_from: self.migrated_from.as_ref(),
            owner: self.owner.as_ref(),
            lanes: &self.lanes,
            viewer_checkpoint_id: self.viewer_checkpoint_id.as_ref(),
            edit_messages: &self.edit_messages,
            conflicts: &self.conflicts,
        })
    }
}

/// 🛡️ Terminal shell for one exact document record. Deep fields are ManuallyDrop from
/// birth and can leave the shell only through the bounded store/completed-record owner protocols.
pub struct ArtifactEnvelope<P, Mutation> {
    owners: std::mem::ManuallyDrop<ArtifactEnvelopeOwners<P, Mutation>>,
    owners_detached: bool,
}

impl<P, Mutation> ArtifactEnvelope<P, Mutation> {
    pub fn from_owners(owners: ArtifactEnvelopeOwners<P, Mutation>) -> Self {
        Self { owners: std::mem::ManuallyDrop::new(owners), owners_detached: false }
    }

    /// 🧺️ Consumes the terminal shell and hands back its owners. This is the ONLY way a caller
    /// outside this module can read an envelope's fields: the shell's `Drop` asserts that its owners
    /// were detached first, so reading fields by reference and letting the shell fall out of scope
    /// aborts at runtime ("terminal shell reached Drop before ... detached every nested owner").
    /// `🖥️host`'s `BackboneDocument` construction goes through here for exactly that reason.
    pub fn into_owners(mut self) -> ArtifactEnvelopeOwners<P, Mutation> {
        assert!(!self.owners_detached, "artifact envelope owners were detached twice");
        self.owners_detached = true;
        unsafe { std::mem::ManuallyDrop::take(&mut self.owners) }
    }

    /// 🧹️ Retires a candidate envelope that no store adopted. {@link into_owners} hands back
    /// fixed ledgers (`vcs.edits`/`changes`/`checkpoints`/`alternatives`, `edit_messages`) that each
    /// carry their own terminal-empty `Drop` witness, so dropping a POPULATED candidate aborts the
    /// process on that witness instead of surfacing the refusal. Every entry is popped here, in the
    /// same tail-first order {@link ArtifactStore::close_take_final_envelope_retirement} leaves the
    /// ledgers in, and nothing else about the refusal changes. The initial snapshot and every popped
    /// edit are retired through the technology's own vocabulary, never dropped: a procedural
    /// snapshot's `OrderedMap` layout and its operations' roots abort the guest on a bare drop (hub
    /// genesis of `3d.generation`, 2026-09-28, ticket 26/09/23 slice S19).
    pub fn retire_unadopted(self)
    where
        Mutation: self::Mutation<P>,
    {
        let ArtifactEnvelopeOwners { schema, id, vcs, backbone, active_alternative_id, cursor, dialect, migrated_from, owner, lanes, viewer_checkpoint_id, mut edit_messages, conflicts, transitions, history_shape: _, open_transaction: _ } = self.into_owners();
        let ArtifactVcs { initial_snapshot, mut edits, mut changes, mut checkpoints, mut alternatives } = vcs;
        while let Some(edit) = edits.pop() {
            retire_scratch_edits::<P, Mutation>([edit]);
        }
        while changes.pop().is_some() {}
        while checkpoints.pop().is_some() {}
        while alternatives.pop().is_some() {}
        while edit_messages.pop().is_some() {}
        drop((schema, id, edits, changes, checkpoints, alternatives, backbone, active_alternative_id, cursor, dialect, migrated_from, owner, lanes, viewer_checkpoint_id, edit_messages, conflicts, transitions));
        retire_replayed_projection::<P, Mutation>(initial_snapshot);
    }

    /// 🌱️ Moves the sole snapshot from a decoder-proven fresh envelope. Rejection
    /// returns the exact shell untouched; accepted metadata is definitionally bounded and empty.
    pub fn try_into_fresh_snapshot(self) -> Result<P, Self> {
        if self.schema.len() > 256
            || self.id.len() > 256
            || !self.vcs.edits.is_empty()
            || !self.vcs.changes.is_empty()
            || !self.vcs.checkpoints.is_empty()
            || !self.vcs.alternatives.is_empty()
            || self.backbone.is_some()
            || self.active_alternative_id.is_some()
            || self.cursor.is_some()
            || self.dialect.is_some()
            || self.migrated_from.is_some()
            || self.owner.is_some()
            || !self.lanes.is_empty()
            || self.viewer_checkpoint_id.is_some()
            || !self.edit_messages.is_empty()
            || !self.conflicts.is_empty()
            || !self.transitions.is_empty()
        {
            return Err(self);
        }
        let ArtifactEnvelopeOwners { schema, id, vcs, backbone, active_alternative_id, cursor, dialect, migrated_from, owner, lanes, viewer_checkpoint_id, edit_messages, conflicts, transitions, history_shape: _, open_transaction: _ } = self.into_owners();
        let ArtifactVcs { initial_snapshot, edits, changes, checkpoints, alternatives } = vcs;
        drop((schema, id, edits, changes, checkpoints, alternatives, backbone, active_alternative_id, cursor, dialect, migrated_from, owner, lanes, viewer_checkpoint_id, edit_messages, conflicts, transitions));
        Ok(initial_snapshot)
    }
}

impl<P, Mutation> std::ops::Deref for ArtifactEnvelope<P, Mutation> {
    type Target = ArtifactEnvelopeOwners<P, Mutation>;

    fn deref(&self) -> &Self::Target {
        &self.owners
    }
}

impl<P, Mutation> std::ops::DerefMut for ArtifactEnvelope<P, Mutation> {
    fn deref_mut(&mut self) -> &mut Self::Target {
        &mut self.owners
    }
}

impl<P: std::fmt::Debug, Mutation: std::fmt::Debug> std::fmt::Debug for ArtifactEnvelope<P, Mutation> {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        self.owners.fmt(formatter)
    }
}

impl<P: PartialEq, Mutation: PartialEq> PartialEq for ArtifactEnvelope<P, Mutation> {
    fn eq(&self, other: &Self) -> bool {
        self.owners.eq(&other.owners)
    }
}

impl<P, Mutation> Drop for ArtifactEnvelope<P, Mutation> {
    fn drop(&mut self) {
        assert!(std::thread::panicking() || (self.owners_detached), "artifact envelope terminal shell reached Drop before its app-owned bounded retirement authority detached every nested owner");
    }
}

/// 🧬️ Provenance stamp for an envelope produced by `migrate_document`: which prior document,
/// which dialect it was in, and (if the migration ran at a specific checkpoint rather than the
/// live tip) which checkpoint. `migrated_at` follows this crate's existing `Checkpoint.timestamp`/
/// `Edit.started_at` convention (a caller-supplied string stamped via `now_iso()`, see below) — no
/// new clock abstraction introduced for this one field.
#[derive(Clone, Debug, PartialEq, ToValue, FromValue)]
#[value(rename_all = "camelCase")]
pub struct MigrationProvenance {
    pub document_id: String,
    pub dialect: crate::os_io::ArtifactDialect,
    #[value(default, skip_serializing_if = "Option::is_none")]
    pub checkpoint_id: Option<String>,
    pub migrated_at: String,
}

#[derive(Clone, Debug, PartialEq, ToValue, FromValue)]
#[value(tag = "kind", rename_all = "camelCase")]
pub enum ArtifactCommand<Mutation> {
    /// ▶️ Records `mutations` as one edit; `transaction` names the committed tool transaction that authored them, stamped
    /// on every operation's metadata and wire envelope.
    Apply {
        mutations: Vec<Mutation>,
        #[value(skip_serializing_if = "Option::is_none")]
        description: Option<String>,
        #[value(default, skip_serializing_if = "Option::is_none")]
        transaction: Option<protocol::TransactionRef>,
    },
    Undo,
    Redo,
    UndoWithPolicy {
        policy: UndoPolicy,
        #[value(default, skip_serializing_if = "Option::is_none")]
        semantic_command: Option<Box<ArtifactCommand<Mutation>>>,
    },
    /// 🛤️ `Apply`'s lane-tagged twin — records the resulting edit under `lane` (via
    /// `ArtifactEnvelope.lanes`) instead of the implicit `HistoryLane::Document` a plain `Apply`
    /// gets.
    ApplyInLane {
        mutations: Vec<Mutation>,
        #[value(skip_serializing_if = "Option::is_none")]
        description: Option<String>,
        #[value(default)]
        lane: HistoryLane,
        #[value(default, skip_serializing_if = "Option::is_none")]
        transaction: Option<protocol::TransactionRef>,
    },
    /// 🛤️ Explicit lane-scoped undo: mirrors plain `Undo`'s selective (own-author) semantics
    /// but searches `applied_edit_ids` for the nearest local entry whose `HistoryLane` is exactly
    /// `lane`, instead of `HistoryLane::Document`. Lets a caller walk a non-`Document` lane on
    /// purpose — the completing half of "default `Undo`/`Redo` skip non-`Document` lanes" (see
    /// `ArtifactStore::dispatch`'s `Undo` arm).
    UndoInLane {
        lane: HistoryLane,
    },
    /// 🛤️ `UndoInLane`'s redo-direction sibling — mirrors plain `Redo`, but pops the
    /// nearest-to-top `redo_edit_ids` entry whose `HistoryLane` is exactly `lane`.
    RedoInLane {
        lane: HistoryLane,
    },
    CommitCheckpoint {
        #[value(skip_serializing_if = "Option::is_none")]
        message: Option<String>,
        #[value(default, skip_serializing_if = "Vec::is_empty")]
        authors: Vec<Author>,
    },
    CreateAlternative {
        name: String,
    },
    SwitchAlternative {
        alternative_id: String,
    },
    CheckoutCheckpoint {
        #[value(rename = "checkpointId")]
        checkpoint_id: String,
    },
    /// 🕸️ Feeds a remote MutationEnvelope through the causal DAG into the edit timeline.
    IngestRemote {
        #[value(serialize_with = "operation_envelope_serde::to_value", deserialize_with = "operation_envelope_serde::from_value")]
        envelope: crate::os_spr::MutationEnvelope,
    },
    /// 🧹 Clears volatile draft-lane history that must never enter a Change/Checkpoint.
    PruneDrafts,
    /// ⚖️ Sets this store's local `crate::os_spr::MergePolicy` — authority-local state, never
    /// carried on a `crate::os_spr::MutationEnvelope`/`BackboneMessage`, never part of shared
    /// history (`26/08/16/MUTATION-OUTCOMES-MERGE-POLICIES-AND-FIRST-CLASS-CONFLICTS` §C6). Ordinal
    /// 15 — frozen, appended after `PruneDrafts`.
    SetMergePolicy {
        policy: crate::os_spr::MergePolicy,
    },
    /// ⚔️ Resolves an `Open` `crate::os_spr::Conflict` by id — see
    /// `ArtifactStore::resolve_conflict` for what `Accept`/`Discard` do for each conflict kind.
    /// Ordinal 16 — frozen.
    ResolveConflict {
        conflict_id: String,
        resolution: crate::os_spr::ConflictResolution,
    },
    /// ✏️ Supersedes the effective input of applied operations, non-destructively: each input replaces its target's
    /// input (`None` withdraws it) in every alternative, or only within the alternative `scope`. Refused atomically
    /// with `Rejected { policy: Normal }` when the Report replay of everything downstream raises an `Error` or `Fatal`.
    /// Ordinal 17.
    Supersede {
        #[value(default, skip_serializing_if = "Option::is_none")]
        scope: Option<String>,
        inputs: Vec<SupersedeInput<Mutation>>,
    },
    /// 🌿️ Commits the pending edits, branches the alternative `name` at the head and supersedes `inputs` within it —
    /// one atomic dispatch leaving in one outbound batch. Ordinal 18.
    CreateAlternativeWithSupersede {
        name: String,
        inputs: Vec<SupersedeInput<Mutation>>,
    },
    /// 🎞️ Appends `mutations` to the open edit of the tool transaction `transaction`, opening it with its first append:
    /// a streamed tool's ticks become one edit, every operation stamped with the ref and none announced before
    /// `CommitTransaction`. While it is open the store refuses every command but its appends, its commit or abort, a remote
    /// ingest and a merge-policy change (`VcsError::TransactionOpen`). Ordinal 19.
    AppendTransaction {
        mutations: Vec<Mutation>,
        transaction: protocol::TransactionRef,
    },
    /// ✅️ Closes the open edit of the tool transaction `transaction_id` and announces every operation it holds. Ordinal 20.
    CommitTransaction {
        transaction_id: String,
    },
    /// 🧨️ Reverts the open edit of the tool transaction `transaction_id` with zero trace: no edit, no operation, no
    /// announcement, the projection and revision of before its first append. Ordinal 21.
    AbortTransaction {
        transaction_id: String,
    },
}

/// 🎞️ The tool transaction a store holds open ([`ArtifactCommand::AppendTransaction`]): its ref and the one edit its
/// appends grow, kept at the tail of the local applied history until its commit announces it or its abort removes it.
#[derive(Clone, Debug, PartialEq)]
pub struct OpenToolTransaction {
    pub transaction: protocol::TransactionRef,
    pub edit_id: String,
}

/// 🐢️ A history change this store admitted but has not adopted yet (design §16.6): the remote `transitions` it admitted
/// ([`ArtifactStore::defer_remote_replays`]) and at most one `local` step this replica authored
/// ([`ArtifactStore::defer_local_replays`]) wait outside the log while their Report replay steps turn by turn; the replay
/// restarts whenever the history it started from changed (the content revision it names).
struct PendingReprojection<P, Mutation>
where
    Mutation: self::Mutation<P>,
{
    transitions: Vec<crate::os_spr::MutationEnvelope>,
    local: Option<PendingLocalStep>,
    replay: Option<([u8; 32], EditReplay<P, Mutation>)>,
}

impl<P, Mutation> PendingReprojection<P, Mutation>
where
    Mutation: self::Mutation<P>,
{
    /// 🫗️ Nothing admitted yet.
    fn empty() -> Self {
        Self { transitions: Vec::new(), local: None, replay: None }
    }
}

/// 🪃️ A local history step whose Report replay outlasts its dispatch: the transitions it authored (neither recorded nor
/// announced yet), the head `(line, checkpoint)` it moves this replica to, and whether it finalizes a supersession — whose
/// report must not block finalizing, or the step is refused with nothing of it recorded.
struct PendingLocalStep {
    envelopes: Vec<crate::os_spr::MutationEnvelope>,
    head: (Option<String>, Option<String>),
    finalizing: bool,
}

/// ⏩️ Where one advance of a deferred reprojection left it.
enum ReprojectionAdvance {
    Pending(ReplayProgress),
    Adopted(Vec<crate::os_spr::EditMessages>),
}

/// ⏱️ How far one turn of a deferred reprojection replays (design §7: ≤ 4 ms slices): until the turn's wall deadline on
/// `now_us` — `wall_us` after the turn began, or the runtime's own turn deadline ([`ArtifactStore::step_reprojection`]) —
/// and at most `operations` operations, whichever comes first; every turn replays at least one operation. `now_us` is the
/// job clock ([`semio_framework_job::default_now_us`]); laws inject their own.
#[derive(Clone, Copy, Debug)]
pub struct ReplayTurnBudget {
    pub wall_us: u64,
    pub operations: usize,
    pub now_us: fn() -> Option<u64>,
}

impl ReplayTurnBudget {
    /// 🕓️ `wall_us` of the job clock per turn, with `operations` as the secondary cap.
    pub fn wall(wall_us: u64, operations: usize) -> Self {
        Self { wall_us, operations, now_us: semio_framework_job::default_now_us }
    }

    /// 🔢️ `operations` per turn and no wall limit: what a law that counts operations replays with.
    pub fn operations(operations: usize) -> Self {
        Self { wall_us: u64::MAX, operations, now_us: semio_framework_job::default_now_us }
    }

    /// ⌛️ The turn's deadline on `now_us`: the runtime's `deadline_us`, else `wall_us` from now (now when the clock cannot
    /// be read); `None` without a wall limit.
    fn turn_deadline(&self, deadline_us: Option<u64>) -> Option<u64> {
        deadline_us.or_else(|| (self.wall_us != u64::MAX).then(|| (self.now_us)().map_or(0, |now| now.saturating_add(self.wall_us))))
    }

    /// 🛎️ Whether a turn that replayed `replayed` operations ends: its cap is reached or its deadline passed on `now_us`
    /// (an unreadable clock ends it).
    fn turn_ends(&self, replayed: usize, deadline_us: Option<u64>) -> bool {
        replayed >= self.operations || deadline_us.is_some_and(|deadline| (self.now_us)().is_none_or(|now| now >= deadline))
    }
}

/// ✏️ One input of [`ArtifactCommand::Supersede`]: the superseded operation and the replacement it folds as from now
/// on (`None` withdraws it).
#[derive(Clone, Debug, PartialEq, ToValue, FromValue)]
#[value(rename_all = "camelCase")]
pub struct SupersedeInput<Mutation> {
    pub target: MutationId,
    #[value(default, skip_serializing_if = "Option::is_none")]
    pub replacement: Option<Mutation>,
}

impl<Mutation> ArtifactCommand<Mutation> {
    /// 🔮️ Names the projection-invalidating transition this command performs, if it has one.
    pub async fn projection_cause(&self) -> Option<ArtifactProjectionCause> {
        match self {
            Self::Apply { .. } | Self::ApplyInLane { .. } => Some(ArtifactProjectionCause::Apply),
            Self::IngestRemote { .. } => Some(ArtifactProjectionCause::RemoteIngest),
            Self::Undo | Self::UndoWithPolicy { .. } | Self::UndoInLane { .. } => Some(ArtifactProjectionCause::Undo),
            Self::Redo | Self::RedoInLane { .. } => Some(ArtifactProjectionCause::Redo),
            Self::CheckoutCheckpoint { .. } | Self::CreateAlternative { .. } | Self::SwitchAlternative { .. } => Some(ArtifactProjectionCause::Checkout),
            Self::CommitCheckpoint { .. } => Some(ArtifactProjectionCause::Checkpoint),
            Self::PruneDrafts => Some(ArtifactProjectionCause::PruneDrafts),
            Self::SetMergePolicy { .. } => Some(ArtifactProjectionCause::PolicyChange),
            Self::ResolveConflict { .. } => Some(ArtifactProjectionCause::RemoteIngest),
            Self::Supersede { .. } | Self::CreateAlternativeWithSupersede { .. } => Some(ArtifactProjectionCause::Replay),
            Self::AppendTransaction { .. } | Self::CommitTransaction { .. } => Some(ArtifactProjectionCause::Apply),
            Self::AbortTransaction { .. } => Some(ArtifactProjectionCause::Undo),
        }
    }

    /// 🚦️ Whether this command moves history positions — an undo, redo, checkpoint, alternative, checkout, supersession or
    /// conflict resolution: what a store whose local history step still replays refuses ([`VcsError::HistoryReplaying`]).
    pub fn moves_history(&self) -> bool {
        !self.history_transition_kinds().is_empty() || matches!(self, Self::ResolveConflict { .. })
    }

    /// 🏷️ Every kind of history transition this command may author, in authoring order: what the store's
    /// [`crate::os_spr::HistoryShape`] must admit before the command runs.
    pub fn history_transition_kinds(&self) -> &'static [crate::os_spr::HistoryTransitionKind] {
        use crate::os_spr::HistoryTransitionKind::{Branch, Checkout, Commit, Reinstate, Revert, Supersede};
        match self {
            Self::Undo | Self::UndoWithPolicy { .. } | Self::UndoInLane { .. } => &[Revert],
            Self::Redo | Self::RedoInLane { .. } => &[Reinstate],
            Self::CommitCheckpoint { .. } => &[Commit],
            Self::CreateAlternative { .. } => &[Commit, Branch],
            Self::SwitchAlternative { .. } | Self::CheckoutCheckpoint { .. } => &[Checkout],
            Self::Supersede { .. } => &[Supersede],
            Self::CreateAlternativeWithSupersede { .. } => &[Commit, Branch, Supersede],
            Self::Apply { .. }
            | Self::ApplyInLane { .. }
            | Self::IngestRemote { .. }
            | Self::PruneDrafts
            | Self::SetMergePolicy { .. }
            | Self::ResolveConflict { .. }
            | Self::AppendTransaction { .. }
            | Self::CommitTransaction { .. }
            | Self::AbortTransaction { .. } => &[],
        }
    }
}
//#endregion 🔖️Schemas

//#region 🔖️Composition
// 🧩️ Composable-vs-referenceable artifact primitives (ticket `26/08/12/UNIFIED-COMPOSABLE-
// ARTIFACT-SYSTEM` `📓️design-full-plan.md` §"1. Kernel primitives"). Two structurally distinct
// relationships between artifacts:
// - a **CHILD** (`ArtifactChild<S>` on the parent's snapshot / `OwnerRef` on the child's own
//   envelope): the parent creates and deletes it, it has exactly one owner, no pin, no
//   independent lifecycle, and nests inline in UI — but it is still its OWN `ArtifactEnvelope`
//   with its own `ArtifactVcs` history and store, never an inline subtree (this crate's own doc
//   comment / the design doc's "Child = own envelope" decision). Consequently a parent's diff
//   NEVER embeds a child diff.
// - a **LINK** (`ArtifactLink`/`LinkPin`): an independent lifecycle of its own, a PIN (so it can
//   be frozen to a specific `Head`/`Checkpoint`/content-addressed `Snapshot`), and renders as a
//   chip, never nested inline.
//
// `ArtifactRefs` lets a snapshot type declare its own children/links (defaulted to none, so a
// leaf artifact needs zero boilerplate); `LinkResolver`/`ChildStoreFactory` are the host-side
// seams that turn those declarations into real bytes/stores. `CompositionCoordinator` (its own
// `🔖️CompositionCoordinator` region, after `🔖️Space` below) orchestrates atomic multi-store
// dispatch across a parent and its children on top of these types.

/// 🧸️ Ownership handle a parent SNAPSHOT embeds for one owned child slot (e.g. a plugin's
/// generated field `mesh_child: ArtifactChild<MeshSnapshot>`). `S` is a compile-time-only phantom
/// naming which snapshot type the child is expected to materialize as — it never appears on the
/// wire and never constrains this type's own capabilities. `Clone`/`Debug`/`PartialEq` are
/// hand-implemented below (not `#[derive(..)]`'d): deriving them on a `PhantomData<S>`-carrying
/// struct adds an unwanted `S: Trait` bound to every impl even though `S` never appears in any
/// stored/compared data, so those three derives would silently fail to work "for any `S`" (the
/// task's own requirement) the moment a caller picked an `S` that itself didn't implement
/// `Clone`/`Debug`/`PartialEq`. `Serialize`/`Deserialize` avoid the same trap via `#[serde(bound =
/// "")]` instead of a hand impl — the standard serde idiom for a `PhantomData<S>` field, since
/// serde's derive macro honors an explicit empty bound list rather than inferring one from `S`.
/// `local_owner` is a serialization-skipped, immutable materialization retained by this exact
/// handle; it is intentionally absent from equality, debug, DSL, pack, and JSON identity. No pin,
/// no independent lifecycle: see the region doc's CHILD-vs-LINK split.
struct ArtifactChildLocalText(Arc<str>);

/// 🚫️ Why an owned child's local materialization cannot be read at a typed boundary.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ArtifactChildMaterializationError {
    Absent,
    WrongType,
}

impl std::fmt::Display for ArtifactChildMaterializationError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Absent => formatter.write_str("artifact child is not materialized"),
            Self::WrongType => formatter.write_str("artifact child materialization has a different exact type"),
        }
    }
}

impl std::error::Error for ArtifactChildMaterializationError {}

/// 🆔️ The content-addressed id of a composed child or persisted scene: `<prefix>-` + the first 16 lowercase hex digits
/// of SHA-256 over `bytes` (the child schema's `ContentId`). Specified, stable across processes, platforms and
/// toolchains, and reproducible by any implementation — unlike a `std` hasher, whose algorithm Rust leaves unspecified.
/// A site that addresses several fields joins them with U+001F. TypeScript twin: `contentId` (`🪆️child/🧬️schema/🟦️.ts`).
pub fn content_id(prefix: &str, bytes: &[u8]) -> String {
    format!("{prefix}-{}", semio_framework_hash::hex_lower(&semio_framework_hash::Sha256::digest(bytes)[..8]))
}

pub struct ArtifactChild<S> {
    pub child_id: String,
    pub target: crate::os_io::ArtifactRef,
    local_owner: Option<Arc<dyn std::any::Any + Send + Sync>>,
    _snapshot: PhantomData<S>,
}

impl<S> ArtifactChild<S> {
    /// 🏗️ Constructs a handle, threading the phantom marker for the caller.
    pub fn new(child_id: String, target: crate::os_io::ArtifactRef) -> Self {
        Self { child_id, target, local_owner: None, _snapshot: PhantomData }
    }

    /// 🪆 Attaches an immutable local-only materialization to this owned child handle.
    pub fn with_local_owner<T: std::any::Any + Send + Sync>(mut self, owner: Arc<T>) -> Self {
        self.local_owner = Some(owner);
        self
    }

    /// 🪆 Replaces this handle's immutable local-only materialization owner.
    pub fn set_local_owner<T: std::any::Any + Send + Sync>(&mut self, owner: Arc<T>) {
        self.local_owner = Some(owner);
    }

    /// 🧵 Retains a type-checked local-only materialization without cloning its payload.
    pub fn local_owner<T: std::any::Any + Send + Sync>(&self) -> Option<Arc<T>> {
        Arc::downcast::<T>(self.local_owner.clone()?).ok()
    }

    /// 📤️ Requires the exact local materialization at content-reading boundaries. Exporters must
    /// propagate this failure instead of serializing the handle or substituting default content.
    pub fn require_local_owner<T: std::any::Any + Send + Sync>(&self) -> Result<Arc<T>, ArtifactChildMaterializationError> {
        let owner = self.local_owner.clone().ok_or(ArtifactChildMaterializationError::Absent)?;
        Arc::downcast::<T>(owner).map_err(|_| ArtifactChildMaterializationError::WrongType)
    }

    /// 📤️ Transfers the exact typed local owner; a type mismatch retains the untouched owner.
    pub fn take_local_owner<T: std::any::Any + Send + Sync>(&mut self) -> Result<Option<Arc<T>>, &'static str> {
        let Some(owner) = self.local_owner.take() else {
            return Ok(None);
        };
        match Arc::downcast::<T>(owner) {
            Ok(owner) => Ok(Some(owner)),
            Err(owner) => {
                self.local_owner = Some(owner);
                Err("artifact child local owner has a different exact type")
            }
        }
    }

    /// 🪆 Attaches immutable local-only text to this owned child handle.
    pub fn with_local_text(mut self, text: Arc<str>) -> Self {
        self.local_owner = Some(Arc::new(ArtifactChildLocalText(text)));
        self
    }

    /// 🪆 Replaces this handle's immutable local-only text owner.
    pub fn set_local_text(&mut self, text: Arc<str>) {
        self.local_owner = Some(Arc::new(ArtifactChildLocalText(text)));
    }

    /// 🔎 Borrows this handle's local-only text when the child has been materialized.
    pub fn local_text(&self) -> Option<&str> {
        self.local_owner.as_deref()?.downcast_ref::<ArtifactChildLocalText>().map(|owner| owner.0.as_ref())
    }

    /// 🧵 Retains this handle's local-only text owner without copying its bytes.
    pub fn local_text_owner(&self) -> Option<Arc<str>> {
        self.local_owner.as_deref()?.downcast_ref::<ArtifactChildLocalText>().map(|owner| owner.0.clone())
    }

    /// 🪪️ Drops the compile-time-only `S` phantom, producing the type-erased projection
    /// `ArtifactRefs::child_refs` returns.
    pub async fn to_child_ref(&self, slot: &str) -> ChildRef {
        ChildRef { slot: slot.to_string(), child_id: self.child_id.clone(), target: self.target.clone() }
    }
}

impl<S> Clone for ArtifactChild<S> {
    fn clone(&self) -> Self {
        Self { child_id: self.child_id.clone(), target: self.target.clone(), local_owner: self.local_owner.clone(), _snapshot: PhantomData }
    }
}

impl<S> semio_framework_schema_composition::ChildFieldRefs for ArtifactChild<S> {
    const MANY: bool = false;
    fn visit_child_field<'a, V: semio_framework_schema_composition::ChildRefVisitor<'a>>(&'a self, slot: &'static str, visitor: &mut V) -> Result<(), V::Error> {
        visitor.step()?;
        visitor.child(
            slot,
            semio_framework_schema_composition::ChildRefFields {
                child_id: &self.child_id,
                artifact_id: &self.target.artifact_id,
                artifact_kind: &self.target.dialect.artifact_kind,
                standard: &self.target.dialect.standard,
                subset: &self.target.dialect.subset,
            },
        )
    }
}

impl<S> std::fmt::Debug for ArtifactChild<S> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("ArtifactChild").field("child_id", &self.child_id).field("target", &self.target).finish()
    }
}

impl<S> PartialEq for ArtifactChild<S> {
    fn eq(&self, other: &Self) -> bool {
        self.child_id == other.child_id && self.target == other.target
    }
}

/// 🌉️ Hand-written, not derived: `ArtifactChild<S>`'s `local_owner`/`_snapshot` fields are
/// serialization-skipped (see the struct's own doc comment), a shape `#[derive(ToValue,
/// FromValue)]` does not support — mirrors the pre-existing `#[serde(skip)]` hand-treatment,
/// round-tripping only `child_id`/`target`.
impl<S> ToValue for ArtifactChild<S> {
    fn to_value(&self) -> DslValue {
        DslValue::object([("childId".to_string(), ToValue::to_value(&self.child_id)), ("target".to_string(), ToValue::to_value(&self.target))])
    }
    fn to_value_controlled(&self,control:&mut protocol::value::NativeEncodeControl<'_>)->Result<DslValue,ValueError>{
        control.scoped_depth(64,|control|control.scoped_stage(|control|{
            control.begin_stage(2)?;
            let mut fields=protocol::value::DecodedValue::new(control.allocate_vec::<(String,DslValue)>(2)?,|fields:Vec<(String,DslValue)>|{for(_,value)in fields{<DslValue as FromValue>::retire_decoded(value);}});
            let key=control.copy_text("childId")?;let child_id=ToValue::to_value_controlled(&self.child_id,control).map_err(|error|error.under("childId"))?;fields.get_mut().push((key,child_id));control.step()?;
            let key=control.copy_text("target")?;let target=ToValue::to_value_controlled(&self.target,control).map_err(|error|error.under("target"))?;fields.get_mut().push((key,target));control.step()?;
            Ok(DslValue::Object(fields.take()))
        }))
    }

}

impl<S> FromValue for ArtifactChild<S> {
    fn from_value(value: DslValue) -> Result<Self, ValueError> {
        let DslValue::Object(fields) = value else {
            return Err(ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue, format!("expected an object for ArtifactChild, found {value:?}")));
        };
        let mut child_id = None;
        let mut target = None;
        for (key, entry) in fields {
            match key.as_str() {
                "childId" => child_id = Some(String::from_value(entry).map_err(|e| e.under("childId"))?),
                "target" => target = Some(crate::os_io::ArtifactRef::from_value(entry).map_err(|e| e.under("target"))?),
                _ => return Err(ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue, format!("ArtifactChild has unknown field {key}"))),
            }
        }
        Ok(ArtifactChild { child_id: child_id.ok_or_else(|| ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue, "ArtifactChild missing childId"))?, target: target.ok_or_else(|| ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue, "ArtifactChild missing target"))?, local_owner: None, _snapshot: PhantomData })
    }
    fn from_value_controlled(value:&DslValue,control:&mut protocol::value::NativeDecodeControl<'_>)->Result<Self,ValueError>{
        let DslValue::Object(fields)=value else{return Err(ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue, "expected an object for ArtifactChild"))};
        control.scoped_depth(64,|control|control.scoped_stage(|control|{
            control.begin_stage(fields.len())?;
            let mut child_id=None;let mut target=None;
            for(key,entry)in fields{
                match key.as_str(){
                    "childId"=>child_id=Some(String::from_value_controlled(entry,control).map_err(|error|error.under("childId"))?),
                    "target"=>target=Some(crate::os_io::ArtifactRef::from_value_controlled(entry,control).map_err(|error|error.under("target"))?),
                    _=>return Err(ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue, "ArtifactChild has an unknown field")),
                }
                control.step()?;
            }
            control.checkpoint()?;
            Ok(Self{child_id:child_id.ok_or_else(||ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue, "ArtifactChild missing childId"))?,target:target.ok_or_else(||ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue, "ArtifactChild missing target"))?,local_owner:None,_snapshot:PhantomData})
        }))
    }

}

/// 🪪️ Type-erased projection of one `ArtifactChild<S>` field, dropping the compile-time-only
/// `S` phantom so `ArtifactRefs::child_refs` can return a single homogeneous `Vec` across however
/// many differently-`S`-typed child slots a snapshot declares.
#[derive(Clone, Debug, PartialEq, ToValue, FromValue)]
#[value(rename_all = "camelCase")]
pub struct ChildRef {
    pub slot: String,
    pub child_id: String,
    pub target: crate::os_io::ArtifactRef,
}

/// 📏️ Fixed restore admission bounds; sparse container walks consume their own step budget.
pub const CHILD_RESTORE_MAXIMUM_REFERENCES: usize = 64;
pub const CHILD_RESTORE_MAXIMUM_FIELD_BYTES: usize = 256;
pub const CHILD_RESTORE_MAXIMUM_VISIT_STEPS: usize = 256;

/// 🛑️ Exact loaded-parent projection failures, before opening or publishing any child store.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ChildRestoreProjectionError {
    InvalidSlot,
    InvalidReference,
    DuplicateChild,
    SingularSlot,
    ReferenceLimit,
    TraversalLimit,
    IncompleteSet,
}

impl std::fmt::Display for ChildRestoreProjectionError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(formatter, "child restore projection: {self:?}")
    }
}

impl std::error::Error for ChildRestoreProjectionError {}

/// 🌳️ Bounded borrowed authority derived only from the loaded parent's declared child fields.
#[derive(Debug)]
pub struct ChildRestoreProjection<'a> {
    slots: &'static [semio_framework_schema_composition::ChildSlotSpec],
    rows: [Option<(&'static str, semio_framework_schema_composition::ChildRefFields<'a>)>; CHILD_RESTORE_MAXIMUM_REFERENCES],
    length: usize,
    steps: usize,
}

impl<'a> ChildRestoreProjection<'a> {
    /// 🔎️ Visits actual typed snapshot fields without cloning handles, leases or child content.
    pub fn from_snapshot<S: semio_framework_schema_composition::ArtifactCompositionFields>(snapshot: &'a S) -> Result<Self, ChildRestoreProjectionError> {
        let slots = S::child_slots();
        if slots.len() > CHILD_RESTORE_MAXIMUM_REFERENCES {
            return Err(ChildRestoreProjectionError::ReferenceLimit);
        }
        for (index, slot) in slots.iter().enumerate() {
            if slot.name.is_empty()
                || slot.name.len() > CHILD_RESTORE_MAXIMUM_FIELD_BYTES
                || slot.kind.len() > CHILD_RESTORE_MAXIMUM_FIELD_BYTES
                || !crate::os_io::is_canonical_artifact_kind(slot.kind)
                || slots[..index].iter().any(|prior| prior.name == slot.name)
            {
                return Err(ChildRestoreProjectionError::InvalidSlot);
            }
        }
        let mut projection = Self { slots, rows: [None; CHILD_RESTORE_MAXIMUM_REFERENCES], length: 0, steps: 0 };
        snapshot.visit_child_refs(&mut projection)?;
        Ok(projection)
    }

    /// 🧮️ Number of exact child references carried by this loaded parent.
    pub fn len(&self) -> usize {
        self.length
    }

    /// 🍃️ Whether this projection has no populated child fields.
    pub fn is_empty(&self) -> bool {
        self.length == 0
    }

    /// 🌿️ Reads one admitted typed child row without copying handles or payload owners.
    pub fn get(&self, index: usize) -> Option<(&'static str, semio_framework_schema_composition::ChildRefFields<'a>)> {
        self.rows.get(index).copied().flatten()
    }

    /// 🪪️ Checks one member against the actual loaded parent, without treating it as a full batch.
    pub fn admits_member(&self, slot: &str, expected: &crate::os_io::ArtifactRef) -> bool {
        self.rows[..self.length].iter().flatten().any(|(name, fields)| {
            *name == slot
                && fields.artifact_id == expected.artifact_id
                && fields.artifact_kind == expected.dialect.artifact_kind
                && fields.standard == expected.dialect.standard
                && fields.subset == expected.dialect.subset
        })
    }

    /// ⚖️ Admits exactly one unordered complete set: no omission, substitution or duplicate.
    pub fn admit_complete<'b>(&self, incoming: impl IntoIterator<Item = (&'b str, semio_framework_schema_composition::ChildRefFields<'b>)>) -> Result<(), ChildRestoreProjectionError> {
        let mut seen = [false; CHILD_RESTORE_MAXIMUM_REFERENCES];
        let mut count = 0;
        for (slot, fields) in incoming {
            if count == CHILD_RESTORE_MAXIMUM_REFERENCES {
                return Err(ChildRestoreProjectionError::ReferenceLimit);
            }
            let index = self.rows[..self.length].iter().position(|entry| entry.as_ref().is_some_and(|(name, expected)| *name == slot && *expected == fields)).ok_or(ChildRestoreProjectionError::IncompleteSet)?;
            if seen[index] {
                return Err(ChildRestoreProjectionError::DuplicateChild);
            }
            seen[index] = true;
            count += 1;
        }
        if count != self.length {
            return Err(ChildRestoreProjectionError::IncompleteSet);
        }
        Ok(())
    }
}

impl<'a> semio_framework_schema_composition::ChildRefVisitor<'a> for ChildRestoreProjection<'a> {
    type Error = ChildRestoreProjectionError;
    fn step(&mut self) -> Result<(), Self::Error> {
        if self.steps == CHILD_RESTORE_MAXIMUM_VISIT_STEPS {
            return Err(Self::Error::TraversalLimit);
        }
        self.steps += 1;
        Ok(())
    }
    fn child(&mut self, slot: &'static str, fields: semio_framework_schema_composition::ChildRefFields<'a>) -> Result<(), Self::Error> {
        if self.length == CHILD_RESTORE_MAXIMUM_REFERENCES {
            return Err(Self::Error::ReferenceLimit);
        }
        let spec = self.slots.iter().find(|spec| spec.name == slot).ok_or(Self::Error::InvalidSlot)?;
        if fields.artifact_kind != spec.kind
            || [fields.child_id, fields.artifact_id, fields.artifact_kind, fields.standard, fields.subset].iter().any(|field| field.is_empty() || field.len() > CHILD_RESTORE_MAXIMUM_FIELD_BYTES)
        {
            return Err(Self::Error::InvalidReference);
        }
        for (name, prior) in self.rows[..self.length].iter().flatten() {
            if prior.child_id == fields.child_id {
                return Err(Self::Error::DuplicateChild);
            }
            if *name == slot && !spec.many {
                return Err(Self::Error::SingularSlot);
            }
        }
        self.rows[self.length] = Some((slot, fields));
        self.length += 1;
        Ok(())
    }
}

/// 🏠️ The ownership stamp placed on the CHILD's own `ArtifactEnvelope.owner` (not only on
/// the parent's `ArtifactChild` handle), so ownership is queryable directly from the child side —
/// e.g. "is this document embeddable standalone, or does deleting it require going through its
/// owner". `child_id` matches the owning `ArtifactChild<S>.child_id`/`ChildRef.child_id` exactly.
#[path = "🪆️child/🏠️owner/🧬️schema/🦀️.rs"]
mod artifact_child_owner_schema;
pub use artifact_child_owner_schema::OwnerRef;

#[path = "🔗️link/🧬️schema/🦀️.rs"]
mod artifact_link_schema;
pub use artifact_link_schema::{ArtifactLink, LinkPin};

/// 🌳️ Lets a snapshot type declare its own composed children / referenced links. Both
/// methods default to empty, so a leaf artifact (the overwhelming majority) needs zero
/// boilerplate — only a technology that actually embeds `ArtifactChild<S>`/`ArtifactLink` fields
/// overrides them (typically derive-generated in a later wave, per the design doc's
/// `ChildSlotSpec`/`LinkSlotSpec` schema facets).
pub trait ArtifactRefs {
    async fn child_refs(&self) -> Vec<ChildRef> {
        Vec::new()
    }
    async fn links(&self) -> Vec<ArtifactLink> {
        Vec::new()
    }
}

/// 🔎️ What resolving one `ArtifactLink` found: the target materialized as real bytes, that
/// it is simply absent, or (for a `LinkPin::Snapshot`) only the escrowed blob reference is known
/// without the resolver having fetched its bytes yet.
#[derive(Clone, Debug, PartialEq)]
pub enum LinkState {
    Resolved { pack_bytes: Vec<u8>, dialect: crate::os_io::ArtifactDialect },
    Missing,
    PinnedOnly { blob: BlobRef },
}

/// 🕵️ Host-side, LAZY link resolution — never called during `CompositionCoordinator`
/// dispatch (links have no bearing on group-atomicity: unlike a child, a link's target is not part
/// of this artifact's own document and dispatch never touches it). A UI/renderer calls this only
/// when it actually needs to show/open the linked content.
pub trait LinkResolver {
    async fn resolve(&self, link: &ArtifactLink) -> LinkState;
}

/// 🗂️ The read-only directory a `MemberLinkResolver` resolves against — whatever holds the
/// live members (a `SpaceHost`, or a test fixture). Returns owned PACK bytes rather than a
/// `&dyn SpaceMember` so the resolver can be OWNED and stored (a borrowed member reference could
/// never live in a long-lived host field), and `Option<Result<..>>` distinguishes "no such member"
/// (→ `LinkState::Missing`) from "member exists but reading it failed" (→ a real error, never
/// silently reported as absent).
pub trait MemberDirectory {
    async fn head_pack(&self, artifact_id: &str) -> Option<Result<Vec<u8>, VcsError>>;
    async fn checkpoint_pack(&self, artifact_id: &str, checkpoint_id: &str) -> Option<Result<Vec<u8>, VcsError>>;
}

impl MemberDirectory for SpaceHost {
    async fn head_pack(&self, artifact_id: &str) -> Option<Result<Vec<u8>, VcsError>> {
        match self.member(artifact_id).await {
            Some(member) => Some(member.document_pack_bytes().await),
            None => None,
        }
    }

    async fn checkpoint_pack(&self, artifact_id: &str, checkpoint_id: &str) -> Option<Result<Vec<u8>, VcsError>> {
        match self.member(artifact_id).await {
            Some(member) => Some(member.pack_at_checkpoint(checkpoint_id).await),
            None => None,
        }
    }
}

/// 🕵️ The one production `LinkResolver`: resolves each `LinkPin` against a `MemberDirectory`
/// (plus an optional `BlobStore` for escrowed snapshot pins). This is what makes "referenced
/// artifacts with their own version history" real — `Head` reads the target's live tip, while
/// `Checkpoint` reads the target's content AS OF that checkpoint, so a pinned reference keeps
/// showing what it was pinned to no matter how far the target has since moved.
///
/// A `Snapshot` pin with no blob store, or whose bytes are not in the store, degrades to
/// `PinnedOnly` — the blob reference is still known and displayable (a chip can render "pinned to
/// <hash>" without the content), which is precisely the state `LinkState::PinnedOnly` exists for.
/// A read error is never laundered into `Missing`: absence and failure are different answers, and
/// only absence is benign.
/// 🕳️ The default `B` for a `MemberLinkResolver` that carries no blob escrow — uninhabited,
/// same stand-in shape as `BackboneChannelPorts`/`NoMembers`, so `MemberLinkResolver::new` never
/// needs its caller to name a concrete `BlobStore` implementor it isn't using.
pub enum NoBlobStore {}

impl BlobStore for NoBlobStore {
    async fn put(&self, _bytes: &[u8], _media_type: &str) -> Result<BlobRef, VcsError> {
        match *self {}
    }

    async fn get(&self, _hash: &str) -> Result<Option<Vec<u8>>, VcsError> {
        match *self {}
    }

    async fn has(&self, _hash: &str) -> Result<bool, VcsError> {
        match *self {}
    }

    async fn delete(&self, _hash: &str) -> Result<(), VcsError> {
        match *self {}
    }
}

pub struct MemberLinkResolver<D, B = NoBlobStore> {
    directory: D,
    blobs: Option<Arc<B>>,
}

impl<D: MemberDirectory> MemberLinkResolver<D, NoBlobStore> {
    /// 🏗️ Resolver without blob escrow — `LinkPin::Snapshot` always degrades to `PinnedOnly`.
    pub async fn new(directory: D) -> Self {
        Self { directory, blobs: None }
    }
}

impl<D: MemberDirectory, B: BlobStore> MemberLinkResolver<D, B> {
    /// 🏗️ Resolver that can also materialize content-addressed `LinkPin::Snapshot` blobs.
    pub async fn with_blobs(directory: D, blobs: Arc<B>) -> Self {
        Self { directory, blobs: Some(blobs) }
    }
}

impl<D: MemberDirectory, B: BlobStore> LinkResolver for MemberLinkResolver<D, B> {
    async fn resolve(&self, link: &ArtifactLink) -> LinkState {
        let dialect = link.target.dialect.clone();
        match &link.pin {
            LinkPin::Head => match self.directory.head_pack(&link.target.artifact_id).await {
                Some(Ok(pack_bytes)) => LinkState::Resolved { pack_bytes, dialect },
                Some(Err(_)) | None => LinkState::Missing,
            },
            LinkPin::Checkpoint { id } => match self.directory.checkpoint_pack(&link.target.artifact_id, id).await {
                Some(Ok(pack_bytes)) => LinkState::Resolved { pack_bytes, dialect },
                Some(Err(_)) | None => LinkState::Missing,
            },
            LinkPin::Snapshot { blob } => {
                let resolved = match &self.blobs {
                    Some(blobs) => blobs.get(&blob.hash).await.ok().flatten(),
                    None => None,
                };
                match resolved {
                    Some(pack_bytes) => LinkState::Resolved { pack_bytes, dialect },
                    None => LinkState::PinnedOnly { blob: blob.clone() },
                }
            }
        }
    }
}

/// 🏭️ Generic genesis-construction helper every `space_members!`-generated `MemberFactory::
/// create` arm calls — the composition sibling of `ArtifactCodec`/`register_document_codec` above.
/// Bakes a brand-new child store from a freshly-baked initial pack (composition genesis, see
/// `CompositionCoordinator::dispatch_group`): `initial_pack` decoded as `P` (empty rejected — a
/// genesis caller always has an initial snapshot, and silently substituting `P::default()` would
/// mint a child whose content nobody chose), stamped with `dialect`. Replaces the old
/// `ChildStoreFactory`/`TypedChildStoreFactory` object-erased pair (O1 — a global `Arc<dyn
/// ChildStoreFactory>` registry keyed by runtime kind string is exactly the dyn-dispatched seam the
/// program drops): the registry's kind-keying now lives in the generated enum's own `match kind`.
pub async fn create_member_store<P, Mutation>(schema: &str, id: &str, dialect: &crate::os_io::ArtifactDialect, initial_pack: &[u8]) -> Result<ArtifactStore<P, Mutation>, VcsError>
where
    P: Clone + ToValue + FromValue + ArtifactPack + MemberStoreOwner<Mutation> + Send + 'static,
    Mutation: Clone + ToValue + FromValue + self::Mutation<P> + OpBinary + OpText + Send + 'static,
{
    if initial_pack.is_empty() {
        return Err(VcsError::Deserialize(format!("child genesis for {id} carries an empty initial pack")));
    }
    let initial = P::decode_pack(initial_pack).map_err(|error| VcsError::Deserialize(error.to_string()))?;
    let mut envelope = create_document_envelope::<P, Mutation>(schema, id, initial, None);
    envelope.dialect = Some(dialect.clone());
    let mut store = ArtifactStore::new(envelope).await?;
    store.install_document_store_owners_exact(P::member_store_owners());
    Ok(store)
}

/// 🏭️ Generic reload helper every `space_members!`-generated `MemberFactory::open` arm
/// calls — reconstructs a previously-persisted child from its full envelope pack via the same
/// `parse_document_pack` → `reset(envelope, applied, redo)` path `apply_ops_binary` uses, so a
/// reloaded child restores its exact undo/redo cursor position, not merely its content. The
/// invariant is `owner.is_some() ⇒ dialect.is_some()` — every envelope that is somebody's child
/// knows which dialect it materializes as, which is what lets `ArtifactView.children` type a child
/// without consulting the parent.
pub async fn open_member_store<P, Mutation>(schema: &str, expected: &crate::os_io::ArtifactRef, owner: Option<&OwnerRef>, envelope_pack: &[u8]) -> Result<ArtifactStore<P, Mutation>, VcsError>
where
    P: Clone + ToValue + FromValue + ArtifactPack + MemberStoreOwner<Mutation> + Send + 'static,
    Mutation: Clone + ToValue + FromValue + self::Mutation<P> + OpBinary + OpText + Send + 'static,
{
    if owner.is_some_and(|owner| owner.child_id != expected.artifact_id) {
        return Err(VcsError::Deserialize("member owner child identity does not match requested artifact".into()));
    }
    let (pack, spr) = decode_document_pack_bytes(envelope_pack).await?;
    let history = crate::os_spr::decode_history(&spr, &crate::os_spr::DecodeOptions::default()).await.map_err(|error| VcsError::Deserialize(error.to_string()))?;
    validate_member_history_identity(&history, schema, expected, owner)?;
    let parsed = parse_decoded_document_spr::<P, Mutation>(&pack, history).await.map_err(|error| VcsError::Deserialize(error.to_string()))?;
    let mut store = ArtifactStore::new(parsed.envelope).await?;
    store.install_document_store_owners_exact(P::member_store_owners());
    Ok(store)
}

fn validate_member_history_identity(history: &crate::os_spr::HistoryLog, schema: &str, expected: &crate::os_io::ArtifactRef, owner: Option<&OwnerRef>) -> Result<(), VcsError> {
    let persisted_dialect = history.composition.as_ref().and_then(|composition| composition.dialect.as_ref());
    let dialect_matches = persisted_dialect.is_some_and(|(kind, standard, subset)| kind == &expected.dialect.artifact_kind && standard == &expected.dialect.standard && subset == &expected.dialect.subset);
    let persisted_owner = history.composition.as_ref().and_then(|composition| composition.owner.as_ref());
    let owner_matches = match (persisted_owner, owner) {
        (None, None) => true,
        (Some((parent, slot, child_id)), Some(owner)) => slot == &owner.slot && child_id == &owner.child_id && child_id == &expected.artifact_id && crate::os_io::ArtifactRef::parse_uri(parent).is_ok_and(|parent| parent == owner.parent),
        _ => false,
    };
    if history.doc_id != expected.artifact_id || history.schema != schema || !dialect_matches || !owner_matches {
        return Err(VcsError::Deserialize("member envelope does not match requested identity, schema, dialect and ownership".into()));
    }
    Ok(())
}

//#region 🔖️CompositionDsl
/// 🧬️ Hand-crafted `crate::os_dsl::DslField` records for `ArtifactChild`/`OwnerRef`/`ArtifactLink`/
/// `LinkPin` (P6 idiom, the same one `BackboneMessage`'s `OpText`/`OpBinary` impls near
/// `🔖️Backbone` below use) — NOT new `Shape` variants: the design doc's deviation D1 deliberately
/// keeps `Shape` closed (it is exhaustively matched in ~20 files) and represents every new value
/// type here as an ordinary `Shape::Record`. Targets use the canonical literal
/// `crate::os_io::ArtifactRef` record so each owned reference component remains independent.
// 🚫️async: E4 fn-pointer slot — value stored in `Shape::Record(fn() -> RecordSpec)`
fn artifact_child_spec() -> crate::os_dsl::RecordSpec {
    crate::os_dsl::RecordSpec::new(None, crate::os_dsl::RecordLayout::Inline, vec![crate::os_dsl::FieldSpec::new(0, "child_id", crate::os_dsl::Shape::Text), crate::os_dsl::FieldSpec::new(1, "target", <crate::os_io::ArtifactRef as crate::os_dsl::DslField>::shape())])
}

fn artifact_child_spec_controlled<C:crate::os_dsl::NativeSchemaControl>(control:&mut C)->Result<crate::os_dsl::RecordSpec,semio_framework_value::ValueError>{
    control.scoped_stage(|control|{
        control.begin_stage(2)?;let mut fields=control.allocate_vec::<crate::os_dsl::FieldSpec>(2)?;
        fields.push(crate::os_dsl::schema::producer::field(0,"child_id",crate::os_dsl::Shape::Text,control)?);control.step()?;
        let target=<crate::os_io::ArtifactRef as crate::os_dsl::DslField>::shape_controlled(control)?;
        fields.push(crate::os_dsl::schema::producer::field(1,"target",target,control)?);control.step()?;
        crate::os_dsl::schema::producer::record(None,crate::os_dsl::RecordLayout::Inline,fields,control)
    })
}

fn artifact_child_spec_producer()->crate::os_dsl::RecordSpecProducer{
    crate::os_dsl::RecordSpecProducer{ordinary:artifact_child_spec,decoding:|control|artifact_child_spec_controlled(control),encoding:|control|artifact_child_spec_controlled(control)}
}

// 🚫️async: E1 pure — record conversion with no suspension point, consumed by the sync
// `DslField::to_value` impl below. See R9.
fn artifact_child_to_record<S>(child: &ArtifactChild<S>) -> crate::os_dsl::RecordValue {
    let mut record = crate::os_dsl::RecordValue::default();
    record.fields.insert(0, crate::os_dsl::FieldValue::Text(child.child_id.clone()));
    record.fields.insert(1, <crate::os_io::ArtifactRef as crate::os_dsl::DslField>::to_value(&child.target));
    record
}

// 🚫️async: E1 pure — same sync consumer as `artifact_child_to_record`. See R9.
/// 🧱️ Constructs the persisted child identity and literal target without a local owner.
fn artifact_child_from_record<S>(record: &crate::os_dsl::RecordValue) -> Result<ArtifactChild<S>, String> {
    if record.fields.len()!=2||record.fields.keys().any(|id|*id>1){return Err("artifact child requires its two literal fields".into());}
    let child_id = match record.get(0) {
        Some(crate::os_dsl::FieldValue::Text(s)) => s.clone(),
        other => return Err(format!("expected child_id, found {other:?}")),
    };
    let target=<crate::os_io::ArtifactRef as crate::os_dsl::DslField>::from_value(record.get(1).ok_or("missing artifact child target")?)?;
    Ok(ArtifactChild { child_id, target, local_owner: None, _snapshot: PhantomData })
}

impl<S> crate::os_dsl::DslField for ArtifactChild<S> {
    /// 🚫️async: E4 — see `DslField::shape`'s tag on the trait.
    fn shape() -> crate::os_dsl::Shape {
        crate::os_dsl::Shape::Record(artifact_child_spec_producer())
    }
    fn shape_controlled<C:crate::os_dsl::NativeSchemaControl>(control:&mut C)->Result<crate::os_dsl::Shape,semio_framework_value::ValueError>{control.checkpoint()?;Ok(crate::os_dsl::Shape::Record(artifact_child_spec_producer()))}
    fn to_value(&self) -> crate::os_dsl::FieldValue {
        crate::os_dsl::FieldValue::Record(artifact_child_to_record(self))
    }
    fn to_value_controlled(&self,control:&mut crate::os_dsl::NativeEncodeControl<'_>)->Result<crate::os_dsl::FieldValue,semio_framework_value::ValueError>{
        <Self as crate::os_dsl::DslField>::to_record_controlled(self,control).map(crate::os_dsl::FieldValue::Record)
    }
    fn to_record_controlled(&self,control:&mut crate::os_dsl::NativeEncodeControl<'_>)->Result<crate::os_dsl::RecordValue,semio_framework_value::ValueError>{
        control.scoped_depth(64,|control|control.scoped_stage(|control|{
            control.begin_stage(2)?;let mut record=crate::os_dsl::native_encoding::EncodedRecord::new(2,control)?;
            record.insert(0,crate::os_dsl::FieldValue::Text(control.copy_text(&self.child_id)?))?;control.step()?;
            record.insert(1,<crate::os_io::ArtifactRef as crate::os_dsl::DslField>::to_value_controlled(&self.target,control)?)?;control.step()?;
            Ok(record.take())
        }))
    }

    fn from_value(value: &crate::os_dsl::FieldValue) -> Result<Self, String> {
        match value {
            crate::os_dsl::FieldValue::Record(record) => artifact_child_from_record(record),
            other => Err(format!("expected Record, found {other:?}")),
        }
    }    fn from_value_controlled(value:&crate::os_dsl::FieldValue,control:&mut crate::os_dsl::NativeDecodeControl<'_>)->Result<Self,semio_framework_value::ValueError>{
        let crate::os_dsl::FieldValue::Record(record)=value else{return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"expected artifact child Record"));};
        Self::from_record_controlled(record,control)
    }
    fn from_record_controlled(record:&crate::os_dsl::RecordValue,control:&mut crate::os_dsl::NativeDecodeControl<'_>)->Result<Self,semio_framework_value::ValueError>{
        control.scoped_stage(|control|{
            control.begin_stage(2)?;
            if record.fields.len()!=2||record.fields.keys().any(|id|*id>1){return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"artifact child requires its two literal fields"));}
            let Some(crate::os_dsl::FieldValue::Text(child_id))=record.get(0) else{return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"expected artifact child identity Text"));};
            let target=record.get(1).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"missing artifact child target"))?;
            let child_id=control.copy_text(child_id)?;control.step()?;
            let target=<crate::os_io::ArtifactRef as crate::os_dsl::DslField>::from_value_controlled(target,control)?;control.step()?;
            Ok(Self{child_id,target,local_owner:None,_snapshot:PhantomData})
        })
    }

}

