#[derive(Clone)]
struct CursorRevisionRecord {
    id_digest: [u8; 32],
    edit_digest: [u8; 32],
    prefix_digest: [u8; 32],
}

#[derive(Clone)]
struct CursorRevisionAccumulator {
    identity_digest: [u8; 32],
    applied: crate::os_vcs::HistoryPageStack<CursorRevisionRecord>,
    redo: crate::os_vcs::HistoryPageStack<CursorRevisionRecord>,
    applied_tail_chains: Option<([u8; 32], EditDigestChains)>,
}

/// 📍️ The first applied and redo positions whose ids changed since [`ArtifactStore::bump`] last mirrored both stacks into the
/// persisted cursor and the revision records — what keeps both mirrors O(change) per mutation. `usize::MAX` is clean.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct StackMirrorDirt {
    applied: usize,
    redo: usize,
}

impl StackMirrorDirt {
    const CLEAN: Self = Self { applied: usize::MAX, redo: usize::MAX };
    const ALL: Self = Self { applied: 0, redo: 0 };
}

/// 🧮️ Test-only census of whole-history work on the mutation path: full folds of the event log, edits hashed for prefix
/// digests, ids mirrored into the persisted cursor and revision records rebuilt — what the O(change) laws count.
#[cfg(test)]
pub(crate) mod hot_path_census {
    thread_local! {
        static CENSUS: std::cell::Cell<HotPathCensus> = const { std::cell::Cell::new(HotPathCensus { folds: 0, digested: 0, mirrored: 0, rebuilt: 0 }) };
    }

    /// 📊️ Counts since the thread's last [`take`].
    #[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
    pub struct HotPathCensus {
        pub folds: usize,
        pub digested: usize,
        pub mirrored: usize,
        pub rebuilt: usize,
    }

    pub(crate) fn count(update: impl FnOnce(&mut HotPathCensus)) {
        CENSUS.with(|census| {
            let mut next = census.get();
            update(&mut next);
            census.set(next);
        });
    }

    /// 🧾️ The counts so far, resetting them.
    pub fn take() -> HotPathCensus {
        CENSUS.with(|census| census.replace(HotPathCensus::default()))
    }
}

/// 🔬️ Histories up to this many applied edits re-derive every incremental mirror from scratch after each test-build bump.
#[cfg(test)]
const MIRROR_ORACLE_HISTORY: usize = 256;

/// 🔗️ Running per-list digests of a coalesced edit's operations: what lets an amend extend its edit's revision identity by
/// the operations it appended instead of re-encoding the whole run (a typing run amends one edit per key).
#[derive(Clone, Copy, Default)]
struct EditDigestChains {
    forwards: usize,
    inverse: usize,
    meta: usize,
    forwards_digest: [u8; 32],
    inverse_digest: [u8; 32],
    meta_digest: [u8; 32],
}

impl EditDigestChains {
    /// 🔗️ The chains over every operation of `edit`, continued from these; `None` when `edit` is not an extension of the lists
    /// these were taken over (a list shrank).
    fn extended<Mutation: ToValue>(mut self, edit: &Edit<Mutation>) -> Option<Self> {
        if self.forwards > edit.forwards.len() || self.inverse > edit.inverse.len() || self.meta > edit.mutation_meta.len() {
            return None;
        }
        for operation in &edit.forwards[self.forwards..] {
            self.forwards_digest = CursorRevisionAccumulator::hash_record(b"edit-forward", &[&self.forwards_digest, semio_framework_pack_json::to_json_string(operation).as_bytes()]);
        }
        for operation in &edit.inverse[self.inverse..] {
            self.inverse_digest = CursorRevisionAccumulator::hash_record(b"edit-inverse", &[&self.inverse_digest, semio_framework_pack_json::to_json_string(operation).as_bytes()]);
        }
        for meta in &edit.mutation_meta[self.meta..] {
            self.meta_digest = CursorRevisionAccumulator::hash_record(b"edit-meta", &[&self.meta_digest, semio_framework_pack_json::to_json_string(meta).as_bytes()]);
        }
        self.forwards = edit.forwards.len();
        self.inverse = edit.inverse.len();
        self.meta = edit.mutation_meta.len();
        Some(self)
    }
}

/// 🧮️ Domain-neutral incremental digest for retained store initialization. A
/// caller observes at most one already-admitted field/page per job step and never materializes a
/// serialized document or edit merely to derive revision identity.
pub struct ArtifactStoreInitializationDigest {
    lanes: [u64; 4],
    bytes: u64,
}

impl ArtifactStoreInitializationDigest {
    pub fn new(domain: &[u8]) -> Self {
        let mut digest = Self { lanes: [0xcbf2_9ce4_8422_2325, 0x9e37_79b9_7f4a_7c15, 0x6a09_e667_f3bc_c909, 0xbb67_ae85_84ca_a73b], bytes: 0 };
        digest.observe(domain);
        digest
    }

    pub fn observe(&mut self, bytes: &[u8]) {
        for (offset, byte) in bytes.iter().copied().enumerate() {
            let lane = (self.bytes as usize + offset) & 3;
            self.lanes[lane] ^= u64::from(byte);
            self.lanes[lane] = self.lanes[lane].wrapping_mul(0x0000_0100_0000_01b3).rotate_left((lane as u32 + 1) * 7);
        }
        self.bytes = self.bytes.checked_add(bytes.len() as u64).expect("pre-admitted initialization byte credits cannot overflow u64");
    }

    pub fn finish(self) -> [u8; 32] {
        let mut output = [0; 32];
        for (index, lane) in self.lanes.into_iter().enumerate() {
            output[index * 8..(index + 1) * 8].copy_from_slice(&lane.wrapping_add(self.bytes.rotate_left(index as u32 * 11)).to_be_bytes());
        }
        output
    }
}

/// 🗂️ The edit ids of an envelope a retained initializer validates, admitted one edit per job step ([`Self::admit`]) and
/// found in O(1) ([`Self::position`]): the one mechanism that keeps every store initializer's duplicate check and its
/// applied and redo lookups linear in the history.
#[derive(Debug, Default)]
pub struct ArtifactStoreInitializationEditIndex {
    positions: HashMap<String, usize>,
}

/// 🪜️ What admitting one edit to an [`ArtifactStoreInitializationEditIndex`] found.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ArtifactStoreInitializationEditAdmission {
    Admitted,
    Complete,
    Oversized,
    Duplicate,
}

impl ArtifactStoreInitializationEditIndex {
    /// ➕️ Admits the edit at `position` of `edits`: `Complete` once no edit is left, `Oversized` when its id is longer than
    /// `max_id_bytes`, `Duplicate` when it repeats an admitted edit's id.
    pub fn admit<Mutation>(&mut self, edits: &ArtifactHistoryLedger<Edit<Mutation>>, position: usize, max_id_bytes: usize) -> ArtifactStoreInitializationEditAdmission {
        match edits.get(position) {
            None => ArtifactStoreInitializationEditAdmission::Complete,
            Some(edit) if edit.id.len() > max_id_bytes => ArtifactStoreInitializationEditAdmission::Oversized,
            Some(edit) if self.positions.insert(edit.id.clone(), position).is_some() => ArtifactStoreInitializationEditAdmission::Duplicate,
            Some(_) => ArtifactStoreInitializationEditAdmission::Admitted,
        }
    }

    /// 🔎️ The ledger position of the admitted edit `edit_id`.
    pub fn position(&self, edit_id: &str) -> Option<usize> {
        self.positions.get(edit_id).copied()
    }

    /// 🧹️ Forgets every admitted id once the applied and redo lookups are done.
    pub fn clear(&mut self) {
        self.positions = HashMap::new();
    }
}

impl CursorRevisionAccumulator {
    fn hash_record(domain: &[u8], parts: &[&[u8]]) -> [u8; 32] {
        let mut digest = semio_framework_hash::Sha256::new();
        digest.update(b"semio.artifact.cursor.v2");
        digest.update(&(domain.len() as u64).to_be_bytes());
        digest.update(domain);
        for part in parts {
            digest.update(&(part.len() as u64).to_be_bytes());
            digest.update(part);
        }
        digest.finalize()
    }

    fn new<P, Mutation>(envelope: &ArtifactEnvelope<P, Mutation>, initial_digest: [u8; 32]) -> Self {
        let identity_digest = Self::hash_record(b"initial", &[envelope.id.as_bytes(), envelope.schema.as_bytes(), &initial_digest]);
        Self { identity_digest, applied: crate::os_vcs::HistoryPageStack::new(), redo: crate::os_vcs::HistoryPageStack::new(), applied_tail_chains: None }
    }

    /// 🔏️ Revision identity of one edit — a pure function of the edit. A single-operation edit hashes its canonical JSON
    /// (exactly what the one-item byte sealer streams); a coalesced edit that grew past one operation hashes its header
    /// fields and one running chain per operation list ([`EditDigestChains`]), which an amend extends in O(appended).
    fn edit_digest<Mutation: ToValue>(edit: &Edit<Mutation>) -> [u8; 32] {
        Self::edit_digest_extending(edit, None).0
    }

    /// 🔏️ [`Self::edit_digest`], continuing `known` chains when the edit only grew since they were taken (an amend).
    fn edit_digest_extending<Mutation: ToValue>(edit: &Edit<Mutation>, known: Option<EditDigestChains>) -> ([u8; 32], Option<EditDigestChains>) {
        if edit.forwards.len() <= 1 {
            let encoded = semio_framework_pack_json::to_json_string(edit).into_bytes();
            return (Self::hash_record(b"edit", &[edit.id.as_bytes(), &encoded]), None);
        }
        let chains = known.and_then(|chains| chains.extended(edit)).unwrap_or_else(|| EditDigestChains::default().extended(edit).expect("empty chains extend every edit"));
        let tag = |value: Option<&String>| [u8::from(value.is_some())];
        let digest = Self::hash_record(
            b"edit-chained",
            &[
                edit.id.as_bytes(),
                &tag(edit.actor.as_ref()),
                edit.actor.as_deref().unwrap_or_default().as_bytes(),
                &tag(edit.description.as_ref()),
                edit.description.as_deref().unwrap_or_default().as_bytes(),
                &edit.sequence_number.to_be_bytes(),
                edit.started_at.as_bytes(),
                &tag(edit.finished_at.as_ref()),
                edit.finished_at.as_deref().unwrap_or_default().as_bytes(),
                &(chains.forwards as u64).to_be_bytes(),
                &chains.forwards_digest,
                &(chains.inverse as u64).to_be_bytes(),
                &chains.inverse_digest,
                &(chains.meta as u64).to_be_bytes(),
                &chains.meta_digest,
            ],
        );
        let digest = match edit.verb.as_deref() {
            Some(verb) => Self::hash_record(b"edit-verb", &[&digest, verb.as_bytes()]),
            None => digest,
        };
        let digest = Self::hash_record(b"edit-line", &[&digest, &[u8::from(edit.line.is_some())], edit.line.as_deref().unwrap_or("").as_bytes()]);
        (digest, Some(chains))
    }

    /// 🧮️ Re-derives one cursor stack's records for `ids`, keeping the common prefix. `tail_chains` carries the running
    /// chains of the stack's tail edit between calls, so the amend case (same ids, tail grew) costs O(appended operations).
    /// 🔏️ `digest` of `edit` extended by the digest of the supersessions in effect for its operations: a revision names
    /// the effective forwards, not only the recorded ones.
    fn effective_edit_digest<P, Mutation: self::Mutation<P>>(edit: &Edit<Mutation>, digest: [u8; 32], supersessions: &EffectiveSupersessions) -> [u8; 32] {
        match edit_supersession_digest::<P, Mutation>(edit, supersessions) {
            Some(superseded) => Self::hash_record(b"edit-superseded", &[&digest, &superseded]),
            None => digest,
        }
    }

    /// 🧮️ Rebuilds the records of `ids` from the first position whose id changed (`dirty`, [`StackMirrorDirt`]) and keeps
    /// the common prefix untouched; a tail edit that only grew (an amend) regrows its one record. `dirty_from` names the
    /// first position a replay rewrote (effective input, inverse or messages): records from there on are rebuilt even where
    /// the ids still match. Answers the position of a regrown tail record.
    #[allow(clippy::too_many_arguments)]
    fn reconcile_stack<P, Mutation: ToValue + self::Mutation<P>>(
        records: &mut crate::os_vcs::HistoryPageStack<CursorRevisionRecord>,
        ids: &crate::os_vcs::HistoryPageStack<String>,
        edits: &ArtifactHistoryLedger<Edit<Mutation>>,
        domain: &[u8],
        identity_digest: [u8; 32],
        tail_chains: &mut Option<([u8; 32], EditDigestChains)>,
        supersessions: &EffectiveSupersessions,
        dirty: usize,
        dirty_from: Option<usize>,
    ) -> Option<usize> {
        let mut common = records.len().min(ids.len()).min(dirty);
        if let Some(dirty_from) = dirty_from {
            common = common.min(dirty_from);
            if common < records.len() {
                *tail_chains = None;
            }
        }
        while records.len() > common {
            records.pop().expect("revision suffix record remains present");
        }
        let mut regrown = None;
        if common == ids.len() && common != 0 {
            let id = &ids[common - 1];
            let edit = edits.find_near(|edit| edit.id == *id).expect("validated cursor edit exists");
            let known = tail_chains.filter(|(id_digest, _)| *id_digest == records[common - 1].id_digest).map(|(_, chains)| chains);
            let (edit_digest, chains) = Self::edit_digest_extending(edit, known);
            let edit_digest = Self::effective_edit_digest::<P, Mutation>(edit, edit_digest, supersessions);
            *tail_chains = chains.map(|chains| (records[common - 1].id_digest, chains));
            if records[common - 1].edit_digest != edit_digest {
                records.pop().expect("validated revision record remains present");
                common -= 1;
                regrown = Some(edit_digest);
            }
        }
        let regrown_at = regrown.is_some().then_some(common);
        #[cfg(test)]
        hot_path_census::count(|census| census.rebuilt += ids.len() - common);
        for id in ids.iter_from(common) {
            let id_digest = Self::hash_record(b"edit-id", &[id.as_bytes()]);
            let edit_digest = match regrown.take() {
                Some(edit_digest) => edit_digest,
                None => {
                    let edit = edits.find_near(|edit| edit.id == *id).expect("validated cursor edit exists");
                    let (edit_digest, chains) = Self::edit_digest_extending(edit, None);
                    *tail_chains = chains.map(|chains| (id_digest, chains));
                    Self::effective_edit_digest::<P, Mutation>(edit, edit_digest, supersessions)
                }
            };
            let previous = records.last().map_or(identity_digest, |record| record.prefix_digest);
            let prefix_digest = Self::hash_record(domain, &[&previous, &edit_digest]);
            records.push(CursorRevisionRecord { id_digest, edit_digest, prefix_digest });
        }
        regrown_at
    }

    /// 🧮️ Reconciles both cursor stacks ([`Self::reconcile_stack`]); a replay rewrite rebuilds the whole redo stack. Answers
    /// the position of a regrown applied tail record.
    fn reconcile<P, Mutation: ToValue + self::Mutation<P>>(&mut self, applied_ids: &crate::os_vcs::HistoryPageStack<String>, redo_ids: &crate::os_vcs::HistoryPageStack<String>, edits: &ArtifactHistoryLedger<Edit<Mutation>>, supersessions: &EffectiveSupersessions, dirty: StackMirrorDirt, dirty_from: Option<usize>) -> Option<usize> {
        let regrown = Self::reconcile_stack::<P, Mutation>(&mut self.applied, applied_ids, edits, b"applied", self.identity_digest, &mut self.applied_tail_chains, supersessions, dirty.applied, dirty_from);
        Self::reconcile_stack::<P, Mutation>(&mut self.redo, redo_ids, edits, b"redo", self.identity_digest, &mut None, supersessions, dirty.redo, dirty_from.map(|_| 0));
        regrown
    }

    fn revision(&self, checkpoint_id: Option<&str>) -> [u8; 32] {
        let applied = self.applied.last().map_or(self.identity_digest, |record| record.prefix_digest);
        let redo = self.redo.last().map_or(self.identity_digest, |record| record.prefix_digest);
        let checkpoint = checkpoint_id.unwrap_or_default().as_bytes();
        Self::hash_record(b"cursor", &[&applied, &(self.applied.len() as u64).to_be_bytes(), &redo, &(self.redo.len() as u64).to_be_bytes(), checkpoint])
    }
}

/// 🏗️ Exact runtime owners assembled by a domain's retained store initializer.
/// Every mutating method advances one already-admitted history or reference owner; final store
/// construction only moves these prepared authorities into their from-birth terminal shells.
pub struct ArtifactStoreInitializationOwnerCatalog {
    applied_edit_ids: crate::os_vcs::HistoryPageStack<String>,
    redo_edit_ids: crate::os_vcs::HistoryPageStack<String>,
    cursor_applied_edit_ids: crate::os_vcs::HistoryPageStack<String>,
    cursor_redo_edit_ids: crate::os_vcs::HistoryPageStack<String>,
    applied_revision: crate::os_vcs::HistoryPageStack<CursorRevisionRecord>,
    redo_revision: crate::os_vcs::HistoryPageStack<CursorRevisionRecord>,
}

impl ArtifactStoreInitializationOwnerCatalog {
    fn retain_id_capacity(ids: Vec<String>) -> crate::os_vcs::HistoryPageStack<String> {
        ids.into()
    }

    pub fn try_new() -> Result<Self, &'static str> {
        Ok(Self {
            applied_edit_ids: crate::os_vcs::HistoryPageStack::try_new().map_err(|_| "artifact store applied owner catalog allocation failed")?,
            redo_edit_ids: crate::os_vcs::HistoryPageStack::try_new().map_err(|_| "artifact store redo owner catalog allocation failed")?,
            cursor_applied_edit_ids: crate::os_vcs::HistoryPageStack::try_new().map_err(|_| "artifact store cursor-applied owner catalog allocation failed")?,
            cursor_redo_edit_ids: crate::os_vcs::HistoryPageStack::try_new().map_err(|_| "artifact store cursor-redo owner catalog allocation failed")?,
            applied_revision: crate::os_vcs::HistoryPageStack::try_new().map_err(|_| "artifact store applied revision catalog allocation failed")?,
            redo_revision: crate::os_vcs::HistoryPageStack::try_new().map_err(|_| "artifact store redo revision catalog allocation failed")?,
        })
    }

    pub fn admitted_items(&self) -> usize {
        self.applied_edit_ids.capacity() + self.redo_edit_ids.capacity() + self.cursor_applied_edit_ids.capacity() + self.cursor_redo_edit_ids.capacity() + self.applied_revision.capacity() + self.redo_revision.capacity()
    }

    pub fn admitted_bytes(&self) -> Option<usize> {
        self.applied_edit_ids
            .capacity()
            .checked_mul(size_of::<String>())?
            .checked_add(self.redo_edit_ids.capacity().checked_mul(size_of::<String>())?)?
            .checked_add(self.cursor_applied_edit_ids.capacity().checked_mul(size_of::<String>())?)?
            .checked_add(self.cursor_redo_edit_ids.capacity().checked_mul(size_of::<String>())?)?
            .checked_add(self.applied_revision.capacity().checked_mul(size_of::<CursorRevisionRecord>())?)?
            .checked_add(self.redo_revision.capacity().checked_mul(size_of::<CursorRevisionRecord>())?)
    }
}

pub struct ArtifactStoreInitializationRuntime<P> {
    current: std::mem::ManuallyDrop<Option<P>>,
    applied_edit_ids: std::mem::ManuallyDrop<crate::os_vcs::HistoryPageStack<String>>,
    redo_edit_ids: std::mem::ManuallyDrop<crate::os_vcs::HistoryPageStack<String>>,
    cursor_applied_edit_ids: std::mem::ManuallyDrop<crate::os_vcs::HistoryPageStack<String>>,
    cursor_redo_edit_ids: std::mem::ManuallyDrop<crate::os_vcs::HistoryPageStack<String>>,
    current_checkpoint_id: std::mem::ManuallyDrop<Option<String>>,
    local_actor_id: std::mem::ManuallyDrop<Option<String>>,
    dag: std::mem::ManuallyDrop<Option<crate::os_spr::MutationDag>>,
    edit_sequence: i32,
    clock: HybridLogicalTimestamp,
    initial_digest: [u8; 32],
    revision: std::mem::ManuallyDrop<CursorRevisionAccumulator>,
    close_active: std::mem::ManuallyDrop<Option<Box<dyn ErasedSnapshotRetirement>>>,
    supersessions: std::mem::ManuallyDrop<EffectiveSupersessions>,
    close_phase: u8,
    taken: bool,
}

impl<P> ArtifactStoreInitializationRuntime<P> {
    pub fn new(artifact_id: &str, schema: &str, current: P, initial_digest: [u8; 32]) -> Self {
        let catalog = ArtifactStoreInitializationOwnerCatalog::try_new().expect("artifact store initialization owner catalog must be pre-admitted");
        Self::new_with_owner_catalog(artifact_id, schema, current, initial_digest, catalog)
    }

    pub fn new_with_owner_catalog(artifact_id: &str, schema: &str, current: P, initial_digest: [u8; 32], catalog: ArtifactStoreInitializationOwnerCatalog) -> Self {
        let identity_digest = CursorRevisionAccumulator::hash_record(b"initial", &[artifact_id.as_bytes(), schema.as_bytes(), &initial_digest]);
        let ArtifactStoreInitializationOwnerCatalog { applied_edit_ids, redo_edit_ids, cursor_applied_edit_ids, cursor_redo_edit_ids, applied_revision, redo_revision } = catalog;
        Self {
            current: std::mem::ManuallyDrop::new(Some(current)),
            applied_edit_ids: std::mem::ManuallyDrop::new(applied_edit_ids),
            redo_edit_ids: std::mem::ManuallyDrop::new(redo_edit_ids),
            cursor_applied_edit_ids: std::mem::ManuallyDrop::new(cursor_applied_edit_ids),
            cursor_redo_edit_ids: std::mem::ManuallyDrop::new(cursor_redo_edit_ids),
            current_checkpoint_id: std::mem::ManuallyDrop::new(None),
            local_actor_id: std::mem::ManuallyDrop::new(None),
            dag: std::mem::ManuallyDrop::new(Some(crate::os_spr::MutationDag::new())),
            edit_sequence: 0,
            clock: fresh_replica_clock(),
            initial_digest,
            revision: std::mem::ManuallyDrop::new(CursorRevisionAccumulator { identity_digest, applied: applied_revision, redo: redo_revision, applied_tail_chains: None }),
            close_active: std::mem::ManuallyDrop::new(None),
            supersessions: std::mem::ManuallyDrop::new(EffectiveSupersessions::new()),
            close_phase: 0,
            taken: false,
        }
    }

    pub fn current_mut(&mut self) -> Option<&mut P> {
        self.current.as_mut()
    }

    /// ✏️ Installs the effective supersessions the initializer folds the applied edits with; the adopted store keeps
    /// them as the map its projection was made under.
    pub fn set_supersessions(&mut self, supersessions: EffectiveSupersessions) -> Result<(), String> {
        if !self.supersessions.is_empty() {
            return Err("artifact store initialization supersessions are installed exactly once".into());
        }
        *self.supersessions = supersessions;
        Ok(())
    }

    /// ✏️ The effective supersessions the initializer folds the applied edits with.
    pub fn supersessions(&self) -> &EffectiveSupersessions {
        &self.supersessions
    }

    fn push_revision_record(records: &mut crate::os_vcs::HistoryPageStack<CursorRevisionRecord>, identity_digest: [u8; 32], domain: &[u8], id: &str, edit_digest: [u8; 32]) -> Result<(), String> {
        if !records.admits_one() {
            return Err("artifact store revision ledger is saturated".into());
        }
        let previous = records.last().map_or(identity_digest, |record| record.prefix_digest);
        let prefix_digest = CursorRevisionAccumulator::hash_record(domain, &[&previous, &edit_digest]);
        records.push(CursorRevisionRecord { id_digest: CursorRevisionAccumulator::hash_record(b"edit-id", &[id.as_bytes()]), edit_digest, prefix_digest });
        Ok(())
    }

    pub fn push_applied(&mut self, id: String, edit_digest: [u8; 32]) -> Result<(), String> {
        if !self.applied_edit_ids.admits_one() || !self.cursor_applied_edit_ids.admits_one() || !self.revision.applied.admits_one() {
            return Err("artifact store applied ledger is saturated".into());
        }
        let identity_digest = self.revision.identity_digest;
        Self::push_revision_record(&mut self.revision.applied, identity_digest, b"applied", &id, edit_digest)?;
        self.cursor_applied_edit_ids.push(id.clone());
        self.applied_edit_ids.push(id);
        Ok(())
    }

    pub fn push_applied_edit<Mutation: ToValue + self::Mutation<P>>(&mut self, edit: &Edit<Mutation>) -> Result<(), String> {
        let digest = CursorRevisionAccumulator::effective_edit_digest::<P, Mutation>(edit, CursorRevisionAccumulator::edit_digest(edit), &self.supersessions);
        self.push_applied(edit.id.clone(), digest)
    }

    pub fn push_redo(&mut self, id: String, edit_digest: [u8; 32]) -> Result<(), String> {
        if !self.redo_edit_ids.admits_one() || !self.cursor_redo_edit_ids.admits_one() || !self.revision.redo.admits_one() {
            return Err("artifact store redo ledger is saturated".into());
        }
        let identity_digest = self.revision.identity_digest;
        Self::push_revision_record(&mut self.revision.redo, identity_digest, b"redo", &id, edit_digest)?;
        self.cursor_redo_edit_ids.push(id.clone());
        self.redo_edit_ids.push(id);
        Ok(())
    }

    pub fn push_redo_edit<Mutation: ToValue + self::Mutation<P>>(&mut self, edit: &Edit<Mutation>) -> Result<(), String> {
        let digest = CursorRevisionAccumulator::effective_edit_digest::<P, Mutation>(edit, CursorRevisionAccumulator::edit_digest(edit), &self.supersessions);
        self.push_redo(edit.id.clone(), digest)
    }

    /// 🌱️ Seeds operation `id` of history entry `entry_id` into the causal owner. An edit a replica folded from a peer is
    /// named after its only operation (`edit_from_operation_envelope`), so an operation id equal to its own entry id is the node
    /// the entry already seeded — one node, never two; a repeat across entries still refuses as a duplicate.
    pub fn seed_edit_operation(&mut self, entry_id: &str, id: MutationId) -> Result<(), String> {
        if id.0 == entry_id {
            return Ok(());
        }
        self.seed_mutation(id)
    }

    pub fn seed_mutation(&mut self, id: MutationId) -> Result<(), String> {
        self.dag.as_mut().ok_or_else(|| "artifact store initialization causal owner was already detached".to_string())?.seed_applied(id).map_err(|error| error.to_string())
    }

    pub fn observe_sequence(&mut self, sequence: i32) {
        self.edit_sequence = self.edit_sequence.max(sequence);
    }

    pub fn observe_timestamp(&mut self, timestamp: HybridLogicalTimestamp) {
        self.clock.merge(&timestamp);
    }

    pub fn set_current_checkpoint_id(&mut self, value: Option<String>) {
        *self.current_checkpoint_id = value;
    }

    pub fn set_local_actor_id(&mut self, value: Option<String>) {
        *self.local_actor_id = value;
    }

    /// 🧹️ Retires one exact rejected initialization owner. The current snapshot is
    /// always handed to the domain catalog; history identities and the causal graph then advance
    /// one retained child at a time before the shell can become terminal.
    pub fn close_step(&mut self, current_factory: &dyn ArtifactOwnedValueRetirementFactory<P>, maximum_items: usize, maximum_bytes: usize) -> Result<SnapshotRetirementStep, semio_framework_value::ValueError> {
        if self.taken {
            return Ok(SnapshotRetirementStep::Complete);
        }
        if maximum_items == 0 {
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
        }
        if let Some(active) = self.close_active.as_mut() {
            return match active.close_step(maximum_items.min(1), maximum_bytes)? {
                SnapshotRetirementStep::Pending { released_items, released_bytes } if released_items <= 1 && released_bytes <= maximum_bytes => Ok(SnapshotRetirementStep::Pending { released_items, released_bytes }),
                SnapshotRetirementStep::Pending { .. } => Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "artifact store initialization child exceeded its exact close grant")),
                SnapshotRetirementStep::Blocked => Ok(SnapshotRetirementStep::Blocked),
                SnapshotRetirementStep::Complete if active.terminal_is_empty() => {
                    drop(self.close_active.take());
                    Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 })
                }
                SnapshotRetirementStep::Complete => Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "artifact store initialization child reported Complete without terminal-empty ownership")),
            };
        }
        match self.close_phase {
            0 => {
                if let Some(current) = self.current.take() {
                    *self.close_active = Some(current_factory.retire_owned(current));
                    return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
                }
                self.close_phase = 1;
            }
            1 => {
                if let Some(id) = self.applied_edit_ids.pop() {
                    *self.close_active = Some(Box::new(ArtifactStoreStringRetirement::new(id)));
                    return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
                }
                self.close_phase = 2;
            }
            2 => {
                if let Some(id) = self.redo_edit_ids.pop() {
                    *self.close_active = Some(Box::new(ArtifactStoreStringRetirement::new(id)));
                    return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
                }
                self.close_phase = 3;
            }
            3 => {
                if let Some(id) = self.cursor_applied_edit_ids.pop() {
                    *self.close_active = Some(Box::new(ArtifactStoreStringRetirement::new(id)));
                    return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
                }
                self.close_phase = 4;
            }
            4 => {
                if let Some(id) = self.cursor_redo_edit_ids.pop() {
                    *self.close_active = Some(Box::new(ArtifactStoreStringRetirement::new(id)));
                    return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
                }
                self.close_phase = 5;
            }
            5 => {
                if let Some(id) = self.current_checkpoint_id.take() {
                    *self.close_active = Some(Box::new(ArtifactStoreStringRetirement::new(id)));
                    return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
                }
                self.close_phase = 6;
            }
            6 => {
                if let Some(id) = self.local_actor_id.take() {
                    *self.close_active = Some(Box::new(ArtifactStoreStringRetirement::new(id)));
                    return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
                }
                self.close_phase = 7;
            }
            7 => {
                if let Some(dag) = self.dag.take() {
                    *self.close_active = Some(Box::new(ArtifactStoreMutationDagRetirement::new(dag)));
                    return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
                }
                if let Some(entry) = self.supersessions.pop_first() {
                    *self.close_active = Some(Box::new(ArtifactStoreSupersessionRetirement::new(BTreeMap::from([entry]))));
                    return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
                }
                self.close_phase = 8;
            }
            8 => {
                if self.revision.applied.pop().is_some() {
                    return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
                }
                self.close_phase = 9;
            }
            9 => {
                if self.revision.redo.pop().is_some() {
                    return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
                }
                self.close_phase = 10;
            }
            10 => {
                let applied = unsafe { std::mem::ManuallyDrop::take(&mut self.applied_edit_ids) };
                let redo = unsafe { std::mem::ManuallyDrop::take(&mut self.redo_edit_ids) };
                let cursor_applied = unsafe { std::mem::ManuallyDrop::take(&mut self.cursor_applied_edit_ids) };
                let cursor_redo = unsafe { std::mem::ManuallyDrop::take(&mut self.cursor_redo_edit_ids) };
                let revision = unsafe { std::mem::ManuallyDrop::take(&mut self.revision) };
                let supersessions = unsafe { std::mem::ManuallyDrop::take(&mut self.supersessions) };
                assert!(applied.is_empty() && redo.is_empty() && cursor_applied.is_empty() && cursor_redo.is_empty() && revision.applied.is_empty() && revision.redo.is_empty() && supersessions.is_empty());
                drop((applied, redo, cursor_applied, cursor_redo, revision, supersessions));
                self.close_phase = 11;
                return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
            }
            _ => {
                self.taken = true;
                return Ok(SnapshotRetirementStep::Complete);
            }
        }
        Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 })
    }

    pub fn terminal_is_empty(&self) -> bool {
        self.taken && self.current.is_none() && self.dag.is_none() && self.close_active.is_none()
    }

    #[allow(clippy::type_complexity)]
    fn into_parts(mut self) -> (P, crate::os_vcs::HistoryPageStack<String>, crate::os_vcs::HistoryPageStack<String>, ArtifactCursor, Option<String>, crate::os_spr::MutationDag, i32, HybridLogicalTimestamp, [u8; 32], CursorRevisionAccumulator, EffectiveSupersessions) {
        assert!(self.close_phase == 0 && self.close_active.is_none(), "a closing initialization runtime cannot be adopted");
        let current = self.current.take().expect("validated initialization owns its current snapshot");
        let applied = unsafe { std::mem::ManuallyDrop::take(&mut self.applied_edit_ids) };
        let redo = unsafe { std::mem::ManuallyDrop::take(&mut self.redo_edit_ids) };
        let checkpoint = self.current_checkpoint_id.take();
        let cursor = ArtifactCursor::new(unsafe { std::mem::ManuallyDrop::take(&mut self.cursor_applied_edit_ids) }, unsafe { std::mem::ManuallyDrop::take(&mut self.cursor_redo_edit_ids) }, checkpoint);
        let actor = self.local_actor_id.take();
        let dag = self.dag.take().expect("validated initialization owns its causal graph");
        let revision = unsafe { std::mem::ManuallyDrop::take(&mut self.revision) };
        let supersessions = unsafe { std::mem::ManuallyDrop::take(&mut self.supersessions) };
        self.taken = true;
        (current, applied, redo, cursor, actor, dag, self.edit_sequence, self.clock, self.initial_digest, revision, supersessions)
    }
}

impl<P> Drop for ArtifactStoreInitializationRuntime<P> {
    fn drop(&mut self) {
        assert!(std::thread::panicking() || (self.taken), "artifact store initialization runtime reached Drop before exact store construction or retained rejection cleanup");
    }
}

const ARTIFACT_EDIT_MESSAGE_INDEX_CAPACITY: usize = 8_192;
const ARTIFACT_EDIT_MESSAGE_ID_BYTES: usize = 256;
const ARTIFACT_EDIT_MESSAGE_ENTRY_BYTES: usize = 4_096;

/// ✂️ Bounds `messages`, one edit's message ledger entry, to [`ARTIFACT_EDIT_MESSAGE_ENTRY_BYTES`] deterministically, so
/// no replay yields an unstorable entry and every replica stores the same one: messages are kept worst level first (ties
/// in recorded order) while they fit and stay in recorded order, and the dropped rest is summarized by one
/// `mutation.cascade` info at the operation of the first dropped message. A worst message too large on its own keeps
/// its code with its text cut to fit. Answers whether anything was cut.
pub fn bound_edit_messages(edit_id: &str, messages: &mut Vec<crate::os_spr::MutationMessage>) -> bool {
    let size = |message: &crate::os_spr::MutationMessage| message.code.0.len().saturating_add(message.message.len()).saturating_add(message.target.iter().map(String::len).sum::<usize>());
    if messages.iter().fold(edit_id.len(), |bytes, message| bytes.saturating_add(size(message))) <= ARTIFACT_EDIT_MESSAGE_ENTRY_BYTES {
        return false;
    }
    let summary = |dropped: usize, op_index: Option<u32>| {
        let mut summary = crate::os_spr::MutationMessage::info("mutation.cascade", format!("{dropped} more messages"));
        summary.op_index = op_index;
        summary
    };
    let budget = ARTIFACT_EDIT_MESSAGE_ENTRY_BYTES.saturating_sub(edit_id.len()).saturating_sub(size(&summary(messages.len(), None)));
    let mut ranked: Vec<usize> = (0..messages.len()).collect();
    ranked.sort_by_key(|index| std::cmp::Reverse(messages[*index].level));
    let mut kept = vec![false; messages.len()];
    let mut used = 0usize;
    for index in ranked.iter().copied() {
        let bytes = size(&messages[index]);
        if used.saturating_add(bytes) > budget {
            break;
        }
        used += bytes;
        kept[index] = true;
    }
    if let Some(worst) = ranked.first().copied().filter(|_| !kept.iter().any(|kept| *kept)) {
        let message = &mut messages[worst];
        message.target.clear();
        let mut cut = budget.saturating_sub(message.code.0.len()).min(message.message.len());
        while !message.message.is_char_boundary(cut) {
            cut -= 1;
        }
        message.message.truncate(cut);
        kept[worst] = true;
    }
    let first_dropped = kept.iter().position(|kept| !*kept).map(|index| messages[index].op_index);
    let dropped = kept.iter().filter(|kept| !**kept).count();
    let mut flags = kept.into_iter();
    messages.retain(|_| flags.next().unwrap_or(false));
    if let Some(op_index) = first_dropped {
        messages.push(summary(dropped, op_index));
    }
    true
}
const ARTIFACT_EDIT_MESSAGE_LEDGER_BYTES: usize = ARTIFACT_EDIT_MESSAGE_INDEX_CAPACITY * ARTIFACT_EDIT_MESSAGE_ENTRY_BYTES;
const ARTIFACT_EDIT_MESSAGE_INDEX_EMPTY: u16 = u16::MAX;
const ARTIFACT_EDIT_MESSAGE_INDEX_TOMBSTONE: u16 = u16::MAX - 1;
const ARTIFACT_EDIT_MESSAGE_LEDGER_SLOT_NONE: u16 = u16::MAX;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct ArtifactEditMessageTicket {
    slot: u16,
    generation: u64,
}

pub struct ArtifactEditMessageLedger {
    slots: Box<[std::mem::MaybeUninit<crate::os_spr::EditMessages>]>,
    generations: Box<[u64]>,
    occupied: Box<[bool]>,
    next: Box<[u16]>,
    previous: Box<[u16]>,
    buckets: Box<[u16]>,
    free: Box<[u16]>,
    free_len: usize,
    head: u16,
    tail: u16,
    len: usize,
}

pub struct ArtifactEditMessageLedgerIter<'a> {
    ledger: &'a ArtifactEditMessageLedger,
    next: u16,
}

impl<'a> Iterator for ArtifactEditMessageLedgerIter<'a> {
    type Item = &'a crate::os_spr::EditMessages;

    fn next(&mut self) -> Option<Self::Item> {
        if self.next == ARTIFACT_EDIT_MESSAGE_LEDGER_SLOT_NONE {
            return None;
        }
        let slot = usize::from(self.next);
        self.next = self.ledger.next[slot];
        Some(unsafe { self.ledger.slots[slot].assume_init_ref() })
    }
}

pub struct ArtifactEditMessageLedgerRejected {
    entries: std::mem::ManuallyDrop<Vec<crate::os_spr::EditMessages>>,
    active: std::mem::ManuallyDrop<Option<ArtifactStoreMessageLedgerRetirement>>,
    entries_terminal: bool,
    reason: &'static str,
}

impl ArtifactEditMessageLedger {
    pub fn new() -> Self {
        Self {
            slots: Box::<[crate::os_spr::EditMessages]>::new_uninit_slice(ARTIFACT_EDIT_MESSAGE_INDEX_CAPACITY),
            generations: vec![0; ARTIFACT_EDIT_MESSAGE_INDEX_CAPACITY].into_boxed_slice(),
            occupied: vec![false; ARTIFACT_EDIT_MESSAGE_INDEX_CAPACITY].into_boxed_slice(),
            next: vec![ARTIFACT_EDIT_MESSAGE_LEDGER_SLOT_NONE; ARTIFACT_EDIT_MESSAGE_INDEX_CAPACITY].into_boxed_slice(),
            previous: vec![ARTIFACT_EDIT_MESSAGE_LEDGER_SLOT_NONE; ARTIFACT_EDIT_MESSAGE_INDEX_CAPACITY].into_boxed_slice(),
            buckets: vec![ARTIFACT_EDIT_MESSAGE_INDEX_EMPTY; ARTIFACT_EDIT_MESSAGE_INDEX_CAPACITY].into_boxed_slice(),
            free: (0..ARTIFACT_EDIT_MESSAGE_INDEX_CAPACITY).rev().map(|slot| slot as u16).collect::<Vec<_>>().into_boxed_slice(),
            free_len: ARTIFACT_EDIT_MESSAGE_INDEX_CAPACITY,
            head: ARTIFACT_EDIT_MESSAGE_LEDGER_SLOT_NONE,
            tail: ARTIFACT_EDIT_MESSAGE_LEDGER_SLOT_NONE,
            len: 0,
        }
    }

    pub fn try_from_entries(entries: Vec<crate::os_spr::EditMessages>) -> Result<Self, ArtifactEditMessageLedgerRejected> {
        if let Err(reason) = Self::preflight_entries(&entries) {
            return Err(ArtifactEditMessageLedgerRejected::new(entries, reason));
        }
        let mut ledger = Self::new();
        for entry in entries {
            ledger.push_reserved(entry).expect("preflighted artifact edit-message ledger slot remains admissible");
        }
        Ok(ledger)
    }

    pub fn from_preflighted_entries(entries: Vec<crate::os_spr::EditMessages>) -> Self {
        assert!(Self::preflight_entries(&entries).is_ok(), "preflighted artifact edit-message entries changed before fixed-ledger adoption");
        let mut ledger = Self::new();
        for entry in entries {
            ledger.push_reserved(entry).unwrap_or_else(|_| panic!("preflighted artifact edit-message slot remains admissible"));
        }
        ledger
    }

    fn preflight_entries(entries: &[crate::os_spr::EditMessages]) -> Result<(), &'static str> {
        if entries.len() > ARTIFACT_EDIT_MESSAGE_INDEX_CAPACITY {
            return Err("artifact edit-message ledger exceeds its exact fixed item authority");
        }
        let mut preflight_buckets = vec![ARTIFACT_EDIT_MESSAGE_INDEX_EMPTY; ARTIFACT_EDIT_MESSAGE_INDEX_CAPACITY].into_boxed_slice();
        let mut admitted_bytes = 0usize;
        for (entry_index, entry) in entries.iter().enumerate() {
            let Some(entry_bytes) = Self::entry_bytes(entry) else {
                return Err("artifact edit-message ledger byte authority overflowed");
            };
            if entry.edit_id.len() > ARTIFACT_EDIT_MESSAGE_ID_BYTES || entry_bytes > ARTIFACT_EDIT_MESSAGE_ENTRY_BYTES {
                return Err("artifact edit-message ledger contains an entry outside its fixed byte authority");
            }
            admitted_bytes = match admitted_bytes.checked_add(entry_bytes) {
                Some(bytes) if bytes <= ARTIFACT_EDIT_MESSAGE_LEDGER_BYTES => bytes,
                _ => return Err("artifact edit-message ledger exceeds its exact aggregate byte authority"),
            };
            let start = Self::hash(&entry.edit_id) % ARTIFACT_EDIT_MESSAGE_INDEX_CAPACITY;
            let mut admitted = false;
            for probe in 0..ARTIFACT_EDIT_MESSAGE_INDEX_CAPACITY {
                let bucket = (start + probe) % ARTIFACT_EDIT_MESSAGE_INDEX_CAPACITY;
                let established = preflight_buckets[bucket];
                if established == ARTIFACT_EDIT_MESSAGE_INDEX_EMPTY {
                    preflight_buckets[bucket] = entry_index as u16;
                    admitted = true;
                    break;
                }
                if entries[usize::from(established)].edit_id == entry.edit_id {
                    return Err("artifact edit-message ledger contains a duplicate identity");
                }
            }
            if !admitted {
                return Err("artifact edit-message ledger fixed identity table is saturated");
            }
        }
        Ok(())
    }

    fn entry_bytes(entry: &crate::os_spr::EditMessages) -> Option<usize> {
        entry.messages.iter().try_fold(entry.edit_id.len(), |bytes, message| message.target.iter().try_fold(bytes.checked_add(message.code.0.len())?.checked_add(message.message.len())?, |bytes, segment| bytes.checked_add(segment.len())))
    }

    fn hash(id: &str) -> usize {
        id.as_bytes().iter().fold(0xcbf29ce484222325u64, |hash, byte| (hash ^ u64::from(*byte)).wrapping_mul(0x100000001b3)) as usize
    }

    fn find_ticket(&self, id: &str) -> Option<ArtifactEditMessageTicket> {
        if id.len() > ARTIFACT_EDIT_MESSAGE_ID_BYTES {
            return None;
        }
        let start = Self::hash(id) % ARTIFACT_EDIT_MESSAGE_INDEX_CAPACITY;
        for probe in 0..ARTIFACT_EDIT_MESSAGE_INDEX_CAPACITY {
            let slot = self.buckets[(start + probe) % ARTIFACT_EDIT_MESSAGE_INDEX_CAPACITY];
            if slot == ARTIFACT_EDIT_MESSAGE_INDEX_EMPTY {
                return None;
            }
            if slot == ARTIFACT_EDIT_MESSAGE_INDEX_TOMBSTONE {
                continue;
            }
            let slot = usize::from(slot);
            if self.occupied[slot] && unsafe { self.slots[slot].assume_init_ref() }.edit_id == id {
                return Some(ArtifactEditMessageTicket { slot: slot as u16, generation: self.generations[slot] });
            }
        }
        None
    }

    fn reserve_identity(&mut self, slot: u16, id: &str) {
        let start = Self::hash(id) % ARTIFACT_EDIT_MESSAGE_INDEX_CAPACITY;
        let mut tombstone = None;
        for probe in 0..ARTIFACT_EDIT_MESSAGE_INDEX_CAPACITY {
            let bucket = (start + probe) % ARTIFACT_EDIT_MESSAGE_INDEX_CAPACITY;
            match self.buckets[bucket] {
                ARTIFACT_EDIT_MESSAGE_INDEX_EMPTY => {
                    self.buckets[tombstone.unwrap_or(bucket)] = slot;
                    return;
                }
                ARTIFACT_EDIT_MESSAGE_INDEX_TOMBSTONE => {
                    tombstone.get_or_insert(bucket);
                }
                _ => {}
            }
        }
        self.buckets[tombstone.expect("preflighted artifact edit-message identity has a deterministic bucket")] = slot;
    }

    fn reserved_identity_bucket(&self, slot: u16, id: &str) -> Option<usize> {
        let start = Self::hash(id) % ARTIFACT_EDIT_MESSAGE_INDEX_CAPACITY;
        for probe in 0..ARTIFACT_EDIT_MESSAGE_INDEX_CAPACITY {
            let bucket = (start + probe) % ARTIFACT_EDIT_MESSAGE_INDEX_CAPACITY;
            if self.buckets[bucket] == slot {
                return Some(bucket);
            }
            if self.buckets[bucket] == ARTIFACT_EDIT_MESSAGE_INDEX_EMPTY {
                return None;
            }
        }
        None
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn iter(&self) -> ArtifactEditMessageLedgerIter<'_> {
        ArtifactEditMessageLedgerIter { ledger: self, next: self.head }
    }

    pub fn first(&self) -> Option<&crate::os_spr::EditMessages> {
        (self.head != ARTIFACT_EDIT_MESSAGE_LEDGER_SLOT_NONE).then(|| unsafe { self.slots[usize::from(self.head)].assume_init_ref() })
    }

    pub fn last(&self) -> Option<&crate::os_spr::EditMessages> {
        (self.tail != ARTIFACT_EDIT_MESSAGE_LEDGER_SLOT_NONE).then(|| unsafe { self.slots[usize::from(self.tail)].assume_init_ref() })
    }

    pub fn get_by_id(&self, id: &str) -> Option<&crate::os_spr::EditMessages> {
        self.find_ticket(id).and_then(|ticket| self.get(ticket))
    }

    pub fn get_mut_by_id(&mut self, id: &str) -> Option<&mut crate::os_spr::EditMessages> {
        let ticket = self.find_ticket(id)?;
        self.get_mut(ticket)
    }

    fn get(&self, ticket: ArtifactEditMessageTicket) -> Option<&crate::os_spr::EditMessages> {
        let slot = usize::from(ticket.slot);
        (slot < ARTIFACT_EDIT_MESSAGE_INDEX_CAPACITY && self.occupied[slot] && self.generations[slot] == ticket.generation).then(|| unsafe { self.slots[slot].assume_init_ref() })
    }

    fn get_mut(&mut self, ticket: ArtifactEditMessageTicket) -> Option<&mut crate::os_spr::EditMessages> {
        let slot = usize::from(ticket.slot);
        (slot < ARTIFACT_EDIT_MESSAGE_INDEX_CAPACITY && self.occupied[slot] && self.generations[slot] == ticket.generation).then(|| unsafe { self.slots[slot].assume_init_mut() })
    }

    fn try_push(&mut self, entry: crate::os_spr::EditMessages) -> Result<ArtifactEditMessageTicket, crate::os_spr::EditMessages> {
        if self.free_len == 0 || entry.edit_id.len() > ARTIFACT_EDIT_MESSAGE_ID_BYTES || Self::entry_bytes(&entry).is_none_or(|bytes| bytes > ARTIFACT_EDIT_MESSAGE_ENTRY_BYTES) || self.find_ticket(&entry.edit_id).is_some() {
            return Err(entry);
        }
        self.push_reserved(entry)
    }

    pub fn admit(&mut self, entry: crate::os_spr::EditMessages) -> Result<(), crate::os_spr::EditMessages> {
        self.try_push(entry).map(|_| ())
    }

    fn push_reserved(&mut self, entry: crate::os_spr::EditMessages) -> Result<ArtifactEditMessageTicket, crate::os_spr::EditMessages> {
        assert!(self.free_len > 0, "artifact edit-message ledger push lacked its exact fixed-slot admission");
        self.free_len -= 1;
        let slot = usize::from(self.free[self.free_len]);
        let Some(generation) = self.generations[slot].checked_add(1) else {
            self.free[self.free_len] = slot as u16;
            self.free_len += 1;
            return Err(entry);
        };
        self.reserve_identity(slot as u16, &entry.edit_id);
        self.slots[slot].write(entry);
        self.generations[slot] = generation;
        self.occupied[slot] = true;
        self.previous[slot] = self.tail;
        self.next[slot] = ARTIFACT_EDIT_MESSAGE_LEDGER_SLOT_NONE;
        if self.tail == ARTIFACT_EDIT_MESSAGE_LEDGER_SLOT_NONE {
            self.head = slot as u16;
        } else {
            self.next[usize::from(self.tail)] = slot as u16;
        }
        self.tail = slot as u16;
        self.len += 1;
        Ok(ArtifactEditMessageTicket { slot: slot as u16, generation: self.generations[slot] })
    }

    pub fn pop(&mut self) -> Option<crate::os_spr::EditMessages> {
        (self.tail != ARTIFACT_EDIT_MESSAGE_LEDGER_SLOT_NONE).then(|| {
            let slot = usize::from(self.tail);
            self.remove(ArtifactEditMessageTicket { slot: slot as u16, generation: self.generations[slot] }).expect("validated artifact edit-message tail remains live")
        })
    }

    fn remove(&mut self, ticket: ArtifactEditMessageTicket) -> Option<crate::os_spr::EditMessages> {
        self.get(ticket)?;
        let slot = usize::from(ticket.slot);
        let identity_bucket = self.reserved_identity_bucket(ticket.slot, &unsafe { self.slots[slot].assume_init_ref() }.edit_id).expect("artifact edit-message identity remains reserved while its slot is live");
        let previous = self.previous[slot];
        let next = self.next[slot];
        if previous == ARTIFACT_EDIT_MESSAGE_LEDGER_SLOT_NONE {
            self.head = next;
        } else {
            self.next[usize::from(previous)] = next;
        }
        if next == ARTIFACT_EDIT_MESSAGE_LEDGER_SLOT_NONE {
            self.tail = previous;
        } else {
            self.previous[usize::from(next)] = previous;
        }
        self.occupied[slot] = false;
        self.buckets[identity_bucket] = ARTIFACT_EDIT_MESSAGE_INDEX_TOMBSTONE;
        self.next[slot] = ARTIFACT_EDIT_MESSAGE_LEDGER_SLOT_NONE;
        self.previous[slot] = ARTIFACT_EDIT_MESSAGE_LEDGER_SLOT_NONE;
        self.free[self.free_len] = ticket.slot;
        self.free_len += 1;
        self.len -= 1;
        Some(unsafe { self.slots[slot].assume_init_read() })
    }

    pub fn remove_id(&mut self, id: &str) -> Option<crate::os_spr::EditMessages> {
        let ticket = self.find_ticket(id)?;
        self.remove(ticket)
    }

    fn terminal_is_empty(&self) -> bool {
        self.len == 0 && self.free_len == ARTIFACT_EDIT_MESSAGE_INDEX_CAPACITY
    }
}

