/// 🪪 Exact live publication metadata minted by the Store and shared immutably with the
/// domain preparation owner. Apps cannot invent cursor position, sequence, clock, or actor.
pub struct ArtifactStoreOneItemLiveAuthority {
    operation: semio_framework_job::OperationId,
    generation: semio_framework_job::Generation,
    base_revision: [u8; 32],
    base_applied_edit_count: usize,
    next_sequence_number: i32,
    next_clock: HybridLogicalTimestamp,
    actor: String,
    line: Option<String>,
    group_id: Option<String>,
    stamped_edit_id: Option<String>,
}

impl ArtifactStoreOneItemLiveAuthority {
    pub fn operation(&self) -> semio_framework_job::OperationId {
        self.operation
    }

    pub fn generation(&self) -> semio_framework_job::Generation {
        self.generation
    }

    pub fn base_revision(&self) -> [u8; 32] {
        self.base_revision
    }

    pub fn base_applied_edit_count(&self) -> usize {
        self.base_applied_edit_count
    }

    pub fn next_sequence_number(&self) -> i32 {
        self.next_sequence_number
    }

    pub fn next_clock(&self) -> HybridLogicalTimestamp {
        self.next_clock
    }

    pub fn actor(&self) -> &str {
        &self.actor
    }

    /// 🪪️ The globally unique identity of the edit this authority publishes — content-addressed
    /// over the actor, the sequence and the HLC tick the Store minted, so two replicas' edits never
    /// share an identity the way a replica-local counter would. The Store stamps it on the staged edit.
    ///
    /// 🔏 A server-stamped publication instead publishes under the identity its durable
    /// decision was hashed over: the approval's own mutation id, itself content-addressed over the
    /// job and the proposal, so the uniqueness argument above still holds and the committed edit
    /// carries the identity every downstream verifier (WAL, ledger, actor frontier) binds against.
    pub fn edit_id(&self) -> String {
        if let Some(stamped) = self.stamped_edit_id.as_ref() {
            return stamped.clone();
        }
        let mut material = Vec::with_capacity(self.actor.len() + 48);
        material.extend_from_slice(&(self.actor.len() as u64).to_le_bytes());
        material.extend_from_slice(self.actor.as_bytes());
        material.extend_from_slice(&self.next_sequence_number.to_le_bytes());
        for part in [self.next_clock.actor, self.next_clock.physical_ms, self.next_clock.logical] {
            material.extend_from_slice(&part.to_le_bytes());
        }
        let digest = semio_framework_hash::hash(&material);
        let mut id = String::with_capacity(21);
        id.push_str("edit-");
        for byte in &digest.as_bytes()[..8] {
            id.push_str(&format!("{byte:02x}"));
        }
        id
    }

    /// 🌿️ The immutable authored branch of this Store publication.
    pub fn line_id(&self) -> Option<&str> { self.line.as_deref() }

    pub fn group_id(&self) -> Option<&str> {
        self.group_id.as_deref()
    }

    /// 🔏 The server-stamped identity this publication was minted under, or `None` for every
    /// local gesture. The fold reads it to keep the stamped mutation id on the first folded item
    /// instead of rewriting it to the store's `<edit-id>#<position>` form.
    pub fn stamped_edit_id(&self) -> Option<&str> {
        self.stamped_edit_id.as_deref()
    }

    /// 🧾️ The ONE semantic edit a one-item preparation publishes: `forward` with its `inverse` rows, minted entirely from
    /// this authority (identity, actor, line, group, sequence, clock, base version) so no domain hand-builds an edit or
    /// invents a field the Store validates. It carries no hand-written description (design §20.6): the fold stamps semantic
    /// kind, label and transaction, and history labels the row from the leaf.
    pub fn next_edit<Mutation>(&self, forward: Mutation, inverse: Vec<Mutation>) -> Edit<Mutation> {
        let id = self.edit_id();
        Edit {
            line: self.line.clone(),
            mutation_meta: vec![MutationMeta {
                mutation_id: Some(MutationId(format!("{id}#0"))),
                dependencies: Vec::new(),
                base_version: self.base_applied_edit_count as u64,
                author_id: Some(ActorId(self.actor.clone())),
                timestamp: self.next_clock,
                undo_policy: UndoPolicy::ExactBaseOnly,
                payload_hash: None,
                semantic_kind: None,
                label: None,
                group_id: self.group_id.clone(),
                origin: Default::default(),
                transaction: None,
            }],
            id,
            actor: Some(self.actor.clone()),
            forwards: vec![forward],
            inverse,
            description: None,
            verb: None,
            sequence_number: self.next_sequence_number,
            started_at: String::new(),
            finished_at: None,
        }
    }

    /// 🧹️ Transfers the authority Arc and its final actor/group strings into byte-bounded retirement.
    pub fn retire(self: Arc<Self>) -> Box<dyn ErasedSnapshotRetirement> {
        Box::new(canonical_edit::ArtifactStoreOneItemAuthorityRetirement::new(self))
    }

    fn validate_semantic_edit<Mutation>(&self, edit: &Edit<Mutation>) -> Result<(), String> {
        let meta = edit.mutation_meta.first().ok_or_else(|| "one-item edit lacks its exact authority metadata".to_string())?;
        if edit.id.is_empty()
            || edit.id.len() > ARTIFACT_STORE_ONE_ITEM_ID_BYTES
            || edit.sequence_number != self.next_sequence_number
            || edit.forwards.len() != 1
            || edit.mutation_meta.len() != 1
            || edit.actor.as_deref() != Some(self.actor.as_str())
            || edit.line != self.line
            || meta.author_id.as_ref().map(|actor| actor.0.as_str()) != Some(self.actor.as_str())
            || meta.timestamp != self.next_clock
            || meta.group_id.as_deref() != self.group_id.as_deref()
        {
            return Err("one-item semantic edit disagrees with its immutable Store authority".into());
        }
        Ok(())
    }

    /// 🔏 Canonical oracle for explicitly bounded edits; retained large edits use the byte sealer.
    pub fn prepared_edit_digest<Mutation: ToValue>(&self, edit: &Edit<Mutation>) -> Result<[u8; 32], String> {
        self.validate_semantic_edit(edit)?;
        Ok(CursorRevisionAccumulator::edit_digest(edit))
    }

    /// 📦 Seals an explicitly bounded semantic edit into exact Store-owned publication authority.
    pub fn prepare_one_item<P, Mutation: ToValue>(self: &Arc<Self>, edit: Edit<Mutation>, post_snapshot: Arc<P>) -> Result<ArtifactStoreOneItemPrepared<P, Mutation>, String> {
        let edit_digest = self.prepared_edit_digest(&edit)?;
        Ok(self.seal_prepared(Box::new(edit), post_snapshot, edit_digest))
    }

    /// 🧵️ Moves the exact edit and post root into retained canonical preparation without encoding.
    pub fn begin_one_item_seal<P, Mutation>(
        self: &Arc<Self>,
        edit: Edit<Mutation>,
        post_snapshot: Arc<P>,
        mutation_retirement: Arc<dyn ArtifactOwnedValueRetirementFactory<Mutation>>,
        snapshot_retirement: Arc<dyn SnapshotRetirementFactory<P>>,
    ) -> ArtifactStoreOneItemSealer<P, Mutation> {
        ArtifactStoreOneItemSealer::new(Arc::clone(self), edit, post_snapshot, mutation_retirement, snapshot_retirement)
    }

    fn seal_prepared<P, Mutation>(self: &Arc<Self>, edit: Box<Edit<Mutation>>, post_snapshot: Arc<P>, edit_digest: [u8; 32]) -> ArtifactStoreOneItemPrepared<P, Mutation> {
        let edit_id = edit.id.clone();
        let identities = [self.actor.clone(), edit_id.clone(), edit_id];
        self.seal_prepared_owned(edit, post_snapshot, edit_digest, identities)
    }

    fn seal_prepared_owned<P, Mutation>(self: &Arc<Self>, edit: Box<Edit<Mutation>>, post_snapshot: Arc<P>, edit_digest: [u8; 32], identities: [String; 3]) -> ArtifactStoreOneItemPrepared<P, Mutation> {
        let [actor, applied_edit_id, tail_edit_id] = identities;
        let seal = ArtifactStoreOneItemSeal { authority: Arc::clone(self), edit_address: edit.as_ref() as *const Edit<Mutation> as usize, post_address: Arc::as_ptr(&post_snapshot) as usize, digest: edit_digest };
        ArtifactStoreOneItemPrepared { edit, post_snapshot, next_clock: self.next_clock, edit_digest, local_actor: Some(actor), applied_edit_id, tail_edit_id, seal }
    }

    fn validate_prepared<P, Mutation>(self: &Arc<Self>, prepared: &ArtifactStoreOneItemPrepared<P, Mutation>) -> Result<(), String> {
        self.validate_semantic_edit(&prepared.edit)?;
        if !Arc::ptr_eq(self, &prepared.seal.authority)
            || prepared.seal.edit_address != prepared.edit.as_ref() as *const Edit<Mutation> as usize
            || prepared.seal.post_address != Arc::as_ptr(&prepared.post_snapshot) as usize
            || prepared.seal.digest != prepared.edit_digest
        {
            return Err("one-item private Store seal disagrees with exact authority or moved owners".into());
        }
        Ok(())
    }
}

struct ArtifactStoreOneItemSeal {
    authority: Arc<ArtifactStoreOneItemLiveAuthority>,
    edit_address: usize,
    post_address: usize,
    digest: [u8; 32],
}

/// 📦 Fully prepared one-item candidate. The domain must build every potentially unbounded
/// mutation inverse/diff/apply/encoding result inside its retained cursor before exposing this
/// value. The store publication turn only validates fixed authorities and moves these owners.
pub struct ArtifactStoreOneItemPrepared<P, Mutation> {
    edit: Box<Edit<Mutation>>,
    post_snapshot: Arc<P>,
    next_clock: HybridLogicalTimestamp,
    edit_digest: [u8; 32],
    local_actor: Option<String>,
    applied_edit_id: String,
    tail_edit_id: String,
    seal: ArtifactStoreOneItemSeal,
}

impl<P, Mutation> ArtifactStoreOneItemPrepared<P, Mutation> {
    pub fn edit_digest(&self) -> [u8; 32] {
        self.edit_digest
    }
}

/// 🧳 Exact owner bundle transferred to a domain preparation factory only after preflight.
pub struct ArtifactStoreOneItemPreparationRequest<P, Mutation> {
    pub operation: semio_framework_job::OperationId,
    pub generation: semio_framework_job::Generation,
    pub base_revision: [u8; 32],
    pub lane: HistoryLane,
    pub authority: Arc<ArtifactStoreOneItemLiveAuthority>,
    pub description: Option<String>,
    pub base: SnapshotRead<P>,
    pub mutation: Mutation,
}

impl<P, Mutation> ArtifactStoreOneItemPreparationRequest<P, Mutation> {
    pub fn into_owners(self) -> (SnapshotRead<P>, Mutation, Option<String>) {
        (self.base, self.mutation, self.description)
    }
}

/// 🧩 Domain-owned retained mutation preparation. Generic `Mutation` is intentionally not
/// invoked by the store: a domain that cannot split its mutation semantics into these turns is
/// rejected at admission instead of receiving false resumability credit.
pub trait ArtifactStoreOneItemPreparation<P, Mutation>: Send {
    fn advance(&mut self, grant: ArtifactStoreOneItemGrant) -> Result<ArtifactStoreOneItemPreparationStep, String>;
    fn checkpoint(&self) -> ArtifactStoreOneItemCheckpoint;
    fn prepared(&self) -> Option<&ArtifactStoreOneItemPrepared<P, Mutation>>;
    fn take_prepared(&mut self) -> Option<ArtifactStoreOneItemPrepared<P, Mutation>>;
    fn cancel(&mut self);
    fn begin_close(&mut self);
    fn close_step(&mut self, grant: ArtifactStoreOneItemGrant) -> Result<SnapshotRetirementStep, semio_framework_value::ValueError>;
    fn terminal_is_empty(&self) -> bool;
}

/// 🏭️ Exact app-owned factory. `preflight` must not allocate, copy the mutation, or retain
/// the supplied references; `begin` receives ownership only after the declared footprint passes.
pub trait ArtifactStoreOneItemPreparationFactory<P, Mutation>: Send + Sync {
    fn preflight(&self, mutation: &Mutation, description: Option<&str>, lane: HistoryLane) -> Result<ArtifactStoreOneItemFootprint, String>;
    fn begin(&self, request: ArtifactStoreOneItemPreparationRequest<P, Mutation>) -> Result<Box<dyn ArtifactStoreOneItemPreparation<P, Mutation>>, ArtifactStoreOneItemPreparationRequest<P, Mutation>>;

    /// 🕰️ Declares a server-derived publication clock the factory will stamp on its prepared edit,
    /// so the Store mints the authority at that exact tick instead of its own wall-clock one. A
    /// factory that returns `None` keeps the Store's clock, which is what every local gesture wants.
    fn stamped_clock(&self) -> Option<HybridLogicalTimestamp> {
        None
    }

    /// 🔏 Declares the server-derived mutation identity the factory will stamp on its prepared edit.
    /// A stamped publication is hashed into a durable decision under this exact identity before the
    /// Store ever sees it, so the Store must publish under it rather than mint its own — otherwise
    /// the committed edit carries an identity no verifier can bind to the approval it executed.
    /// `None` keeps the Store's content-addressed mint, which is what every local gesture wants.
    fn stamped_mutation_id(&self) -> Option<MutationId> {
        None
    }
}

//#region 🧺️BatchSource
/// 🏭️ The per-item app authority one batched gesture draws on, erased over whichever input its
/// lane admits: a typed mutation for the app's own document lane, an owned wire item for a member.
/// The batch machine calls it exactly once per staged mutation and never inspects the input.
trait ArtifactStoreBatchItemAuthority<P, Mutation>: Send + Sync {
    type Input: Send;

    fn preflight(&self, input: &Self::Input, description: Option<&str>, lane: HistoryLane) -> Result<ArtifactStoreOneItemFootprint, String>;
    fn begin(&self, request: ArtifactStoreOneItemPreparationRequest<P, Self::Input>) -> Result<Box<dyn ArtifactStoreOneItemPreparation<P, Mutation>>, ArtifactStoreOneItemPreparationRequest<P, Self::Input>>;

    fn stamped_clock(&self) -> Option<HybridLogicalTimestamp> {
        None
    }

    fn stamped_mutation_id(&self) -> Option<MutationId> {
        None
    }
}

impl<P: Send + Sync, Mutation: Send> ArtifactStoreBatchItemAuthority<P, Mutation> for Arc<dyn ArtifactStoreOneItemPreparationFactory<P, Mutation>> {
    type Input = Mutation;

    fn preflight(&self, input: &Mutation, description: Option<&str>, lane: HistoryLane) -> Result<ArtifactStoreOneItemFootprint, String> {
        self.as_ref().preflight(input, description, lane)
    }

    fn begin(&self, request: ArtifactStoreOneItemPreparationRequest<P, Mutation>) -> Result<Box<dyn ArtifactStoreOneItemPreparation<P, Mutation>>, ArtifactStoreOneItemPreparationRequest<P, Mutation>> {
        self.as_ref().begin(request)
    }

    fn stamped_clock(&self) -> Option<HybridLogicalTimestamp> {
        self.as_ref().stamped_clock()
    }

    fn stamped_mutation_id(&self) -> Option<MutationId> {
        self.as_ref().stamped_mutation_id()
    }
}

impl<P: Send + Sync, Mutation: Send> ArtifactStoreBatchItemAuthority<P, Mutation> for Arc<dyn MemberStoreOneItemWirePreparationFactory<P, Mutation>> {
    type Input = MemberStoreOneItemWire;

    fn preflight(&self, input: &MemberStoreOneItemWire, description: Option<&str>, lane: HistoryLane) -> Result<ArtifactStoreOneItemFootprint, String> {
        self.as_ref().preflight(input, description, lane)
    }

    fn begin(&self, request: ArtifactStoreOneItemPreparationRequest<P, MemberStoreOneItemWire>) -> Result<Box<dyn ArtifactStoreOneItemPreparation<P, Mutation>>, ArtifactStoreOneItemPreparationRequest<P, MemberStoreOneItemWire>> {
        self.as_ref().begin(request)
    }
}

/// 🧳 One item's exact owner bundle, minted by the store from the batch's single shared live
/// authority and the running post root the item before it produced.
struct ArtifactStoreBatchItemRequest<P> {
    operation: semio_framework_job::OperationId,
    generation: semio_framework_job::Generation,
    base_revision: [u8; 32],
    lane: HistoryLane,
    authority: Arc<ArtifactStoreOneItemLiveAuthority>,
    base: SnapshotRead<P>,
}

/// 🧺️ The still-unstaged inputs of one admitted gesture. `remaining` is the only census the batch
/// machine reads; every owner leaves through `begin_next` or one bounded `close_step`.
trait ArtifactStoreBatchSource<P, Mutation>: Send {
    fn remaining(&self) -> usize;
    fn begin_next(&mut self, request: ArtifactStoreBatchItemRequest<P>) -> Result<Box<dyn ArtifactStoreOneItemPreparation<P, Mutation>>, String>;
    fn close_step(&mut self, grant: ArtifactStoreOneItemGrant) -> SnapshotRetirementStep;
    fn terminal_is_empty(&self) -> bool;
}

/// 🧺️ The one batch source shape: an app-owned per-item authority plus the gesture's inputs in
/// reverse authored order, so `pop` hands the next item back in the order the app emitted it.
struct ArtifactStoreBatchSourceOf<P, Mutation, A: ArtifactStoreBatchItemAuthority<P, Mutation>> {
    authority: Option<A>,
    inputs: Vec<A::Input>,
    description: Option<String>,
    marker: PhantomData<fn() -> (P, Mutation)>,
}

impl<P, Mutation, A: ArtifactStoreBatchItemAuthority<P, Mutation>> ArtifactStoreBatchSourceOf<P, Mutation, A> {
    /// 🧮 Declares the whole gesture in one footprint: work items sum across every staged forward
    /// and inverse owner, retained bytes stay the widest single item because only one item's
    /// owners are ever live at once.
    fn footprint(&self, lane: HistoryLane) -> Result<ArtifactStoreOneItemFootprint, String> {
        let authority = self.authority.as_ref().ok_or_else(|| "batch source lost its exact app-owned item authority".to_string())?;
        let description = self.description.as_deref();
        let mut total = ArtifactStoreOneItemFootprint { work_items: 0, retained_bytes: 0 };
        for input in &self.inputs {
            let item = authority.preflight(input, description, lane)?;
            if !item.is_admissible() {
                return Err("one-item preparation footprint exceeds its fixed item or byte capacity".into());
            }
            total = total.merged(item);
        }
        Ok(total)
    }
}

impl<P: Send, Mutation, A: ArtifactStoreBatchItemAuthority<P, Mutation>> ArtifactStoreBatchSource<P, Mutation> for ArtifactStoreBatchSourceOf<P, Mutation, A> {
    fn remaining(&self) -> usize {
        self.inputs.len()
    }

    fn begin_next(&mut self, request: ArtifactStoreBatchItemRequest<P>) -> Result<Box<dyn ArtifactStoreOneItemPreparation<P, Mutation>>, String> {
        let authority = self.authority.as_ref().ok_or_else(|| "batch source lost its exact app-owned item authority".to_string())?;
        let mutation = self.inputs.pop().ok_or_else(|| "batch source was advanced past its last admitted item".to_string())?;
        let ArtifactStoreBatchItemRequest { operation, generation, base_revision, lane, authority: live, base } = request;
        let item = ArtifactStoreOneItemPreparationRequest { operation, generation, base_revision, lane, authority: live, description: self.description.take(), base, mutation };
        match authority.begin(item) {
            Ok(preparation) => Ok(preparation),
            Err(item) => {
                let (base, mutation, description) = item.into_owners();
                let _ = base.return_to_registry();
                self.inputs.push(mutation);
                self.description = description;
                Err("app-owned one-item preparation factory rejected its exact owner bundle".into())
            }
        }
    }

    fn close_step(&mut self, grant: ArtifactStoreOneItemGrant) -> SnapshotRetirementStep {
        if grant.maximum_items == 0 {
            return SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 };
        }
        if self.inputs.pop().is_some() {
            return SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 };
        }
        if let Some(description) = self.description.take() {
            return SnapshotRetirementStep::Pending { released_items: 0, released_bytes: description.len() };
        }
        if self.authority.take().is_some() {
            return SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 };
        }
        SnapshotRetirementStep::Complete
    }

    fn terminal_is_empty(&self) -> bool {
        self.inputs.is_empty() && self.description.is_none() && self.authority.is_none()
    }
}
//#endregion 🧺️BatchSource

//#region 🧩️MemberOneItemPublication
/// 📨 Owned member wire, transferred without decoding or cloning at the composition boundary.
#[derive(Debug)]
pub struct MemberStoreOneItemWire {
    pub schema: String,
    pub bytes: Vec<u8>,
}

/// 🧾 Exact member revision and grouped-history metadata accompanying one owned wire item.
pub struct MemberStoreOneItemWireRequest {
    pub operation: semio_framework_job::OperationId,
    pub expected_generation: u64,
    pub expected_revision: [u8; 32],
    pub actor: String,
    pub group_id: Option<String>,
    pub wire: MemberStoreOneItemWire,
    pub description: Option<String>,
}

/// 🏭 A member's retained decoder and semantic preparation, never a generic `decode_op` fallback.
pub trait MemberStoreOneItemWirePreparationFactory<P, Mutation>: Send + Sync {
    fn preflight(&self, wire: &MemberStoreOneItemWire, description: Option<&str>, lane: HistoryLane) -> Result<ArtifactStoreOneItemFootprint, String>;
    fn begin(&self, request: ArtifactStoreOneItemPreparationRequest<P, MemberStoreOneItemWire>) -> Result<Box<dyn ArtifactStoreOneItemPreparation<P, Mutation>>, ArtifactStoreOneItemPreparationRequest<P, MemberStoreOneItemWire>>;
}

/// 🪪 Erased retained publication; only its exact member may advance the typed candidate.
pub trait ErasedMemberStoreOneItemPublication: Send {
    fn as_any_mut(&mut self) -> &mut dyn std::any::Any;
    fn phase(&self) -> ArtifactStoreOneItemPublicationPhase;
    fn progress(&self) -> ArtifactStoreOneItemCheckpoint;
    fn fault(&self) -> Option<&str>;
    fn retry(&mut self) -> bool;
    fn acknowledge(&mut self) -> bool;
    fn begin_close(&mut self);
    fn close_step(&mut self, grant: ArtifactStoreOneItemGrant) -> Result<SnapshotRetirementStep, semio_framework_value::ValueError>;
    fn terminal_is_empty(&self) -> bool;
}

struct MemberStoreOneItemPublication<P, Mutation> {
    member: Option<Arc<SnapshotReadLeaseRegistry>>,
    publication: ArtifactStoreBatchPublication<P, Mutation>,
    group_history: Option<ArtifactStoreHistoryCommitReservation>,
    group_displaced: Option<ArtifactStoreDisplacedOwnerReservation>,
}

impl<P: Send + Sync + 'static, Mutation: Send + 'static> ErasedMemberStoreOneItemPublication for MemberStoreOneItemPublication<P, Mutation> {
    fn as_any_mut(&mut self) -> &mut dyn std::any::Any {
        self
    }

    fn phase(&self) -> ArtifactStoreOneItemPublicationPhase {
        self.publication.phase()
    }

    fn progress(&self) -> ArtifactStoreOneItemCheckpoint {
        self.publication.progress()
    }

    fn fault(&self) -> Option<&str> {
        self.publication.fault()
    }

    fn retry(&mut self) -> bool {
        self.publication.retry()
    }

    fn acknowledge(&mut self) -> bool {
        self.publication.acknowledge()
    }

    fn begin_close(&mut self) {
        self.publication.begin_close();
    }

    fn close_step(&mut self, grant: ArtifactStoreOneItemGrant) -> Result<SnapshotRetirementStep, semio_framework_value::ValueError> {
        if self.group_history.is_some() || self.group_displaced.is_some() {
            return Ok(SnapshotRetirementStep::Blocked);
        }
        if !self.publication.terminal_is_empty() {
            return self.publication.close_step(grant).map(|step| if step == SnapshotRetirementStep::Complete { SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 } } else { step });
        }
        if grant.maximum_items == 0 {
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
        }
        if self.member.take().is_some() {
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        Ok(SnapshotRetirementStep::Complete)
    }

    fn terminal_is_empty(&self) -> bool {
        self.member.is_none() && self.publication.terminal_is_empty() && self.group_history.is_none() && self.group_displaced.is_none()
    }
}

impl<P, Mutation> Drop for MemberStoreOneItemPublication<P, Mutation> {
    fn drop(&mut self) {
        assert!(std::thread::panicking() || (self.member.is_none() && self.publication.terminal_is_empty() && self.group_history.is_none() && self.group_displaced.is_none()), "member publication reached Drop before exact member, reservation, and candidate retirement");
    }
}
//#endregion 🧩️MemberOneItemPublication

/// 🔄 Persistent store-side operation phases. Publication and ACK are distinct turns; close
/// remains observable until the domain owner proves exact terminal emptiness.
#[derive(Clone, Copy, Debug, PartialEq, Eq, ToValue, FromValue)]
#[value(rename_all = "camelCase")]
pub enum ArtifactStoreOneItemPublicationPhase {
    Preparing,
    PreparingCursor,
    PreflightingCommit,
    Publishing,
    AwaitingAck,
    Closing,
    Complete,
    Fault,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ArtifactStoreOneItemAdvance {
    Progress(ArtifactStoreOneItemCheckpoint),
    Published(LaneItemReceipt),
    AwaitingAck(LaneItemReceipt),
    Complete,
    Blocked,
}

/// 🚫 Exact owners returned when the app has no retained factory, preflight rejects, or the
/// store's live base authority no longer matches. The whole admitted gesture comes back in the
/// order it was offered, so the caller can retry or retire it without reconstructing anything.
#[derive(Debug)]
pub struct ArtifactStoreBatchAdmissionRejected<Mutation> {
    pub reason: String,
    pub mutations: Vec<Mutation>,
    pub description: Option<String>,
}

impl<Mutation> ArtifactStoreBatchAdmissionRejected<Mutation> {
    pub fn into_owners(self) -> (String, Vec<Mutation>, Option<String>) {
        (self.reason, self.mutations, self.description)
    }
}

/// 🧾️ One gesture's staged edit. Every admitted mutation is folded into these exact owners against
/// the running post root, so the whole gesture commits as ONE `Edit` in ONE history ledger slot and
/// is ONE undo step. It carries its own retirement authority: a cancelled batch retires the staged
/// forwards, inverses, metadata and post root one owner per bounded turn.
struct ArtifactStoreBatchStage<P, Mutation> {
    edit: Box<Edit<Mutation>>,
    post: Option<Arc<P>>,
    next_clock: HybridLogicalTimestamp,
    local_actor: Option<String>,
    applied_edit_id: String,
    tail_edit_id: String,
    digest: [u8; 32],
    folded: usize,
    completed_items: u32,
    completed_bytes: u64,
    mutation_retirement: Option<Arc<dyn ArtifactOwnedValueRetirementFactory<Mutation>>>,
    snapshot_retirement: Option<Arc<dyn SnapshotRetirementFactory<P>>>,
    retiring: Option<Box<dyn ErasedSnapshotRetirement>>,
}

impl<P, Mutation> ArtifactStoreBatchStage<P, Mutation> {
    fn checkpoint(&self) -> ArtifactStoreOneItemCheckpoint {
        ArtifactStoreOneItemCheckpoint { cursor: self.folded as u32, completed_items: self.completed_items, completed_bytes: self.completed_bytes, digest: self.digest }
    }

    fn close_step(&mut self, grant: ArtifactStoreOneItemGrant) -> Result<SnapshotRetirementStep, semio_framework_value::ValueError> {
        if let Some(owner) = self.retiring.as_mut() {
            let step = owner.close_step(grant.maximum_items.min(1), grant.maximum_bytes)?;
            if step != SnapshotRetirementStep::Complete {
                return Ok(step);
            }
            if !owner.terminal_is_empty() {
                return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "staged batch owner retirement reported complete without terminal emptiness"));
            }
            self.retiring = None;
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if grant.maximum_items == 0 {
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
        }
        if let Some(value) = self.edit.inverse.pop().or_else(|| self.edit.forwards.pop()) {
            let factory = self.mutation_retirement.as_ref().ok_or_else(|| semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "staged batch edit lacks its exact mutation retirement authority"))?;
            self.retiring = Some(factory.retire_owned(value));
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
        }
        if self.edit.mutation_meta.pop().is_some() {
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if let Some(post) = self.post.take() {
            let factory = self.snapshot_retirement.as_ref().ok_or_else(|| semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "staged batch root lacks its exact snapshot retirement authority"))?;
            self.retiring = Some(factory.retire(post));
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
        }
        for value in [&mut self.edit.id, &mut self.applied_edit_id, &mut self.tail_edit_id, &mut self.edit.started_at] {
            if !value.is_empty() {
                let released = value.len();
                value.clear();
                value.shrink_to_fit();
                return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: released });
            }
        }
        for value in [&mut self.edit.actor, &mut self.edit.line, &mut self.edit.description, &mut self.edit.verb, &mut self.edit.finished_at, &mut self.local_actor] {
            if let Some(taken) = value.take() {
                return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: taken.len() });
            }
        }
        if self.mutation_retirement.take().is_some() || self.snapshot_retirement.take().is_some() {
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        Ok(SnapshotRetirementStep::Complete)
    }

    fn terminal_is_empty(&self) -> bool {
        self.retiring.is_none()
            && self.post.is_none()
            && self.edit.forwards.is_empty()
            && self.edit.inverse.is_empty()
            && self.edit.mutation_meta.is_empty()
            && self.edit.id.is_empty()
            && self.applied_edit_id.is_empty()
            && self.tail_edit_id.is_empty()
            && self.edit.started_at.is_empty()
            && self.edit.actor.is_none()
            && self.edit.line.is_none()
            && self.edit.description.is_none()
            && self.edit.verb.is_none()
            && self.edit.finished_at.is_none()
            && self.local_actor.is_none()
            && self.mutation_retirement.is_none()
            && self.snapshot_retirement.is_none()
    }
}

/// 📬️ Retained batched publication authority: ONE user gesture, N admitted mutations, ONE staged
/// `Edit`, ONE history ledger slot, ONE undo step. Each turn folds at most one mutation — the
/// single-mutation case is simply the N = 1 batch. It never calls `apply_one`, `apply_command`,
/// `replay_mutations`, `pump`, or `flush_outbound`.
pub struct ArtifactStoreBatchPublication<P, Mutation> {
    operation: semio_framework_job::OperationId,
    expected_generation: u64,
    expected_revision: [u8; 32],
    lane: HistoryLane,
    footprint: ArtifactStoreOneItemFootprint,
    admitted_items: usize,
    authority: Option<Arc<ArtifactStoreOneItemLiveAuthority>>,
    authority_retirement: Option<Box<dyn ErasedSnapshotRetirement>>,
    source: Option<Box<dyn ArtifactStoreBatchSource<P, Mutation>>>,
    preparation: Option<Box<dyn ArtifactStoreOneItemPreparation<P, Mutation>>>,
    item_closing: bool,
    stage: Option<Box<ArtifactStoreBatchStage<P, Mutation>>>,
    retained_checkpoint: ArtifactStoreOneItemCheckpoint,
    receipt: Option<LaneItemReceipt>,
    attempts: u8,
    published: bool,
    cancel_requested: bool,
    close_started: bool,
    fault: Option<String>,
    phase: ArtifactStoreOneItemPublicationPhase,
    verb: Option<String>,
    transaction: Option<protocol::TransactionRef>,
    outbound: bool,
    announce_from: usize,
    announce_items: usize,
    transaction_open: bool,
}

impl<P, Mutation> ArtifactStoreBatchPublication<P, Mutation> {
    pub fn operation(&self) -> semio_framework_job::OperationId {
        self.operation
    }

    pub fn phase(&self) -> ArtifactStoreOneItemPublicationPhase {
        self.phase
    }

    /// 🏷️ The id of the action or command this gesture publishes for, stamped on the gesture's new edit (an amend keeps
    /// the verb of the edit it extends). See [`crate::os_spr::command::Edit::verb`].
    pub fn set_verb(&mut self, verb: Option<String>) {
        self.verb = verb.filter(|value| !value.is_empty());
    }

    /// 🧾️ The committed tool transaction this gesture publishes for, stamped on every staged operation.
    pub fn transaction(&self) -> Option<&protocol::TransactionRef> {
        self.transaction.as_ref()
    }

    /// 🫙️ Keeps this gesture's tool transaction open after its operations land: they join the transaction's open edit (the
    /// first streamed gesture opens it) and nothing is announced until a closing gesture or `CommitTransaction` commits
    /// it. A closing gesture (the default) that carries the open transaction's ref appends to its edit and commits it.
    pub fn set_transaction_open(&mut self, open: bool) {
        self.transaction_open = open;
    }

    /// 🔢️ How many mutations this gesture admitted, and how many of them are already staged.
    pub fn admitted_items(&self) -> usize {
        self.admitted_items
    }

    pub fn staged_items(&self) -> usize {
        self.stage.as_ref().map_or(0, |stage| stage.folded)
    }

    /// 🎁️ Hands the staged gesture edit back as ONE sealed candidate so a group-atomic decision can
    /// linearize several stores' candidates before any of them becomes visible. Only the commit turn
    /// may call it, and the publication then owns nothing but its receipt lane.
    fn take_staged_prepared(&mut self) -> Option<ArtifactStoreOneItemPrepared<P, Mutation>> {
        if self.phase != ArtifactStoreOneItemPublicationPhase::Publishing || self.stage.as_ref().is_none_or(|stage| stage.post.is_none()) {
            return None;
        }
        let authority = Arc::clone(self.authority.as_ref()?);
        let stage = self.take_stage()?;
        let ArtifactStoreBatchStage { edit, post, local_actor: _, applied_edit_id, tail_edit_id, digest, .. } = *stage;
        let post = post.expect("validated staged batch post root");
        Some(authority.seal_prepared_owned(edit, post, digest, [authority.actor.clone(), applied_edit_id, tail_edit_id]))
    }

    fn take_stage(&mut self) -> Option<Box<ArtifactStoreBatchStage<P, Mutation>>> {
        let stage = self.stage.take()?;
        self.retained_checkpoint = stage.checkpoint();
        Some(stage)
    }

    /// 📍️ Gesture-wide progress survives folding, publication, acknowledgement, and owner retirement.
    pub fn progress(&self) -> ArtifactStoreOneItemCheckpoint {
        if self.close_started { return self.retained_checkpoint; }
        let staged = self.stage.as_ref().map_or(self.retained_checkpoint, |stage| stage.checkpoint());
        let item = if self.item_closing { ArtifactStoreOneItemCheckpoint::default() } else { self.preparation.as_ref().map_or_else(ArtifactStoreOneItemCheckpoint::default, |owner| owner.checkpoint()) };
        ArtifactStoreOneItemCheckpoint {
            cursor: staged.cursor,
            completed_items: staged.completed_items.saturating_add(item.completed_items),
            completed_bytes: staged.completed_bytes.saturating_add(item.completed_bytes),
            digest: if item.digest == [0; 32] { staged.digest } else { item.digest },
        }
    }

    pub fn fault(&self) -> Option<&str> {
        self.fault.as_deref()
    }

    pub fn retry(&mut self) -> bool {
        if self.phase != ArtifactStoreOneItemPublicationPhase::AwaitingAck || self.attempts >= ARTIFACT_STORE_ONE_ITEM_MAXIMUM_RETRIES {
            return false;
        }
        self.attempts += 1;
        true
    }

    pub fn acknowledge(&mut self) -> bool {
        if self.phase != ArtifactStoreOneItemPublicationPhase::AwaitingAck || self.outbound {
            return false;
        }
        self.phase = ArtifactStoreOneItemPublicationPhase::Closing;
        self.begin_close();
        true
    }

    pub fn begin_close(&mut self) {
        if self.close_started {
            return;
        }
        self.retained_checkpoint = self.progress();
        self.close_started = true;
        self.phase = if self.phase == ArtifactStoreOneItemPublicationPhase::Complete { ArtifactStoreOneItemPublicationPhase::Complete } else { ArtifactStoreOneItemPublicationPhase::Closing };
        if let Some(owner) = self.preparation.as_mut() {
            if !self.published {
                self.cancel_requested = true;
                owner.cancel();
            }
            owner.begin_close();
        }
    }

    pub fn close_step(&mut self, grant: ArtifactStoreOneItemGrant) -> Result<SnapshotRetirementStep, semio_framework_value::ValueError>
    where
        P: Send + Sync + 'static,
    {
        self.begin_close();
        if let Some(owner) = self.preparation.as_mut() {
            let step = owner.close_step(ArtifactStoreOneItemGrant { maximum_items: grant.maximum_items.min(1), maximum_bytes: grant.maximum_bytes })?;
            if step != SnapshotRetirementStep::Complete {
                return Ok(step);
            }
            if !owner.terminal_is_empty() {
                return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "one-item preparation reported complete without terminal emptiness"));
            }
            self.preparation = None;
            self.item_closing = false;
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if let Some(source) = self.source.as_mut() {
            let step = source.close_step(ArtifactStoreOneItemGrant { maximum_items: grant.maximum_items.min(1), maximum_bytes: grant.maximum_bytes });
            if step != SnapshotRetirementStep::Complete {
                return Ok(step);
            }
            if !source.terminal_is_empty() {
                return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "batch source reported complete without terminal emptiness"));
            }
            self.source = None;
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if let Some(stage) = self.stage.as_mut() {
            let step = stage.close_step(grant)?;
            if step != SnapshotRetirementStep::Complete {
                return Ok(step);
            }
            if !stage.terminal_is_empty() {
                return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "staged batch edit reported complete without terminal emptiness"));
            }
            self.stage = None;
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if grant.maximum_items == 0 {
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
        }
        if self.verb.take().is_some() {
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if self.receipt.take().is_some() {
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if let Some(owner) = self.authority_retirement.as_mut() {
            let step = owner.close_step(1, grant.maximum_bytes)?;
            if step != SnapshotRetirementStep::Complete { return Ok(step); }
            if !owner.terminal_is_empty() { return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "batch authority reported complete without terminal emptiness")); }
            self.authority_retirement = None;
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if let Some(authority) = self.authority.take() {
            self.authority_retirement = Some(authority.retire());
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if let Some(fault) = self.fault.as_mut().filter(|fault| !fault.is_empty()) {
            let scalar = fault.chars().next_back().expect("nonempty batch fault");
            if scalar.len_utf8() > grant.maximum_bytes {
                return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
            }
            fault.pop();
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: scalar.len_utf8() });
        }
        self.fault = None;
        self.phase = ArtifactStoreOneItemPublicationPhase::Complete;
        Ok(SnapshotRetirementStep::Complete)
    }

    pub fn terminal_is_empty(&self) -> bool {
        self.phase == ArtifactStoreOneItemPublicationPhase::Complete && self.preparation.is_none() && self.source.is_none() && self.stage.is_none() && self.authority.is_none() && self.authority_retirement.is_none() && self.receipt.is_none() && self.fault.is_none() && self.verb.is_none()
    }

    /// 🔬️ The first owner `close_step` would try to retire, in its exact drain order, plus whether
    /// `begin_close` has run. `close_step` answers only `Pending`/`Blocked`/`Complete`, so a
    /// publication that will not reach terminal emptiness under repeated one-item grants cannot say
    /// WHICH of its seven owners refuses. This names it.
    pub fn closing_owner_witness(&self) -> &'static str {
        if !self.close_started {
            return "close-not-started";
        }
        if self.preparation.is_some() {
            "preparation"
        } else if self.source.is_some() {
            "source"
        } else if self.stage.is_some() {
            "stage"
        } else if self.verb.is_some() {
            "verb"
        } else if self.receipt.is_some() {
            "receipt"
        } else if self.authority_retirement.is_some() {
            "authority-retirement"
        } else if self.authority.is_some() {
            "authority"
        } else if self.fault.is_some() {
            "fault"
        } else {
            "none"
        }
    }
}

impl<P, Mutation> Drop for ArtifactStoreBatchPublication<P, Mutation> {
    fn drop(&mut self) {
        assert!(std::thread::panicking() || (self.terminal_is_empty()), "batched artifact-store publication reached Drop without its exact terminal-empty witness");
    }
}
//#endregion 📬️OneItemPublication

pub struct ArtifactStore<P, Mutation>
where
    P: Clone + ToValue + FromValue,
    Mutation: Clone + ToValue + FromValue + self::Mutation<P>,
{
    envelope: std::mem::ManuallyDrop<ArtifactEnvelope<P, Mutation>>,
    envelope_detached: bool,
    backbone: std::mem::ManuallyDrop<Option<Backbones>>,
    dag: std::mem::ManuallyDrop<crate::os_spr::MutationDag>,
    applied_edit_ids: std::mem::ManuallyDrop<crate::os_vcs::HistoryPageStack<String>>,
    redo_edit_ids: std::mem::ManuallyDrop<crate::os_vcs::HistoryPageStack<String>>,
    edit_sequence: i32,
    generation: u64,
    last_projection_cause: Option<ArtifactProjectionCause>,
    /// 🧭️ The checkpoint new commits parent onto; advances on commit/checkout/switch. Not
    /// part of the wire envelope — callers that reconstruct the store per call (e.g. a WASM plugin)
    /// must save/restore it themselves via {@link current_checkpoint_id}/{@link set_current_checkpoint_id}.
    current_checkpoint_id: std::mem::ManuallyDrop<Option<String>>,
    /// 🖋️ Identity of the local actor driving this store. Set from each local `Apply`/
    /// `Apply`'s operation author; compared against `Edit.actor` so undo never touches foreign
    /// edits. Not part of the wire envelope — callers that reconstruct the store per call must
    /// save/restore it via {@link local_actor_id}/{@link set_local_actor_id}.
    local_actor_id: std::mem::ManuallyDrop<Option<String>>,
    /// ⚖️ This store's local `crate::os_spr::MergePolicy` — authority-local state, defaults
    /// to `Normal`, never carried on the wire envelope (never part of an artifact's shared history).
    merge_policy: crate::os_spr::MergePolicy,
    /// ⏰️ Monotone hybrid logical clock: `tick`s on every local apply, `merge`s in a remote
    /// tick on every ingest — replaces the old per-call `HybridLogicalTimestamp::new(0, now_ms())`
    /// construction in `replay_mutations`. Not part of the wire envelope.
    clock: HybridLogicalTimestamp,
    /// 🧬️ Stable identity of the immutable genesis content, computed once on load/reset rather
    /// than by a composing app's action dispatch.
    initial_digest: [u8; 32],
    /// 🧬️ Fixed cursor digest refreshed at mutation boundaries and cloned by composition reads.
    content_revision: [u8; 32],
    /// 🧬️ Prefix-authenticated applied/redo cursor state. Tail mutations update one record;
    /// load/reset and the already-cold interior-history paths rebuild only their changed suffix.
    revision_accumulator: std::mem::ManuallyDrop<CursorRevisionAccumulator>,
    /// ⚡️ The live, incrementally-maintained RAW fold of `initial_snapshot` over every
    /// `forwards` operation in `applied_edit_ids` order — i.e. exactly what a full
    /// {@link materialize_document_snapshot} replay computes BEFORE its single final
    /// {@link Mutation::reconcile} call. Kept in lock-step by every mutating command below instead of
    /// replaying on every read, so `snapshot()`/`Apply`/`AppendTransaction` are O(new work) instead of
    /// O(total history). Cold-path commands (checkout/switch/set_state, which reassign
    /// `applied_edit_ids` wholesale rather than appending) fall back to a full raw-fold recompute —
    /// see `fold_current`. Differential ground truth: `test_support::assert_live_equals_replay`.
    current: std::mem::ManuallyDrop<Arc<P>>,
    current_detached: bool,
    /// 🪢️ `(edit_id, snapshot right before that edit's forwards were first applied)` for
    /// whichever edit is CURRENTLY the tail of `applied_edit_ids` — refreshed by `Apply`/`AppendTransaction`
    /// (fresh-edit branch)/`Redo`, left untouched by further amends to the same edit (so it always
    /// points at the state before the edit as a whole, not before its latest increment). Powers an
    /// O(1) `Undo` of exactly this edit; any other undo (not the cached tail, or `None`) falls back
    /// to `fold_current` — always correct, just not always O(1).
    tail_undo_cache: std::mem::ManuallyDrop<Option<(String, Arc<P>)>>,
    /// ✏️ The effective supersessions `current` was projected with ([`crate::os_spr::HistoryFold::supersessions`]) —
    /// what {@link reproject} compares a fresh fold against to find the first position whose effective input changed.
    supersessions: std::mem::ManuallyDrop<EffectiveSupersessions>,
    /// 🧭️ Retained projections after applied prefixes ([`PrefixSnapshot`]), at most [`PREFIX_SNAPSHOT_RING_CAPACITY`]
    /// at an adaptive stride: "the state before operation X" costs at most one stride of folds. An entry is valid only
    /// while its forwards-only digest names the live effective prefix; every evicted entry retires through the snapshot
    /// retirement factory (or only drops its alias while another owner holds the root), never a bare drop.
    prefix_ring: std::mem::ManuallyDrop<Vec<PrefixSnapshot<P>>>,
    /// 📍️ The first applied position whose revision record a replay rewrote (effective input, inverse or messages);
    /// the next {@link bump} rebuilds the cursor revision from there.
    revision_dirty_from: Option<usize>,
    /// 🪞️ The first applied and redo positions whose ids changed since {@link bump} last mirrored them ([`StackMirrorDirt`]).
    mirror_dirt: StackMirrorDirt,
    /// ✂️ The first applied position whose id, forwards or effective input changed since the prefix ring was last pruned: every
    /// ring entry past it is stale ({@link prune_prefix_ring}).
    prefix_ring_dirty_from: usize,
    /// 🧭️ The greatest `(hlc)` event key of the log while the live cursor — applied, redo, checkpoint, alternative and
    /// supersessions — is exactly that log's fold at this replica's head; `None` until the next full fold proves it again. What
    /// lets a local edit sorting after every event join the fold as its tail without folding the log ({@link folded_tail}).
    fold_frontier: Option<(u64, u64, u64)>,
    /// 🟰️ Snapshot equality that lets a Report replay stop where it meets the previous projection
    /// ({@link enable_convergence_early_exit}).
    snapshot_equality: Option<fn(&P, &P) -> bool>,
    /// ♻️ Exact domain-owned bounded disposer for immutable snapshot roots transferred out
    /// of this store. Composition retirement fails closed until the owner installs it.
    snapshot_retirement_factory: std::mem::ManuallyDrop<Option<Arc<dyn SnapshotRetirementFactory<P>>>>,
    initial_snapshot_retirement_factory: std::mem::ManuallyDrop<Option<Arc<dyn ArtifactOwnedValueRetirementFactory<P>>>>,
    mutation_retirement_factory: std::mem::ManuallyDrop<Option<Arc<dyn ArtifactOwnedValueRetirementFactory<Mutation>>>>,
    snapshot_read_leases: std::mem::ManuallyDrop<Arc<SnapshotReadLeaseRegistry>>,
    displaced_retirements: std::mem::ManuallyDrop<ArtifactStoreDisplacedRetirements>,
    owned_disposer: std::mem::ManuallyDrop<Option<Box<dyn ArtifactStoreOwnedDisposer<P, Mutation>>>>,
    owned_disposer_terminal: bool,
    one_item_preparation_factory: std::mem::ManuallyDrop<Option<Arc<dyn ArtifactStoreOneItemPreparationFactory<P, Mutation>>>>,
    one_item_wire_preparation_factory: std::mem::ManuallyDrop<Option<Arc<dyn MemberStoreOneItemWirePreparationFactory<P, Mutation>>>>,
    /// 📨️ Transient handoff from whichever `dispatch_inner` arm actually produced messages
    /// this call (`apply_command`/`ingest_remote`/`resolve_conflict`) to `dispatch`,
    /// which drains it into the returned `CommandReceipt`. Reset at the top of every `dispatch`
    /// call; every other arm leaves it at its `Default`. Not part of the wire envelope.
    /// 🪆️ Member-addressed backbone messages this store pumped off its own transport but does
    /// NOT own: a composed document's children are replicas of their own, and only the composing app
    /// knows which live member a `(slot, child_id)` lane names. Buffered here so a pump inside an
    /// ordinary `dispatch` can never silently drop a child's remote edit, drained by
    /// {@link take_member_inbound}, and retired with the transport when the store closes.
    member_inbox: VecDeque<BackboneMessage>,
    /// 🏷️ The id of the action or command whose `Apply` this store is dispatching, stamped on the edit it mints (an
    /// amend keeps the verb of the edit it extends). Set by the dispatching runtime via
    /// {@link set_authoring_verb}; not part of the wire envelope.
    authoring_verb: Option<String>,
    /// 🐢️ How far one turn of a deferred remote reprojection replays; `None` replays inside the ingest.
    replay_budget: Option<ReplayTurnBudget>,
    /// ⏱️ How far one turn of a deferred local history step replays; `None` replays inside the dispatch.
    local_replay_budget: Option<ReplayTurnBudget>,
    /// 🐢️ The history change admitted but not adopted yet ([`Self::step_reprojection`]).
    pending_reprojection: Option<PendingReprojection<P, Mutation>>,
    pending_report: std::mem::ManuallyDrop<PendingCommandReport>,
    durable_group_root: std::mem::ManuallyDrop<Option<durable_group::ArtifactStoreDurableGroupRootV1<P>>>,
}

struct ArtifactStoreDocumentRootCommitAuthority<P, Mutation> {
    snapshot: Arc<dyn SnapshotRetirementFactory<P>>,
    initial_snapshot: Arc<dyn ArtifactOwnedValueRetirementFactory<P>>,
    mutation: Arc<dyn ArtifactOwnedValueRetirementFactory<Mutation>>,
}

struct ArtifactStoreHistoryCommitReservation {
    history: ArtifactHistoryReservation,
    rejected_owner: ArtifactStoreDisplacedOwnerReservation,
}

/// 📨️ See `ArtifactStore::pending_report`'s doc.
#[derive(Default)]
struct PendingCommandReport {
    /// 🎯️ Overrides `dispatch`'s tail-diff `edit_ids` guess — needed once a merge can insert
    /// mid-history (`ingest_remote`/`resolve_conflict`), where "everything past `before`" no longer
    /// names only the newly-landed edits.
    edit_ids: Option<Vec<String>>,
    messages: Vec<crate::os_spr::EditMessages>,
    worst: Option<semio_framework_diagnostic::Severity>,
    /// 📤️ Every event this command authored (edit operations, history transitions), in authoring
    /// order — announced outbound as one `BackboneMessage::Mutations` batch when the command ends.
    outbound: Vec<crate::os_spr::MutationEnvelope>,
}

struct ArtifactStorePendingReportRetirement {
    report: std::mem::ManuallyDrop<Option<PendingCommandReport>>,
    active: std::mem::ManuallyDrop<Option<Box<dyn ErasedSnapshotRetirement>>>,
}

impl ArtifactStorePendingReportRetirement {
    fn new(report: PendingCommandReport) -> Self {
        Self { report: std::mem::ManuallyDrop::new(Some(report)), active: std::mem::ManuallyDrop::new(None) }
    }
}

impl ErasedSnapshotRetirement for ArtifactStorePendingReportRetirement {
    fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<SnapshotRetirementStep, semio_framework_value::ValueError> {
        if maximum_items == 0 {
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
        }
        if let Some(active) = self.active.as_mut() {
            return match active.close_step(maximum_items, maximum_bytes)? {
                SnapshotRetirementStep::Complete => {
                    if !active.terminal_is_empty() {
                        return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "artifact store pending-report child reported Complete without terminal ownership"));
                    }
                    drop(self.active.take());
                    Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 })
                }
                step => Ok(step),
            };
        }
        let Some(report) = self.report.as_mut() else { return Ok(SnapshotRetirementStep::Complete) };
        if let Some(envelope) = report.outbound.pop() {
            *self.active = Some(Box::new(ArtifactStoreConflictRetirement::causal_envelope(envelope)));
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
        }
        if let Some(entry) = report.messages.pop() {
            *self.active = Some(Box::new(ArtifactStoreMessageLedgerRetirement::new(entry.edit_id, entry.messages)));
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
        }
        if let Some(edit_id) = report.edit_ids.as_mut().and_then(Vec::pop) {
            *self.active = Some(Box::new(ArtifactStoreStringRetirement::new(edit_id)));
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
        }
        report.edit_ids = None;
        report.worst = None;
        let report = self.report.take().expect("terminal pending report remains present");
        drop(report);
        Ok(SnapshotRetirementStep::Complete)
    }

    fn terminal_is_empty(&self) -> bool {
        self.report.is_none() && self.active.is_none()
    }
}

impl Drop for ArtifactStorePendingReportRetirement {
    fn drop(&mut self) {
        assert!(std::thread::panicking() || (self.terminal_is_empty()), "artifact store pending-report retirement reached Drop before its exact terminal-empty witness");
    }
}









/// 🖋️ Derives an edit's authoring actor from its per-operation metadata (the author of its
/// first operation), so a local edit records who produced it for later `UndoPolicy` classification.
async fn edit_actor_from_meta(mutation_meta: &[MutationMeta]) -> Option<String> {
    mutation_meta.first().and_then(|meta| meta.author_id.clone()).map(|actor_id| actor_id.0)
}

async fn validate_composition_pins(pins: &[crate::os_vcs::CompositionPin]) -> Result<(), VcsError> {
    let mut children = HashSet::new();
    for pin in pins {
        let child_uri = pin.child_ref.to_uri();
        let reparsed = crate::os_io::ArtifactRef::parse_uri(&child_uri).map_err(VcsError::ValidationFailed)?;
        if reparsed != pin.child_ref || pin.child_ref.artifact_id.trim().is_empty() || pin.checkpoint_id.trim().is_empty() {
            return Err(VcsError::ValidationFailed(format!("invalid composition pin {child_uri}")));
        }
        if !children.insert(child_uri.clone()) {
            return Err(VcsError::ValidationFailed(format!("checkpoint repeats composition child {child_uri}")));
        }
    }
    Ok(())
}

/// 🎚️ Atomically adopts a retained config runtime after typed Pack and history validation.
pub fn config_store_from_initialized_runtime_with_owners<P, Mutation>(
    mut envelope: ArtifactEnvelope<P, Mutation>,
    runtime: ArtifactStoreInitializationRuntime<P>,
    generation: u64,
    owners: DocumentStoreOwners<P, Mutation>,
) -> ConfigStore<P, Mutation>
where
    P: Clone + ToValue + FromValue,
    Mutation: Clone + ToValue + FromValue + self::Mutation<P>,
{
    let (current, applied_edit_ids, redo_edit_ids, cursor, local_actor_id, dag, edit_sequence, clock, initial_digest, revision_accumulator, supersessions) = runtime.into_parts();
    let current_checkpoint_id = cursor.checkpoint_id.clone();
    envelope.cursor = Some(cursor);
    let content_revision = revision_accumulator.revision(current_checkpoint_id.as_deref());
    ArtifactStore {
        envelope: std::mem::ManuallyDrop::new(envelope),
        envelope_detached: false,
        backbone: std::mem::ManuallyDrop::new(None),
        dag: std::mem::ManuallyDrop::new(dag),
        applied_edit_ids: std::mem::ManuallyDrop::new(applied_edit_ids),
        redo_edit_ids: std::mem::ManuallyDrop::new(redo_edit_ids),
        edit_sequence,
        generation,
        last_projection_cause: None,
        current_checkpoint_id: std::mem::ManuallyDrop::new(current_checkpoint_id),
        local_actor_id: std::mem::ManuallyDrop::new(local_actor_id),
        member_inbox: VecDeque::new(),
        authoring_verb: None,
        replay_budget: None,
        local_replay_budget: None,
        pending_reprojection: None,
        merge_policy: crate::os_spr::MergePolicy::default(),
        clock,
        initial_digest,
        content_revision,
        revision_accumulator: std::mem::ManuallyDrop::new(revision_accumulator),
        current: std::mem::ManuallyDrop::new(Arc::new(current)),
        current_detached: false,
        tail_undo_cache: std::mem::ManuallyDrop::new(None),
        supersessions: std::mem::ManuallyDrop::new(supersessions),
        prefix_ring: std::mem::ManuallyDrop::new(Vec::with_capacity(PREFIX_SNAPSHOT_RING_CAPACITY)),
        revision_dirty_from: None,
        mirror_dirt: StackMirrorDirt::CLEAN,
        prefix_ring_dirty_from: usize::MAX,
        fold_frontier: None,
        snapshot_equality: None,
        snapshot_retirement_factory: std::mem::ManuallyDrop::new(Some(owners.snapshot_retirement)),
        initial_snapshot_retirement_factory: std::mem::ManuallyDrop::new(Some(owners.initial_snapshot_retirement)),
        mutation_retirement_factory: std::mem::ManuallyDrop::new(Some(owners.mutation_retirement)),
        snapshot_read_leases: std::mem::ManuallyDrop::new(Arc::new(SnapshotReadLeaseRegistry::new())),
        displaced_retirements: std::mem::ManuallyDrop::new(ArtifactStoreDisplacedRetirements::new()),
        owned_disposer: std::mem::ManuallyDrop::new(Some(owners.store_disposer)),
        owned_disposer_terminal: false,
        one_item_preparation_factory: std::mem::ManuallyDrop::new(owners.one_item_preparation),
        one_item_wire_preparation_factory: std::mem::ManuallyDrop::new(owners.one_item_wire_preparation),
        pending_report: std::mem::ManuallyDrop::new(PendingCommandReport::default()),
        durable_group_root: std::mem::ManuallyDrop::new(None),
    }
}

async fn checkpoint_identity(checkpoint: &Checkpoint, changes: &ArtifactHistoryLedger<Change>) -> String {
    content_addressed_checkpoint_id(checkpoint.parent_id.as_deref(), &checkpoint.change_ids, changes, checkpoint.message.as_deref(), &checkpoint.authors, &checkpoint.timestamp, &checkpoint.composition_pins).await
}

impl<P, Mutation> ArtifactStore<P, Mutation>
where
    P: Clone + ToValue + FromValue + ArtifactPack + Send + 'static,
    Mutation: Clone + ToValue + FromValue + self::Mutation<P> + OpBinary + OpText + Send + 'static,
{
    fn preflight_runtime_seed(identities: &[MutationId]) -> Result<(), VcsError> {
        let mut unique = HashSet::new();
        for identity in identities {
            if identity.0.len() > crate::os_spr::causal::MUTATION_DAG_IDENTIFIER_BYTES {
                return Err(VcsError::ValidationFailed("runtime causal seed identity exceeds its exact byte capacity".into()));
            }
            unique.insert(identity.0.as_str());
            if unique.len() > crate::os_spr::causal::MUTATION_DAG_CAPACITY {
                return Err(VcsError::ValidationFailed("runtime causal seed exceeds its exact identity capacity".into()));
            }
        }
        Ok(())
    }

    fn adopt_runtime_seed(identities: Vec<MutationId>) -> (crate::os_spr::MutationDag, Vec<String>) {
        let mut dag = crate::os_spr::MutationDag::new();
        let mut rejected = Vec::new();
        for identity in identities {
            match dag.seed_applied(identity) {
                Ok(()) => {}
                Err(owner) if owner.error == crate::os_spr::MutationDagError::Duplicate => rejected.push(owner.mutation_id.0),
                Err(_) => unreachable!("prevalidated causal seed admission cannot fail after owner adoption"),
            }
        }
        (dag, rejected)
    }

    fn seed_runtime_state(envelope: &ArtifactEnvelope<P, Mutation>, replica: u64) -> Result<(crate::os_spr::MutationDag, i32, HybridLogicalTimestamp, Vec<String>), VcsError> {
        let mut identities = Vec::new();
        let mut edit_sequence = 0;
        let mut clock = HybridLogicalTimestamp::new(replica, now_ms());
        for edit in &envelope.vcs.edits {
            edit_sequence = edit_sequence.max(edit.sequence_number);
            identities.push(MutationId(edit.id.clone()));
            identities.extend(crate::os_spr::mutation_ids_for_edit(edit));
            for meta in &edit.mutation_meta {
                clock.merge(&meta.timestamp);
            }
        }
        for transition in &envelope.transitions {
            identities.push(transition.mutation_id.clone());
            clock.merge(&transition.timestamp);
        }
        Self::preflight_runtime_seed(&identities)?;
        let (dag, rejected) = Self::adopt_runtime_seed(identities);
        Ok((dag, edit_sequence, clock, rejected))
    }

    /// 🚫️ A store is always constructed with no backbone attached — the envelope's
    /// `backbone` field is a descriptor of the last attachment, never an instruction to
    /// reconnect. Callers attach explicitly via {@link attach_backbone}/{@link attach_backbone_uri}.
    ///
    /// 🎯️ `applied_edit_ids`/`redo_edit_ids`/`current_checkpoint_id`/the active alternative
    /// and `current` are derived by folding the envelope's event log ([`fold_envelope_history`]) —
    /// the persisted history carries events only, so a save/load cycle restores the exact position
    /// by replaying them. `local_actor_id` is seeded from the tail applied edit's actor so
    /// `UndoPolicy::ExactBaseOnly`'s foreign-edit check keeps working immediately after reload (a
    /// real `VcsArtifactApp` overrides it anyway via `set_local_actor_id` on every dispatch).
    ///
    /// 🛡️ A REJECTED construction retires the candidate envelope it consumed. The envelope is
    /// a terminal shell whose `Drop` asserts its owners were detached ([`ArtifactEnvelope::into_owners`]),
    /// so letting a `?` drop it turned every malformed-document refusal — a dangling cursor edit id, a
    /// duplicated authoritative edit, an alternative pinned to a checkpoint that was never recorded —
    /// into a process abort instead of the `VcsError` the caller is meant to read. The candidate lives
    /// in a slot {@link construct} empties only on success; whatever is left is detached here.
    pub async fn new(envelope: ArtifactEnvelope<P, Mutation>) -> Result<Self, VcsError> {
        let mut candidate = Some(envelope);
        let constructed = Self::construct(&mut candidate).await;
        if let Some(rejected) = candidate {
            rejected.retire_unadopted();
        }
        constructed
    }

    async fn construct(candidate: &mut Option<ArtifactEnvelope<P, Mutation>>) -> Result<Self, VcsError> {
        let envelope = candidate.as_mut().expect("artifact store construction holds its candidate envelope");
        validate_durable_history(envelope).await?;
        let crate::os_spr::HistoryFold { applied: loaded_applied_edit_ids, redo: loaded_redo_edit_ids, checkpoint: current_checkpoint_id, alternative, supersessions, .. } = fold_envelope_history(envelope)?;
        envelope.active_alternative_id = alternative;
        validate_history_lanes(envelope, &loaded_applied_edit_ids, &loaded_redo_edit_ids).await?;
        let current = Self::fold_history(envelope, &loaded_applied_edit_ids, &supersessions).await?;
        let initial_digest = *semio_framework_hash::hash(&envelope.vcs.initial_snapshot.encode_pack()).as_bytes();
        let catalog = ArtifactStoreInitializationOwnerCatalog::try_new().map_err(|reason| VcsError::ValidationFailed(reason.into()))?;
        let ArtifactStoreInitializationOwnerCatalog { mut applied_edit_ids, mut redo_edit_ids, mut cursor_applied_edit_ids, mut cursor_redo_edit_ids, applied_revision, redo_revision } = catalog;
        cursor_applied_edit_ids.extend(loaded_applied_edit_ids.iter().cloned());
        cursor_redo_edit_ids.extend(loaded_redo_edit_ids.iter().cloned());
        applied_edit_ids.extend(loaded_applied_edit_ids);
        redo_edit_ids.extend(loaded_redo_edit_ids);
        envelope.cursor = Some(ArtifactCursor::new(cursor_applied_edit_ids, cursor_redo_edit_ids, current_checkpoint_id.clone()));
        let identity_digest = CursorRevisionAccumulator::hash_record(b"initial", &[envelope.id.as_bytes(), envelope.schema.as_bytes(), &initial_digest]);
        let mut revision_accumulator = CursorRevisionAccumulator { identity_digest, applied: applied_revision, redo: redo_revision, applied_tail_chains: None };
        revision_accumulator.reconcile::<P, Mutation>(&applied_edit_ids, &redo_edit_ids, &envelope.vcs.edits, &supersessions, StackMirrorDirt::ALL, None);
        let content_revision = revision_accumulator.revision(current_checkpoint_id.as_deref());
        let local_actor_id = applied_edit_ids.last().and_then(|edit_id| envelope.vcs.edits.find_near(|edit| edit.id == *edit_id)).and_then(|edit| edit.actor.clone());
        let (dag, edit_sequence, clock, rejected_seed_identities) = Self::seed_runtime_state(envelope, fresh_replica_clock().actor)?;
        let mut displaced_retirements = ArtifactStoreDisplacedRetirements::new();
        if !rejected_seed_identities.is_empty() {
            displaced_retirements.push_reserved(Box::new(ArtifactStoreStringVectorRetirement::new(rejected_seed_identities)));
        }
        let envelope = candidate.take().expect("an accepted construction takes its validated envelope exactly once");
        Ok(Self {
            envelope: std::mem::ManuallyDrop::new(envelope),
            envelope_detached: false,
            backbone: std::mem::ManuallyDrop::new(None),
            dag: std::mem::ManuallyDrop::new(dag),
            applied_edit_ids: std::mem::ManuallyDrop::new(applied_edit_ids),
            redo_edit_ids: std::mem::ManuallyDrop::new(redo_edit_ids),
            edit_sequence,
            generation: 0,
            last_projection_cause: None,
            current_checkpoint_id: std::mem::ManuallyDrop::new(current_checkpoint_id),
            local_actor_id: std::mem::ManuallyDrop::new(local_actor_id),
            member_inbox: VecDeque::new(),
            authoring_verb: None,
            replay_budget: None,
            local_replay_budget: None,
            pending_reprojection: None,
            merge_policy: crate::os_spr::MergePolicy::default(),
            clock,
            initial_digest,
            content_revision,
            revision_accumulator: std::mem::ManuallyDrop::new(revision_accumulator),
            current: std::mem::ManuallyDrop::new(Arc::new(current)),
            current_detached: false,
            snapshot_retirement_factory: std::mem::ManuallyDrop::new(None),
            initial_snapshot_retirement_factory: std::mem::ManuallyDrop::new(None),
            mutation_retirement_factory: std::mem::ManuallyDrop::new(None),
            snapshot_read_leases: std::mem::ManuallyDrop::new(Arc::new(SnapshotReadLeaseRegistry::new())),
            displaced_retirements: std::mem::ManuallyDrop::new(displaced_retirements),
            owned_disposer: std::mem::ManuallyDrop::new(None),
            owned_disposer_terminal: false,
            one_item_preparation_factory: std::mem::ManuallyDrop::new(None),
            one_item_wire_preparation_factory: std::mem::ManuallyDrop::new(None),
            tail_undo_cache: std::mem::ManuallyDrop::new(None),
            supersessions: std::mem::ManuallyDrop::new(supersessions),
            prefix_ring: std::mem::ManuallyDrop::new(Vec::with_capacity(PREFIX_SNAPSHOT_RING_CAPACITY)),
            revision_dirty_from: None,
            mirror_dirt: StackMirrorDirt::CLEAN,
            prefix_ring_dirty_from: usize::MAX,
            fold_frontier: None,
            snapshot_equality: None,
            pending_report: std::mem::ManuallyDrop::new(PendingCommandReport::default()),
            durable_group_root: std::mem::ManuallyDrop::new(None),
        })
    }

    /// 🏗️ Atomically adopts a domain-validated initialization runtime. Every
    /// history/reference/snapshot owner was prepared under the caller's StepContext before this
    /// non-suspending move; no validation or collection traversal occurs at publication.
    pub fn from_initialized_runtime_with_owners(envelope: ArtifactEnvelope<P, Mutation>, runtime: ArtifactStoreInitializationRuntime<P>, generation: u64, owners: DocumentStoreOwners<P, Mutation>) -> Self {
        config_store_from_initialized_runtime_with_owners(envelope, runtime, generation, owners)
    }

    fn durable_group_read_root(&self) -> Option<&durable_group::ArtifactStoreDurableGroupRootV1<P>> {
        self.durable_group_root.as_ref().filter(|root| root.visibility.committed() && !root.adopted)
    }

    fn ensure_durable_group_idle(&self) -> Result<(), VcsError> {
        if self.durable_group_root.is_some() {
            return Err(VcsError::ValidationFailed("artifact store belongs to an unresolved durable group decision".into()));
        }
        Ok(())
    }

    pub fn generation(&self) -> u64 {
        self.durable_group_read_root().map_or(self.generation, |root| root.generation)
    }

    /// 🧬️ Returns the current history identity used to invalidate derived work.
    pub fn artifact_revision(&self) -> ArtifactRevision {
        let group = self.durable_group_read_root();
        ArtifactRevision {
            artifact_id: self.envelope.id.clone(),
            schema: self.envelope.schema.clone(),
            applied_edit_ids: group.map_or_else(|| (*self.applied_edit_ids).clone(), |root| root.applied_edit_ids.clone()),
            redo_edit_ids: group.map_or_else(|| (*self.redo_edit_ids).clone(), |root| root.redo_edit_ids.clone()),
            checkpoint_id: (*self.current_checkpoint_id).clone(),
        }
    }

    /// 🪪️ Reads the event-maintained generation at an already-owned operation boundary.
    pub fn generation_now(&self) -> u64 {
        self.generation()
    }

    /// ⏰️ Reads this Store's hybrid logical clock without suspension, so a server that mints a
    /// stamped publication clock can make it strictly after the document's own last edit instead of
    /// guessing from its wall clock.
    pub fn clock_now(&self) -> HybridLogicalTimestamp {
        self.clock
    }

    pub fn content_revision(&self) -> [u8; 32] {
        self.durable_group_read_root().map_or(self.content_revision, |root| root.content_revision)
    }

    /// 🧬️ Reads the fixed-width event-maintained content revision without suspension.
    pub fn content_revision_now(&self) -> [u8; 32] {
        self.content_revision()
    }

    /// 🎯️ Returns the exact revision plus local generation a projection result must match.
    pub fn projection_stamp(&self) -> ArtifactProjectionStamp {
        ArtifactProjectionStamp { revision: self.artifact_revision(), generation: self.generation() }
    }

    /// 📬️ Captures one immutable projection or inference input from the current reconciled snapshot.
    pub fn projection_event<Previous, Policy>(&self, cause: ArtifactProjectionCause, previous: Option<Previous>, cache_mode: ArtifactProjectionCacheMode, policy: Policy) -> Result<ArtifactProjectionEvent<P, Previous, Policy>, VcsError> {
        Ok(ArtifactProjectionEvent { stamp: self.projection_stamp(), cause, state: self.snapshot()?, previous, cache_mode, policy })
    }

    /// 📣️ Returns the last successful transition through the shared projection invalidation seam.
    ///
    /// 🌀️ `projection_stamp` is async; `Option::map`'s closure is sync (R10 shape 1).
    pub fn last_projection_invalidation(&self) -> Option<ArtifactProjectionInvalidation> {
        self.durable_group_read_root().map_or(self.last_projection_cause, |root| root.last_projection_cause).map(|cause| ArtifactProjectionInvalidation { cause, stamp: self.projection_stamp() })
    }

    /// 🔄️ Invalidates projections after a verified replay that did not otherwise change history.
    pub fn invalidate_after_replay(&mut self) -> Result<ArtifactProjectionInvalidation, VcsError> {
        self.invalidate_projections(ArtifactProjectionCause::Replay)
    }

    /// 🛂️ Invalidates projections after a policy change outside semantic event history.
    pub fn invalidate_after_policy_change(&mut self) -> Result<ArtifactProjectionInvalidation, VcsError> {
        self.invalidate_projections(ArtifactProjectionCause::PolicyChange)
    }

    /// 🔗️ Invalidates projections after an external resource changed beneath the artifact.
    pub fn invalidate_after_external_resource_change(&mut self) -> Result<ArtifactProjectionInvalidation, VcsError> {
        self.invalidate_projections(ArtifactProjectionCause::ExternalResourceChange)
    }

    fn invalidate_projections(&mut self, cause: ArtifactProjectionCause) -> Result<ArtifactProjectionInvalidation, VcsError> {
        self.ensure_durable_group_idle()?;
        self.bump()?;
        self.last_projection_cause = Some(cause);
        Ok(ArtifactProjectionInvalidation { cause, stamp: self.projection_stamp() })
    }

    /// 🛂️ Accepts only a result computed for the exact current revision and generation. Accepted
    /// semantic diffs are returned to their owning strict-apply boundary, never applied here.
    ///
    /// 🌀️ A future is consumed by one `.await` (R10 shape 2) — resolved once, reused below.
    pub fn accept_projection_result<Output, Diff>(&self, result: ArtifactProjectionResult<Output, Diff>) -> Result<AcceptedArtifactProjection<Output, Diff>, StaleArtifactProjection> {
        let current = self.projection_stamp();
        if result.stamp != current {
            return Err(StaleArtifactProjection { computed_for: result.stamp, current });
        }
        Ok(AcceptedArtifactProjection { output: result.output, proposed_diff: result.proposed_diff })
    }

    pub fn envelope(&self) -> &ArtifactEnvelope<P, Mutation> {
        &self.envelope
    }

    /// 👁️ Read-only envelope view — prefer this over mutating through public fields.
    pub fn envelope_view(&self) -> ArtifactEnvelopeView<'_, P, Mutation> {
        ArtifactEnvelopeView { envelope: &self.envelope }
    }

    pub fn applied_edit_ids(&self) -> &crate::os_vcs::HistoryPageStack<String> {
        self.durable_group_read_root().map_or(&self.applied_edit_ids, |root| &root.applied_edit_ids)
    }

    /// ↪️ Pending redo stack (edit ids undone since the last fresh `Apply`).
    pub fn redo_edit_ids(&self) -> &crate::os_vcs::HistoryPageStack<String> {
        self.durable_group_read_root().map_or(&self.redo_edit_ids, |root| &root.redo_edit_ids)
    }

    /// 🧭️ The checkpoint new commits currently parent onto (defaults to the latest checkpoint
    /// on construction/`set_state`; advances on commit/checkout/switch).
    pub fn current_checkpoint_id(&self) -> Option<&str> {
        self.current_checkpoint_id.as_deref()
    }

    /// 🖋️ The local actor id used to distinguish this store's own edits from ingested ones.
    /// Not part of the wire envelope — a caller reconstructing the store per call must save/restore
    /// it via {@link set_local_actor_id} for `UndoPolicy` to keep classifying foreign edits.
    pub fn local_actor_id(&self) -> Option<&str> {
        self.durable_group_read_root().map_or_else(|| self.local_actor_id.as_deref(), |root| root.local_actor_id.as_deref())
    }

    /// 🖋️ Sets the local actor id (see {@link local_actor_id}). Called automatically from each
    /// local `Apply`/`AppendTransaction`; callers that reconstruct the store per dispatch restore it here.
    pub fn set_local_actor_id(&mut self, actor_id: Option<String>) -> Result<(), VcsError> {
        self.ensure_durable_group_idle()?;
        self.replace_local_actor_retained(actor_id)
    }

    /// 🏷️ The verb id the next locally minted edit is stamped with (see {@link set_authoring_verb}).
    pub fn authoring_verb(&self) -> Option<&str> {
        self.authoring_verb.as_deref()
    }

    /// 🏷️ Names the action or command whose `Apply` the caller dispatches next, so the edit it mints carries a
    /// locale-neutral label source every reload and peer resolves the same way; the caller clears it after dispatch.
    pub fn set_authoring_verb(&mut self, verb: Option<String>) {
        self.authoring_verb = verb.filter(|value| !value.is_empty());
    }

    /// 🎞️ The tool transaction open on this store, if any ([`ArtifactCommand::AppendTransaction`]).
    pub fn open_transaction(&self) -> Option<&OpenToolTransaction> {
        self.envelope.open_transaction.as_ref()
    }

    /// 🔧️ The most recently created/amended edit's `(forwards, inverse, per-operation meta)`.
    /// Used right after `dispatch(Apply{..})`/`AppendTransaction` to build a `KernelMutation`/`InvocationResult`
    /// with a true inverse from the just-recorded `Edit.inverse`.
    pub fn edit_mutations(&self) -> Option<(&[Mutation], &[Mutation], &[MutationMeta])> {
        self.envelope.vcs.edits.last().map(|edit| (edit.forwards.as_slice(), edit.inverse.as_slice(), edit.mutation_meta.as_slice()))
    }

    /// 📜️ Ancestor-graph rows for this store's checkpoint history. See {@link build_history_columns}.
    pub async fn history_columns(&self) -> Vec<HistoryColumn> {
        build_history_columns(&self.envelope).await
    }

    /// ♻️ Sole public reload API: adopts `envelope`'s event log and derives every position from
    /// it — a reload replays history, it never injects a cursor.
    pub async fn reset(&mut self, envelope: ArtifactEnvelope<P, Mutation>) -> Result<CommandReceipt, VcsError> {
        self.ensure_durable_group_idle()?;
        self.set_state(envelope).await?;
        self.last_projection_cause = Some(ArtifactProjectionCause::Reset);
        Ok(CommandReceipt { edit_ids: self.applied_edit_ids.to_vec(), generation: self.generation(), messages: Vec::new(), worst: None })
    }

    /// 💾️ Adopts full store state from `envelope`'s event log — applied edits, redo stack,
    /// checkpoint and alternative are the fold of its edits and transitions, so `Redo` survives
    /// round-tripping through a serialized envelope (e.g. one `dispatch` call per request). A history change still waiting
    /// for its replay belonged to the replaced log and is dropped with it.
    pub(crate) async fn set_state(&mut self, envelope: ArtifactEnvelope<P, Mutation>) -> Result<(), VcsError> {
        let mut candidate = Some(envelope);
        let adopted = self.adopt_state(&mut candidate).await;
        if let Some(rejected) = candidate {
            rejected.retire_unadopted();
        }
        adopted
    }

    /// 🛡️ The reload proper. Like {@link new}, a REFUSED reload leaves its candidate in the
    /// slot so {@link set_state} can retire it: the live store must survive a rejected reset, and a
    /// dropped populated envelope aborts on the terminal-shell witness instead of returning the
    /// `VcsError` the caller reads.
    async fn adopt_state(&mut self, candidate: &mut Option<ArtifactEnvelope<P, Mutation>>) -> Result<(), VcsError> {
        self.ensure_durable_group_idle()?;
        let envelope = candidate.as_mut().expect("a reload holds its candidate envelope");
        validate_durable_history(envelope).await?;
        let crate::os_spr::HistoryFold { applied: applied_edit_ids, redo: redo_edit_ids, checkpoint: current_checkpoint_id, alternative, supersessions, .. } = fold_envelope_history(envelope)?;
        envelope.active_alternative_id = alternative;
        validate_history_lanes(envelope, &applied_edit_ids, &redo_edit_ids).await?;
        let current = Self::fold_history(envelope, &applied_edit_ids, &supersessions).await?;
        let applied_edit_ids = ArtifactStoreInitializationOwnerCatalog::retain_id_capacity(applied_edit_ids);
        let redo_edit_ids = ArtifactStoreInitializationOwnerCatalog::retain_id_capacity(redo_edit_ids);
        let initial_digest = *semio_framework_hash::hash(&envelope.vcs.initial_snapshot.encode_pack()).as_bytes();
        let revision_accumulator = CursorRevisionAccumulator::new(envelope, initial_digest);
        let runtime_slots = usize::from(self.backbone.is_some())
            + Self::string_owner_slots(&self.current_checkpoint_id)
            + Self::string_vector_owner_slots(&self.applied_edit_ids)
            + Self::string_vector_owner_slots(&self.redo_edit_ids)
            + Self::revision_owner_slots(&self.revision_accumulator)
            + 1;
        let commit_authority = self.prepare_document_root_commit(runtime_slots)?;
        let (dag, edit_sequence, clock, rejected_seed_identities) = Self::seed_runtime_state(envelope, self.clock.actor)?;
        let envelope = candidate.take().expect("an adopted reload takes its validated envelope exactly once");
        self.clear_prefix_ring()?;
        self.commit_document_roots_retained(envelope, Arc::new(current), dag, None, commit_authority);
        self.replace_supersessions_retained(supersessions)?;
        if !rejected_seed_identities.is_empty() {
            self.displaced_retirements.push_reserved(Box::new(ArtifactStoreStringVectorRetirement::new(rejected_seed_identities)));
        }
        if let Some(previous) = self.backbone.take() {
            self.displaced_retirements.push_reserved(Box::new(ArtifactStoreBackboneRetirement::new(previous)));
        }
        self.edit_sequence = edit_sequence;
        if let Some(owner) = Self::take_string_replacement(&mut self.current_checkpoint_id, current_checkpoint_id) {
            self.displaced_retirements.push_reserved(owner);
        }
        self.clock = clock;
        self.initial_digest = initial_digest;
        if let Some(owner) = Self::take_string_vector_replacement(&mut self.applied_edit_ids, applied_edit_ids) {
            self.displaced_retirements.push_reserved(owner);
        }
        if let Some(owner) = Self::take_string_vector_replacement(&mut self.redo_edit_ids, redo_edit_ids) {
            self.displaced_retirements.push_reserved(owner);
        }
        self.push_revision_replacement_reserved(revision_accumulator);
        drop(self.pending_reprojection.take());
        self.mirror_dirt = StackMirrorDirt::ALL;
        self.fold_frontier = None;
        self.bump()?;
        Ok(())
    }

    /// 📌️ Records the composed children a checkpoint was taken against. Not reachable through
    /// an ordinary `Apply` (no mutation can touch checkpoint metadata), so — like `set_owner` — it
    /// needs its own setter. Called by `VcsArtifactApp`'s checkpoint cascade right after the
    /// checkpoint is created, since a pin can only name a child checkpoint that already exists.
    /// Re-derives `content_addressed_checkpoint_id` so the checkpoint's identity actually covers its
    /// pins rather than merely storing them beside it, and records the re-identification as a
    /// `Repin` transition so every replica and every reload derives the same identity.
    #[must_use]
    pub async fn set_checkpoint_composition_pins(&mut self, checkpoint_id: &str, pins: Vec<crate::os_vcs::CompositionPin>) -> Result<ArtifactProjectionInvalidation, VcsError> {
        self.ensure_durable_group_idle()?;
        validate_composition_pins(&pins).await?;
        let target_index = self.envelope.vcs.checkpoints.iter().position(|checkpoint| checkpoint.id == checkpoint_id).ok_or_else(|| VcsError::UnknownChange(checkpoint_id.to_string()))?;
        if self.envelope.vcs.checkpoints.iter().any(|checkpoint| checkpoint.parent_id.as_deref() == Some(checkpoint_id)) {
            return Err(VcsError::ValidationFailed(format!("cannot repin checkpoint {checkpoint_id} after a descendant exists")));
        }
        let checkpoint = &self.envelope.vcs.checkpoints[target_index];
        let previous_id = checkpoint.id.clone();
        let next_id = content_addressed_checkpoint_id(checkpoint.parent_id.as_deref(), &checkpoint.change_ids, &self.envelope.vcs.changes, checkpoint.message.as_deref(), &checkpoint.authors, &checkpoint.timestamp, &pins).await;
        if next_id != previous_id && self.envelope.vcs.checkpoints.iter().enumerate().any(|(index, checkpoint)| index != target_index && checkpoint.id == next_id) {
            return Err(VcsError::ValidationFailed(format!("rederived checkpoint identity {next_id} collides with established history")));
        }
        let dependencies = self.checkpoint_origin(&previous_id).into_iter().collect();
        let pins = pins.iter().map(|pin| crate::os_spr::TransitionPin { child_uri: pin.child_ref.to_uri(), checkpoint_id: pin.checkpoint_id.clone() }).collect();
        self.replace_pending_report_retained(PendingCommandReport::default())?;
        self.commit_transition(crate::os_spr::HistoryTransition::Repin { checkpoint_id: previous_id, pinned_checkpoint_id: next_id, pins }, dependencies).await?;
        self.flush_outbound().await?;
        self.invalidate_projections(ArtifactProjectionCause::Checkpoint)
    }

    /// ⚡️ The live snapshot: the incrementally-maintained `current` fold, as-is. Always `Ok`
    /// in practice (kept as `Result` for API stability); O(1) instead of a full replay. See the
    /// `current` field doc for the maintenance invariant.
    pub fn snapshot(&self) -> Result<P, VcsError> {
        Ok(self.durable_group_read_root().map_or(self.current.as_ref(), |root| root.current.as_ref().expect("unadopted durable group root retains its current snapshot").as_ref()).clone())
    }

    /// 🔎️ Borrows the current immutable fold without issuing or cloning a snapshot owner.
    pub fn snapshot_ref(&self) -> &P {
        self.durable_group_read_root().map_or(self.current.as_ref(), |root| root.current.as_ref().expect("unadopted durable group root retains its current snapshot").as_ref())
    }

    /// 🪞️ An erased read of `alias`, a snapshot this store derived but never published (a history edit's preview),
    /// leased through the same registry as [`Self::snapshot_read`] so a composing parent's content view can show it in
    /// this member's place under the same retirement discipline.
    pub fn snapshot_read_erased_of(&self, alias: Arc<P>) -> Result<ErasedSnapshotRead, VcsError>
    where
        P: Sync,
    {
        if !self.snapshot_read_leases.publish_authority(self.generation(), self.content_revision()) {
            return Err(VcsError::ValidationFailed("snapshot read commit authority is busy or exhausted".into()));
        }
        let lease = self.snapshot_read_leases.try_issue(alias.clone()).map_err(|_| VcsError::ValidationFailed("snapshot read lease registry is busy, saturated, or exhausted".into()))?;
        Ok(ErasedSnapshotRead::new(alias, lease))
    }

    /// 🧵️ Immutable O(1) snapshot capability for worker and composition boundaries.
    pub fn snapshot_read(&self) -> Result<SnapshotRead<P>, VcsError>
    where
        P: Sync,
    {
        let generation = self.generation();
        let content_revision = self.content_revision();
        if !self.snapshot_read_leases.publish_authority(generation, content_revision) {
            return Err(VcsError::ValidationFailed("snapshot read commit authority is busy or exhausted".into()));
        }
        let owner = self.snapshot_owner();
        let lease = self.snapshot_read_leases.try_issue(owner.clone()).map_err(|_| VcsError::ValidationFailed("snapshot read lease registry is busy, saturated, or exhausted".into()))?;
        Ok(SnapshotRead::new(owner, lease))
    }

    pub fn snapshot_owner(&self) -> Arc<P> {
        self.durable_group_read_root().map_or_else(|| Arc::clone(&*self.current), |root| Arc::clone(root.current.as_ref().expect("unadopted durable group root retains its current snapshot")))
    }

    /// 🧵️ Captures the immutable event-maintained snapshot root in O(1).
    pub fn snapshot_root(&self) -> Arc<P> {
        self.snapshot_owner()
    }

    pub fn install_snapshot_retirement_factory(&mut self, factory: Arc<dyn SnapshotRetirementFactory<P>>) -> Result<(), VcsError> {
        self.ensure_durable_group_idle()?;
        if self.snapshot_retirement_factory.is_some() {
            return Err(VcsError::Deserialize("snapshot retirement factory is already installed".into()));
        }
        *self.snapshot_retirement_factory = Some(factory);
        Ok(())
    }

    pub fn install_owned_disposer(&mut self, disposer: Box<dyn ArtifactStoreOwnedDisposer<P, Mutation>>) -> Result<(), VcsError> {
        self.ensure_durable_group_idle()?;
        if self.owned_disposer.is_some() || self.owned_disposer_terminal {
            return Err(VcsError::Deserialize("artifact store owned disposer is already installed or terminal".into()));
        }
        *self.owned_disposer = Some(disposer);
        Ok(())
    }

    /// 🔐️ Installs the one domain-supplied owner catalog before a store can enter
    /// retained replacement or close. There is no default catalog and a second installation faults.
    pub fn install_document_store_owners_exact(&mut self, owners: DocumentStoreOwners<P, Mutation>) {
        assert!(
            self.snapshot_retirement_factory.is_none() && self.initial_snapshot_retirement_factory.is_none() && self.mutation_retirement_factory.is_none() && self.owned_disposer.is_none() && !self.owned_disposer_terminal,
            "a freshly constructed member store must not carry preinstalled or terminal owner authority"
        );
        *self.snapshot_retirement_factory = Some(owners.snapshot_retirement);
        *self.initial_snapshot_retirement_factory = Some(owners.initial_snapshot_retirement);
        *self.mutation_retirement_factory = Some(owners.mutation_retirement);
        *self.owned_disposer = Some(owners.store_disposer);
        *self.one_item_preparation_factory = owners.one_item_preparation;
        *self.one_item_wire_preparation_factory = owners.one_item_wire_preparation;
    }

    pub fn owned_disposer_installed(&self) -> bool {
        self.owned_disposer.is_some() || self.owned_disposer_terminal
    }

    fn replace_current_retained(&mut self, next: Arc<P>) -> Result<(), VcsError> {
        if Arc::ptr_eq(&self.current, &next) {
            return Ok(());
        }
        let previous_is_tail = !self.current_detached && self.tail_undo_cache.as_ref().is_some_and(|(_, snapshot)| Arc::ptr_eq(snapshot, &self.current));
        let factory = if previous_is_tail {
            None
        } else {
            self.displaced_retirements.reserve(1)?;
            Some((*self.snapshot_retirement_factory).clone().ok_or_else(|| VcsError::ValidationFailed("artifact store current replacement requires its exact snapshot retirement factory".into()))?)
        };
        let previous = std::mem::replace(&mut *self.current, next);
        if previous_is_tail {
            drop(previous);
        } else {
            self.displaced_retirements.push_reserved(factory.expect("non-tail current factory was validated").retire(previous));
        }
        Ok(())
    }

    fn displaced_envelope_retirement(&self, envelope: ArtifactEnvelope<P, Mutation>) -> Result<Box<dyn ErasedSnapshotRetirement>, VcsError> {
        let initial_snapshot_factory = (*self.initial_snapshot_retirement_factory).clone().ok_or_else(|| VcsError::ValidationFailed("artifact store envelope replacement requires its exact initial-snapshot retirement factory".into()))?;
        let mutation_factory = (*self.mutation_retirement_factory).clone().ok_or_else(|| VcsError::ValidationFailed("artifact store envelope replacement requires its exact mutation retirement factory".into()))?;
        Ok(Box::new(ArtifactStoreEnvelopeRetirement::new(envelope, initial_snapshot_factory, mutation_factory)))
    }

    fn replace_envelope_retained(&mut self, next: ArtifactEnvelope<P, Mutation>) -> Result<(), VcsError> {
        self.displaced_retirements.reserve(1)?;
        let initial_snapshot_factory = (*self.initial_snapshot_retirement_factory).clone().ok_or_else(|| VcsError::ValidationFailed("artifact store envelope replacement requires its exact initial-snapshot retirement factory".into()))?;
        let mutation_factory = (*self.mutation_retirement_factory).clone().ok_or_else(|| VcsError::ValidationFailed("artifact store envelope replacement requires its exact mutation retirement factory".into()))?;
        let previous = std::mem::replace(&mut *self.envelope, next);
        self.displaced_retirements.push_reserved(Box::new(ArtifactStoreEnvelopeRetirement::new(previous, initial_snapshot_factory, mutation_factory)));
        Ok(())
    }

    fn replace_document_roots_retained(&mut self, next_envelope: ArtifactEnvelope<P, Mutation>, next_current: Arc<P>) -> Result<(), VcsError> {
        self.displaced_retirements.reserve(2)?;
        let initial_snapshot_factory = (*self.initial_snapshot_retirement_factory).clone().ok_or_else(|| VcsError::ValidationFailed("artifact store document-root replacement requires its exact initial-snapshot retirement factory".into()))?;
        let mutation_factory = (*self.mutation_retirement_factory).clone().ok_or_else(|| VcsError::ValidationFailed("artifact store document-root replacement requires its exact mutation retirement factory".into()))?;
        let snapshot_factory = (*self.snapshot_retirement_factory).clone().ok_or_else(|| VcsError::ValidationFailed("artifact store document-root replacement requires its exact snapshot retirement factory".into()))?;
        let previous_envelope = std::mem::replace(&mut *self.envelope, next_envelope);
        let previous_current = std::mem::replace(&mut *self.current, next_current);
        self.displaced_retirements.push_reserved(Box::new(ArtifactStoreEnvelopeRetirement::new(previous_envelope, initial_snapshot_factory, mutation_factory)));
        self.displaced_retirements.push_reserved(snapshot_factory.retire(previous_current));
        Ok(())
    }

    fn prepare_document_root_commit(&mut self, additional_displaced_owners: usize) -> Result<ArtifactStoreDocumentRootCommitAuthority<P, Mutation>, VcsError> {
        let tail_slots = self.tail_undo_cache.as_ref().map_or(0, |(edit_id, snapshot)| usize::from(!edit_id.is_empty()) + usize::from(self.current_detached || !Arc::ptr_eq(snapshot, &self.current)));
        self.displaced_retirements
            .reserve(3usize.checked_add(tail_slots).and_then(|slots| slots.checked_add(additional_displaced_owners)).ok_or_else(|| VcsError::ValidationFailed("artifact store document-root retirement reservation overflowed".into()))?)?;
        Ok(ArtifactStoreDocumentRootCommitAuthority {
            snapshot: (*self.snapshot_retirement_factory).clone().ok_or_else(|| VcsError::ValidationFailed("artifact store document-root transaction requires its exact snapshot retirement factory".into()))?,
            initial_snapshot: (*self.initial_snapshot_retirement_factory).clone().ok_or_else(|| VcsError::ValidationFailed("artifact store document-root transaction requires its exact initial-snapshot retirement factory".into()))?,
            mutation: (*self.mutation_retirement_factory).clone().ok_or_else(|| VcsError::ValidationFailed("artifact store document-root transaction requires its exact mutation retirement factory".into()))?,
        })
    }

    fn commit_document_roots_retained(
        &mut self,
        next_envelope: ArtifactEnvelope<P, Mutation>,
        next_current: Arc<P>,
        next_dag: crate::os_spr::MutationDag,
        next_tail: Option<(String, Arc<P>)>,
        authority: ArtifactStoreDocumentRootCommitAuthority<P, Mutation>,
    ) {
        if let Some((edit_id, snapshot)) = self.tail_undo_cache.take() {
            if !edit_id.is_empty() {
                self.displaced_retirements.push_reserved(Box::new(ArtifactStoreStringRetirement::new(edit_id)));
            }
            if !self.current_detached && Arc::ptr_eq(&snapshot, &self.current) {
                drop(snapshot);
            } else {
                self.displaced_retirements.push_reserved(authority.snapshot.retire(snapshot));
            }
        }
        let previous_envelope = std::mem::replace(&mut *self.envelope, next_envelope);
        let previous_current = std::mem::replace(&mut *self.current, next_current);
        let previous_dag = std::mem::replace(&mut *self.dag, next_dag);
        self.displaced_retirements.push_reserved(Box::new(ArtifactStoreEnvelopeRetirement::new(previous_envelope, authority.initial_snapshot, authority.mutation)));
        self.displaced_retirements.push_reserved(authority.snapshot.retire(previous_current));
        self.displaced_retirements.push_reserved(Box::new(ArtifactStoreMutationDagRetirement::new(previous_dag)));
        *self.tail_undo_cache = next_tail;
    }

    fn string_vector_owner_slots(values: &crate::os_vcs::HistoryPageStack<String>) -> usize {
        usize::from(!values.is_empty() || values.capacity() != 0)
    }

    fn string_owner_slots(value: &Option<String>) -> usize {
        usize::from(value.is_some())
    }

    fn revision_owner_slots(value: &CursorRevisionAccumulator) -> usize {
        usize::from(!value.applied.is_empty() || value.applied.capacity() != 0 || !value.redo.is_empty() || value.redo.capacity() != 0)
    }

    fn pending_report_owner_slots(value: &PendingCommandReport) -> usize {
        usize::from(value.edit_ids.as_ref().is_some_and(|ids| !ids.is_empty() || ids.capacity() != 0) || !value.messages.is_empty() || value.messages.capacity() != 0 || value.worst.is_some() || !value.outbound.is_empty() || value.outbound.capacity() != 0)
    }

