    (pub enum $enum_name:ident, $open_name:ident { $($variant:ident($kind:literal, $standard:literal, $subset:literal, $schema:literal) => ($snapshot:ty, $mutation:ty)),+ $(,)? }) => {
        pub enum $enum_name {
            $($variant(Box<$crate::os_store::ArtifactStore<$snapshot, $mutation>>)),+
